BEGIN;

CREATE TABLE IF NOT EXISTS public.builds (
    slug TEXT PRIMARY KEY REFERENCES public.pokemon(slug)
);

ALTER TABLE public.builds
    ADD COLUMN IF NOT EXISTS caps TEXT[] NOT NULL DEFAULT '{}',
    ADD COLUMN IF NOT EXISTS dicas JSONB NOT NULL DEFAULT '{}'::jsonb,
    ADD COLUMN IF NOT EXISTS images JSONB NOT NULL DEFAULT '{}'::jsonb,
    ADD COLUMN IF NOT EXISTS categorias JSONB NOT NULL DEFAULT '{}'::jsonb;

INSERT INTO public.builds (slug, caps, dicas)
VALUES ('pokemon-blue', ARRAY['1º GYM - BROCK', '2º GYM - MISTY', '3º GYM - LT. SURGE', '4º GYM - ERIKA', '5º GYM - KOGA', '6º GYM - SABRINA', '7º GYM - BLAINE', '8º GYM - GIOVANNI', 'ELITE FOUR - LORELEI', 'ELITE FOUR - BRUNO', 'ELITE FOUR - AGATHA', 'ELITE FOUR - LANCE', 'CHAMPION'],
    jsonb_build_object('1º GYM - BROCK', jsonb_build_array('Brock usa dois Pokémon dos tipos Pedra e Terra. Seu time começa com Geodude no nível 12 e termina com Onix no nível 14.', 'Os dois recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Golpes dos tipos Lutador e Terra também são superefetivos.', 'Se você escolheu Squirtle, treine-o até aprender Bubble no nível 8 e use o golpe contra os dois Pokémon de Brock.', 'Se você escolheu Bulbasaur, treine-o até aprender Vine Whip no nível 13. O golpe tem vantagem contra os dois adversários.', 'Se você escolheu Charmander, capture um Caterpie na Viridian Forest e evolua-o até Butterfree. No nível 12, Butterfree aprende Confusion, que pode causar um bom dano em Geodude e Onix.', 'Tenha cuidado quando Onix usar Bide. Ele acumula o dano recebido por alguns turnos e depois devolve o dobro, então aproveite esse momento para usar golpes que não causem dano, como Growl ou Tail Whip, e espere o Bide terminar antes de voltar a atacar.', 'Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon.')))
ON CONFLICT (slug) DO NOTHING;

-- Registros disponíveis para todos os jogos cadastrados em builds.
INSERT INTO public.builds (slug)
SELECT slug FROM public.pokemon
ON CONFLICT (slug) DO NOTHING;

-- Atualiza a versão inicial da estratégia do Brock sem sobrescrever edições posteriores.
UPDATE public.builds
SET dicas = jsonb_set(dicas, ARRAY['1º GYM - BROCK'], jsonb_build_array('Brock usa dois Pokémon dos tipos Pedra e Terra. Seu time começa com Geodude no nível 12 e termina com Onix no nível 14.', 'Os dois recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Golpes dos tipos Lutador e Terra também são superefetivos.', 'Se você escolheu Squirtle, treine-o até aprender Bubble no nível 8 e use o golpe contra os dois Pokémon de Brock.', 'Se você escolheu Bulbasaur, treine-o até aprender Vine Whip no nível 13. O golpe tem vantagem contra os dois adversários.', 'Se você escolheu Charmander, capture um Caterpie na Viridian Forest e evolua-o até Butterfree. No nível 12, Butterfree aprende Confusion, que pode causar um bom dano em Geodude e Onix.', 'Tenha cuidado quando Onix usar Bide. Ele acumula o dano recebido por alguns turnos e depois devolve o dobro, então aproveite esse momento para usar golpes que não causem dano, como Growl ou Tail Whip, e espere o Bide terminar antes de voltar a atacar.', 'Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon.'), true)
WHERE slug = 'pokemon-blue' AND dicas->'1º GYM - BROCK' = jsonb_build_array('Brock, líder especialista no tipo Pedra, usa um Geodude de nível 12 e um Onix de nível 14, ambos dos tipos Pedra e Terra e vulneráveis a golpes de Água, Planta, Lutador e Terra.', 'É recomendado usar um dos iniciais que têm vantagem contra Brock: Squirtle, do tipo Água, ou Bulbasaur, dos tipos Planta e Veneno.', 'Tenha cuidado com o golpe Bide de Onix, que acumula o dano recebido antes de devolvê-lo.');

-- Estratégia da Misty para Pokémon Blue, preservando conteúdo já editado.
UPDATE public.builds
SET dicas = jsonb_set(dicas, ARRAY['2º GYM - MISTY'], jsonb_build_array('Misty é especialista no tipo Água e usa Staryu no nível 18 e Starmie no nível 21. Starmie também é do tipo Psíquico, mas os dois são vulneráveis a golpes dos tipos Elétrico e Planta.', 'Se você escolheu Bulbasaur, ele continua sendo uma boa opção para essa batalha. Treine-o e use seus golpes do tipo Planta contra os dois Pokémon de Misty.', 'Outra opção é Pikachu, que pode ser encontrado na Viridian Forest. Treine-o e use Thunder Shock para aproveitar a fraqueza dos dois adversários.', 'Se preferir um Pokémon de Planta, capture um Bellsprout nas rotas 24 ou 25, ao norte de Cerulean City, e use Vine Whip durante a batalha.', 'Tenha cuidado com BubbleBeam de Starmie, um golpe forte para essa parte da jornada. Evite deixar Pokémon dos tipos Fogo, Pedra ou Terra diante dele e mantenha a equipe com bastante vida.', 'Cure seus Pokémon antes de entrar no ginásio e leve algumas Potions para o caso de precisar se recuperar durante a batalha.'), true)
WHERE slug = 'pokemon-blue' AND NOT (dicas ? '2º GYM - MISTY');


-- Estratégias de Kanto revisadas para Pokémon Blue.
UPDATE public.builds SET caps = CASE WHEN cardinality(caps) = 0 THEN (SELECT caps FROM public.builds WHERE slug = 'pokemon-blue') ELSE caps END, dicas = dicas || jsonb_build_object('1º GYM - BROCK', (SELECT dicas->'1º GYM - BROCK' FROM public.builds WHERE slug = 'pokemon-blue')) || '{"2º GYM - MISTY":["Misty usa dois Pokémon do tipo Água. Seu time começa com Staryu no nível 18 e termina com Starmie no nível 21, que também é do tipo Psíquico.","Os dois recebem dano superefetivo de golpes dos tipos Elétrico e Planta.","Se você escolheu Bulbasaur, ele já pode ter evoluído para Ivysaur no nível 16. Use Vine Whip para aproveitar a fraqueza dos dois Pokémon de Misty.","Se você escolheu Squirtle ou Charmander, capture um Pikachu na Viridian Forest e use Thunder Shock. Outra opção é capturar um Bellsprout nas Routes 24 ou 25, ao norte de Cerulean City, e usar Vine Whip.","Tenha cuidado com o BubbleBeam de Starmie, um golpe forte para essa parte da jornada. Evite deixar Pokémon dos tipos Fogo, Pedra ou Terra diante dele e mantenha a vida da equipe alta.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"3º GYM - LT. SURGE":["Lt. Surge usa três Pokémon do tipo Elétrico. Seu time começa com Voltorb no nível 21, seguido de Pikachu no nível 18 e Raichu no nível 24.","Os três recebem dano superefetivo de golpes do tipo Terra. Pokémon desse tipo também são imunes aos golpes elétricos da equipe de Surge.","Independentemente do inicial escolhido, capture um Diglett na Diglett''s Cave, a leste de Vermilion City. Treine-o até aprender Dig no nível 19 e use o golpe contra os três adversários.","Na mesma caverna, você também pode encontrar Dugtrio, que já aparece em níveis mais altos e pode usar Dig. Ele é raro e forte para essa parte da jornada, então tenha cuidado ao tentar capturá-lo.","Outra opção é usar Nidoking ou Nidoqueen. Você pode capturar um Nidoran na Route 22, treiná-lo até evoluir no nível 16 e usar uma Moon Stone encontrada no Mt. Moon para completar sua evolução.","Tenha cuidado com o SonicBoom de Voltorb, que causa sempre 20 pontos de dano. Como Diglett tem pouco HP, mantenha sua vida acima desse valor e observe também o Quick Attack de Pikachu.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"4º GYM - ERIKA":["Erika usa três Pokémon do tipo Planta. Seu time começa com Victreebel no nível 29, seguido de Tangela no nível 24 e Vileplume no nível 29. Victreebel e Vileplume também são do tipo Veneno.","Os três recebem dano superefetivo de golpes dos tipos Fogo, Voador e Gelo. Victreebel e Vileplume também são vulneráveis a golpes do tipo Psíquico.","Se você escolheu Charmander, ele já pode ter evoluído para Charmeleon. Use seus golpes do tipo Fogo para aproveitar a fraqueza de toda a equipe de Erika.","Se você escolheu Squirtle ou Bulbasaur, capture um Vulpix nas Routes 7 ou 8 e use Ember. Você também pode comprar uma Fire Stone no Celadon Department Store para evoluí-lo para Ninetales.","Se você treinou um Pidgey, ele já pode ter evoluído para Pidgeotto ou Pidgeot. Use Fly ou Wing Attack para aproveitar a fraqueza dos Pokémon de Erika ao tipo Voador.","Outra opção é Butterfree com Confusion, que causa dano superefetivo em Victreebel e Vileplume por causa do tipo Veneno dos dois.","Tenha cuidado com Sleep Powder, Poison Powder e Stun Spore, que podem fazer seus Pokémon dormirem, ficarem envenenados ou paralisados. Victreebel e Tangela também podem usar Wrap e Bind para prender seu Pokémon.","Antes da batalha, cure sua equipe e leve algumas Potions, Antidotes, Awakenings e Parlyz Heals para se preparar."],"5º GYM - KOGA":["Koga usa quatro Pokémon do tipo Veneno. Seu time começa com Koffing no nível 37, seguido de Muk no nível 39, outro Koffing no nível 37 e Weezing no nível 43.","Os quatro recebem dano superefetivo de golpes dos tipos Psíquico e Terra.","Independentemente do inicial escolhido, você pode usar Kadabra ou Alakazam com golpes do tipo Psíquico. Abra pode ser encontrado nas Routes 24 e 25 ou recebido como prêmio no Game Corner de Celadon, depois evolui para Kadabra no nível 16 e para Alakazam por troca.","Se você treinou Butterfree, seus golpes Confusion ou Psybeam também são superefetivos contra toda a equipe de Koga. Mantenha atenção à vida dele, pois Butterfree pode sofrer bastante dano.","Se você já tem Diglett ou Dugtrio, use Dig para aproveitar a fraqueza dos quatro adversários. Em Red e Blue, Koffing e Weezing ainda não possuem a habilidade Levitate, então golpes do tipo Terra funcionam contra eles.","Onix também pode ser uma opção se você o capturou no Rock Tunnel e ensinou Dig pela TM28. Já Nidoking ou Nidoqueen podem ajudar com sua resistência ao tipo Veneno, mas precisam conhecer um golpe adequado para causar dano à equipe de Koga.","Tenha muito cuidado com o Selfdestruct de Weezing, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Koga também usa Toxic e golpes que podem envenenar sua equipe, então tente não prolongar a batalha.","Antes de enfrentar Koga, cure sua equipe e leve Potions e Antidotes para se preparar caso precise recuperar seus Pokémon."],"6º GYM - SABRINA":["Sabrina usa principalmente Pokémon do tipo Psíquico. Seu time começa com Kadabra no nível 38, seguido de Mr. Mime no nível 37, Venomoth no nível 38 e Alakazam no nível 43.","Kadabra, Mr. Mime e Alakazam são do tipo Psíquico, enquanto Venomoth é dos tipos Inseto e Veneno.","Independentemente do inicial escolhido, você pode usar um Pokémon com boa força física, como Snorlax, para atacar Kadabra e Alakazam, que possuem Defesa mais baixa.","Se você capturou um Gastly na Pokémon Tower, pode usar Gastly ou suas evoluções para tentar colocar os adversários para dormir com Hypnosis ou confundi-los com Confuse Ray. Tenha cuidado, pois eles também são do tipo Veneno e recebem dano superefetivo de golpes Psíquicos.","Para enfrentar Venomoth, use um Pokémon com golpes dos tipos Fogo, Voador, Pedra ou Psíquico.","Tenha cuidado com Kadabra e Alakazam, que são rápidos e possuem golpes Psíquicos fortes. Eles também podem usar Recover para recuperar vida, enquanto Alakazam pode usar Reflect para reduzir o dano dos seus golpes físicos.","Antes da batalha, cure sua equipe e leve Potions, Awakenings e Parlyz Heals para se preparar caso precise recuperar seus Pokémon."],"7º GYM - BLAINE":["Blaine usa quatro Pokémon do tipo Fogo. Seu time começa com Growlithe no nível 42, seguido de Ponyta no nível 40, Rapidash no nível 42 e Arcanine no nível 47.","Os quatro recebem dano superefetivo de golpes dos tipos Água, Terra e Pedra.","Se você escolheu Squirtle, ele já pode ter evoluído para Blastoise. Use Surf para aproveitar a fraqueza de toda a equipe de Blaine.","Se você escolheu Bulbasaur ou Charmander, uma opção é usar Gyarados. Caso tenha guardado um Magikarp durante a jornada, treine-o até o nível 20 para evoluí-lo e ensine Surf.","Se você já treinou Diglett ou Dugtrio, também pode usar Dig contra os Pokémon de Blaine. Onix é outra opção caso conheça um golpe dos tipos Terra ou Pedra.","Outra opção é Dratini ou Dragonair. Além de resistir aos golpes do tipo Fogo, ele pode aprender Surf e causar dano superefetivo. Em Pokémon Blue, Dratini pode ser obtido como prêmio no Game Corner de Celadon ou pescado na Safari Zone com a Super Rod.","Tenha cuidado com o Fire Blast de Arcanine, que causa bastante dano e pode deixar seu Pokémon queimado. Evite colocar seus Pokémon dos tipos Planta ou Inseto diante dele.","Antes da batalha, cure sua equipe e leve algumas Potions e Burn Heals para se preparar caso precise recuperar seus Pokémon."],"8º GYM - GIOVANNI":["Giovanni usa cinco Pokémon do tipo Terra. Seu time começa com Rhyhorn no nível 45, seguido de Dugtrio no nível 42, Nidoqueen no nível 44, Nidoking no nível 45 e Rhydon no nível 50.","Todos recebem dano superefetivo de golpes dos tipos Água e Gelo. Rhyhorn e Rhydon também são do tipo Pedra, então recebem quatro vezes mais dano de golpes dos tipos Água e Planta.","Se você escolheu Squirtle, ele já pode ter evoluído para Blastoise. Use Surf contra toda a equipe de Giovanni, especialmente contra Rhyhorn e Rhydon.","Se você escolheu Bulbasaur, Venusaur pode usar golpes do tipo Planta contra Rhyhorn, Dugtrio e Rhydon. Tenha mais cuidado contra Nidoqueen e Nidoking, pois o tipo Veneno deles reduz a vantagem dos golpes de Planta.","Se você escolheu Charmander, use um Pokémon de Água, como Gyarados com Surf, para enfrentar a equipe. Dratini ou Dragonair com Surf também podem aproveitar a fraqueza dos adversários.","Tenha muito cuidado com Fissure e Horn Drill de Rhydon, pois os dois podem derrotar seu Pokémon em um único golpe se acertarem. Na primeira geração, esses golpes falham se o alvo for mais rápido que o usuário, então um Pokémon rápido com Surf é uma boa escolha..","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"ELITE FOUR - LORELEI":["Lorelei é a primeira integrante da Elite Four e usa Pokémon dos tipos Água, Gelo e Psíquico. Seu time começa com Dewgong no nível 54, seguido de Cloyster no nível 53, Slowbro no nível 54, Jynx no nível 56 e Lapras no nível 56.","Dewgong, Cloyster, Slowbro e Lapras recebem dano superefetivo de golpes do tipo Elétrico. Jynx é vulnerável a golpes dos tipos Fogo e Pedra.","Independentemente do inicial escolhido, Pikachu ou Raichu com Thunderbolt são boas opções contra Dewgong, Cloyster, Slowbro e Lapras. Pikachu pode ser encontrado na Viridian Forest e evolui para Raichu com uma Thunder Stone.","Outra opção para enfrentar os quatro Pokémon de Água é Jolteon. Para obtê-lo, entre pela parte de trás da Celadon Mansion, suba até o último andar para receber um Eevee e use nele uma Thunder Stone, que pode ser comprada no Celadon Mall.","Contra Jynx, se você escolheu Charmander, pode usar seu Charizard com golpes do tipo Fogo. Outras opções são Growlithe ou Vulpix, que podem ser evoluídos para Arcanine ou Ninetales com uma Fire Stone comprada no Celadon Mall. Nos jogos Red e Blue, Growlithe aparece no Red e Vulpix no Blue.","Se você escolheu Bulbasaur, Venusaur pode enfrentar Slowbro com golpes de Planta, mas tenha cuidado com os golpes de Gelo da equipe de Lorelei.","Tenha cuidado com Amnesia de Slowbro, que aumenta bastante seu atributo Special, e com Confuse Ray e Blizzard de Lapras, que podem confundir ou congelar seu Pokémon. Cloyster também pode usar Clamp para prender seu adversário.","Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Lorelei, aproveite para recuperar seus Pokémon antes de seguir para Bruno."],"ELITE FOUR - BRUNO":["Bruno é o segundo integrante da Elite Four e usa Pokémon dos tipos Lutador, Pedra e Terra. Seu time começa com Onix no nível 53, seguido de Hitmonchan no nível 55, Hitmonlee no nível 55, outro Onix no nível 56 e Machamp no nível 58.","Os dois Onix são dos tipos Pedra e Terra e recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Hitmonchan, Hitmonlee e Machamp são do tipo Lutador e recebem dano superefetivo de golpes dos tipos Psíquico e Voador.","Se você escolheu Squirtle, use seu Blastoise com Surf contra os dois Onix. Se escolheu Bulbasaur, seu Venusaur pode enfrentá-los com golpes de Planta, como Razor Leaf.","Se você escolheu Charmander, pode usar o Lapras recebido na Silph Company com Surf contra os dois Onix. Outra opção é capturar um Magikarp com a Old Rod, recebida em Vermilion City, e treiná-lo até o nível 20 para evoluí-lo em Gyarados, que também pode aprender Surf.","Contra Hitmonchan, Hitmonlee e Machamp, Kadabra ou Alakazam são boas opções com golpes do tipo Psíquico. Você pode capturar um Abra nas rotas ao norte de Cerulean City ou obtê-lo como prêmio no Game Corner de Celadon. Abra evolui para Kadabra no nível 16 e Kadabra evolui para Alakazam por troca.","Pokémon voadores, como Pidgeot, também podem enfrentar os três lutadores com golpes do tipo Voador. Pidgey pode ser capturado no início da jornada e evolui para Pidgeotto no nível 18 e Pidgeot no nível 36.","Se você escolheu Charmander, ele também pode ajudar nessa parte da batalha depois de evoluir para Charizard. No Pokémon Yellow, você pode ensiná-lo Fly para enfrentar Hitmonchan, Hitmonlee e Machamp.","Tenha cuidado com Ice Punch e ThunderPunch de Hitmonchan, que podem atingir Pokémon voadores com dano superefetivo. Os dois Onix também usam Rock Throw, então mantenha seus voadores longe deles.","O Machamp de Bruno conhece Fissure, um golpe que pode derrotar seu Pokémon em um único acerto. Procure atacá-lo rapidamente com golpes do tipo Psíquico ou Voador antes que ele tenha muitas oportunidades de usá-lo.","Depois da vitória, recupere sua equipe e prepare seus Pokémon para a próxima integrante da Elite Four, Agatha."],"ELITE FOUR - AGATHA":["Agatha é a terceira integrante da Elite Four e usa Pokémon dos tipos Fantasma, Veneno e Voador. Seu time começa com Gengar no nível 56, seguido de Golbat no nível 56, Haunter no nível 55, Arbok no nível 58 e outro Gengar no nível 60.","Todos os Pokémon de Agatha são do tipo Veneno e recebem dano superefetivo de golpes do tipo Psíquico. Golpes do tipo Terra também são eficazes contra os dois Gengar, Haunter e Arbok, mas não atingem Golbat, pois ele também é do tipo Voador.","Kadabra ou Alakazam com Psychic são excelentes opções contra toda a equipe. Você pode capturar um Abra nas rotas ao norte de Cerulean City ou obtê-lo como prêmio no Game Corner de Celadon. Abra evolui para Kadabra no nível 16 e Kadabra evolui para Alakazam por troca.","Outra opção é Starmie com Psychic, que também pode usar golpes do tipo Água contra os Pokémon de Bruno e golpes do tipo Elétrico contra os Pokémon de Lorelei. Staryu pode ser capturado pescando e evolui para Starmie com uma Water Stone. A TM29 Psychic é entregue por Mr. Psychic em Saffron City e pode ser ensinada a Pokémon compatíveis.","Se você treinou um Nidoking ou Nidoqueen, pode usar Earthquake contra Gengar, Haunter e Arbok. Nidoran pode ser encontrado na Route 22 e suas evoluções finais são obtidas ao usar uma Moon Stone em Nidorino ou Nidorina.","Contra Golbat, Pikachu, Raichu ou Jolteon com Thunderbolt também são boas opções, pois seus golpes elétricos são superefetivos contra o tipo Voador.","Tenha cuidado com Hypnosis dos Gengar e de Haunter, que pode colocar seu Pokémon para dormir, e com Dream Eater, que causa dano enquanto ele estiver dormindo. Eles também podem usar Confuse Ray para causar confusão.","Evite usar golpes dos tipos Normal e Lutador contra Gengar e Haunter, pois os dois são imunes a esses ataques. Leve itens para acordar sua equipe e curar outros efeitos de estado antes de enfrentar Agatha.","Depois da vitória, recupere seus Pokémon e prepare sua equipe para o último integrante da Elite Four, Lance."],"CHAMPION":["Depois de vencer a Elite Four, seu último desafio é Blue, seu rival, que chegou à Liga antes de você e se tornou Champion.","Em Pokémon Red e Blue, ele sempre começa com Pidgeot no nível 61, Alakazam no nível 59 e Rhydon no nível 61. Os outros três Pokémon dependem do inicial que você escolheu no começo da jornada.","Se você escolheu Bulbasaur, Blue usa Exeggutor no nível 61, Gyarados no nível 63 e Charizard no nível 65.","Se você escolheu Charmander, ele usa Arcanine no nível 61, Exeggutor no nível 63 e Blastoise no nível 65.","Se você escolheu Squirtle, ele usa Gyarados no nível 61, Arcanine no nível 63 e Venusaur no nível 65.","Contra Pidgeot, use Pikachu, Raichu ou Jolteon com Thunderbolt. Eles também são boas opções contra Gyarados e Blastoise, caso estejam na equipe de Blue. Gyarados recebe quatro vezes mais dano de golpes elétricos por ser dos tipos Água e Voador.","Para enfrentar Rhydon, use Blastoise ou Lapras com Surf, ou Venusaur com golpes de Planta. Rhydon é dos tipos Pedra e Terra e recebe quatro vezes mais dano de golpes desses dois tipos.","Alakazam é rápido e pode causar bastante dano com golpes do tipo Psíquico. Uma opção é usar Snorlax com Body Slam, aproveitando seus muitos pontos de vida e seu ataque físico. Snorlax pode ser encontrado bloqueando a passagem nas Routes 12 e 16 e despertado com a Poké Flute.","Contra Exeggutor ou Venusaur, use Charizard, Arcanine ou Ninetales com golpes de Fogo. Se preferir, Lapras com Ice Beam também pode enfrentar os dois com golpes de Gelo.","Contra Arcanine ou Charizard, use Blastoise ou Lapras com Surf. Golpes elétricos também são eficazes contra Charizard por ele ser do tipo Voador.","Tenha cuidado com Alakazam, que pode usar Recover para recuperar sua vida, e com Rhydon, que conhece Fissure e pode derrotar seu Pokémon em um único acerto.","Depois de derrotar Blue, o Professor Carvalho aparecerá e levará você ao Hall da Fama, onde sua equipe será registrada como a nova Champion de Kanto."],"ELITE FOUR - LANCE":["Lance é o último integrante da Elite Four e usa Pokémon dos tipos Dragão, Água, Voador e Pedra. Seu time começa com Gyarados no nível 58, seguido de dois Dragonair no nível 56, Aerodactyl no nível 60 e Dragonite no nível 62.","Gyarados é dos tipos Água e Voador e recebe quatro vezes mais dano de golpes do tipo Elétrico. Os dois Dragonair são vulneráveis a golpes de Gelo, enquanto Dragonite recebe quatro vezes mais dano desse tipo por também ser Voador. Aerodactyl é vulnerável a golpes dos tipos Água, Elétrico, Gelo e Pedra.","Contra Gyarados, use Pikachu, Raichu ou Jolteon com Thunderbolt. Os três também podem enfrentar Aerodactyl com golpes elétricos.","Para os dois Dragonair e Dragonite, uma ótima opção é o Lapras com Ice Beam. Ele é recebido na Silph Company e aprende Ice Beam no nível 38. Lapras também pode usar Surf contra Aerodactyl.","Se você capturou e treinou Dratini, ele pode ter se tornado um Dragonite no nível 55. Com Ice Beam, ensinado pela TM13, seu Dragonite pode enfrentar os dois Dragonair e o Dragonite de Lance.","Tenha cuidado com Hyper Beam, que toda a equipe de Lance conhece e pode causar muito dano. Nos jogos Red e Blue, se o golpe derrotar seu Pokémon, o adversário não precisará descansar no turno seguinte.","Depois da vitória, recupere sua equipe e prepare seus Pokémon para a última batalha da Liga, contra o Champion."]}'::jsonb WHERE slug IN ('pokemon-blue', 'pokemon-red', 'pokemon-green', 'pokemon-fire-red', 'pokemon-leaf-green');


-- Builds de Johto para Gold, Silver e seus remakes.
UPDATE public.builds SET caps = ARRAY['1º GYM - FALKNER', '2º GYM - BUGSY', '3º GYM - WHITNEY', '4º GYM - MORTY', '5º GYM - CHUCK', '6º GYM - JASMINE', '7º GYM - PRYCE', '8º GYM - CLAIR', 'ELITE FOUR - WILL', 'ELITE FOUR - KOGA', 'ELITE FOUR - BRUNO', 'ELITE FOUR - KAREN', 'CHAMPION'], dicas = dicas || '{"1º GYM - FALKNER":["Falkner usa dois Pokémon dos tipos Normal e Voador. Seu time começa com Pidgey no nível 7 e termina com Pidgeotto no nível 9.","Os dois recebem dano superefetivo de golpes dos tipos Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, capture um Geodude na Dark Cave e treine-o até o nível 11 para aprender Rock Throw. O golpe tem vantagem contra os dois Pokémon de Falkner.","Outra opção é Mareep, que pode ser encontrado na Route 32, ao sul de Violet City, em Gold e Silver. Treine-o e use Thunder Shock contra os dois adversários.","Se você escolheu Chikorita, tenha cuidado com Pidgeotto, pois seu golpe Gust é superefetivo contra Pokémon do tipo Planta. Nesse caso, Geodude ou Mareep são boas opções para a batalha.","Se você escolheu Cyndaquil ou Totodile, também pode usá-los na luta, mas mantenha atenção à vida deles e use Geodude ou Mareep para aproveitar a fraqueza dos adversários.","Tenha cuidado com Mud-Slap, que causa dano e reduz a precisão do seu Pokémon. O golpe é especialmente perigoso para Geodude e Cyndaquil, pois os dois são vulneráveis ao tipo Terra.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"2º GYM - BUGSY":["Bugsy usa três Pokémon do tipo Inseto. Seu time começa com Metapod no nível 14, seguido de Kakuna no nível 14 e termina com Scyther no nível 16.","Os três recebem dano superefetivo de golpes dos tipos Fogo, Voador e Pedra. Scyther também é do tipo Voador, então recebe quatro vezes mais dano de golpes de Pedra.","Se você escolheu Cyndaquil, treine-o até aprender Ember no nível 12 e use o golpe contra toda a equipe de Bugsy. No nível 14, ele evolui para Quilava, ficando ainda mais preparado para a batalha.","Se você escolheu Totodile ou Chikorita, uma boa opção é o Geodude que pode ter sido treinado para enfrentar Falkner. Use Rock Throw contra os três adversários, principalmente Scyther.","Se preferir outro Pokémon, Onix pode ser encontrado na Union Cave ou recebido em troca de um Bellsprout em uma casa de Violet City. Treine-o até aprender Rock Throw no nível 14 para enfrentar a equipe de Bugsy.","Se você escolheu Chikorita, tenha cuidado especial com Scyther. Seu golpe Fury Cutter é superefetivo contra Chikorita e fica mais forte a cada acerto consecutivo.","Mesmo com os outros iniciais, não subestime Fury Cutter. Procure derrotar Scyther rapidamente e mantenha sua equipe com bastante vida. Kakuna também pode envenenar seus Pokémon com Poison Sting.","Antes da batalha, cure sua equipe e leve algumas Potions e Antidotes para se preparar caso precise recuperar seus Pokémon."],"3º GYM - WHITNEY":["Whitney usa dois Pokémon do tipo Normal. Seu time começa com Clefairy no nível 18 e termina com a temida Miltank no nível 20.","As duas recebem dano superefetivo de golpes do tipo Lutador, então essa será a melhor opção para a batalha.","Independentemente do inicial escolhido, capture um Drowzee na Route 34, ao sul de Goldenrod City, e troque-o por um Machop no Goldenrod Department Store. Use os golpes do tipo Lutador de Machop contra Clefairy e Miltank.","O Machop recebido nessa troca é fêmea, então não será afetado pelo Attract da Miltank. Treine-o antes de entrar no ginásio para aumentar suas chances de resistir aos ataques.","Se você treinou Geodude ou Onix para enfrentar os líderes anteriores, eles também podem ajudar contra Miltank. Os dois resistem a Stomp e Rollout, mas ainda podem sofrer bastante dano se Rollout acertar vários turnos seguidos.","Seu inicial também pode participar da batalha, seja Quilava, Croconaw ou Bayleef, mas tenha cuidado ao deixá-lo enfrentar Miltank por muito tempo, principalmente se for macho e for afetado por Attract.","O maior perigo é Rollout, que fica mais forte a cada acerto consecutivo. Miltank também usa Milk Drink para recuperar vida e Stomp, que pode fazer seu Pokémon perder o turno. Já Attract pode impedir Pokémon machos de atacar.","Antes da batalha, cure sua equipe e leve algumas Potions. Procure manter Machop com bastante vida e derrotar Miltank antes que Rollout acumule muito dano."],"4º GYM - MORTY":["Morty usa quatro Pokémon dos tipos Fantasma e Veneno. Seu time começa com Gastly no nível 21, seguido de Haunter no nível 21, Gengar no nível 25 e outro Haunter no nível 23.","Os quatro recebem dano superefetivo de golpes dos tipos Fantasma, Sombrio, Psíquico e Terra. Eles também são imunes a golpes dos tipos Normal e Lutador.","Se você escolheu Totodile, ele já pode ter evoluído para Croconaw. Treine-o até aprender Bite no nível 21 e use o golpe do tipo Sombrio contra toda a equipe de Morty.","Se você escolheu Cyndaquil ou Chikorita, uma opção é capturar um Drowzee na Route 34 e treiná-lo até aprender Confusion no nível 18. O golpe Psíquico é superefetivo contra todos os Pokémon de Morty por causa do tipo Veneno deles.","Se você treinou Geodude ou Onix, também pode usar Magnitude ou outro golpe do tipo Terra que eles conheçam. Em Gold e Silver, Gastly, Haunter e Gengar ainda não possuem a habilidade Levitate, então podem ser atingidos por esses golpes.","Tenha muito cuidado com o Gengar de Morty. Ele pode usar Hypnosis para colocar seu Pokémon para dormir e depois atacar com Dream Eater. Gengar também conhece Shadow Ball, que causa bastante dano e é superefetivo contra Drowzee.","Gastly e um dos Haunter também podem usar Curse, que retira parte da vida do seu Pokémon a cada turno. Se for atingido, troque de Pokémon para remover o efeito.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para acordar seus Pokémon caso sejam atingidos por Hypnosis."],"5º GYM - CHUCK":["Chuck usa dois Pokémon do tipo Lutador. Seu time começa com Primeape no nível 27 e termina com Poliwrath no nível 30, que também é do tipo Água.","Os dois recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Poliwrath também é vulnerável a golpes dos tipos Elétrico e Planta por causa do seu tipo Água.","Se você escolheu Chikorita, ela já pode ter evoluído para Bayleef. Use Razor Leaf contra Poliwrath para aproveitar sua fraqueza ao tipo Planta.","Se você escolheu Cyndaquil ou Totodile, uma opção contra Poliwrath é Flaaffy ou Ampharos com golpes elétricos. Mareep pode ser encontrado na Route 32, evolui para Flaaffy no nível 15 e depois para Ampharos no nível 30.","Independentemente do inicial escolhido, você pode usar Drowzee ou Hypno com Confusion contra os dois Pokémon de Chuck. Drowzee pode ser encontrado na Route 34, aprende Confusion no nível 18 e evolui para Hypno no nível 26.","Se você treinou um Pidgey ou Hoothoot, eles também podem ajudar depois de evoluir para Pidgeotto ou Noctowl. Use golpes do tipo Voador, como Gust ou Peck, contra Primeape e Poliwrath.","Tenha cuidado com Hypnosis de Poliwrath, que pode colocar seu Pokémon para dormir. Ele também pode combinar Mind Reader com DynamicPunch, garantindo o acerto do próximo golpe. DynamicPunch causa bastante dano e deixa o alvo confuso quando acerta.","Antes da batalha, cure sua equipe e leve algumas Potions, Awakenings e itens para curar confusão."],"6º GYM - JASMINE":["Jasmine usa três Pokémon do tipo Aço. Seu time começa com dois Magnemite no nível 30 e termina com Steelix no nível 35.","Os dois Magnemite também são do tipo Elétrico e recebem quatro vezes mais dano de golpes do tipo Terra. Steelix também é do tipo Terra e é vulnerável a golpes dos tipos Água, Fogo, Lutador e Terra.","Se você escolheu Cyndaquil, ele já pode ter evoluído para Quilava. Use seus golpes do tipo Fogo contra os dois Magnemite e Steelix, mas tenha cuidado com o Rock Throw de Steelix.","Se você escolheu Totodile, seu Croconaw pode usar Surf contra Steelix. Evite colocá-lo contra os Magnemite, pois os dois conhecem Thunderbolt e têm vantagem contra Pokémon de Água.","Se você escolheu Chikorita, pode capturar um Tentacool ou Tentacruel enquanto atravessa o mar entre Olivine e Cianwood. Ensine Surf a um deles e use o golpe contra Steelix. Tome cuidado com os Magnemite, pois seus golpes elétricos são superefetivos contra Pokémon de Água.","Independentemente do inicial escolhido, Geodude ou Graveler com Magnitude são boas opções contra toda a equipe. Os golpes do tipo Terra causam quatro vezes mais dano aos Magnemite, e Geodude pode ser encontrado na Dark Cave ou na Union Cave.","O Machop recebido em troca de um Drowzee no Goldenrod Department Store também pode enfrentar os três adversários com golpes do tipo Lutador. Se você o treinou até o nível 28, ele já terá evoluído para Machoke.","Outra opção é Heracross com Rock Smash. Ele pode ser encontrado usando Headbutt em árvores e aprende o golpe Lutador pela TM08, recebida na Route 36 depois de remover Sudowoodo. Rock Smash é superefetivo contra os três Pokémon de Jasmine, mas tem pouca potência, então mantenha atenção à vida de Heracross.","Tenha cuidado com Thunder Wave e Supersonic dos Magnemite, que podem paralisar e confundir sua equipe. Steelix pode usar Screech para reduzir a Defesa do seu Pokémon e depois atacar com Iron Tail ou Rock Throw.","Steelix também pode usar Sunny Day, que fortalece golpes de Fogo e enfraquece golpes de Água. Se isso acontecer, seus golpes de Surf causarão menos dano por alguns turnos.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"7º GYM - PRYCE":["Pryce é especialista no tipo Gelo. Seu time começa com Seel no nível 27, seguido de Dewgong no nível 29 e termina com Piloswine no nível 31. Seel é do tipo Água, Dewgong é dos tipos Água e Gelo, e Piloswine é dos tipos Gelo e Terra.","Seel e Dewgong recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Dewgong também é vulnerável a golpes do tipo Lutador, assim como Piloswine, que também recebe dano superefetivo de golpes dos tipos Água, Fogo e Planta.","Se você escolheu Totodile, seu Croconaw ou Feraligatr pode usar Surf contra Piloswine. Contra Seel e Dewgong, prefira um Pokémon com golpes elétricos ou de Planta.","Se você escolheu Cyndaquil, seu Quilava ou Typhlosion pode usar golpes do tipo Fogo contra Dewgong e Piloswine. Tenha cuidado contra Seel e Dewgong, pois os dois são do tipo Água e resistem aos golpes de Fogo.","Se você escolheu Chikorita, seu Bayleef ou Meganium pode usar golpes de Planta contra os três adversários. Contudo, tenha muito cuidado com os golpes de Gelo da equipe de Pryce, que são superefetivos contra Pokémon de Planta.","Se você treinou Flaaffy ou Ampharos, use seus golpes elétricos contra Seel e Dewgong. Não use esses golpes contra Piloswine, pois ele é do tipo Terra e imune a ataques elétricos.","Heracross com Rock Smash pode enfrentar Dewgong e Piloswine com um golpe do tipo Lutador. Ele pode ser encontrado usando Headbutt nas árvores depois de receber a TM02 na Ilex Forest. A TM08 Rock Smash é recebida na Route 36 depois de capturar ou derrotar Sudowoodo.","Rock Smash tem pouca potência em Gold e Silver, então mantenha atenção à vida de Heracross e não conte com uma vitória rápida. Outra opção é o Machop ou Machoke recebido por troca em Goldenrod, que pode usar golpes Lutadores contra Dewgong e Piloswine.","Tenha cuidado com Icy Wind, que causa dano e reduz a Velocidade, e com Blizzard de Piloswine, que pode causar bastante dano e congelar seu Pokémon. Dewgong também pode usar Rest para recuperar vida.","Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals para se preparar."],"8º GYM - CLAIR":["Clair é especialista no tipo Dragão. Seu time começa com três Dragonair no nível 37 e termina com Kingdra no nível 40, que é dos tipos Água e Dragão.","Os três Dragonair recebem dano superefetivo de golpes dos tipos Gelo e Dragão. Kingdra, por ser dos tipos Água e Dragão, recebe dano superefetivo apenas de golpes do tipo Dragão em Gold e Silver.","Independentemente do inicial escolhido, uma ótima opção contra os três Dragonair é Lapras com Ice Beam. Ele pode ser encontrado no andar mais profundo da Union Cave às sextas-feiras, depois que você conseguir usar Surf, e aprende Ice Beam no nível 36.","Se você capturou o Gyarados vermelho no Lake of Rage, pode treiná-lo até aprender Twister no nível 35. O golpe do tipo Dragão é superefetivo contra toda a equipe de Clair, incluindo Kingdra, mas tenha cuidado com o Dragonair que conhece Thunderbolt.","Seu inicial também pode ajudar contra Kingdra com golpes que causem bastante dano. Seja Typhlosion, Feraligatr ou Meganium, mantenha atenção à vida dele e prepare outro Pokémon caso precise trocar durante a batalha.","Tenha cuidado com os três Dragonair, pois cada um conhece um golpe diferente entre Surf, Thunderbolt e Ice Beam. Os três também podem usar Thunder Wave para paralisar sua equipe.","O Kingdra de Clair pode usar Smokescreen para reduzir a precisão dos seus golpes e DragonBreath, que também pode causar paralisia. Ele conhece Hyper Beam, um golpe muito forte que exige um turno de descanso depois de ser usado.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals. Se a precisão do seu Pokémon cair muito, considere trocá-lo para remover a redução antes de continuar atacando."],"ELITE FOUR - WILL":["Will é o primeiro integrante da Elite Four e usa Pokémon do tipo Psíquico. Seu time começa com Xatu no nível 40, seguido de Jynx no nível 41, Exeggutor no nível 41, Slowbro no nível 41 e outro Xatu no nível 42.","Todos recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma. Os dois Xatu e Slowbro também são vulneráveis ao tipo Elétrico, enquanto Jynx e Exeggutor são vulneráveis ao tipo Fogo.","Independentemente do inicial escolhido, Umbreon com Shadow Ball é uma boa opção contra toda a equipe. Para obtê-lo, encontre Bill no Pokémon Center de Ecruteak e depois visite sua casa em Goldenrod para receber um Eevee. Aumente a amizade de Eevee e faça-o subir de nível durante a noite para evoluí-lo em Umbreon.","A TM30 Shadow Ball é recebida ao derrotar Morty e pode ser ensinada a Umbreon. Por ser do tipo Sombrio, ele também é imune aos golpes Psíquicos da equipe de Will.","O Gyarados vermelho, encontrado no Lake of Rage, também pode enfrentar os cinco adversários com Bite, caso ainda conheça o golpe. Tenha cuidado com o Ice Punch de Jynx e mantenha a vida de Gyarados alta durante a luta.","Se você treinou Flaaffy ou Ampharos, use seus golpes elétricos contra os dois Xatu e Slowbro. Mareep pode ser encontrado na Route 32 e evolui para Flaaffy no nível 15 e Ampharos no nível 30.","Se você escolheu Cyndaquil, seu Typhlosion pode usar golpes de Fogo contra Jynx e Exeggutor. Caso tenha escolhido Totodile ou Chikorita, outro Pokémon com golpes de Fogo também pode enfrentar os dois.","Se você capturou Lapras na Union Cave, ele pode usar Ice Beam contra os dois Xatu e Exeggutor. Lapras aprende o golpe no nível 36, mas tenha cuidado com os ataques Psíquicos e com a confusão causada por Xatu.","Tenha cuidado com Lovely Kiss de Jynx, que pode colocar seu Pokémon para dormir, e com Confuse Ray dos Xatu. Slowbro também pode usar Amnesia para aumentar sua Defesa Especial e resistir melhor a golpes como Thunderbolt e Bite.","Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Will, aproveite para recuperar seus Pokémon antes de seguir para Koga."],"ELITE FOUR - KOGA":["Koga é o segundo integrante da Elite Four e usa principalmente Pokémon dos tipos Veneno e Inseto. Seu time começa com Ariados no nível 40, seguido de Venomoth no nível 41, Forretress no nível 43, Muk no nível 42 e Crobat no nível 44.","Ariados, Venomoth, Muk e Crobat recebem dano superefetivo de golpes do tipo Psíquico. Forretress é dos tipos Inseto e Aço e recebe quatro vezes mais dano de golpes do tipo Fogo.","Se você escolheu Cyndaquil, seu Typhlosion pode usar golpes de Fogo contra Ariados, Venomoth e Forretress. Procure derrotar Forretress rapidamente para evitar que ele use Explosion.","Se você escolheu Totodile ou Chikorita, também pode preparar um Pokémon com golpes de Fogo para enfrentar esses três adversários. Contra Forretress, essa é a opção que mais aproveita sua fraqueza.","Drowzee ou Hypno com Confusion podem enfrentar Ariados, Venomoth, Muk e Crobat. Drowzee pode ser capturado na Route 34, aprende Confusion no nível 18 e evolui para Hypno no nível 26. Tenha cuidado com Psychic de Venomoth, que também pode causar bastante dano ao seu Pokémon Psíquico.","Se você capturou Geodude e o evoluiu para Graveler, pode usar golpes do tipo Terra, como Magnitude, contra Muk. Evite esses golpes contra Crobat, pois ele também é do tipo Voador e não pode ser atingido por ataques de Terra.","Para enfrentar Crobat, você também pode usar Ampharos com golpes elétricos ou Lapras com Ice Beam. Os dois golpes são superefetivos por causa do tipo Voador de Crobat.","Tenha muito cuidado com Explosion de Forretress, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Venomoth, Muk e Crobat também podem usar Toxic, que envenena gravemente e causa cada vez mais dano a cada turno.","Antes da batalha, cure sua equipe e prepare Potions e Antidotes. Depois de vencer Koga, aproveite para recuperar seus Pokémon antes de seguir para Bruno."],"ELITE FOUR - BRUNO":["Bruno é o terceiro integrante da Elite Four e usa principalmente Pokémon do tipo Lutador. Seu time começa com Hitmontop no nível 42, seguido de Hitmonlee no nível 42, Hitmonchan no nível 42, Onix no nível 43 e Machamp no nível 46.","Hitmontop, Hitmonlee, Hitmonchan e Machamp recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Onix é dos tipos Pedra e Terra e recebe quatro vezes mais dano de golpes dos tipos Água e Planta.","Independentemente do inicial escolhido, Drowzee ou Hypno com Confusion podem enfrentar os quatro Pokémon Lutadores. Drowzee pode ser capturado na Route 34 e evolui para Hypno no nível 26.","Se você recebeu o Eevee de Bill e o evoluiu para Espeon, ele também é uma boa opção contra os quatro Lutadores com Psybeam, aprendido no nível 36. Para obter Espeon, aumente a amizade de Eevee e faça-o subir de nível durante o dia.","Pokémon voadores, como Pidgeot ou Noctowl, também podem usar golpes do tipo Voador contra os Lutadores. Tenha cuidado ao enfrentar Hitmonchan e Machamp, pois eles conhecem golpes que são superefetivos contra Pokémon voadores.","Se você escolheu Totodile, use seu Feraligatr com Surf contra Onix. Se escolheu Chikorita, seu Meganium pode enfrentá-lo com golpes do tipo Planta, como Razor Leaf.","Se você escolheu Cyndaquil, pode usar Lapras ou Gyarados com Surf contra Onix. Lapras pode ser encontrado na Union Cave às sextas-feiras, enquanto o Gyarados vermelho pode ser capturado no Lake of Rage.","Tenha cuidado com Ice Punch e ThunderPunch de Hitmonchan e com Rock Slide de Machamp, que podem causar bastante dano aos seus Pokémon voadores. Hitmontop também conhece Pursuit, um golpe do tipo Sombrio que pode atingir seus Pokémon Psíquicos com vantagem.","O golpe Cross Chop de Machamp causa bastante dano e tem uma chance maior de acerto crítico, então mantenha seu Pokémon com bastante vida ao enfrentá-lo.","Depois da vitória, recupere sua equipe e prepare seus Pokémon para a próxima integrante da Elite Four, Karen."],"ELITE FOUR - KAREN":["Karen é a última integrante da Elite Four e usa principalmente Pokémon do tipo Sombrio. Seu time começa com Umbreon no nível 42, seguido de Vileplume no nível 42, Gengar no nível 45, Murkrow no nível 44 e Houndoom no nível 47.","Umbreon e Houndoom recebem dano superefetivo de golpes do tipo Lutador. Vileplume é vulnerável aos tipos Fogo, Gelo, Voador e Psíquico, enquanto Gengar recebe dano superefetivo de golpes dos tipos Terra, Psíquico, Fantasma e Sombrio. Murkrow é vulnerável aos tipos Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, você pode usar Machoke ou Heracross com golpes do tipo Lutador contra Umbreon. Machop pode ser recebido em troca de um Drowzee no Goldenrod Department Store e evolui para Machoke no nível 28.","Heracross pode ser encontrado usando Headbutt nas árvores e aprender Rock Smash pela TM08. Ele também tem vantagem contra Houndoom com esse golpe, mas tenha muito cuidado, pois Houndoom conhece Flamethrower, que causa quatro vezes mais dano a Heracross por ele ser dos tipos Inseto e Lutador.","Se você escolheu Cyndaquil, seu Typhlosion pode usar golpes do tipo Fogo contra Vileplume. Outra opção é Lapras com Ice Beam, que também pode enfrentar Murkrow com golpes de Gelo.","Contra Gengar, você pode usar Hypno com Confusion ou Graveler com Magnitude. Drowzee pode ser capturado na Route 34 e evolui para Hypno no nível 26, enquanto Geodude pode ser encontrado na Dark Cave ou Union Cave e evolui para Graveler no nível 25.","Para enfrentar Murkrow, use Ampharos com golpes elétricos. Mareep pode ser encontrado na Route 32 e evolui para Flaaffy no nível 15 e Ampharos no nível 30.","Contra Houndoom, Feraligatr, Lapras ou Gyarados com Surf são boas opções. Se você escolheu Cyndaquil ou Chikorita, Lapras pode ser encontrado na Union Cave às sextas-feiras e o Gyarados vermelho pode ser capturado no Lake of Rage.","Tenha muito cuidado com Destiny Bond de Gengar. Se ele usar o golpe e for derrotado antes de realizar sua próxima ação, também levará seu Pokémon junto. Nessa situação, use um golpe que não cause dano e espere Gengar agir novamente antes de atacá-lo.","Umbreon também pode usar Confuse Ray e Mean Look para confundir seu Pokémon e impedir que ele seja trocado. Já Houndoom conhece Flamethrower e Crunch, dois golpes fortes que podem causar bastante dano.","Depois da vitória, recupere sua equipe e prepare seus Pokémon para a última batalha da Liga, contra o Champion Lance."],"CHAMPION":["Lance é o Champion da Liga e especialista no tipo Dragão. Seu time começa com Gyarados no nível 44, seguido de dois Dragonite no nível 47, Aerodactyl no nível 46, Charizard no nível 46 e outro Dragonite no nível 50.","Gyarados recebe quatro vezes mais dano de golpes do tipo Elétrico, enquanto os três Dragonite recebem quatro vezes mais dano de golpes do tipo Gelo. Charizard recebe quatro vezes mais dano de golpes do tipo Pedra, e Aerodactyl é vulnerável aos tipos Água, Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, Ampharos com golpes elétricos é uma ótima opção contra Gyarados. Ele também pode enfrentar Aerodactyl e Charizard, que recebem dano superefetivo do tipo Elétrico.","Contra os três Dragonite, uma ótima opção é Lapras com Ice Beam. Ele pode ser encontrado no andar mais profundo da Union Cave às sextas-feiras e aprende Ice Beam no nível 36.","Outra opção é Piloswine com golpes de Gelo. Você pode capturar um Swinub na Ice Path e treiná-lo até o nível 33 para evoluí-lo. Por também ser do tipo Terra, Piloswine é imune ao Thunder de um dos Dragonite, mas deve tomar cuidado com o Fire Blast do Dragonite de nível 50.","Se você escolheu Totodile, seu Feraligatr com Surf pode enfrentar Aerodactyl e Charizard. Se escolheu outro inicial, Lapras ou Gyarados com Surf também podem usar a fraqueza dos dois ao tipo Água.","Se você treinou Graveler ou Golem, eles podem usar golpes de Pedra contra Charizard, que recebe quatro vezes mais dano desse tipo. Também podem enfrentar Aerodactyl, mas tenha cuidado com os ataques dele e mantenha sua vida alta.","Os três Dragonite conhecem golpes diferentes. Um dos que estão no nível 47 usa Thunder, o outro usa Blizzard, enquanto o Dragonite no nível 50 conhece Fire Blast e Outrage. Tome cuidado especialmente com Thunder se estiver usando Lapras ou outro Pokémon de Água.","Todos os Pokémon de Lance conhecem Hyper Beam, um golpe muito forte que exige um turno de descanso depois de ser usado. Aproveite esse momento para atacar ou recuperar sua equipe.","Depois de derrotar Lance, o Professor Carvalho aparecerá e levará você ao Hall da Fama, onde sua equipe será registrada como Champion."]}'::jsonb WHERE slug IN ('pokemon-gold', 'pokemon-silver', 'pokemon-heart-gold', 'pokemon-soul-silver');


-- Builds revisadas de Hoenn para os jogos originais.
UPDATE public.builds SET caps = ARRAY['1º GYM - ROXANNE', '2º GYM - BRAWLY', '3º GYM - WATTSON', '4º GYM - FLANNERY', '5º GYM - NORMAN', '6º GYM - WINONA', '7º GYM - TATE E LIZA', '8º GYM - WALLACE', 'ELITE FOUR - SIDNEY', 'ELITE FOUR - PHOEBE', 'ELITE FOUR - GLACIA', 'ELITE FOUR - DRAKE', 'CHAMPION'], dicas = dicas || '{"1º GYM - ROXANNE":["Roxanne é especialista no tipo Pedra. Em Ruby e Sapphire, ela usa Geodude no nível 14 e Nosepass no nível 15.","Em Emerald, sua equipe tem dois Geodude no nível 12 e um Nosepass no nível 15.","Geodude também é do tipo Terra e recebe quatro vezes mais dano de golpes dos tipos Água e Planta. Nosepass é vulnerável a esses dois tipos, além de golpes dos tipos Lutador e Terra.","Se você escolheu Mudkip, treine-o até aprender Water Gun no nível 10 e use o golpe contra toda a equipe de Roxanne.","Se você escolheu Treecko, use Absorb, que ele aprende no nível 6. O golpe tem vantagem contra todos os adversários e ainda recupera parte da vida de Treecko.","Se você escolheu Torchic, uma opção é capturar um Shroomish na Petalburg Woods e usar Absorb contra os Pokémon de Roxanne.","Outra opção para quem escolheu Torchic é treiná-lo até o nível 16, quando evolui para Combusken e pode aprender Double Kick. O golpe do tipo Lutador é superefetivo contra toda a equipe de Roxanne.","Tenha cuidado com Rock Tomb, principalmente se estiver usando Torchic ou Combusken. O golpe é superefetivo contra Pokémon de Fogo e também reduz a Velocidade do alvo.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"2º GYM - BRAWLY":["Brawly é especialista no tipo Lutador. Em Ruby e Sapphire, ele usa Machop no nível 17 e Makuhita no nível 18.","Em Emerald, seu time começa com Machop no nível 16, seguido de Meditite no nível 16 e Makuhita no nível 19.","Machop e Makuhita recebem dano superefetivo de golpes dos tipos Voador e Psíquico. Meditite também é do tipo Psíquico, então golpes Psíquicos causam dano normal nele, mas golpes do tipo Voador continuam sendo superefetivos.","Independentemente do inicial escolhido, você pode capturar um Taillow na Route 104 e usar seus golpes do tipo Voador contra toda a equipe de Brawly.","Outra opção é Wingull, que também pode ser encontrado na Route 104. Treine-o até aprender Wing Attack no nível 13 e use o golpe contra os adversários.","Se você capturou um Ralts na Route 102, treine-o e use Confusion contra Machop e Makuhita. Para enfrentar o Meditite de Emerald, prefira Taillow ou Wingull para aproveitar a fraqueza ao tipo Voador.","Se você escolheu Torchic, ele já pode ter evoluído para Combusken. Tenha cuidado ao usá-lo, pois ele também é do tipo Lutador e pode sofrer bastante dano dos adversários de Brawly.","Se você escolheu Treecko ou Mudkip, seus iniciais podem ajudar durante a batalha, mas Taillow, Wingull ou Ralts terão golpes com vantagem contra parte da equipe.","Tenha cuidado com Bulk Up, que aumenta o Ataque e a Defesa do adversário. Procure não prolongar a batalha, principalmente contra Makuhita, para que ele não acumule vários aumentos.","Em Emerald, Meditite também pode usar Reflect e Light Screen para reduzir o dano recebido pela equipe. Além disso, cuidado com Focus Punch, um golpe forte que pode falhar se você atingir Meditite antes de ele atacar.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"3º GYM - WATTSON":["Wattson é especialista no tipo Elétrico. Em Ruby e Sapphire, seu time começa com Magnemite no nível 22, seguido de Voltorb no nível 20 e Magneton no nível 23.","Em Emerald, ele usa Voltorb no nível 20, Electrike no nível 20, Magneton no nível 22 e Manectric no nível 24.","Todos recebem dano superefetivo de golpes do tipo Terra. Magnemite e Magneton também são do tipo Aço, então recebem quatro vezes mais dano desses golpes. Pokémon do tipo Terra também são imunes aos golpes elétricos da equipe de Wattson.","Se você escolheu Mudkip, treine-o até evoluir para Marshtomp no nível 16 e aprender Mud Shot. Por ser dos tipos Água e Terra, Marshtomp é imune aos golpes elétricos e pode usar Mud Shot contra toda a equipe de Wattson.","Se você escolheu Treecko ou Torchic, pode capturar um Geodude na Granite Cave, em Dewford. Treine-o até aprender Magnitude no nível 16 e use o golpe contra os adversários de Wattson.","Se você escolheu Torchic e já o evoluiu para Combusken, ele pode usar Double Kick contra Magnemite e Magneton, que também são vulneráveis ao tipo Lutador. Seus golpes de Fogo também têm vantagem contra os dois, mas mantenha cuidado com os ataques elétricos.","Se você escolheu Treecko, ele já pode ter evoluído para Grovyle. Ele resiste a golpes elétricos, mas não causa dano superefetivo com ataques de Planta, então Geodude será uma opção melhor para aproveitar a fraqueza da equipe.","Tenha muito cuidado com Selfdestruct de Voltorb, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Pokémon do tipo Terra são imunes aos golpes elétricos, mas ainda podem ser atingidos por essa explosão.","Magnemite e Magneton também podem usar SonicBoom, que causa sempre 20 pontos de dano, além de Supersonic, que confunde seu Pokémon. Mantenha a vida da equipe alta durante a batalha.","Antes de enfrentar Wattson, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"4º GYM - FLANNERY":["Flannery é especialista no tipo Fogo. Em Ruby e Sapphire, ela usa dois Slugma no nível 26 e um Torkoal no nível 28.","Em Emerald, seu time começa com Numel no nível 24, seguido de Slugma no nível 24, Camerupt no nível 26 e Torkoal no nível 29.","Todos recebem dano superefetivo de golpes dos tipos Água e Terra. Numel e Camerupt também são do tipo Terra, então recebem quatro vezes mais dano de golpes de Água. Slugma e Torkoal também são vulneráveis ao tipo Pedra.","Se você escolheu Mudkip, seu Marshtomp pode usar golpes de Água contra toda a equipe. Em Emerald, aproveite principalmente a fraqueza de Numel e Camerupt.","Se você escolheu Treecko ou Torchic, uma opção é Wingull, encontrado na Route 104. Ele pode usar Water Gun contra toda a equipe e já pode ter ajudado na batalha contra Brawly.","Outra opção é Marill, que pode ser encontrado na Route 117. Treine-o até o nível 18 para evoluí-lo em Azumarill e use seus golpes de Água contra os Pokémon de Flannery.","Se você capturou Geodude na Granite Cave para enfrentar Wattson, ele já pode ter evoluído para Graveler. Use Magnitude contra toda a equipe ou golpes de Pedra contra Slugma e Torkoal.","Você também pode capturar um Numel na Route 112 e treiná-lo até aprender Magnitude no nível 19. Seus golpes do tipo Terra são superefetivos contra todos os Pokémon de Flannery.","Tenha cuidado com Overheat, um golpe de Fogo muito forte. Depois de usá-lo, o Ataque Especial do adversário diminui, mas em Emerald o Torkoal segura uma White Herb, que remove essa redução uma vez.","A equipe de Flannery também pode usar Sunny Day, que fortalece golpes de Fogo e enfraquece golpes de Água por alguns turnos. Mantenha atenção à vida da equipe, mesmo quando estiver usando um Pokémon com vantagem.","Antes da batalha, cure seus Pokémon e leve algumas Potions e Burn Heals para se preparar."],"5º GYM - NORMAN":["Norman é especialista no tipo Normal. Em Ruby e Sapphire, seu time começa com Slaking no nível 28, seguido de Vigoroth no nível 30 e outro Slaking no nível 31.","Em Emerald, ele usa Spinda no nível 27, Vigoroth no nível 27, Linoone no nível 29 e Slaking no nível 31. Todos recebem dano superefetivo de golpes do tipo Lutador.","Se você escolheu Torchic, seu Combusken pode usar Double Kick contra toda a equipe. Mantenha atenção à vida dele, pois os ataques de Slaking podem causar bastante dano.","Se você escolheu Treecko ou Mudkip, pode capturar um Makuhita na Granite Cave e usar seus golpes do tipo Lutador. Ele evolui para Hariyama no nível 24 e pode enfrentar todos os Pokémon de Norman.","Outra opção é o Shroomish que pode ter ajudado contra Roxanne. Treine-o até evoluir para Breloom no nível 23, quando pode aprender Mach Punch, um golpe do tipo Lutador que ataca com prioridade.","Se você capturou Aron na Granite Cave, ele pode ajudar a resistir aos golpes do tipo Normal da equipe de Norman, incluindo Facade. Mas, em Ruby e Sapphire, tenha muito cuidado com o Focus Punch do Slaking de nível 31, que causa quatro vezes mais dano a Aron.","Em Sapphire e Emerald, você também pode capturar Sableye na Granite Cave. Por ser do tipo Fantasma, ele é imune aos golpes Normais, mas não está totalmente protegido, pois os Pokémon de Norman conhecem Faint Attack, que pode atingi-lo.","Os Slaking possuem a habilidade Truant, que os faz descansar no turno seguinte ao que agem. Aproveite esses turnos para atacar ou recuperar sua equipe. Vigoroth não possui essa habilidade e pode agir em todos os turnos.","Tenha cuidado com Facade, que fica mais forte se o usuário estiver envenenado, paralisado ou queimado. Em Emerald, Slaking também conhece Counter, que pode devolver o dobro do dano recebido de um golpe físico.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings, pois Slaking também pode usar Yawn para fazer seu Pokémon dormir."],"6º GYM - WINONA":["Winona é especialista no tipo Voador. Em Ruby e Sapphire, ela usa Swellow no nível 31, Pelipper no nível 30, Skarmory no nível 32 e Altaria no nível 33.","Em Emerald, seu time tem Swablu no nível 29, Tropius no nível 29, Pelipper no nível 30, Skarmory no nível 31 e Altaria no nível 33.","Pelipper recebe quatro vezes mais dano de golpes elétricos. Já Altaria recebe quatro vezes mais dano de Gelo, assim como Tropius em Emerald. Swellow, Swablu e Pelipper também são vulneráveis a golpes de Pedra.","Se você treinou Electrike ou Manectric, use golpes elétricos contra Swellow, Swablu, Pelipper e Skarmory, conforme os adversários da sua versão. Electrike pode ser encontrado na Route 110 e evolui para Manectric no nível 26.","Outra opção elétrica é Magnemite ou Magneton. Depois de vencer Norman e obter Surf, converse com Wattson em Mauville para acessar New Mauville, onde Magnemite pode ser capturado. Ele evolui para Magneton no nível 30 e pode enfrentar os mesmos adversários com golpes elétricos.","Se você capturou Aron na Granite Cave, ele já pode ter evoluído para Lairon no nível 32. Os dois resistem bastante aos golpes Voadores e podem usar golpes de Pedra contra Swellow, Swablu, Tropius e Altaria. Porém, cuidado com Pelipper, cujos golpes de Água causam quatro vezes mais dano a eles.","O Geodude ou Graveler que pode ter ajudado contra Wattson e Flannery também pode usar golpes de Pedra contra esses voadores. Assim como Aron e Lairon, ele precisa tomar cuidado com a Água de Pelipper.","Para enfrentar Altaria, uma opção é o Castform recebido no Weather Institute. Treine-o até aprender Weather Ball no nível 30 e use Hail antes do ataque para transformar Weather Ball em um golpe de Gelo. A estratégia também funciona contra Tropius em Emerald.","Se você escolheu Torchic, seu Combusken pode usar golpes de Fogo contra Skarmory e Tropius. Tenha cuidado com os golpes Voadores, que são superefetivos contra ele por também ser do tipo Lutador.","O maior perigo é Altaria, que usa Dragon Dance para aumentar seu Ataque e Velocidade e conhece Earthquake. O golpe causa quatro vezes mais dano a Aron e Lairon e também é perigoso para Manectric, Magneton e Combusken.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals, pois Dragon Breath de Altaria pode causar paralisia."],"7º GYM - TATE E LIZA":["Tate e Liza são especialistas no tipo Psíquico e enfrentam você em uma batalha dupla, então prepare dois Pokémon para lutar ao mesmo tempo.","Em Ruby e Sapphire, eles usam Lunatone e Solrock no nível 42. Em Emerald, começam com Claydol e Xatu no nível 41, além de Lunatone e Solrock no nível 42.","Todos recebem dano superefetivo de golpes do tipo Sombrio. Lunatone, Solrock e Claydol também são vulneráveis aos tipos Água e Planta, enquanto Xatu recebe dano superefetivo de golpes dos tipos Elétrico e Gelo.","Independentemente do inicial escolhido, Mightyena com Bite pode enfrentar toda a equipe. Poochyena pode ser encontrado no início da jornada, aprende Bite no nível 13 e evolui para Mightyena no nível 18. Por ser do tipo Sombrio, Mightyena também é imune aos golpes Psíquicos dos adversários.","Outra opção é Sharpedo, dos tipos Água e Sombrio. Você pode pescar um Carvanha com a Good Rod na Route 118 e treiná-lo até o nível 30 para evoluí-lo. Sharpedo pode usar golpes Sombrio contra toda a equipe e golpes de Água contra Lunatone, Solrock e Claydol.","Se você capturou Seedot, ele já pode ter evoluído para Nuzleaf ou Shiftry. Use Faint Attack contra toda a equipe de Tate e Liza. Nuzleaf aprende o golpe no nível 31, então ensine-o antes de usar uma Leaf Stone para evoluí-lo em Shiftry. Por também serem do tipo Sombrio, os dois são imunes aos golpes Psíquicos dos adversários. Em Ruby e Emerald, Seedot pode ser encontrado na Route 102; em Sapphire, precisa ser obtido por troca.","Se você capturou Trapinch no deserto da Route 111, treine-o até aprender Crunch no nível 33 e evoluir para Vibrava no nível 35. Crunch é superefetivo contra toda a equipe de Tate e Liza, e a habilidade Levitate de Vibrava também o protege do Earthquake de Claydol em Emerald.","Em Sapphire e Emerald, Sableye é outra opção. Ele pode ser capturado na Granite Cave e usar Faint Attack, aprendido no nível 29, contra os adversários. Por ser do tipo Sombrio, Sableye também é imune a golpes Psíquicos.","Se você escolheu Mudkip, seu Marshtomp ou Swampert pode usar Surf contra Lunatone, Solrock e Claydol. Nos jogos de GBA, Surf atinge os dois adversários na batalha dupla.","Se você escolheu Treecko, seu Grovyle ou Sceptile pode usar golpes de Planta contra Lunatone, Solrock e Claydol. Se escolheu Torchic, você pode usar um Pokémon de Água, como Pelipper ou Azumarill, para ajudar contra os três.","Tenha cuidado com Sunny Day de Solrock, que enfraquece golpes de Água e permite que ele use Solar Beam sem esperar um turno para carregar. O golpe de Planta é especialmente perigoso para Marshtomp e Swampert, que recebem quatro vezes mais dano dele.","Em Emerald, Claydol conhece Earthquake, que atinge os outros Pokémon em campo. Xatu e os dois Pokémon com Levitate, Lunatone e Solrock, não são atingidos, mas seus Pokémon podem sofrer dano.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings, pois Lunatone pode usar Hypnosis para colocar seus Pokémon para dormir."],"ELITE FOUR - SIDNEY":["Sidney é o primeiro integrante da Elite Four e especialista no tipo Sombrio. Em Ruby e Sapphire, seu time tem Mightyena no nível 46, Shiftry no nível 48, Cacturne no nível 46, Sharpedo no nível 48 e Absol no nível 49.","Em Emerald, Sidney usa a mesma equipe, mas troca Sharpedo por um Crawdaunt no nível 48.","Todos recebem dano superefetivo de golpes do tipo Lutador. Shiftry e Cacturne também são do tipo Planta, então recebem quatro vezes mais dano de golpes do tipo Inseto. Sharpedo e Crawdaunt são dos tipos Água e Sombrio e também são vulneráveis a golpes Elétricos e de Planta.","Se você escolheu Torchic, seu Blaziken pode usar golpes Lutadores contra toda a equipe. Seus golpes de Fogo também são superefetivos contra Shiftry e Cacturne.","Tenha cuidado ao usar Blaziken contra Sharpedo ou Crawdaunt, pois os dois conhecem Surf. Shiftry também conhece Extrasensory, e Absol conhece Aerial Ace, golpes que têm vantagem contra Pokémon Lutadores.","Se você treinou Makuhita desde a Granite Cave, seu Hariyama pode enfrentar toda a equipe com golpes do tipo Lutador. Ele é uma opção mesmo que você tenha escolhido Treecko ou Mudkip.","O Shroomish que pode ter ajudado contra Roxanne também pode participar. Seu Breloom com Mach Punch tem vantagem contra toda a equipe, mas deve tomar cuidado com Extrasensory de Shiftry e Aerial Ace de Absol.","Outra opção é Heracross, que pode ser capturado na Safari Zone. Seus golpes Lutadores são superefetivos contra toda a equipe, e golpes do tipo Inseto causam quatro vezes mais dano a Shiftry e Cacturne. Mantenha-o longe de Aerial Ace de Absol, que causa quatro vezes mais dano a ele.","Se você treinou Manectric ou Magneton para enfrentar Winona e o último ginásio, use seus golpes elétricos contra Sharpedo em Ruby e Sapphire ou Crawdaunt em Emerald.","Contra Shiftry e Cacturne, você também pode usar um Pokémon com golpes do tipo Voador, como o Swellow que pode ter acompanhado você desde a Route 104.","Tenha cuidado com Swords Dance de Absol, que aumenta bastante seu Ataque, e com Sand Attack de Mightyena, que reduz a precisão dos seus golpes.","Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Sidney, aproveite para recuperar seus Pokémon antes de seguir para Phoebe."],"ELITE FOUR - PHOEBE":["Phoebe é a segunda integrante da Elite Four e especialista no tipo Fantasma. Em Ruby, Sapphire e Emerald, seu time começa com Dusclops no nível 48, seguido de Banette no nível 49, Sableye no nível 50, outro Banette no nível 49 e outro Dusclops no nível 51. Os golpes de alguns deles mudam conforme a versão.","Os dois Dusclops e os dois Banette recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma. Sableye é dos tipos Sombrio e Fantasma e não possui fraqueza de tipo nesses jogos, pois o tipo Fada ainda não existia.","Se você treinou Poochyena, seu Mightyena pode usar Bite ou Crunch contra os dois Dusclops e os dois Banette. Poochyena pode ser encontrado no início da jornada e evolui para Mightyena no nível 18.","Se você capturou Carvanha na Route 118, seu Sharpedo também pode usar golpes Sombrios contra esses quatro adversários. Ele também pode usar Surf contra Sableye, causando dano normal.","Em Sapphire e Emerald, você pode usar o Sableye capturado na Granite Cave. Seus golpes Sombrio e Fantasma têm vantagem contra Dusclops e Banette, mas tenha cuidado, pois os golpes Fantasmas dos adversários também são superefetivos contra ele.","Se você treinou Seedot em Ruby ou Emerald, seu Nuzleaf ou Shiftry com Faint Attack também pode enfrentar os dois Dusclops e os dois Banette. Nuzleaf aprende o golpe no nível 31, antes de evoluir para Shiftry com uma Leaf Stone.","O Trapinch capturado no deserto da Route 111 também pode ajudar. Se você ensinou Crunch a ele no nível 33, seu Vibrava ou Flygon pode usar o golpe contra Dusclops e Banette. Em Emerald, porém, tome muito cuidado com o Ice Beam do Dusclops de nível 51, que causa quatro vezes mais dano a Vibrava e Flygon.","Contra Sableye, use um golpe forte que cause dano normal, como Surf de Swampert, Pelipper ou Sharpedo, ou um golpe de Fogo de Blaziken. Não use golpes dos tipos Normal ou Lutador, pois Sableye e os outros fantasmas são imunes a eles.","Tenha cuidado com Confuse Ray e Curse do primeiro Dusclops. Banette também pode usar Will-O-Wisp para queimar seu Pokémon, além de Grudge, que pode esgotar os PP do golpe usado para derrotá-lo.","Em Emerald, o último Dusclops conhece Ice Beam, Earthquake e Rock Slide, então escolha com cuidado qual Pokémon ficará em campo contra ele.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Glacia, a próxima integrante da Elite Four."],"ELITE FOUR - GLACIA":["Glacia é a terceira integrante da Elite Four e especialista no tipo Gelo. Nas três versões, ela usa dois Glalie, nos níveis 50 e 52, dois Sealeo, nos níveis 50 e 52, e um Walrein no nível 53.","Em Ruby e Sapphire, ela começa a batalha com Glalie. Em Emerald, começa com Sealeo. Alguns golpes também mudam entre as versões.","Os dois Glalie recebem dano superefetivo de golpes dos tipos Fogo, Lutador, Pedra e Aço. Sealeo e Walrein também são do tipo Água, então são vulneráveis a golpes dos tipos Elétrico, Planta, Lutador e Pedra.","Se você escolheu Torchic, seu Blaziken pode usar golpes do tipo Lutador contra toda a equipe. Contra os dois Glalie, seus golpes de Fogo também têm vantagem. Tenha cuidado contra Sealeo e Walrein, pois os dois podem usar golpes de Água.","Se você treinou Makuhita desde a Granite Cave, seu Hariyama também pode usar golpes Lutadores contra todos os Pokémon de Glacia.","O Breloom que pode ter acompanhado você desde a Petalburg Woods também possui vantagem com golpes Lutadores. Porém, ele é do tipo Planta e recebe dano superefetivo dos golpes de Gelo de toda a equipe, então mantenha bastante atenção à vida dele.","Se você treinou Electrike ou Manectric, use seus golpes elétricos contra os dois Sealeo e Walrein. Magneton, que pode ser obtido a partir de um Magnemite capturado em New Mauville, também pode enfrentar os três com ataques elétricos.","Se você treinou Aron desde a Granite Cave, seu Lairon ou Aggron pode usar golpes de Pedra ou Aço contra os dois Glalie. Tenha cuidado contra Sealeo e Walrein, pois os golpes de Água deles são superefetivos contra a linha de Aron.","Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Sealeo e Walrein, mas tome muito cuidado com os golpes de Gelo. Se escolheu Mudkip, seu Swampert pode ajudar com golpes que não sejam de Água ou Gelo, mas as outras opções aproveitam melhor as fraquezas da equipe de Glacia.","Tenha muito cuidado com Sheer Cold de Walrein, que pode derrotar seu Pokémon em um único acerto. Se o seu Pokémon estiver acima do nível 53, o golpe falhará contra ele.","Em Emerald, o Glalie de nível 52 conhece Explosion, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Procure derrotá-lo rapidamente e mantenha a vida da equipe alta.","Depois da vitória, cure seus Pokémon e prepare a equipe para Drake, o último integrante da Elite Four."],"ELITE FOUR - DRAKE":["Drake é o último integrante da Elite Four e especialista no tipo Dragão. Em Ruby e Sapphire, seu time começa com Shelgon no nível 52, seguido de Altaria no nível 54, dois Flygon no nível 53 e Salamence no nível 55.","Em Emerald, ele usa a mesma equipe, mas troca um dos Flygon por um Kingdra no nível 53. Depois de Drake, o Champion é Steven em Ruby e Sapphire e Wallace em Emerald.","Shelgon recebe dano superefetivo de golpes do tipo Gelo. Altaria, Flygon e Salamence recebem quatro vezes mais dano desse tipo. Já Kingdra é dos tipos Água e Dragão, então não é vulnerável a golpes de Gelo e recebe dano superefetivo apenas do tipo Dragão nesses jogos.","Independentemente do inicial escolhido, Sealeo ou Walrein com Aurora Beam são boas opções contra Shelgon, Altaria, Flygon e Salamence. Você pode capturar um Spheal na Shoal Cave, ao norte de Mossdeep City. Ele evolui para Sealeo no nível 32 e para Walrein no nível 44.","Se preferir um golpe de Gelo mais forte, você pode ensinar Ice Beam pela TM13 a um Pokémon compatível, como Walrein ou Swampert. A TM pode ser obtida na Abandoned Ship, usando Surf e Dive, ou como prêmio no Game Corner de Mauville.","O Castform recebido no Weather Institute também pode enfrentar Shelgon, Altaria, Flygon e Salamence. Use Hail e depois Weather Ball para atacar com um golpe do tipo Gelo.","Se você treinou o Trapinch capturado no deserto, seu Vibrava ou Flygon com Dragon Breath pode enfrentar os dragões de Drake, incluindo Kingdra em Emerald. Mas tenha cuidado, pois seus próprios Pokémon Dragões também recebem dano superefetivo dos golpes desse tipo.","Se você escolheu Mudkip, seu Swampert pode usar Ice Beam contra os dragões vulneráveis a Gelo. Se escolheu Treecko ou Torchic, Sealeo, Walrein ou Castform são opções que não dependem do inicial escolhido.","Tenha cuidado com Dragon Dance de Altaria, que aumenta seu Ataque e Velocidade. Em Emerald, Kingdra também conhece Dragon Dance e pode usar Smokescreen para reduzir a precisão dos seus golpes.","O Salamence de Drake conhece Dragon Claw e Flamethrower, além de golpes que variam entre as versões. Procure manter seu Pokémon com bastante vida e aproveitar a fraqueza de quatro vezes a Gelo.","Depois da vitória, recupere toda a equipe e prepare seus Pokémon para a última batalha da Liga, contra o Champion."],"8º GYM - WALLACE":["Wallace é especialista no tipo Água. Seu time começa com Luvdisc no nível 40, seguido de Whiscash no nível 42, Sealeo no nível 40, Seaking no nível 42 e Milotic no nível 43.","Luvdisc, Sealeo, Seaking e Milotic recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Whiscash também é do tipo Terra, então é imune a golpes elétricos e recebe quatro vezes mais dano de golpes de Planta.","Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra toda a equipe. Contra Whiscash, aproveite a fraqueza de quatro vezes, mas tenha cuidado com Aurora Beam de Sealeo e Ice Beam de Milotic.","Se você treinou Electrike ou Manectric, use seus golpes elétricos contra Luvdisc, Sealeo, Seaking e Milotic. Evite usar ataques elétricos contra Whiscash.","Magnemite ou Magneton, que podem ter ajudado contra Winona, também são boas opções elétricas. Magnemite pode ser encontrado em New Mauville depois que você recebe Surf e a chave de Wattson.","Em Ruby, se você treinou um Seedot, seu Nuzleaf ou Shiftry pode usar golpes de Planta contra a equipe de Wallace. Os dois podem aprender Bullet Seed pela TM09, recebida na Route 104, e são boas opções principalmente contra Whiscash.","Em Sapphire, outra opção é Lotad, encontrado na Route 102. Ele evolui para Lombre no nível 14 e depois para Ludicolo com uma Water Stone. Seus golpes de Planta também podem ajudar contra Whiscash e os demais Pokémon de Água.","Tenha cuidado com Milotic, que pode usar Recover para recuperar vida. Seaking também conhece Horn Drill, que pode derrotar seu Pokémon em um único acerto.","Antes da batalha, cure sua equipe e leve algumas Potions e itens para curar confusão, pois Luvdisc pode usar Sweet Kiss e os Pokémon de Wallace conhecem Water Pulse."],"CHAMPION":["Steven é o Champion de Hoenn em Pokémon Ruby e Sapphire. Embora seja conhecido pelos Pokémon do tipo Aço, sua equipe também inclui Pokémon dos tipos Pedra, Terra e Psíquico.","Seu time começa com Skarmory no nível 57, seguido de Claydol no nível 55, Aggron no nível 56, Cradily no nível 56, Armaldo no nível 56 e Metagross no nível 58.","Skarmory é vulnerável aos tipos Fogo e Elétrico. Aggron recebe quatro vezes mais dano dos tipos Lutador e Terra, enquanto Metagross é vulnerável a Fogo e Terra.","Claydol pode ser enfrentado com golpes de Água, Planta, Gelo, Inseto, Fantasma ou Sombrio. Cradily é vulnerável aos tipos Gelo, Lutador, Inseto e Aço, e Armaldo recebe dano superefetivo dos tipos Água, Pedra e Aço.","Se você escolheu Torchic, seu Blaziken pode usar golpes de Fogo contra Skarmory e Metagross e golpes Lutadores contra Aggron e Cradily. Tenha cuidado com Psychic de Metagross, que é superefetivo contra Blaziken por ele também ser do tipo Lutador.","Se você escolheu Mudkip, seu Swampert com Surf pode enfrentar Claydol, Aggron e Armaldo. Swampert também pode usar Earthquake contra Aggron e Metagross, mas não contra Claydol, pois ele possui a habilidade Levitate.","Tenha muito cuidado ao usar Swampert contra Aggron, que conhece Solar Beam. O golpe de Planta causa quatro vezes mais dano a Swampert. Se Aggron começar a carregar Solar Beam, aproveite para atacar ou trocar de Pokémon.","Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Claydol. Contra o restante da equipe, procure aproveitar os outros Pokémon que você treinou durante a jornada.","Manectric ou Magneton são boas opções contra Skarmory, usando golpes elétricos. Os dois podem ter ajudado anteriormente contra Winona, mas devem tomar cuidado com os golpes do tipo Terra de Aggron e Metagross.","Se você treinou Makuhita, seu Hariyama com golpes Lutadores pode enfrentar Aggron e Cradily. O Breloom que pode ter acompanhado você desde a Petalburg Woods também pode usar golpes Lutadores contra os dois.","O Trapinch capturado no deserto já pode ter evoluído para Flygon. Seus golpes do tipo Terra podem ser usados contra Aggron e Metagross. Por possuir Levitate, Flygon também fica imune aos golpes Earthquake dos dois, mas precisa tomar cuidado com Dragon Claw de Aggron.","Para enfrentar Armaldo, você pode usar Pelipper, Sharpedo ou Azumarill com golpes de Água, além de Swampert. Se você treinou Aron até Aggron, seus golpes do tipo Aço também têm vantagem contra Armaldo e Cradily.","Tenha cuidado com Spikes de Skarmory, que causa dano aos Pokémon atingidos pelo efeito quando entram em campo, e com Reflect e Light Screen de Claydol, que reduzem o dano recebido pela equipe de Steven.","O maior desafio é Metagross. Ele conhece Meteor Mash, Earthquake, Psychic e Hyper Beam, então mantenha seu Pokémon com bastante vida e aproveite suas fraquezas a golpes de Fogo ou Terra.","Depois de derrotar Steven, você e sua equipe serão registrados no Hall da Fama como os novos Champions de Hoenn."]}'::jsonb WHERE slug IN ('pokemon-ruby', 'pokemon-sapphire');
UPDATE public.builds SET caps = ARRAY['1º GYM - ROXANNE', '2º GYM - BRAWLY', '3º GYM - WATTSON', '4º GYM - FLANNERY', '5º GYM - NORMAN', '6º GYM - WINONA', '7º GYM - TATE E LIZA', '8º GYM - JUAN', 'ELITE FOUR - SIDNEY', 'ELITE FOUR - PHOEBE', 'ELITE FOUR - GLACIA', 'ELITE FOUR - DRAKE', 'CHAMPION'], dicas = dicas || '{"1º GYM - ROXANNE":["Roxanne é especialista no tipo Pedra. Em Ruby e Sapphire, ela usa Geodude no nível 14 e Nosepass no nível 15.","Em Emerald, sua equipe tem dois Geodude no nível 12 e um Nosepass no nível 15.","Geodude também é do tipo Terra e recebe quatro vezes mais dano de golpes dos tipos Água e Planta. Nosepass é vulnerável a esses dois tipos, além de golpes dos tipos Lutador e Terra.","Se você escolheu Mudkip, treine-o até aprender Water Gun no nível 10 e use o golpe contra toda a equipe de Roxanne.","Se você escolheu Treecko, use Absorb, que ele aprende no nível 6. O golpe tem vantagem contra todos os adversários e ainda recupera parte da vida de Treecko.","Se você escolheu Torchic, uma opção é capturar um Shroomish na Petalburg Woods e usar Absorb contra os Pokémon de Roxanne.","Outra opção para quem escolheu Torchic é treiná-lo até o nível 16, quando evolui para Combusken e pode aprender Double Kick. O golpe do tipo Lutador é superefetivo contra toda a equipe de Roxanne.","Tenha cuidado com Rock Tomb, principalmente se estiver usando Torchic ou Combusken. O golpe é superefetivo contra Pokémon de Fogo e também reduz a Velocidade do alvo.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"2º GYM - BRAWLY":["Brawly é especialista no tipo Lutador. Em Ruby e Sapphire, ele usa Machop no nível 17 e Makuhita no nível 18.","Em Emerald, seu time começa com Machop no nível 16, seguido de Meditite no nível 16 e Makuhita no nível 19.","Machop e Makuhita recebem dano superefetivo de golpes dos tipos Voador e Psíquico. Meditite também é do tipo Psíquico, então golpes Psíquicos causam dano normal nele, mas golpes do tipo Voador continuam sendo superefetivos.","Independentemente do inicial escolhido, você pode capturar um Taillow na Route 104 e usar seus golpes do tipo Voador contra toda a equipe de Brawly.","Outra opção é Wingull, que também pode ser encontrado na Route 104. Treine-o até aprender Wing Attack no nível 13 e use o golpe contra os adversários.","Se você capturou um Ralts na Route 102, treine-o e use Confusion contra Machop e Makuhita. Para enfrentar o Meditite de Emerald, prefira Taillow ou Wingull para aproveitar a fraqueza ao tipo Voador.","Se você escolheu Torchic, ele já pode ter evoluído para Combusken. Tenha cuidado ao usá-lo, pois ele também é do tipo Lutador e pode sofrer bastante dano dos adversários de Brawly.","Se você escolheu Treecko ou Mudkip, seus iniciais podem ajudar durante a batalha, mas Taillow, Wingull ou Ralts terão golpes com vantagem contra parte da equipe.","Tenha cuidado com Bulk Up, que aumenta o Ataque e a Defesa do adversário. Procure não prolongar a batalha, principalmente contra Makuhita, para que ele não acumule vários aumentos.","Em Emerald, Meditite também pode usar Reflect e Light Screen para reduzir o dano recebido pela equipe. Além disso, cuidado com Focus Punch, um golpe forte que pode falhar se você atingir Meditite antes de ele atacar.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"3º GYM - WATTSON":["Wattson é especialista no tipo Elétrico. Em Ruby e Sapphire, seu time começa com Magnemite no nível 22, seguido de Voltorb no nível 20 e Magneton no nível 23.","Em Emerald, ele usa Voltorb no nível 20, Electrike no nível 20, Magneton no nível 22 e Manectric no nível 24.","Todos recebem dano superefetivo de golpes do tipo Terra. Magnemite e Magneton também são do tipo Aço, então recebem quatro vezes mais dano desses golpes. Pokémon do tipo Terra também são imunes aos golpes elétricos da equipe de Wattson.","Se você escolheu Mudkip, treine-o até evoluir para Marshtomp no nível 16 e aprender Mud Shot. Por ser dos tipos Água e Terra, Marshtomp é imune aos golpes elétricos e pode usar Mud Shot contra toda a equipe de Wattson.","Se você escolheu Treecko ou Torchic, pode capturar um Geodude na Granite Cave, em Dewford. Treine-o até aprender Magnitude no nível 16 e use o golpe contra os adversários de Wattson.","Se você escolheu Torchic e já o evoluiu para Combusken, ele pode usar Double Kick contra Magnemite e Magneton, que também são vulneráveis ao tipo Lutador. Seus golpes de Fogo também têm vantagem contra os dois, mas mantenha cuidado com os ataques elétricos.","Se você escolheu Treecko, ele já pode ter evoluído para Grovyle. Ele resiste a golpes elétricos, mas não causa dano superefetivo com ataques de Planta, então Geodude será uma opção melhor para aproveitar a fraqueza da equipe.","Tenha muito cuidado com Selfdestruct de Voltorb, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Pokémon do tipo Terra são imunes aos golpes elétricos, mas ainda podem ser atingidos por essa explosão.","Magnemite e Magneton também podem usar SonicBoom, que causa sempre 20 pontos de dano, além de Supersonic, que confunde seu Pokémon. Mantenha a vida da equipe alta durante a batalha.","Antes de enfrentar Wattson, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"4º GYM - FLANNERY":["Flannery é especialista no tipo Fogo. Em Ruby e Sapphire, ela usa dois Slugma no nível 26 e um Torkoal no nível 28.","Em Emerald, seu time começa com Numel no nível 24, seguido de Slugma no nível 24, Camerupt no nível 26 e Torkoal no nível 29.","Todos recebem dano superefetivo de golpes dos tipos Água e Terra. Numel e Camerupt também são do tipo Terra, então recebem quatro vezes mais dano de golpes de Água. Slugma e Torkoal também são vulneráveis ao tipo Pedra.","Se você escolheu Mudkip, seu Marshtomp pode usar golpes de Água contra toda a equipe. Em Emerald, aproveite principalmente a fraqueza de Numel e Camerupt.","Se você escolheu Treecko ou Torchic, uma opção é Wingull, encontrado na Route 104. Ele pode usar Water Gun contra toda a equipe e já pode ter ajudado na batalha contra Brawly.","Outra opção é Marill, que pode ser encontrado na Route 117. Treine-o até o nível 18 para evoluí-lo em Azumarill e use seus golpes de Água contra os Pokémon de Flannery.","Se você capturou Geodude na Granite Cave para enfrentar Wattson, ele já pode ter evoluído para Graveler. Use Magnitude contra toda a equipe ou golpes de Pedra contra Slugma e Torkoal.","Você também pode capturar um Numel na Route 112 e treiná-lo até aprender Magnitude no nível 19. Seus golpes do tipo Terra são superefetivos contra todos os Pokémon de Flannery.","Tenha cuidado com Overheat, um golpe de Fogo muito forte. Depois de usá-lo, o Ataque Especial do adversário diminui, mas em Emerald o Torkoal segura uma White Herb, que remove essa redução uma vez.","A equipe de Flannery também pode usar Sunny Day, que fortalece golpes de Fogo e enfraquece golpes de Água por alguns turnos. Mantenha atenção à vida da equipe, mesmo quando estiver usando um Pokémon com vantagem.","Antes da batalha, cure seus Pokémon e leve algumas Potions e Burn Heals para se preparar."],"5º GYM - NORMAN":["Norman é especialista no tipo Normal. Em Ruby e Sapphire, seu time começa com Slaking no nível 28, seguido de Vigoroth no nível 30 e outro Slaking no nível 31.","Em Emerald, ele usa Spinda no nível 27, Vigoroth no nível 27, Linoone no nível 29 e Slaking no nível 31. Todos recebem dano superefetivo de golpes do tipo Lutador.","Se você escolheu Torchic, seu Combusken pode usar Double Kick contra toda a equipe. Mantenha atenção à vida dele, pois os ataques de Slaking podem causar bastante dano.","Se você escolheu Treecko ou Mudkip, pode capturar um Makuhita na Granite Cave e usar seus golpes do tipo Lutador. Ele evolui para Hariyama no nível 24 e pode enfrentar todos os Pokémon de Norman.","Outra opção é o Shroomish que pode ter ajudado contra Roxanne. Treine-o até evoluir para Breloom no nível 23, quando pode aprender Mach Punch, um golpe do tipo Lutador que ataca com prioridade.","Se você capturou Aron na Granite Cave, ele pode ajudar a resistir aos golpes do tipo Normal da equipe de Norman, incluindo Facade. Mas, em Ruby e Sapphire, tenha muito cuidado com o Focus Punch do Slaking de nível 31, que causa quatro vezes mais dano a Aron.","Em Sapphire e Emerald, você também pode capturar Sableye na Granite Cave. Por ser do tipo Fantasma, ele é imune aos golpes Normais, mas não está totalmente protegido, pois os Pokémon de Norman conhecem Faint Attack, que pode atingi-lo.","Os Slaking possuem a habilidade Truant, que os faz descansar no turno seguinte ao que agem. Aproveite esses turnos para atacar ou recuperar sua equipe. Vigoroth não possui essa habilidade e pode agir em todos os turnos.","Tenha cuidado com Facade, que fica mais forte se o usuário estiver envenenado, paralisado ou queimado. Em Emerald, Slaking também conhece Counter, que pode devolver o dobro do dano recebido de um golpe físico.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings, pois Slaking também pode usar Yawn para fazer seu Pokémon dormir."],"6º GYM - WINONA":["Winona é especialista no tipo Voador. Em Ruby e Sapphire, ela usa Swellow no nível 31, Pelipper no nível 30, Skarmory no nível 32 e Altaria no nível 33.","Em Emerald, seu time tem Swablu no nível 29, Tropius no nível 29, Pelipper no nível 30, Skarmory no nível 31 e Altaria no nível 33.","Pelipper recebe quatro vezes mais dano de golpes elétricos. Já Altaria recebe quatro vezes mais dano de Gelo, assim como Tropius em Emerald. Swellow, Swablu e Pelipper também são vulneráveis a golpes de Pedra.","Se você treinou Electrike ou Manectric, use golpes elétricos contra Swellow, Swablu, Pelipper e Skarmory, conforme os adversários da sua versão. Electrike pode ser encontrado na Route 110 e evolui para Manectric no nível 26.","Outra opção elétrica é Magnemite ou Magneton. Depois de vencer Norman e obter Surf, converse com Wattson em Mauville para acessar New Mauville, onde Magnemite pode ser capturado. Ele evolui para Magneton no nível 30 e pode enfrentar os mesmos adversários com golpes elétricos.","Se você capturou Aron na Granite Cave, ele já pode ter evoluído para Lairon no nível 32. Os dois resistem bastante aos golpes Voadores e podem usar golpes de Pedra contra Swellow, Swablu, Tropius e Altaria. Porém, cuidado com Pelipper, cujos golpes de Água causam quatro vezes mais dano a eles.","O Geodude ou Graveler que pode ter ajudado contra Wattson e Flannery também pode usar golpes de Pedra contra esses voadores. Assim como Aron e Lairon, ele precisa tomar cuidado com a Água de Pelipper.","Para enfrentar Altaria, uma opção é o Castform recebido no Weather Institute. Treine-o até aprender Weather Ball no nível 30 e use Hail antes do ataque para transformar Weather Ball em um golpe de Gelo. A estratégia também funciona contra Tropius em Emerald.","Se você escolheu Torchic, seu Combusken pode usar golpes de Fogo contra Skarmory e Tropius. Tenha cuidado com os golpes Voadores, que são superefetivos contra ele por também ser do tipo Lutador.","O maior perigo é Altaria, que usa Dragon Dance para aumentar seu Ataque e Velocidade e conhece Earthquake. O golpe causa quatro vezes mais dano a Aron e Lairon e também é perigoso para Manectric, Magneton e Combusken.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals, pois Dragon Breath de Altaria pode causar paralisia."],"7º GYM - TATE E LIZA":["Tate e Liza são especialistas no tipo Psíquico e enfrentam você em uma batalha dupla, então prepare dois Pokémon para lutar ao mesmo tempo.","Em Ruby e Sapphire, eles usam Lunatone e Solrock no nível 42. Em Emerald, começam com Claydol e Xatu no nível 41, além de Lunatone e Solrock no nível 42.","Todos recebem dano superefetivo de golpes do tipo Sombrio. Lunatone, Solrock e Claydol também são vulneráveis aos tipos Água e Planta, enquanto Xatu recebe dano superefetivo de golpes dos tipos Elétrico e Gelo.","Independentemente do inicial escolhido, Mightyena com Bite pode enfrentar toda a equipe. Poochyena pode ser encontrado no início da jornada, aprende Bite no nível 13 e evolui para Mightyena no nível 18. Por ser do tipo Sombrio, Mightyena também é imune aos golpes Psíquicos dos adversários.","Outra opção é Sharpedo, dos tipos Água e Sombrio. Você pode pescar um Carvanha com a Good Rod na Route 118 e treiná-lo até o nível 30 para evoluí-lo. Sharpedo pode usar golpes Sombrio contra toda a equipe e golpes de Água contra Lunatone, Solrock e Claydol.","Se você capturou Seedot, ele já pode ter evoluído para Nuzleaf ou Shiftry. Use Faint Attack contra toda a equipe de Tate e Liza. Nuzleaf aprende o golpe no nível 31, então ensine-o antes de usar uma Leaf Stone para evoluí-lo em Shiftry. Por também serem do tipo Sombrio, os dois são imunes aos golpes Psíquicos dos adversários. Em Ruby e Emerald, Seedot pode ser encontrado na Route 102; em Sapphire, precisa ser obtido por troca.","Se você capturou Trapinch no deserto da Route 111, treine-o até aprender Crunch no nível 33 e evoluir para Vibrava no nível 35. Crunch é superefetivo contra toda a equipe de Tate e Liza, e a habilidade Levitate de Vibrava também o protege do Earthquake de Claydol em Emerald.","Em Sapphire e Emerald, Sableye é outra opção. Ele pode ser capturado na Granite Cave e usar Faint Attack, aprendido no nível 29, contra os adversários. Por ser do tipo Sombrio, Sableye também é imune a golpes Psíquicos.","Se você escolheu Mudkip, seu Marshtomp ou Swampert pode usar Surf contra Lunatone, Solrock e Claydol. Nos jogos de GBA, Surf atinge os dois adversários na batalha dupla.","Se você escolheu Treecko, seu Grovyle ou Sceptile pode usar golpes de Planta contra Lunatone, Solrock e Claydol. Se escolheu Torchic, você pode usar um Pokémon de Água, como Pelipper ou Azumarill, para ajudar contra os três.","Tenha cuidado com Sunny Day de Solrock, que enfraquece golpes de Água e permite que ele use Solar Beam sem esperar um turno para carregar. O golpe de Planta é especialmente perigoso para Marshtomp e Swampert, que recebem quatro vezes mais dano dele.","Em Emerald, Claydol conhece Earthquake, que atinge os outros Pokémon em campo. Xatu e os dois Pokémon com Levitate, Lunatone e Solrock, não são atingidos, mas seus Pokémon podem sofrer dano.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings, pois Lunatone pode usar Hypnosis para colocar seus Pokémon para dormir."],"ELITE FOUR - SIDNEY":["Sidney é o primeiro integrante da Elite Four e especialista no tipo Sombrio. Em Ruby e Sapphire, seu time tem Mightyena no nível 46, Shiftry no nível 48, Cacturne no nível 46, Sharpedo no nível 48 e Absol no nível 49.","Em Emerald, Sidney usa a mesma equipe, mas troca Sharpedo por um Crawdaunt no nível 48.","Todos recebem dano superefetivo de golpes do tipo Lutador. Shiftry e Cacturne também são do tipo Planta, então recebem quatro vezes mais dano de golpes do tipo Inseto. Sharpedo e Crawdaunt são dos tipos Água e Sombrio e também são vulneráveis a golpes Elétricos e de Planta.","Se você escolheu Torchic, seu Blaziken pode usar golpes Lutadores contra toda a equipe. Seus golpes de Fogo também são superefetivos contra Shiftry e Cacturne.","Tenha cuidado ao usar Blaziken contra Sharpedo ou Crawdaunt, pois os dois conhecem Surf. Shiftry também conhece Extrasensory, e Absol conhece Aerial Ace, golpes que têm vantagem contra Pokémon Lutadores.","Se você treinou Makuhita desde a Granite Cave, seu Hariyama pode enfrentar toda a equipe com golpes do tipo Lutador. Ele é uma opção mesmo que você tenha escolhido Treecko ou Mudkip.","O Shroomish que pode ter ajudado contra Roxanne também pode participar. Seu Breloom com Mach Punch tem vantagem contra toda a equipe, mas deve tomar cuidado com Extrasensory de Shiftry e Aerial Ace de Absol.","Outra opção é Heracross, que pode ser capturado na Safari Zone. Seus golpes Lutadores são superefetivos contra toda a equipe, e golpes do tipo Inseto causam quatro vezes mais dano a Shiftry e Cacturne. Mantenha-o longe de Aerial Ace de Absol, que causa quatro vezes mais dano a ele.","Se você treinou Manectric ou Magneton para enfrentar Winona e o último ginásio, use seus golpes elétricos contra Sharpedo em Ruby e Sapphire ou Crawdaunt em Emerald.","Contra Shiftry e Cacturne, você também pode usar um Pokémon com golpes do tipo Voador, como o Swellow que pode ter acompanhado você desde a Route 104.","Tenha cuidado com Swords Dance de Absol, que aumenta bastante seu Ataque, e com Sand Attack de Mightyena, que reduz a precisão dos seus golpes.","Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Sidney, aproveite para recuperar seus Pokémon antes de seguir para Phoebe."],"ELITE FOUR - PHOEBE":["Phoebe é a segunda integrante da Elite Four e especialista no tipo Fantasma. Em Ruby, Sapphire e Emerald, seu time começa com Dusclops no nível 48, seguido de Banette no nível 49, Sableye no nível 50, outro Banette no nível 49 e outro Dusclops no nível 51. Os golpes de alguns deles mudam conforme a versão.","Os dois Dusclops e os dois Banette recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma. Sableye é dos tipos Sombrio e Fantasma e não possui fraqueza de tipo nesses jogos, pois o tipo Fada ainda não existia.","Se você treinou Poochyena, seu Mightyena pode usar Bite ou Crunch contra os dois Dusclops e os dois Banette. Poochyena pode ser encontrado no início da jornada e evolui para Mightyena no nível 18.","Se você capturou Carvanha na Route 118, seu Sharpedo também pode usar golpes Sombrios contra esses quatro adversários. Ele também pode usar Surf contra Sableye, causando dano normal.","Em Sapphire e Emerald, você pode usar o Sableye capturado na Granite Cave. Seus golpes Sombrio e Fantasma têm vantagem contra Dusclops e Banette, mas tenha cuidado, pois os golpes Fantasmas dos adversários também são superefetivos contra ele.","Se você treinou Seedot em Ruby ou Emerald, seu Nuzleaf ou Shiftry com Faint Attack também pode enfrentar os dois Dusclops e os dois Banette. Nuzleaf aprende o golpe no nível 31, antes de evoluir para Shiftry com uma Leaf Stone.","O Trapinch capturado no deserto da Route 111 também pode ajudar. Se você ensinou Crunch a ele no nível 33, seu Vibrava ou Flygon pode usar o golpe contra Dusclops e Banette. Em Emerald, porém, tome muito cuidado com o Ice Beam do Dusclops de nível 51, que causa quatro vezes mais dano a Vibrava e Flygon.","Contra Sableye, use um golpe forte que cause dano normal, como Surf de Swampert, Pelipper ou Sharpedo, ou um golpe de Fogo de Blaziken. Não use golpes dos tipos Normal ou Lutador, pois Sableye e os outros fantasmas são imunes a eles.","Tenha cuidado com Confuse Ray e Curse do primeiro Dusclops. Banette também pode usar Will-O-Wisp para queimar seu Pokémon, além de Grudge, que pode esgotar os PP do golpe usado para derrotá-lo.","Em Emerald, o último Dusclops conhece Ice Beam, Earthquake e Rock Slide, então escolha com cuidado qual Pokémon ficará em campo contra ele.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Glacia, a próxima integrante da Elite Four."],"ELITE FOUR - GLACIA":["Glacia é a terceira integrante da Elite Four e especialista no tipo Gelo. Nas três versões, ela usa dois Glalie, nos níveis 50 e 52, dois Sealeo, nos níveis 50 e 52, e um Walrein no nível 53.","Em Ruby e Sapphire, ela começa a batalha com Glalie. Em Emerald, começa com Sealeo. Alguns golpes também mudam entre as versões.","Os dois Glalie recebem dano superefetivo de golpes dos tipos Fogo, Lutador, Pedra e Aço. Sealeo e Walrein também são do tipo Água, então são vulneráveis a golpes dos tipos Elétrico, Planta, Lutador e Pedra.","Se você escolheu Torchic, seu Blaziken pode usar golpes do tipo Lutador contra toda a equipe. Contra os dois Glalie, seus golpes de Fogo também têm vantagem. Tenha cuidado contra Sealeo e Walrein, pois os dois podem usar golpes de Água.","Se você treinou Makuhita desde a Granite Cave, seu Hariyama também pode usar golpes Lutadores contra todos os Pokémon de Glacia.","O Breloom que pode ter acompanhado você desde a Petalburg Woods também possui vantagem com golpes Lutadores. Porém, ele é do tipo Planta e recebe dano superefetivo dos golpes de Gelo de toda a equipe, então mantenha bastante atenção à vida dele.","Se você treinou Electrike ou Manectric, use seus golpes elétricos contra os dois Sealeo e Walrein. Magneton, que pode ser obtido a partir de um Magnemite capturado em New Mauville, também pode enfrentar os três com ataques elétricos.","Se você treinou Aron desde a Granite Cave, seu Lairon ou Aggron pode usar golpes de Pedra ou Aço contra os dois Glalie. Tenha cuidado contra Sealeo e Walrein, pois os golpes de Água deles são superefetivos contra a linha de Aron.","Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Sealeo e Walrein, mas tome muito cuidado com os golpes de Gelo. Se escolheu Mudkip, seu Swampert pode ajudar com golpes que não sejam de Água ou Gelo, mas as outras opções aproveitam melhor as fraquezas da equipe de Glacia.","Tenha muito cuidado com Sheer Cold de Walrein, que pode derrotar seu Pokémon em um único acerto. Se o seu Pokémon estiver acima do nível 53, o golpe falhará contra ele.","Em Emerald, o Glalie de nível 52 conhece Explosion, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Procure derrotá-lo rapidamente e mantenha a vida da equipe alta.","Depois da vitória, cure seus Pokémon e prepare a equipe para Drake, o último integrante da Elite Four."],"ELITE FOUR - DRAKE":["Drake é o último integrante da Elite Four e especialista no tipo Dragão. Em Ruby e Sapphire, seu time começa com Shelgon no nível 52, seguido de Altaria no nível 54, dois Flygon no nível 53 e Salamence no nível 55.","Em Emerald, ele usa a mesma equipe, mas troca um dos Flygon por um Kingdra no nível 53. Depois de Drake, o Champion é Steven em Ruby e Sapphire e Wallace em Emerald.","Shelgon recebe dano superefetivo de golpes do tipo Gelo. Altaria, Flygon e Salamence recebem quatro vezes mais dano desse tipo. Já Kingdra é dos tipos Água e Dragão, então não é vulnerável a golpes de Gelo e recebe dano superefetivo apenas do tipo Dragão nesses jogos.","Independentemente do inicial escolhido, Sealeo ou Walrein com Aurora Beam são boas opções contra Shelgon, Altaria, Flygon e Salamence. Você pode capturar um Spheal na Shoal Cave, ao norte de Mossdeep City. Ele evolui para Sealeo no nível 32 e para Walrein no nível 44.","Se preferir um golpe de Gelo mais forte, você pode ensinar Ice Beam pela TM13 a um Pokémon compatível, como Walrein ou Swampert. A TM pode ser obtida na Abandoned Ship, usando Surf e Dive, ou como prêmio no Game Corner de Mauville.","O Castform recebido no Weather Institute também pode enfrentar Shelgon, Altaria, Flygon e Salamence. Use Hail e depois Weather Ball para atacar com um golpe do tipo Gelo.","Se você treinou o Trapinch capturado no deserto, seu Vibrava ou Flygon com Dragon Breath pode enfrentar os dragões de Drake, incluindo Kingdra em Emerald. Mas tenha cuidado, pois seus próprios Pokémon Dragões também recebem dano superefetivo dos golpes desse tipo.","Se você escolheu Mudkip, seu Swampert pode usar Ice Beam contra os dragões vulneráveis a Gelo. Se escolheu Treecko ou Torchic, Sealeo, Walrein ou Castform são opções que não dependem do inicial escolhido.","Tenha cuidado com Dragon Dance de Altaria, que aumenta seu Ataque e Velocidade. Em Emerald, Kingdra também conhece Dragon Dance e pode usar Smokescreen para reduzir a precisão dos seus golpes.","O Salamence de Drake conhece Dragon Claw e Flamethrower, além de golpes que variam entre as versões. Procure manter seu Pokémon com bastante vida e aproveitar a fraqueza de quatro vezes a Gelo.","Depois da vitória, recupere toda a equipe e prepare seus Pokémon para a última batalha da Liga, contra o Champion."],"8º GYM - JUAN":["Juan é especialista no tipo Água. Seu time começa com Luvdisc no nível 41, seguido de Whiscash no nível 41, Sealeo no nível 43, Crawdaunt no nível 43 e Kingdra no nível 46.","Luvdisc, Sealeo e Crawdaunt recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Whiscash é imune a golpes elétricos e recebe quatro vezes mais dano de Planta. Já Kingdra é dos tipos Água e Dragão e, em Emerald, recebe dano superefetivo apenas de golpes do tipo Dragão.","Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Luvdisc, Whiscash, Sealeo e Crawdaunt. Tenha cuidado com Aurora Beam de Sealeo e Ice Beam de Kingdra, que são perigosos para Pokémon de Planta.","Se você treinou Manectric ou Magneton, use seus golpes elétricos contra Luvdisc, Sealeo e Crawdaunt. Não use esses golpes contra Whiscash, pois ele é do tipo Terra e imune a ataques elétricos.","Se você capturou Seedot na Route 102, seu Nuzleaf ou Shiftry com Bullet Seed pode ajudar contra Whiscash e os outros Pokémon vulneráveis a Planta. Outra opção é Ludicolo, obtido a partir de Lotad, que também pode ser encontrado na Route 102.","Se você treinou o Trapinch do deserto, ele já pode ter evoluído para Vibrava ou Flygon. Use Dragon Breath contra Kingdra para aproveitar sua fraqueza ao tipo Dragão, mas tenha muito cuidado com Ice Beam, que causa quatro vezes mais dano a Vibrava e Flygon.","O Kingdra de Juan pode usar Double Team para aumentar sua evasão e Rest para recuperar vida. Ele segura uma Chesto Berry, que o acorda na primeira vez que usar Rest.","Antes da batalha, cure sua equipe e leve algumas Potions e itens para curar confusão, pois os Pokémon de Juan podem usar Water Pulse e Sweet Kiss."]}'::jsonb WHERE slug IN ('pokemon-emerald');


-- Champion de Pokémon Emerald.
UPDATE public.builds SET dicas = jsonb_set(dicas, ARRAY['CHAMPION'], '["Wallace é o Champion de Hoenn em Pokémon Emerald e especialista no tipo Água. Seu time começa com Wailord no nível 57, seguido de Tentacruel no nível 55, Ludicolo no nível 56, Whiscash no nível 56, Gyarados no nível 56 e Milotic no nível 58.","Wailord, Tentacruel e Milotic recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Gyarados também é do tipo Voador e recebe quatro vezes mais dano de golpes elétricos.","Whiscash é dos tipos Água e Terra, então é imune a golpes elétricos e recebe quatro vezes mais dano de Planta. Ludicolo é dos tipos Água e Planta e é vulnerável aos tipos Voador, Inseto e Veneno.","Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Wailord, Whiscash e Milotic. Contra Whiscash, aproveite a fraqueza de quatro vezes, mas tenha cuidado com Blizzard de Wailord e Ice Beam de Milotic.","Se você treinou Electrike ou Manectric, use seus golpes elétricos contra Wailord, Tentacruel, Gyarados e Milotic. Eles podem ter acompanhado você desde a Route 110 e ajudado contra Winona e Juan.","Outra opção elétrica é Magneton, que pode ser obtido ao capturar Magnemite em New Mauville e treiná-lo até o nível 30. Tenha muito cuidado contra Whiscash e Gyarados, pois os dois conhecem Earthquake, que causa quatro vezes mais dano a Magneton.","Contra Ludicolo, você pode usar Swellow com golpes Voadores ou Crobat, caso tenha treinado um Zubat capturado na Granite Cave. Tenha cuidado se a chuva estiver ativa, pois Ludicolo pode ficar mais rápido.","Se você capturou Seedot, seu Nuzleaf ou Shiftry com Bullet Seed pode enfrentar Whiscash e os outros adversários vulneráveis a Planta. Tenha cuidado com os golpes de Gelo de Wailord, Tentacruel e Milotic, que são superefetivos contra eles.","O Breloom que pode ter acompanhado você desde a Petalburg Woods também pode usar golpes de Planta contra Whiscash, mas deve evitar os Pokémon que conhecem golpes de Gelo.","Tenha cuidado com Rain Dance de Wailord, que fortalece os golpes de Água, e com Dragon Dance de Gyarados, que aumenta seu Ataque e Velocidade. Ludicolo também pode usar Double Team e Leech Seed, dificultando seus ataques e recuperando vida ao longo da batalha.","O maior desafio é Milotic, que conhece Surf, Ice Beam, Toxic e Recover. Procure manter sua equipe saudável e usar golpes elétricos fortes para não deixar a batalha se prolongar.","Depois de derrotar Wallace, você e sua equipe serão registrados no Hall da Fama como os novos Champions de Hoenn."]'::jsonb, true) WHERE slug = 'pokemon-emerald';


-- Lucian e Cynthia de Sinnoh.
UPDATE public.builds SET caps = CASE WHEN cardinality(caps) = 0 THEN ARRAY['1º GYM - ROARK', '2º GYM - GARDENIA', '3º GYM - MAYLENE', '4º GYM - CRASHER WAKE', '5º GYM - FANTINA', '6º GYM - BYRON', '7º GYM - CANDICE', '8º GYM - VOLKNER', 'ELITE FOUR - AARON', 'ELITE FOUR - BERTHA', 'ELITE FOUR - FLINT', 'ELITE FOUR - LUCIAN', 'CHAMPION'] ELSE caps || ARRAY(SELECT item FROM unnest(ARRAY['ELITE FOUR - LUCIAN', 'CHAMPION']) AS item WHERE NOT item = ANY(caps)) END, dicas = dicas || '{"ELITE FOUR - LUCIAN":["Lucian é o último integrante da Elite Four e especialista no tipo Psíquico. Seu time é formado por Mr. Mime no nível 59, Girafarig no nível 59, Medicham no nível 60, Alakazam no nível 60 e Bronzong no nível 63.","Mr. Mime, Medicham e Alakazam são vulneráveis aos tipos Sombrio, Fantasma e Inseto. Girafarig também é do tipo Normal, então é imune a golpes Fantasmas, mas continua vulnerável aos tipos Sombrio e Inseto.","Bronzong é dos tipos Aço e Psíquico e possui Levitate, que o protege de golpes de Terra. Nesses jogos, golpes Sombrio e Fantasma causam dano normal nele; sua fraqueza é o tipo Fogo.","Se você treinou Shinx desde o início da jornada, seu Luxray com Crunch pode enfrentar Mr. Mime, Girafarig, Medicham e Alakazam. Contra Medicham, mantenha cuidado com seus golpes Lutadores.","Se você capturou um Stunky, seu Skuntank pode usar golpes Sombrio contra Mr. Mime, Girafarig, Medicham e Alakazam. Por ser do tipo Sombrio, ele é imune aos golpes Psíquicos da equipe. Tenha cuidado com Drain Punch de Medicham e Focus Blast de Alakazam, que são perigosos para ele.","Se você conseguiu capturar Spiritomb na Route 209, ele pode usar golpes Sombrio contra Girafarig e golpes Sombrio ou Fantasma contra Mr. Mime, Medicham e Alakazam. Spiritomb é imune aos golpes Psíquicos e não possui fraquezas de tipo nesses jogos.","Para enfrentar Medicham, seu Staraptor com golpes Voadores também é uma opção. Tenha cuidado com Ice Punch e ThunderPunch, que são superefetivos contra ele.","Contra Bronzong, se você escolheu Chimchar, seu Infernape pode usar golpes de Fogo. Outra opção é Rapidash, evoluído de Ponyta. Não use golpes de Terra contra Bronzong, pois Levitate o torna imune a eles.","Tenha cuidado com Reflect e Light Screen de Mr. Mime, que reduzem o dano recebido pela equipe de Lucian. Alakazam também pode usar Recover, enquanto Bronzong conhece Calm Mind e Earthquake.","Depois da vitória, cure sua equipe e prepare seus Pokémon para a última batalha da Liga, contra a Champion Cynthia."],"CHAMPION":["Cynthia é a Champion de Sinnoh. Seu time começa com Spiritomb no nível 61, seguido de Roserade no nível 60, Gastrodon no nível 60, Lucario no nível 63, Milotic no nível 63 e Garchomp no nível 66.","Spiritomb é dos tipos Fantasma e Sombrio e não possui fraquezas de tipo nesses jogos. Roserade é vulnerável a Fogo, Gelo, Voador e Psíquico. Gastrodon recebe quatro vezes mais dano de Planta, enquanto Garchomp recebe quatro vezes mais dano de Gelo.","Use golpes fortes que causem dano normal contra Spiritomb, como Surf de Empoleon ou Floatzel. Golpes dos tipos Normal e Lutador não o atingem, e Spiritomb conhece Psychic, perigoso para Pokémon de Lutador e Veneno.","Se você escolheu Chimchar, Infernape pode usar golpes de Fogo contra Roserade e contra Lucario. Seu Staraptor também pode usar golpes Voadores contra Roserade. Tenha cuidado com Earthquake de Lucario, que é superefetivo contra Infernape.","Se você escolheu Turtwig, Torterra pode usar golpes de Planta contra Gastrodon e Milotic. Roserade e Carnivine também podem aproveitar a fraqueza de quatro vezes de Gastrodon. Mantenha seus Pokémon de Planta longe do Ice Beam de Milotic.","Se você treinou Shinx, Luxray pode usar golpes elétricos contra Milotic. Tenha cuidado com Mirror Coat, que pode devolver o dobro do dano recebido de um golpe especial, como os elétricos.","Contra Lucario, use golpes de Fogo de Rapidash ou golpes de Terra de Gastrodon e Hippowdon. Lucario conhece Psychic e Aura Sphere, então escolha com cuidado quem ficará em campo.","Contra Garchomp, um Pokémon com Ice Beam, como Empoleon ou Gastrodon, pode aproveitar a fraqueza de quatro vezes a Gelo. Você também pode usar Sneasel ou Weavile com um golpe de Gelo. Sneasel pode ser encontrado nas rotas nevadas e evolui para Weavile ao subir de nível à noite segurando uma Razor Claw.","Garchomp é rápido e conhece Dragon Rush, Earthquake, Brick Break e Giga Impact. Earthquake é perigoso para Empoleon, e Brick Break é superefetivo contra Weavile, então procure manter sua equipe com bastante vida e atacar antes que Garchomp possa reagir.","Depois de derrotar Cynthia, o Professor Rowan acompanhará você e sua equipe até o Hall da Fama, onde serão registrados como os novos Champions de Sinnoh."]}'::jsonb WHERE slug IN ('pokemon-diamond', 'pokemon-pearl');
UPDATE public.builds SET caps = CASE WHEN cardinality(caps) = 0 THEN ARRAY['1º GYM - ROARK', '2º GYM - GARDENIA', '3º GYM - FANTINA', '4º GYM - MAYLENE', '5º GYM - CRASHER WAKE', '6º GYM - BYRON', '7º GYM - CANDICE', '8º GYM - VOLKNER', 'ELITE FOUR - AARON', 'ELITE FOUR - BERTHA', 'ELITE FOUR - FLINT', 'ELITE FOUR - LUCIAN', 'CHAMPION'] ELSE caps || ARRAY(SELECT item FROM unnest(ARRAY['ELITE FOUR - LUCIAN', 'CHAMPION']) AS item WHERE NOT item = ANY(caps)) END, dicas = dicas || '{"ELITE FOUR - LUCIAN":["Lucian é o último integrante da Elite Four e especialista no tipo Psíquico. Seu time é formado por Mr. Mime no nível 53, Espeon no nível 55, Bronzong no nível 54, Alakazam no nível 56 e Gallade no nível 59.","Mr. Mime, Espeon, Alakazam e Gallade são vulneráveis aos tipos Fantasma e Voador, no caso de Gallade, ou Fantasma, Sombrio e Inseto, no caso dos três Psíquicos puros. Bronzong possui Levitate e é vulnerável ao tipo Fogo.","Se você treinou Shinx, seu Luxray com Crunch pode enfrentar Mr. Mime, Espeon e Alakazam. Espeon conhece Signal Beam, então mantenha a vida de Luxray alta durante a batalha.","Se você recebeu o Eevee de Bebe e o evoluiu para Umbreon, ele pode usar golpes Sombrio contra Mr. Mime, Espeon e Alakazam e é imune aos golpes Psíquicos deles. Tenha cuidado com Signal Beam de Espeon e Focus Blast de Alakazam, que são superefetivos contra Umbreon.","Contra Gallade, seu Staraptor com golpes Voadores pode aproveitar sua fraqueza. Tenha muito cuidado com Stone Edge, que é superefetivo contra Staraptor. Gallade também conhece Drain Punch, que recupera parte da vida dele ao causar dano.","O Rotom capturado no Old Chateau pode usar golpes Fantasmas contra Mr. Mime, Espeon, Alakazam e Gallade. Tenha cuidado contra Shadow Ball de Espeon, que também é superefetivo contra Rotom.","Contra Bronzong, se você escolheu Chimchar, use os golpes de Fogo do seu Infernape. Rapidash ou Flareon também são opções. Não use golpes de Terra, pois Levitate protege Bronzong deles.","Tenha cuidado com Reflect e Light Screen de Mr. Mime, com Recover de Alakazam e com Calm Mind de Bronzong. Gallade também pode causar bastante dano com Psycho Cut e Stone Edge.","Depois da vitória, cure sua equipe e prepare seus Pokémon para a última batalha da Liga, contra a Champion Cynthia."],"CHAMPION":["Cynthia é a Champion de Sinnoh. Seu time começa com Spiritomb no nível 58, seguido de Roserade no nível 58, Togekiss no nível 60, Lucario no nível 60, Milotic no nível 58 e Garchomp no nível 62.","Spiritomb é dos tipos Fantasma e Sombrio e não possui fraquezas de tipo nesses jogos. Roserade é vulnerável a Fogo, Gelo, Voador e Psíquico. Togekiss é vulnerável a Elétrico, Gelo e Pedra, enquanto Garchomp recebe quatro vezes mais dano de Gelo.","Use golpes fortes que causem dano normal contra Spiritomb, como Surf de Empoleon ou Floatzel. Golpes dos tipos Normal e Lutador não o atingem, e Spiritomb conhece Psychic, perigoso para Pokémon de Lutador e Veneno.","Se você escolheu Chimchar, Infernape pode usar golpes de Fogo contra Roserade e Lucario. Staraptor também pode usar golpes Voadores contra Roserade. Lucario conhece Aura Sphere e Stone Edge, então tenha cuidado com os Pokémon que você colocar diante dele.","Se você treinou Shinx, Luxray pode usar golpes elétricos contra Togekiss e Milotic. Magneton ou Magnezone também podem enfrentar os dois com ataques elétricos, mas devem tomar cuidado com Aura Sphere de Togekiss.","Se você recebeu o Eevee de Bebe, Leafeon pode usar golpes de Planta contra Milotic. Torterra, Roserade e Carnivine também são opções, mas devem tomar cuidado com Ice Beam. Milotic conhece Mirror Coat, que pode devolver o dobro do dano recebido de um golpe especial, como ataques de Planta e Elétrico.","Contra Lucario, use golpes de Fogo de Infernape ou Rapidash, ou golpes de Terra de Gastrodon e Hippowdon. Lucario também conhece Shadow Ball e Stone Edge, então evite deixá-lo atacar seus Pokémon sem necessidade.","Contra Garchomp, Empoleon ou Gastrodon com Ice Beam podem aproveitar sua fraqueza de quatro vezes a Gelo. Você também pode usar Sneasel ou Weavile com um golpe de Gelo, ou Glaceon, obtido ao subir o nível de Eevee na Route 217.","Garchomp é rápido e conhece Dragon Rush, Earthquake, Flamethrower e Giga Impact. Earthquake é perigoso para Empoleon, e Flamethrower é superefetivo contra Weavile e Glaceon, então procure atacá-lo antes que ele possa reagir.","Depois de derrotar Cynthia, o Professor Rowan acompanhará você e sua equipe até o Hall da Fama, onde serão registrados como os novos Champions de Sinnoh."]}'::jsonb WHERE slug IN ('pokemon-platinum');


-- Builds de Sinnoh: ginásios e Elite Four.
UPDATE public.builds SET dicas = COALESCE(dicas, '{}'::jsonb) || '{"1º GYM - ROARK":["Roark é especialista no tipo Pedra. Seu time começa com Geodude no nível 12, seguido de Onix no nível 12 e Cranidos no nível 14.","Geodude e Onix também são do tipo Terra, então recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Cranidos é do tipo Pedra e também é vulnerável a Água e Planta, além dos tipos Lutador e Terra.","Se você escolheu Turtwig, treine-o até aprender Absorb no nível 9 e use o golpe contra toda a equipe de Roark. Absorb também recupera parte da vida de Turtwig durante a batalha.","Se você escolheu Piplup, treine-o até aprender Bubble no nível 8 e use o golpe contra os três adversários.","Se você escolheu Chimchar, pode treiná-lo até evoluir para Monferno no nível 14. Ao evoluir, ele pode aprender Mach Punch, um golpe do tipo Lutador que tem vantagem contra toda a equipe de Roark.","Outra opção para quem escolheu Chimchar é capturar um Machop na Route 207, ao norte de Oreburgh City, e usar seus golpes do tipo Lutador.","Independentemente do inicial escolhido, você também pode treinar um Bidoof até o nível 15, quando evolui para Bibarel e pode aprender Water Gun. Seus golpes de Água têm vantagem contra os três adversários.","Tenha cuidado com Headbutt de Cranidos, que causa bastante dano e pode fazer seu Pokémon perder o turno. Ele também conhece Pursuit, que pode atingir seu Pokémon antes de uma troca.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"2º GYM - GARDENIA":["Gardenia é especialista no tipo Planta. Ela usa Cherubi no nível 19, Turtwig no nível 19 e Roserade no nível 22.","Todos recebem dano superefetivo de golpes dos tipos Fogo, Voador e Gelo. Roserade também é do tipo Veneno e recebe dano superefetivo de golpes do tipo Psíquico.","Se você escolheu Chimchar, seu Monferno pode usar golpes de Fogo contra toda a equipe. Ele aprende Flame Wheel no nível 19, uma boa opção para essa batalha.","Se você escolheu Turtwig ou Piplup, pode usar um Starly capturado no início da jornada. Ele aprende Wing Attack no nível 9 e evolui para Staravia no nível 14, podendo enfrentar todos os Pokémon de Gardenia com golpes Voadores.","Outra opção é Zubat, que pode ser encontrado em cavernas durante a jornada. Treine-o até aprender Wing Attack no nível 17 e use o golpe contra os três adversários.","Se você capturou um Wurmple na Eterna Forest e ele evoluiu para Silcoon, poderá treiná-lo até evoluir para Beautifly no nível 10. Beautifly pode usar Gust para aproveitar a fraqueza da equipe ao tipo Voador.","Se você treinou um Abra, seu Kadabra pode usar golpes Psíquicos contra Roserade, aproveitando a fraqueza causada pelo tipo Veneno dela.","Tenha cuidado com Stun Spore de Roserade, que pode paralisar seu Pokémon, e com seus golpes de Planta, especialmente se estiver usando Piplup ou Prinplup. Turtwig também pode usar Reflect para reduzir o dano dos seus golpes físicos.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"3º GYM - MAYLENE":["Maylene é especialista no tipo Lutador e lidera o ginásio de Veilstone City. Ela usa Meditite no nível 27, Machoke no nível 27 e Lucario no nível 30.","Machoke recebe dano superefetivo de golpes dos tipos Voador e Psíquico. Meditite também é do tipo Psíquico, então recebe dano superefetivo de golpes Voadores, mas golpes Psíquicos causam dano normal nele.","Lucario é dos tipos Lutador e Aço e recebe dano superefetivo de golpes dos tipos Fogo, Lutador e Terra. Os tipos Voador e Psíquico causam dano normal nele.","Se você escolheu Chimchar, seu Monferno pode usar Flame Wheel contra Lucario. Tome cuidado com Bone Rush, pois o golpe do tipo Terra é superefetivo contra Monferno.","Se você treinou Starly, seu Staravia com Wing Attack pode enfrentar Meditite e Machoke. Tenha cuidado com Rock Tomb de Machoke, que é superefetivo contra Pokémon Voadores.","Zubat ou Golbat também podem usar Wing Attack contra Meditite e Machoke. Porém, Meditite conhece Confusion, que causa dano superefetivo aos dois por também serem do tipo Veneno.","Se você capturou Abra, seu Kadabra pode usar golpes Psíquicos contra Machoke. Para enfrentar Lucario, escolha um Pokémon com golpes de Fogo, Lutador ou Terra para aproveitar suas fraquezas.","Outra opção é Bronzor, que pode ser encontrado na Wayward Cave. Ele pode usar golpes Psíquicos contra Machoke e, se possuir a habilidade Levitate, fica imune ao Bone Rush de Lucario.","Se você capturou um Machop na Route 207 para enfrentar Roark, ele já pode ter evoluído para Machoke e usar golpes Lutadores contra Lucario.","Tenha cuidado com Drain Punch de Lucario, que causa dano e recupera parte da vida dele. Ele também pode usar Force Palm, que pode deixar seu Pokémon paralisado.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"4º GYM - CRASHER WAKE":["Crasher Wake é especialista no tipo Água e lidera o ginásio de Pastoria City. Ele usa Gyarados no nível 27, Quagsire no nível 27 e Floatzel no nível 30.","Gyarados também é do tipo Voador e recebe quatro vezes mais dano de golpes elétricos. Quagsire é dos tipos Água e Terra, então é imune a golpes elétricos e recebe quatro vezes mais dano de golpes de Planta. Floatzel é vulnerável aos tipos Elétrico e Planta.","Se você escolheu Turtwig, seu Grotle ou Torterra pode usar golpes de Planta contra Quagsire e Floatzel. Contra Floatzel, tenha cuidado com Ice Fang, que é superefetivo contra Grotle e causa quatro vezes mais dano a Torterra.","Se você treinou um Shinx desde o início da jornada, seu Luxio ou Luxray pode usar golpes elétricos contra Gyarados e Floatzel. Shinx evolui para Luxio no nível 15 e depois para Luxray no nível 30.","Outra opção elétrica é Pachirisu, que pode ser encontrado na Route 205. Seus golpes elétricos também têm vantagem contra Gyarados e Floatzel, mas não devem ser usados contra Quagsire.","Se você capturou Budew, ele pode ter evoluído para Roselia e usar golpes de Planta contra Quagsire e Floatzel. Budew pode ser encontrado na Route 204 e evolui com amizade alta ao subir de nível durante o dia.","Outra opção contra Quagsire é Carnivine, encontrado na Great Marsh, em Pastoria City. Seus golpes de Planta também aproveitam a fraqueza de quatro vezes de Quagsire.","Se você escolheu Chimchar, evite deixar seu Monferno ou Infernape contra os golpes de Água de Wake. Se escolheu Piplup, seu Prinplup ou Empoleon pode ajudar, mas conte com Pokémon elétricos ou de Planta para explorar as fraquezas da equipe adversária.","Tenha cuidado com Ice Fang de Floatzel, que pode congelar seu Pokémon ou fazê-lo perder o turno. Ele também usa Brine, que causa mais dano quando o alvo está com metade da vida ou menos.","Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals para se preparar."],"5º GYM - FANTINA":["Fantina é especialista no tipo Fantasma e lidera o ginásio de Hearthome City. Ela usa Drifblim no nível 32, Gengar no nível 34 e Mismagius no nível 36.","Todos recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma e são imunes a golpes dos tipos Normal e Lutador. Drifblim também é do tipo Voador, então é vulnerável a golpes dos tipos Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, você pode usar Luxio ou Luxray com Bite contra toda a equipe. Se você treinou um Shinx desde o início da jornada, ele já pode ter evoluído para Luxio e aprendido o golpe. Luxray também pode usar golpes elétricos contra Drifblim.","Outra opção é Gyarados com Bite. Você pode obter um Magikarp usando a Old Rod e treiná-lo até o nível 20 para evoluí-lo. Mantenha a vida de Gyarados alta, pois os golpes Fantasmas de Fantina ainda podem causar bastante dano.","Você também pode capturar um Stunky na Route 206. Seus golpes do tipo Sombrio são superefetivos contra a equipe de Fantina. Stunky evolui para Skuntank no nível 34, podendo ajudar como outra opção para essa batalha.","Se você conseguiu capturar Spiritomb na Hallowed Tower da Route 209, ele pode usar golpes Sombrio e Fantasma contra toda a equipe. Para encontrá-lo, coloque uma Odd Keystone na torre e converse 32 vezes com outros jogadores no Underground.","Se você capturou um Gastly na Old Chateau, ele pode ter evoluído para Haunter e usar golpes do tipo Fantasma contra os adversários. Tenha cuidado, pois Haunter também recebe dano superefetivo dos golpes Fantasmas da equipe de Fantina.","Se você escolheu Chimchar, Turtwig ou Piplup, seus iniciais também podem ajudar usando golpes que não sejam dos tipos Normal ou Lutador. Porém, Pokémon com golpes Sombrio ou Fantasma aproveitam melhor as fraquezas dos adversários.","Tenha cuidado com Shadow Ball de Mismagius, um golpe forte que pode reduzir a Defesa Especial do alvo. Ela também pode usar Confuse Ray para confundir seu Pokémon.","Antes da batalha, cure sua equipe e leve algumas Potions, Burn Heals e Awakenings para se preparar."],"6º GYM - BYRON":["Byron é especialista no tipo Aço e lidera o ginásio de Canalave City. Ele usa Bronzor no nível 36, Steelix no nível 36 e Bastiodon no nível 39.","Steelix recebe dano superefetivo de golpes dos tipos Água, Fogo, Lutador e Terra. Bastiodon também é do tipo Pedra e recebe quatro vezes mais dano de golpes dos tipos Lutador e Terra.","Se você escolheu Chimchar, seu Monferno ou Infernape pode usar golpes de Fogo contra toda a equipe e golpes Lutadores contra Steelix e Bastiodon. Tenha cuidado com os golpes de Terra, Pedra e Psíquico dos adversários.","Se você escolheu Piplup, seu Prinplup ou Empoleon com golpes de Água pode enfrentar Steelix e Bastiodon.","Se você treinou um Machop capturado na Route 207, seu Machoke pode usar golpes Lutadores contra Steelix e Bastiodon. Contra Bastiodon, aproveite a fraqueza de quatro vezes.","Outra opção é Shellos, que pode ser encontrado em rotas próximas ao Valley Windworks. Seu Gastrodon pode usar golpes de Água contra Steelix e Bastiodon.","Se você capturou Croagunk na Great Marsh, em Pastoria City, ele pode ter evoluído para Toxicroak no nível 37. Use seus golpes Lutadores contra Steelix e Bastiodon. Tenha cuidado com os golpes Psíquicos de Bronzor, que causam quatro vezes mais dano a Toxicroak.","Tenha cuidado com Bronzor. Ele possui Levitate, então golpes de Terra não o atingem. Um Pokémon com golpes de Fogo pode enfrentar Bronzor, mas deve tomar cuidado com Hypnosis e Confuse Ray.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para se preparar."],"7º GYM - CANDICE":["Candice é especialista no tipo Gelo e lidera o ginásio de Snowpoint City. Seu time começa com Snover no nível 38, seguido de Sneasel no nível 38, Medicham no nível 40 e Abomasnow no nível 42.","Snover e Abomasnow são dos tipos Planta e Gelo e recebem quatro vezes mais dano de golpes de Fogo. Sneasel é dos tipos Sombrio e Gelo e recebe quatro vezes mais dano de golpes Lutadores. Medicham é dos tipos Lutador e Psíquico e é vulnerável a golpes dos tipos Voador e Fantasma.","Se você escolheu Chimchar, seu Infernape pode usar golpes de Fogo contra Snover e Abomasnow e golpes Lutadores contra Sneasel. Evite deixá-lo contra Medicham, que conhece Confusion.","Se você treinou Machop desde a Route 207, seu Machoke pode usar golpes Lutadores contra Snover, Sneasel e Abomasnow. Se conseguiu evoluí-lo por troca, Machamp também pode cumprir essa função.","Staravia ou Staraptor podem usar golpes Voadores contra Medicham. Tenha cuidado com Ice Punch, que é superefetivo contra eles.","Se você escolheu Piplup, seu Empoleon resiste aos golpes de Gelo e pode usar golpes do tipo Aço contra Snover, Sneasel e Abomasnow. Mantenha-o longe de Medicham e dos golpes Lutadores.","Tenha cuidado com Snow Warning de Abomasnow, que inicia uma tempestade de granizo e causa dano ao fim dos turnos em Pokémon que não são do tipo Gelo. Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals."],"8º GYM - VOLKNER":["Volkner é o líder de Sunyshore City e especialista no tipo Elétrico. Seu time começa com Raichu no nível 46, seguido de Ambipom no nível 47, Octillery no nível 47 e Luxray no nível 49.","Raichu e Luxray são do tipo Elétrico e recebem dano superefetivo de golpes do tipo Terra. Ambipom é do tipo Normal e é vulnerável a golpes Lutadores, enquanto Octillery é do tipo Água e recebe dano superefetivo dos tipos Elétrico e Planta.","Se você escolheu Turtwig, seu Torterra pode usar golpes de Terra contra Raichu e Luxray, além de golpes de Planta contra Octillery. Tenha muito cuidado com Aurora Beam de Octillery, que causa quatro vezes mais dano a Torterra.","Se você treinou Shellos, seu Gastrodon pode usar golpes de Terra contra Raichu e Luxray. Por também ser do tipo Terra, ele é imune aos golpes elétricos, mas deve ficar longe de Bullet Seed de Octillery, que causa quatro vezes mais dano a ele.","Depois de vencer Byron e obter permissão para usar Strength, você pode capturar Gible na área escondida da Wayward Cave. Ele evolui para Gabite no nível 24 e depois para Garchomp no nível 48. Seus golpes de Terra têm vantagem contra Raichu e Luxray, mas Aurora Beam de Octillery causa quatro vezes mais dano a Gabite e Garchomp.","Se você treinou Shinx, seu Luxray pode usar golpes elétricos contra Octillery. Roselia ou Roserade também podem usar golpes de Planta contra ele.","Para enfrentar Ambipom, use um Pokémon com golpes Lutadores, como Machoke, Machamp ou Toxicroak.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals, pois Raichu e Luxray podem usar Thunder Wave."],"ELITE FOUR - AARON":["Aaron é o primeiro integrante da Elite Four e especialista no tipo Inseto. Seu time começa com Dustox no nível 53, seguido de Beautifly no nível 53, Vespiquen no nível 54, Heracross no nível 54 e Drapion no nível 57.","Dustox é vulnerável aos tipos Fogo, Voador, Pedra e Psíquico. Beautifly e Vespiquen recebem quatro vezes mais dano de Pedra, enquanto Heracross recebe quatro vezes mais dano de Voador. Drapion é dos tipos Veneno e Sombrio e só é vulnerável ao tipo Terra.","Se você escolheu Chimchar, seu Infernape pode usar golpes de Fogo contra Dustox, Beautifly, Vespiquen e Heracross. Outra opção é Rapidash, evoluído de Ponyta, que também pode usar golpes de Fogo contra os quatro.","Se você treinou um Starly desde o início da jornada, seu Staraptor pode usar golpes Voadores contra os quatro Pokémon de Inseto. Contra Heracross, aproveite a fraqueza de quatro vezes, mas tenha cuidado com Stone Edge, que é superefetivo contra Staraptor.","Para Beautifly e Vespiquen, Graveler ou Golem com golpes de Pedra também aproveitam a fraqueza de quatro vezes. Golem pode ser obtido ao evoluir Geodude para Graveler no nível 25 e depois realizar uma troca. Evite deixá-los contra Close Combat de Heracross.","O Lucario que pode ser obtido a partir do ovo de Riolu da Iron Island ajuda contra Dustox e Drapion. Por ser dos tipos Lutador e Aço, ele é imune a golpes de Veneno e resiste bastante aos golpes de Inseto e Sombrio dos adversários.","Contra Drapion, use Gastrodon, Torterra, Gabite ou Garchomp com golpes de Terra. Tome muito cuidado com Ice Fang, que causa quatro vezes mais dano a Torterra, Gabite e Garchomp.","Tenha cuidado com Toxic de Dustox, que envenena gravemente, e com Heal Order de Vespiquen, que recupera sua vida. Drapion também conhece Cross Poison e Aerial Ace.","Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Aaron, recupere seus Pokémon antes de seguir para Bertha."],"ELITE FOUR - BERTHA":["Bertha é a segunda integrante da Elite Four e especialista no tipo Terra. Seu time é formado por Quagsire no nível 55, Sudowoodo no nível 56, Golem no nível 56, Whiscash no nível 55 e Hippowdon no nível 59.","Quagsire e Whiscash recebem quatro vezes mais dano de Planta. Golem recebe quatro vezes mais dano de Água e Planta. Sudowoodo também é vulnerável aos tipos Água, Planta, Lutador e Terra, enquanto Hippowdon é vulnerável a Água, Planta e Gelo.","Se você escolheu Turtwig, seu Torterra pode usar golpes de Planta contra toda a equipe, especialmente contra Quagsire, Golem e Whiscash.","Se você treinou Budew, sua Roselia ou Roserade também pode usar golpes de Planta contra os cinco adversários. Outra opção é Carnivine, encontrado na Great Marsh de Pastoria City.","Se você escolheu Piplup, seu Empoleon com Surf pode enfrentar Sudowoodo, Golem e Hippowdon. Golem recebe quatro vezes mais dano de Água, mas tenha cuidado com Earthquake de Sudowoodo e Golem, que é superefetivo contra Empoleon.","Gastrodon ou Floatzel com Surf também podem enfrentar Sudowoodo, Golem e Hippowdon. Shellos pode ser capturado durante a jornada, enquanto Buizel evolui para Floatzel no nível 26. Contra Quagsire e Whiscash, prefira golpes de Planta para aproveitar a fraqueza de quatro vezes.","Se você treinou Machop, seu Machoke ou Machamp pode usar golpes Lutadores contra Sudowoodo e Golem. O mesmo vale para Lucario, obtido a partir do Riolu da Iron Island, e Toxicroak, evoluído de um Croagunk da Great Marsh.","Os Lutadores precisam ter cuidado com Earthquake. Toxicroak recebe quatro vezes mais dano desse golpe, enquanto Lucario recebe dano superefetivo por também ser do tipo Aço. Se você escolheu Chimchar, seu Infernape também pode usar golpes Lutadores contra os Pokémon de Pedra, mas deve evitar Earthquake.","Tenha cuidado com Fissure de Whiscash, que pode derrotar seu Pokémon em um único acerto. O golpe falha se o alvo estiver em um nível maior que o de Whiscash. Hippowdon também conhece Earthquake e Stone Edge.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Flint."],"ELITE FOUR - FLINT":["Flint é o terceiro integrante da Elite Four e especialista no tipo Fogo. Seu time começa com Rapidash no nível 58, seguido de Steelix no nível 57, Drifblim no nível 58, Lopunny no nível 57 e Infernape no nível 61.","Rapidash e Infernape recebem dano superefetivo dos tipos Água e Terra. Steelix é vulnerável a Água, Fogo, Lutador e Terra. Drifblim é vulnerável aos tipos Elétrico, Gelo, Pedra, Fantasma e Sombrio, enquanto Lopunny recebe dano superefetivo do tipo Lutador.","Se você escolheu Piplup, seu Empoleon com Surf pode enfrentar Rapidash, Steelix e Infernape. Tenha cuidado com Earthquake de Infernape, que é superefetivo contra Empoleon.","Gastrodon com Surf também pode enfrentar Rapidash, Steelix e Infernape. Contudo, Rapidash conhece Solar Beam, que causa quatro vezes mais dano a Gastrodon. Se o sol estiver ativo, o golpe pode ser usado sem esperar um turno para carregar.","Floatzel, evoluído de Buizel, é outra opção de Água contra Rapidash, Steelix e Infernape. Mantenha cuidado com ThunderPunch de Infernape, que é superefetivo contra ele.","Se você treinou Shinx, seu Luxray com golpes elétricos pode enfrentar Drifblim. Outra opção é usar golpes de Pedra com Graveler ou Golem, mas lembre-se de que Drifblim pode usar Will-O-Wisp para queimá-los.","Contra Lopunny, use golpes Lutadores de Machoke, Machamp, Lucario ou Toxicroak. Se você escolheu Chimchar, seu Infernape também pode aproveitar essa fraqueza.","Se você treinou Gible até Gabite ou Garchomp, seus golpes de Terra podem enfrentar Rapidash, Steelix e Infernape. Tenha cuidado com os ataques adversários e não deixe a vida deles baixa antes de entrar em campo.","Flint pode usar Sunny Day para fortalecer golpes de Fogo e enfraquecer golpes de Água. Rapidash, Steelix e Lopunny conhecem esse golpe. Lopunny também conhece Mirror Coat, que pode devolver dano de um golpe especial, então tenha cuidado ao usar ataques especiais contra ele.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Lucian."]}'::jsonb WHERE slug = 'pokemon-diamond';
UPDATE public.builds SET dicas = COALESCE(dicas, '{}'::jsonb) || '{"1º GYM - ROARK":["Roark é especialista no tipo Pedra. Seu time começa com Geodude no nível 12, seguido de Onix no nível 12 e Cranidos no nível 14.","Geodude e Onix também são do tipo Terra, então recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Cranidos é do tipo Pedra e também é vulnerável a Água e Planta, além dos tipos Lutador e Terra.","Se você escolheu Turtwig, treine-o até aprender Absorb no nível 9 e use o golpe contra toda a equipe de Roark. Absorb também recupera parte da vida de Turtwig durante a batalha.","Se você escolheu Piplup, treine-o até aprender Bubble no nível 8 e use o golpe contra os três adversários.","Se você escolheu Chimchar, pode treiná-lo até evoluir para Monferno no nível 14. Ao evoluir, ele pode aprender Mach Punch, um golpe do tipo Lutador que tem vantagem contra toda a equipe de Roark.","Outra opção para quem escolheu Chimchar é capturar um Machop na Route 207, ao norte de Oreburgh City, e usar seus golpes do tipo Lutador.","Independentemente do inicial escolhido, você também pode treinar um Bidoof até o nível 15, quando evolui para Bibarel e pode aprender Water Gun. Seus golpes de Água têm vantagem contra os três adversários.","Tenha cuidado com Headbutt de Cranidos, que causa bastante dano e pode fazer seu Pokémon perder o turno. Ele também conhece Pursuit, que pode atingir seu Pokémon antes de uma troca.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"2º GYM - GARDENIA":["Gardenia é especialista no tipo Planta. Ela usa Cherubi no nível 19, Turtwig no nível 19 e Roserade no nível 22.","Todos recebem dano superefetivo de golpes dos tipos Fogo, Voador e Gelo. Roserade também é do tipo Veneno e recebe dano superefetivo de golpes do tipo Psíquico.","Se você escolheu Chimchar, seu Monferno pode usar golpes de Fogo contra toda a equipe. Ele aprende Flame Wheel no nível 19, uma boa opção para essa batalha.","Se você escolheu Turtwig ou Piplup, pode usar um Starly capturado no início da jornada. Ele aprende Wing Attack no nível 9 e evolui para Staravia no nível 14, podendo enfrentar todos os Pokémon de Gardenia com golpes Voadores.","Outra opção é Zubat, que pode ser encontrado em cavernas durante a jornada. Treine-o até aprender Wing Attack no nível 17 e use o golpe contra os três adversários.","Se você capturou um Wurmple na Eterna Forest e ele evoluiu para Silcoon, poderá treiná-lo até evoluir para Beautifly no nível 10. Beautifly pode usar Gust para aproveitar a fraqueza da equipe ao tipo Voador.","Se você treinou um Abra, seu Kadabra pode usar golpes Psíquicos contra Roserade, aproveitando a fraqueza causada pelo tipo Veneno dela.","Tenha cuidado com Stun Spore de Roserade, que pode paralisar seu Pokémon, e com seus golpes de Planta, especialmente se estiver usando Piplup ou Prinplup. Turtwig também pode usar Reflect para reduzir o dano dos seus golpes físicos.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"3º GYM - MAYLENE":["Maylene é especialista no tipo Lutador e lidera o ginásio de Veilstone City. Ela usa Meditite no nível 27, Machoke no nível 27 e Lucario no nível 30.","Machoke recebe dano superefetivo de golpes dos tipos Voador e Psíquico. Meditite também é do tipo Psíquico, então recebe dano superefetivo de golpes Voadores, mas golpes Psíquicos causam dano normal nele.","Lucario é dos tipos Lutador e Aço e recebe dano superefetivo de golpes dos tipos Fogo, Lutador e Terra. Os tipos Voador e Psíquico causam dano normal nele.","Se você escolheu Chimchar, seu Monferno pode usar Flame Wheel contra Lucario. Tome cuidado com Bone Rush, pois o golpe do tipo Terra é superefetivo contra Monferno.","Se você treinou Starly, seu Staravia com Wing Attack pode enfrentar Meditite e Machoke. Tenha cuidado com Rock Tomb de Machoke, que é superefetivo contra Pokémon Voadores.","Zubat ou Golbat também podem usar Wing Attack contra Meditite e Machoke. Porém, Meditite conhece Confusion, que causa dano superefetivo aos dois por também serem do tipo Veneno.","Se você capturou Abra, seu Kadabra pode usar golpes Psíquicos contra Machoke. Para enfrentar Lucario, escolha um Pokémon com golpes de Fogo, Lutador ou Terra para aproveitar suas fraquezas.","Outra opção é Bronzor, que pode ser encontrado na Wayward Cave. Ele pode usar golpes Psíquicos contra Machoke e, se possuir a habilidade Levitate, fica imune ao Bone Rush de Lucario.","Se você capturou um Machop na Route 207 para enfrentar Roark, ele já pode ter evoluído para Machoke e usar golpes Lutadores contra Lucario.","Tenha cuidado com Drain Punch de Lucario, que causa dano e recupera parte da vida dele. Ele também pode usar Force Palm, que pode deixar seu Pokémon paralisado.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"4º GYM - CRASHER WAKE":["Crasher Wake é especialista no tipo Água e lidera o ginásio de Pastoria City. Ele usa Gyarados no nível 27, Quagsire no nível 27 e Floatzel no nível 30.","Gyarados também é do tipo Voador e recebe quatro vezes mais dano de golpes elétricos. Quagsire é dos tipos Água e Terra, então é imune a golpes elétricos e recebe quatro vezes mais dano de golpes de Planta. Floatzel é vulnerável aos tipos Elétrico e Planta.","Se você escolheu Turtwig, seu Grotle ou Torterra pode usar golpes de Planta contra Quagsire e Floatzel. Contra Floatzel, tenha cuidado com Ice Fang, que é superefetivo contra Grotle e causa quatro vezes mais dano a Torterra.","Se você treinou um Shinx desde o início da jornada, seu Luxio ou Luxray pode usar golpes elétricos contra Gyarados e Floatzel. Shinx evolui para Luxio no nível 15 e depois para Luxray no nível 30.","Outra opção elétrica é Pachirisu, que pode ser encontrado na Route 205. Seus golpes elétricos também têm vantagem contra Gyarados e Floatzel, mas não devem ser usados contra Quagsire.","Se você capturou Budew, ele pode ter evoluído para Roselia e usar golpes de Planta contra Quagsire e Floatzel. Budew pode ser encontrado na Route 204 e evolui com amizade alta ao subir de nível durante o dia.","Outra opção contra Quagsire é Carnivine, encontrado na Great Marsh, em Pastoria City. Seus golpes de Planta também aproveitam a fraqueza de quatro vezes de Quagsire.","Se você escolheu Chimchar, evite deixar seu Monferno ou Infernape contra os golpes de Água de Wake. Se escolheu Piplup, seu Prinplup ou Empoleon pode ajudar, mas conte com Pokémon elétricos ou de Planta para explorar as fraquezas da equipe adversária.","Tenha cuidado com Ice Fang de Floatzel, que pode congelar seu Pokémon ou fazê-lo perder o turno. Ele também usa Brine, que causa mais dano quando o alvo está com metade da vida ou menos.","Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals para se preparar."],"5º GYM - FANTINA":["Fantina é especialista no tipo Fantasma e lidera o ginásio de Hearthome City. Ela usa Drifblim no nível 32, Gengar no nível 34 e Mismagius no nível 36.","Todos recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma e são imunes a golpes dos tipos Normal e Lutador. Drifblim também é do tipo Voador, então é vulnerável a golpes dos tipos Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, você pode usar Luxio ou Luxray com Bite contra toda a equipe. Se você treinou um Shinx desde o início da jornada, ele já pode ter evoluído para Luxio e aprendido o golpe. Luxray também pode usar golpes elétricos contra Drifblim.","Outra opção é Gyarados com Bite. Você pode obter um Magikarp usando a Old Rod e treiná-lo até o nível 20 para evoluí-lo. Mantenha a vida de Gyarados alta, pois os golpes Fantasmas de Fantina ainda podem causar bastante dano.","Se você conseguiu capturar Spiritomb na Hallowed Tower da Route 209, ele pode usar golpes Sombrio e Fantasma contra toda a equipe. Para encontrá-lo, coloque uma Odd Keystone na torre e converse 32 vezes com outros jogadores no Underground.","Se você capturou um Gastly na Old Chateau, ele pode ter evoluído para Haunter e usar golpes do tipo Fantasma contra os adversários. Tenha cuidado, pois Haunter também recebe dano superefetivo dos golpes Fantasmas da equipe de Fantina.","Se você escolheu Chimchar, Turtwig ou Piplup, seus iniciais também podem ajudar usando golpes que não sejam dos tipos Normal ou Lutador. Porém, Pokémon com golpes Sombrio ou Fantasma aproveitam melhor as fraquezas dos adversários.","Tenha cuidado com Shadow Ball de Mismagius, um golpe forte que pode reduzir a Defesa Especial do alvo. Ela também pode usar Confuse Ray para confundir seu Pokémon.","Antes da batalha, cure sua equipe e leve algumas Potions, Burn Heals e Awakenings para se preparar."],"6º GYM - BYRON":["Byron é especialista no tipo Aço e lidera o ginásio de Canalave City. Ele usa Bronzor no nível 36, Steelix no nível 36 e Bastiodon no nível 39.","Steelix recebe dano superefetivo de golpes dos tipos Água, Fogo, Lutador e Terra. Bastiodon também é do tipo Pedra e recebe quatro vezes mais dano de golpes dos tipos Lutador e Terra.","Se você escolheu Chimchar, seu Monferno ou Infernape pode usar golpes de Fogo contra toda a equipe e golpes Lutadores contra Steelix e Bastiodon. Tenha cuidado com os golpes de Terra, Pedra e Psíquico dos adversários.","Se você escolheu Piplup, seu Prinplup ou Empoleon com golpes de Água pode enfrentar Steelix e Bastiodon.","Se você treinou um Machop capturado na Route 207, seu Machoke pode usar golpes Lutadores contra Steelix e Bastiodon. Contra Bastiodon, aproveite a fraqueza de quatro vezes.","Outra opção é Shellos, que pode ser encontrado em rotas próximas ao Valley Windworks. Seu Gastrodon pode usar golpes de Água contra Steelix e Bastiodon.","Se você capturou Croagunk na Great Marsh, em Pastoria City, ele pode ter evoluído para Toxicroak no nível 37. Use seus golpes Lutadores contra Steelix e Bastiodon. Tenha cuidado com os golpes Psíquicos de Bronzor, que causam quatro vezes mais dano a Toxicroak.","Tenha cuidado com Bronzor. Ele possui Levitate, então golpes de Terra não o atingem. Um Pokémon com golpes de Fogo pode enfrentar Bronzor, mas deve tomar cuidado com Hypnosis e Confuse Ray.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para se preparar."],"7º GYM - CANDICE":["Candice é especialista no tipo Gelo e lidera o ginásio de Snowpoint City. Seu time começa com Snover no nível 38, seguido de Sneasel no nível 38, Medicham no nível 40 e Abomasnow no nível 42.","Snover e Abomasnow são dos tipos Planta e Gelo e recebem quatro vezes mais dano de golpes de Fogo. Sneasel é dos tipos Sombrio e Gelo e recebe quatro vezes mais dano de golpes Lutadores. Medicham é dos tipos Lutador e Psíquico e é vulnerável a golpes dos tipos Voador e Fantasma.","Se você escolheu Chimchar, seu Infernape pode usar golpes de Fogo contra Snover e Abomasnow e golpes Lutadores contra Sneasel. Evite deixá-lo contra Medicham, que conhece Confusion.","Se você treinou Machop desde a Route 207, seu Machoke pode usar golpes Lutadores contra Snover, Sneasel e Abomasnow. Se conseguiu evoluí-lo por troca, Machamp também pode cumprir essa função.","Staravia ou Staraptor podem usar golpes Voadores contra Medicham. Tenha cuidado com Ice Punch, que é superefetivo contra eles.","Se você escolheu Piplup, seu Empoleon resiste aos golpes de Gelo e pode usar golpes do tipo Aço contra Snover, Sneasel e Abomasnow. Mantenha-o longe de Medicham e dos golpes Lutadores.","Tenha cuidado com Snow Warning de Abomasnow, que inicia uma tempestade de granizo e causa dano ao fim dos turnos em Pokémon que não são do tipo Gelo. Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals."],"8º GYM - VOLKNER":["Volkner é o líder de Sunyshore City e especialista no tipo Elétrico. Seu time começa com Raichu no nível 46, seguido de Ambipom no nível 47, Octillery no nível 47 e Luxray no nível 49.","Raichu e Luxray são do tipo Elétrico e recebem dano superefetivo de golpes do tipo Terra. Ambipom é do tipo Normal e é vulnerável a golpes Lutadores, enquanto Octillery é do tipo Água e recebe dano superefetivo dos tipos Elétrico e Planta.","Se você escolheu Turtwig, seu Torterra pode usar golpes de Terra contra Raichu e Luxray, além de golpes de Planta contra Octillery. Tenha muito cuidado com Aurora Beam de Octillery, que causa quatro vezes mais dano a Torterra.","Se você treinou Shellos, seu Gastrodon pode usar golpes de Terra contra Raichu e Luxray. Por também ser do tipo Terra, ele é imune aos golpes elétricos, mas deve ficar longe de Bullet Seed de Octillery, que causa quatro vezes mais dano a ele.","Depois de vencer Byron e obter permissão para usar Strength, você pode capturar Gible na área escondida da Wayward Cave. Ele evolui para Gabite no nível 24 e depois para Garchomp no nível 48. Seus golpes de Terra têm vantagem contra Raichu e Luxray, mas Aurora Beam de Octillery causa quatro vezes mais dano a Gabite e Garchomp.","Se você treinou Shinx, seu Luxray pode usar golpes elétricos contra Octillery. Roselia ou Roserade também podem usar golpes de Planta contra ele.","Para enfrentar Ambipom, use um Pokémon com golpes Lutadores, como Machoke, Machamp ou Toxicroak.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals, pois Raichu e Luxray podem usar Thunder Wave."],"ELITE FOUR - AARON":["Aaron é o primeiro integrante da Elite Four e especialista no tipo Inseto. Seu time começa com Dustox no nível 53, seguido de Beautifly no nível 53, Vespiquen no nível 54, Heracross no nível 54 e Drapion no nível 57.","Dustox é vulnerável aos tipos Fogo, Voador, Pedra e Psíquico. Beautifly e Vespiquen recebem quatro vezes mais dano de Pedra, enquanto Heracross recebe quatro vezes mais dano de Voador. Drapion é dos tipos Veneno e Sombrio e só é vulnerável ao tipo Terra.","Se você escolheu Chimchar, seu Infernape pode usar golpes de Fogo contra Dustox, Beautifly, Vespiquen e Heracross. Outra opção é Rapidash, evoluído de Ponyta, que também pode usar golpes de Fogo contra os quatro.","Se você treinou um Starly desde o início da jornada, seu Staraptor pode usar golpes Voadores contra os quatro Pokémon de Inseto. Contra Heracross, aproveite a fraqueza de quatro vezes, mas tenha cuidado com Stone Edge, que é superefetivo contra Staraptor.","Para Beautifly e Vespiquen, Graveler ou Golem com golpes de Pedra também aproveitam a fraqueza de quatro vezes. Golem pode ser obtido ao evoluir Geodude para Graveler no nível 25 e depois realizar uma troca. Evite deixá-los contra Close Combat de Heracross.","O Lucario que pode ser obtido a partir do ovo de Riolu da Iron Island ajuda contra Dustox e Drapion. Por ser dos tipos Lutador e Aço, ele é imune a golpes de Veneno e resiste bastante aos golpes de Inseto e Sombrio dos adversários.","Contra Drapion, use Gastrodon, Torterra, Gabite ou Garchomp com golpes de Terra. Tome muito cuidado com Ice Fang, que causa quatro vezes mais dano a Torterra, Gabite e Garchomp.","Tenha cuidado com Toxic de Dustox, que envenena gravemente, e com Heal Order de Vespiquen, que recupera sua vida. Drapion também conhece Cross Poison e Aerial Ace.","Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Aaron, recupere seus Pokémon antes de seguir para Bertha."],"ELITE FOUR - BERTHA":["Bertha é a segunda integrante da Elite Four e especialista no tipo Terra. Seu time é formado por Quagsire no nível 55, Sudowoodo no nível 56, Golem no nível 56, Whiscash no nível 55 e Hippowdon no nível 59.","Quagsire e Whiscash recebem quatro vezes mais dano de Planta. Golem recebe quatro vezes mais dano de Água e Planta. Sudowoodo também é vulnerável aos tipos Água, Planta, Lutador e Terra, enquanto Hippowdon é vulnerável a Água, Planta e Gelo.","Se você escolheu Turtwig, seu Torterra pode usar golpes de Planta contra toda a equipe, especialmente contra Quagsire, Golem e Whiscash.","Se você treinou Budew, sua Roselia ou Roserade também pode usar golpes de Planta contra os cinco adversários. Outra opção é Carnivine, encontrado na Great Marsh de Pastoria City.","Se você escolheu Piplup, seu Empoleon com Surf pode enfrentar Sudowoodo, Golem e Hippowdon. Golem recebe quatro vezes mais dano de Água, mas tenha cuidado com Earthquake de Sudowoodo e Golem, que é superefetivo contra Empoleon.","Gastrodon ou Floatzel com Surf também podem enfrentar Sudowoodo, Golem e Hippowdon. Shellos pode ser capturado durante a jornada, enquanto Buizel evolui para Floatzel no nível 26. Contra Quagsire e Whiscash, prefira golpes de Planta para aproveitar a fraqueza de quatro vezes.","Se você treinou Machop, seu Machoke ou Machamp pode usar golpes Lutadores contra Sudowoodo e Golem. O mesmo vale para Lucario, obtido a partir do Riolu da Iron Island, e Toxicroak, evoluído de um Croagunk da Great Marsh.","Os Lutadores precisam ter cuidado com Earthquake. Toxicroak recebe quatro vezes mais dano desse golpe, enquanto Lucario recebe dano superefetivo por também ser do tipo Aço. Se você escolheu Chimchar, seu Infernape também pode usar golpes Lutadores contra os Pokémon de Pedra, mas deve evitar Earthquake.","Tenha cuidado com Fissure de Whiscash, que pode derrotar seu Pokémon em um único acerto. O golpe falha se o alvo estiver em um nível maior que o de Whiscash. Hippowdon também conhece Earthquake e Stone Edge.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Flint."],"ELITE FOUR - FLINT":["Flint é o terceiro integrante da Elite Four e especialista no tipo Fogo. Seu time começa com Rapidash no nível 58, seguido de Steelix no nível 57, Drifblim no nível 58, Lopunny no nível 57 e Infernape no nível 61.","Rapidash e Infernape recebem dano superefetivo dos tipos Água e Terra. Steelix é vulnerável a Água, Fogo, Lutador e Terra. Drifblim é vulnerável aos tipos Elétrico, Gelo, Pedra, Fantasma e Sombrio, enquanto Lopunny recebe dano superefetivo do tipo Lutador.","Se você escolheu Piplup, seu Empoleon com Surf pode enfrentar Rapidash, Steelix e Infernape. Tenha cuidado com Earthquake de Infernape, que é superefetivo contra Empoleon.","Gastrodon com Surf também pode enfrentar Rapidash, Steelix e Infernape. Contudo, Rapidash conhece Solar Beam, que causa quatro vezes mais dano a Gastrodon. Se o sol estiver ativo, o golpe pode ser usado sem esperar um turno para carregar.","Floatzel, evoluído de Buizel, é outra opção de Água contra Rapidash, Steelix e Infernape. Mantenha cuidado com ThunderPunch de Infernape, que é superefetivo contra ele.","Se você treinou Shinx, seu Luxray com golpes elétricos pode enfrentar Drifblim. Outra opção é usar golpes de Pedra com Graveler ou Golem, mas lembre-se de que Drifblim pode usar Will-O-Wisp para queimá-los.","Contra Lopunny, use golpes Lutadores de Machoke, Machamp, Lucario ou Toxicroak. Se você escolheu Chimchar, seu Infernape também pode aproveitar essa fraqueza.","Se você treinou Gible até Gabite ou Garchomp, seus golpes de Terra podem enfrentar Rapidash, Steelix e Infernape. Tenha cuidado com os ataques adversários e não deixe a vida deles baixa antes de entrar em campo.","Flint pode usar Sunny Day para fortalecer golpes de Fogo e enfraquecer golpes de Água. Rapidash, Steelix e Lopunny conhecem esse golpe. Lopunny também conhece Mirror Coat, que pode devolver dano de um golpe especial, então tenha cuidado ao usar ataques especiais contra ele.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Lucian."]}'::jsonb WHERE slug = 'pokemon-pearl';
UPDATE public.builds SET dicas = COALESCE(dicas, '{}'::jsonb) || '{"1º GYM - ROARK":["Roark é especialista no tipo Pedra. Seu time começa com Geodude no nível 12, seguido de Onix no nível 12 e Cranidos no nível 14.","Geodude e Onix também são do tipo Terra, então recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Cranidos é do tipo Pedra e também é vulnerável a Água e Planta, além dos tipos Lutador e Terra.","Se você escolheu Turtwig, treine-o até aprender Absorb no nível 9 e use o golpe contra toda a equipe de Roark. Absorb também recupera parte da vida de Turtwig durante a batalha.","Se você escolheu Piplup, treine-o até aprender Bubble no nível 8 e use o golpe contra os três adversários.","Se você escolheu Chimchar, pode treiná-lo até evoluir para Monferno no nível 14. Ao evoluir, ele pode aprender Mach Punch, um golpe do tipo Lutador que tem vantagem contra toda a equipe de Roark.","Outra opção para quem escolheu Chimchar é capturar um Machop na Route 207, ao norte de Oreburgh City, e usar seus golpes do tipo Lutador.","Independentemente do inicial escolhido, você também pode treinar um Bidoof até o nível 15, quando evolui para Bibarel e pode aprender Water Gun. Seus golpes de Água têm vantagem contra os três adversários.","Tenha cuidado com Headbutt de Cranidos, que causa bastante dano e pode fazer seu Pokémon perder o turno. Ele também conhece Pursuit, que pode atingir seu Pokémon antes de uma troca.","Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."],"2º GYM - GARDENIA":["Gardenia é especialista no tipo Planta. Seu time tem Turtwig no nível 20, Cherrim no nível 20 e Roserade no nível 22.","Todos recebem dano superefetivo de golpes dos tipos Fogo, Voador e Gelo. Roserade também é do tipo Veneno e recebe dano superefetivo de golpes do tipo Psíquico.","Se você escolheu Chimchar, seu Monferno pode usar golpes de Fogo contra toda a equipe. Ele aprende Flame Wheel no nível 19, uma boa opção para essa batalha.","Se você escolheu Turtwig ou Piplup, pode usar um Starly capturado no início da jornada. Ele aprende Wing Attack no nível 9 e evolui para Staravia no nível 14, podendo enfrentar todos os Pokémon de Gardenia com golpes Voadores.","Outra opção é Zubat, que pode ser encontrado em cavernas durante a jornada. Treine-o até aprender Wing Attack no nível 17 e use o golpe contra os três adversários.","Se você capturou um Wurmple na Eterna Forest e ele evoluiu para Silcoon, poderá treiná-lo até evoluir para Beautifly no nível 10. Beautifly pode usar Gust para aproveitar a fraqueza da equipe ao tipo Voador.","Se você treinou um Abra, seu Kadabra pode usar golpes Psíquicos contra Roserade, aproveitando a fraqueza causada pelo tipo Veneno dela.","Tenha cuidado com Stun Spore de Roserade, que pode paralisar seu Pokémon, e com seus golpes de Planta, especialmente se estiver usando Piplup ou Prinplup. Turtwig também pode usar Reflect para reduzir o dano dos seus golpes físicos.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"4º GYM - MAYLENE":["Maylene é especialista no tipo Lutador e lidera o ginásio de Veilstone City. Sua equipe tem Meditite no nível 28, Machoke no nível 29 e Lucario no nível 32.","Machoke recebe dano superefetivo de golpes dos tipos Voador e Psíquico. Meditite também é do tipo Psíquico, então recebe dano superefetivo de golpes Voadores, mas golpes Psíquicos causam dano normal nele.","Lucario é dos tipos Lutador e Aço e recebe dano superefetivo de golpes dos tipos Fogo, Lutador e Terra. Os tipos Voador e Psíquico causam dano normal nele.","Se você escolheu Chimchar, seu Monferno pode usar Flame Wheel contra Lucario. Tome cuidado com Bone Rush, pois o golpe do tipo Terra é superefetivo contra Monferno.","Se você treinou Starly, seu Staravia com Wing Attack pode enfrentar Meditite e Machoke. Tenha cuidado com Rock Tomb de Machoke, que é superefetivo contra Pokémon Voadores.","Zubat ou Golbat também podem usar Wing Attack contra Meditite e Machoke. Porém, Meditite conhece Confusion, que causa dano superefetivo aos dois por também serem do tipo Veneno.","Se você capturou Abra, seu Kadabra pode usar golpes Psíquicos contra Machoke. Para enfrentar Lucario, escolha um Pokémon com golpes de Fogo, Lutador ou Terra para aproveitar suas fraquezas.","Outra opção é Bronzor, que pode ser encontrado na Wayward Cave. Ele pode usar golpes Psíquicos contra Machoke e, se possuir a habilidade Levitate, fica imune ao Bone Rush de Lucario.","Se você capturou um Machop na Route 207 para enfrentar Roark, ele já pode ter evoluído para Machoke e usar golpes Lutadores contra Lucario.","Tenha cuidado com Drain Punch de Lucario, que causa dano e recupera parte da vida dele. Ele também pode usar Force Palm, que pode deixar seu Pokémon paralisado.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."],"5º GYM - CRASHER WAKE":["Crasher Wake é especialista no tipo Água e lidera o ginásio de Pastoria City. Sua equipe tem Gyarados no nível 33, Quagsire no nível 34 e Floatzel no nível 37.","Gyarados também é do tipo Voador e recebe quatro vezes mais dano de golpes elétricos. Quagsire é dos tipos Água e Terra, então é imune a golpes elétricos e recebe quatro vezes mais dano de golpes de Planta. Floatzel é vulnerável aos tipos Elétrico e Planta.","Se você escolheu Turtwig, seu Grotle ou Torterra pode usar golpes de Planta contra Quagsire e Floatzel. Contra Floatzel, tenha cuidado com Ice Fang, que é superefetivo contra Grotle e causa quatro vezes mais dano a Torterra.","Se você treinou um Shinx desde o início da jornada, seu Luxio ou Luxray pode usar golpes elétricos contra Gyarados e Floatzel. Shinx evolui para Luxio no nível 15 e depois para Luxray no nível 30.","Outra opção elétrica é Pachirisu, que pode ser encontrado na Route 205. Seus golpes elétricos também têm vantagem contra Gyarados e Floatzel, mas não devem ser usados contra Quagsire.","Se você capturou Budew, ele pode ter evoluído para Roselia e usar golpes de Planta contra Quagsire e Floatzel. Budew pode ser encontrado na Route 204 e evolui com amizade alta ao subir de nível durante o dia.","Outra opção contra Quagsire é Carnivine, encontrado na Great Marsh, em Pastoria City. Seus golpes de Planta também aproveitam a fraqueza de quatro vezes de Quagsire.","Se você escolheu Chimchar, evite deixar seu Monferno ou Infernape contra os golpes de Água de Wake. Se escolheu Piplup, seu Prinplup ou Empoleon pode ajudar, mas conte com Pokémon elétricos ou de Planta para explorar as fraquezas da equipe adversária.","Tenha cuidado com Ice Fang de Floatzel, que pode congelar seu Pokémon ou fazê-lo perder o turno. Ele também usa Brine, que causa mais dano quando o alvo está com metade da vida ou menos.","Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals para se preparar."],"3º GYM - FANTINA":["Fantina é especialista no tipo Fantasma e lidera o ginásio de Hearthome City. Seu time tem Duskull no nível 24, Haunter no nível 24 e Mismagius no nível 26.","Todos recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma e são imunes a golpes dos tipos Normal e Lutador.","Independentemente do inicial escolhido, você pode usar Luxio ou Luxray com Bite contra toda a equipe. Se você treinou um Shinx desde o início da jornada, ele já pode ter evoluído para Luxio e aprendido o golpe.","Outra opção é Gyarados com Bite. Você pode obter um Magikarp usando a Old Rod e treiná-lo até o nível 20 para evoluí-lo. Mantenha a vida de Gyarados alta, pois os golpes Fantasmas de Fantina ainda podem causar bastante dano.","Você pode capturar Rotom no Old Chateau, na Eterna Forest, examinando a televisão à noite depois de conseguir Cut. Ele pode usar golpes do tipo Fantasma contra a equipe de Fantina, mas também é vulnerável aos golpes Fantasmas dela.","Se você capturou um Gastly na Old Chateau, ele pode ter evoluído para Haunter e usar golpes do tipo Fantasma contra os adversários. Tenha cuidado, pois Haunter também recebe dano superefetivo dos golpes Fantasmas da equipe de Fantina.","Se você escolheu Chimchar, Turtwig ou Piplup, seus iniciais também podem ajudar usando golpes que não sejam dos tipos Normal ou Lutador. Porém, Pokémon com golpes Sombrio ou Fantasma aproveitam melhor as fraquezas dos adversários.","Tenha cuidado com Shadow Ball de Mismagius, um golpe forte que pode reduzir a Defesa Especial do alvo. Ela também pode usar Confuse Ray para confundir seu Pokémon.","Duskull conhece Will-O-Wisp, que pode queimar seu Pokémon, enquanto Haunter pode usar Hypnosis para colocá-lo para dormir.","Antes da batalha, cure sua equipe e leve algumas Potions, Burn Heals e Awakenings para se preparar."],"6º GYM - BYRON":["Byron é especialista no tipo Aço e lidera o ginásio de Canalave City. Ele usa Magneton no nível 37, seguido de Steelix no nível 38 e Bastiodon no nível 41.","Steelix recebe dano superefetivo de golpes dos tipos Água, Fogo, Lutador e Terra. Bastiodon também é do tipo Pedra e recebe quatro vezes mais dano de golpes dos tipos Lutador e Terra. Magneton também recebe quatro vezes mais dano do tipo Terra.","Se você escolheu Chimchar, seu Monferno ou Infernape pode usar golpes de Fogo contra toda a equipe e golpes Lutadores contra Steelix, Bastiodon e Magneton. Tenha cuidado com os golpes de Terra, Pedra e Psíquico dos adversários.","Se você escolheu Piplup, seu Prinplup ou Empoleon com golpes de Água pode enfrentar Steelix e Bastiodon. Mantenha-o longe dos golpes elétricos de Magneton.","Se você treinou um Machop capturado na Route 207, seu Machoke pode usar golpes Lutadores contra Steelix, Bastiodon e Magneton. Contra Bastiodon, aproveite a fraqueza de quatro vezes.","Outra opção é Shellos, que pode ser encontrado em rotas próximas ao Valley Windworks. Seu Gastrodon pode usar golpes de Água contra Steelix e Bastiodon e golpes de Terra contra Magneton.","Você também pode capturar Gible na Wayward Cave antes de Byron. Seu Gabite pode usar golpes de Terra contra Magneton, Steelix e Bastiodon, mas tome muito cuidado com Ice Fang de Steelix, que causa quatro vezes mais dano a ele.","Se você capturou Croagunk na Great Marsh, em Pastoria City, ele pode ter evoluído para Toxicroak no nível 37. Use seus golpes Lutadores contra Magneton, Steelix e Bastiodon. Tenha muito cuidado com Earthquake de Steelix, que causa quatro vezes mais dano a Toxicroak.","Bastiodon conhece Metal Burst, que pode devolver mais dano após ser atingido. Mantenha seu Pokémon com bastante vida e evite contar com um ataque se não tiver certeza de que ele será suficiente para vencê-lo.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para se preparar."],"7º GYM - CANDICE":["Candice é especialista no tipo Gelo e lidera o ginásio de Snowpoint City. Seu time começa com Sneasel no nível 40, seguido de Piloswine no nível 40, Abomasnow no nível 42 e Froslass no nível 44.","Sneasel recebe quatro vezes mais dano de golpes Lutadores, enquanto Abomasnow recebe quatro vezes mais dano de golpes de Fogo. Piloswine também é do tipo Terra e é vulnerável aos tipos Água, Fogo, Planta, Lutador e Aço. Froslass é dos tipos Gelo e Fantasma, então é imune a golpes Lutadores e vulnerável a Fogo, Pedra, Fantasma, Sombrio e Aço.","Se você escolheu Chimchar, seu Infernape pode usar golpes Lutadores contra Sneasel e golpes de Fogo contra Abomasnow e Froslass. Tenha muito cuidado com Earthquake de Piloswine, que é superefetivo contra Infernape.","Se você escolheu Piplup, seu Empoleon pode usar golpes de Água contra Piloswine e golpes de Aço contra Sneasel, Abomasnow e Froslass. Porém, Earthquake de Piloswine também é superefetivo contra Empoleon.","Se você escolheu Turtwig, seu Torterra deve tomar muito cuidado: golpes de Gelo causam quatro vezes mais dano a ele. Use outro integrante da equipe para enfrentar os Pokémon de Candice.","Se você treinou Machop, seu Machoke ou Machamp pode usar golpes Lutadores contra Sneasel, Piloswine e Abomasnow. Não use esses golpes contra Froslass, pois ela é imune a eles.","Para enfrentar Froslass, Luxray com Bite ou Crunch pode aproveitar sua fraqueza ao tipo Sombrio. Outra opção é um Pokémon com golpes de Fogo, como Rapidash, evoluído de Ponyta.","Se você recebeu o Eevee de Bebe em Hearthome City, pode usar uma Fire Stone para evoluí-lo em Flareon. Seus golpes de Fogo têm vantagem contra Sneasel, Abomasnow e Froslass. Uma Fire Stone pode ser encontrada na Fuego Ironworks, acessível com Surf. Tenha cuidado com Piloswine, pois Earthquake é superefetivo contra Flareon.","Tenha cuidado com Earthquake de Piloswine e Blizzard de Froslass. A tempestade de granizo pode ser ativada durante a batalha e aumenta a precisão de Blizzard, além de causar dano ao fim dos turnos em Pokémon que não são do tipo Gelo.","Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals para se preparar."],"8º GYM - VOLKNER":["Volkner é o líder de Sunyshore City e especialista no tipo Elétrico. Seu time começa com Jolteon no nível 46, seguido de Raichu no nível 46, Luxray no nível 48 e Electivire no nível 50.","Todos recebem dano superefetivo de golpes do tipo Terra. Pokémon desse tipo também são imunes aos golpes elétricos da equipe.","Se você escolheu Turtwig, seu Torterra pode usar golpes de Terra contra toda a equipe. Tenha muito cuidado com Ice Fang de Luxray, que causa quatro vezes mais dano a Torterra.","Se você treinou Shellos, seu Gastrodon também pode usar golpes de Terra contra os quatro adversários. Ele é imune aos golpes elétricos por também ser do tipo Terra.","Se você capturou Gible na Wayward Cave, seu Gabite ou Garchomp pode usar golpes de Terra contra a equipe. Assim como Torterra, os dois recebem quatro vezes mais dano de Ice Fang, então mantenha cuidado ao enfrentar Luxray.","Outra opção é Hippopotas, que pode ser encontrado na Maniac Tunnel, próxima à Route 214. Ele evolui para Hippowdon no nível 34 e pode enfrentar a equipe com golpes do tipo Terra.","Se você treinou Geodude, seu Graveler ou Golem também pode usar golpes de Terra. Tenha cuidado com Focus Blast de Raichu, que causa dano superefetivo contra eles por também serem do tipo Pedra.","O Eevee recebido de Bebe pode ter evoluído para Leafeon ao subir de nível perto da Moss Rock, na Eterna Forest. Ele resiste aos golpes elétricos e pode ajudar com ataques fortes, mas deve tomar cuidado com Ice Fang e Fire Fang de Luxray.","Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals. Depois da vitória, você terá as oito insígnias e poderá seguir em direção à Liga Pokémon."],"ELITE FOUR - AARON":["Aaron é o primeiro integrante da Elite Four e especialista no tipo Inseto. Seu time é formado por Yanmega no nível 49, Scizor no nível 49, Vespiquen no nível 50, Heracross no nível 51 e Drapion no nível 53.","Yanmega e Vespiquen recebem quatro vezes mais dano de Pedra. Scizor recebe quatro vezes mais dano de Fogo, e Heracross recebe quatro vezes mais dano de Voador. Drapion é dos tipos Veneno e Sombrio e só é vulnerável ao tipo Terra.","Se você escolheu Chimchar, seu Infernape pode usar golpes de Fogo contra Yanmega e Scizor. Outra opção é Rapidash, evoluído de Ponyta. Contra Scizor, os dois aproveitam a fraqueza de quatro vezes ao tipo Fogo.","Graveler ou Golem com golpes de Pedra podem enfrentar Yanmega e Vespiquen, que recebem quatro vezes mais dano desse tipo. Evite deixá-los diante de Close Combat de Heracross.","Se você treinou Starly, seu Staraptor com golpes Voadores pode enfrentar Yanmega, Vespiquen e Heracross. Heracross recebe quatro vezes mais dano, mas conhece Stone Edge. Vespiquen também conhece Power Gem, então mantenha cuidado ao usar Staraptor contra os dois.","O Lucario evoluído do Riolu da Iron Island pode ajudar contra Drapion. Seu tipo Aço o torna imune a golpes de Veneno, e ele também resiste aos ataques dos tipos Inseto e Sombrio.","Para explorar a fraqueza de Drapion, você pode usar Gastrodon, Torterra, Gabite ou Garchomp com golpes de Terra. Tenha cuidado com Ice Fang, especialmente se estiver usando Torterra, Gabite ou Garchomp, que recebem quatro vezes mais dano de Gelo.","Tenha cuidado com Double Team de Yanmega, que dificulta acertar seus golpes, e com Heal Order de Vespiquen, que recupera sua vida. Depois da vitória, cure sua equipe antes de seguir para Bertha."],"ELITE FOUR - BERTHA":["Bertha é a segunda integrante da Elite Four e especialista no tipo Terra. Seu time é formado por Whiscash no nível 50, Gliscor no nível 53, Hippowdon no nível 52, Golem no nível 52 e Rhyperior no nível 55.","Whiscash recebe quatro vezes mais dano de Planta. Golem e Rhyperior recebem quatro vezes mais dano de Água e Planta, enquanto Gliscor recebe quatro vezes mais dano de Gelo. Golem e Rhyperior também são vulneráveis ao tipo Lutador.","Se você escolheu Turtwig, seu Torterra pode usar golpes de Planta contra Whiscash, Hippowdon, Golem e Rhyperior. Evite colocá-lo contra Gliscor, que conhece Ice Fang, causando quatro vezes mais dano a Torterra.","Roserade ou Carnivine também podem usar golpes de Planta contra esses quatro adversários. Se você recebeu o Eevee de Bebe e o evoluiu para Leafeon, ele é outra opção para aproveitar as mesmas fraquezas.","Se você escolheu Piplup, seu Empoleon com Surf pode enfrentar Gliscor, Hippowdon, Golem e Rhyperior. Tenha cuidado com Earthquake, que é superefetivo contra Empoleon.","Gastrodon ou Floatzel com Surf também podem enfrentar Gliscor, Hippowdon, Golem e Rhyperior. Para Gliscor, um Pokémon com Ice Beam pode aproveitar a fraqueza de quatro vezes a Gelo.","Machoke, Machamp, Lucario, Toxicroak e Infernape podem usar golpes Lutadores contra Golem e Rhyperior. Os dois conhecem Earthquake, então mantenha cuidado com seus Lutadores, principalmente Toxicroak, que recebe quatro vezes mais dano de Terra.","Tenha cuidado com Rock Wrecker de Rhyperior, um golpe de Pedra muito forte. Depois de usá-lo, Rhyperior precisa descansar por um turno, que você pode aproveitar para atacar ou recuperar sua equipe.","Depois da vitória, cure sua equipe e prepare seus Pokémon para Flint."],"ELITE FOUR - FLINT":["Flint é o terceiro integrante da Elite Four e especialista no tipo Fogo. Seu time é formado por Houndoom no nível 52, Flareon no nível 55, Rapidash no nível 53, Infernape no nível 55 e Magmortar no nível 57.","Todos recebem dano superefetivo dos tipos Água e Terra. Houndoom também é vulnerável a golpes Lutadores e de Pedra, enquanto os demais também recebem dano superefetivo de golpes de Pedra.","Se você escolheu Piplup, seu Empoleon com Surf pode enfrentar toda a equipe. Tenha muito cuidado com Earthquake e ThunderPunch de Infernape e com Thunderbolt de Magmortar, que são superefetivos contra Empoleon.","Gastrodon também pode usar Surf ou golpes de Terra contra a equipe. Por ser dos tipos Água e Terra, ele é imune aos golpes elétricos, mas deve tomar muito cuidado com Solar Beam de Rapidash, que causa quatro vezes mais dano a ele.","Floatzel ou Gyarados com Surf são outras opções de Água. Evite deixá-los diante de ThunderPunch de Infernape ou Thunderbolt de Magmortar. No caso de Gyarados, os golpes elétricos causam quatro vezes mais dano.","Se você treinou Gible até Gabite ou Garchomp, seus golpes de Terra podem enfrentar os cinco adversários. Graveler ou Golem também podem usar golpes de Terra e Pedra, mas devem tomar cuidado com ataques Lutadores.","Se você capturou Hippopotas na Maniac Tunnel, próxima à Route 214, ele pode ter evoluído para Hippowdon no nível 34. Use seus golpes do tipo Terra contra Houndoom e os demais Pokémon de Flint. Sua habilidade Sand Stream pode iniciar uma tempestade de areia, substituindo o sol de Sunny Day.","Tenha cuidado com Sunny Day de Rapidash, que fortalece golpes de Fogo e permite que Solar Beam seja usado sem esperar um turno para carregar. Infernape e Magmortar também possuem golpes elétricos para surpreender Pokémon de Água.","Depois da vitória, recupere sua equipe e prepare seus Pokémon para Lucian, o último integrante da Elite Four antes da Champion."]}'::jsonb WHERE slug = 'pokemon-platinum';


-- Builds de Lucian e Cynthia nos remakes de Sinnoh.
UPDATE public.builds SET caps = CASE WHEN COALESCE(cardinality(caps), 0) = 0 THEN ARRAY['1º GYM - ROARK', '2º GYM - GARDENIA', '3º GYM - MAYLENE', '4º GYM - CRASHER WAKE', '5º GYM - FANTINA', '6º GYM - BYRON', '7º GYM - CANDICE', '8º GYM - VOLKNER', 'ELITE FOUR - AARON', 'ELITE FOUR - BERTHA', 'ELITE FOUR - FLINT', 'ELITE FOUR - LUCIAN', 'CHAMPION'] ELSE caps || ARRAY(SELECT item FROM unnest(ARRAY['ELITE FOUR - LUCIAN','CHAMPION']) AS item WHERE NOT item = ANY(caps)) END, dicas = COALESCE(dicas, '{}'::jsonb) || '{"ELITE FOUR - LUCIAN":["Lucian é o último integrante da Elite Four e usa principalmente Pokémon do tipo Psíquico. Seu time começa com Mr. Mime no nível 59, seguido de Girafarig no nível 59, Medicham no nível 60, Alakazam no nível 60 e Bronzong no nível 63.","Mr. Mime é dos tipos Psíquico e Fada e recebe dano superefetivo de golpes dos tipos Veneno, Fantasma e Aço. Girafarig é vulnerável aos tipos Inseto e Sombrio, enquanto Medicham recebe dano superefetivo dos tipos Voador, Fantasma e Fada.","Alakazam é vulnerável aos tipos Inseto, Fantasma e Sombrio. Bronzong recebe dano superefetivo dos tipos Fogo, Fantasma e Sombrio, mas sua habilidade Levitate o protege de golpes do tipo Terra.","Contra Mr. Mime, use Roserade com Sludge Bomb ou Toxicroak com Poison Jab. Budew pode ser encontrado na Route 204 e evolui para Roselia com amizade durante o dia, depois use uma Shiny Stone para obter Roserade. Croagunk pode ser encontrado na Great Marsh e evolui para Toxicroak no nível 37.","Tenha cuidado com Toxicroak nessa batalha, pois ele recebe quatro vezes mais dano de golpes Psíquicos e Mr. Mime conhece Psychic.","Para enfrentar Girafarig e Alakazam, use Luxray com Crunch. Shinx pode ser encontrado nas primeiras rotas da jornada e evolui para Luxio no nível 15 e para Luxray no nível 30.","Outra opção contra Girafarig e Alakazam é Drapion com Crunch. Você pode encontrar Skorupi na Great Marsh ou no Grand Underground e evoluí-lo para Drapion no nível 40. Por ser do tipo Sombrio, Drapion é imune aos golpes Psíquicos deles.","Contra Medicham, Staraptor com Brave Bird é uma boa opção. Starly pode ser encontrado nas primeiras rotas e evolui para Staravia no nível 14 e para Staraptor no nível 34. Tenha cuidado com Ice Punch e Thunder Punch, que causam dano superefetivo em Staraptor.","Se você treinou Clefable com um golpe do tipo Fada, ele também pode enfrentar Medicham. Clefairy pode ser encontrado no Mt. Coronet e evolui para Clefable com uma Moon Stone.","Contra Bronzong, seu Infernape, caso tenha escolhido Chimchar, pode usar golpes do tipo Fogo. Outra opção é Rapidash, que evolui de Ponyta no nível 40 e também pode usar golpes de Fogo.","Tenha cuidado com Reflect e Light Screen de Mr. Mime, pois eles reduzem o dano recebido pela equipe de Lucian durante vários turnos. Girafarig e Bronzong também podem usar Trick Room, fazendo os Pokémon mais lentos atacarem primeiro por alguns turnos.","Medicham possui Pure Power, que aumenta seu Ataque, enquanto Alakazam pode usar Nasty Plot para aumentar bastante seu Ataque Especial. Bronzong conhece Earthquake, então cuidado ao usar Infernape, Rapidash ou Drapion contra ele.","Depois da vitória, recupere sua equipe e prepare seus Pokémon para a última batalha da Liga, contra a Champion Cynthia."],"CHAMPION":["Cynthia é a Champion da Liga Pokémon de Sinnoh e usa uma equipe com tipos variados. Seu time começa com Spiritomb no nível 61, seguido de Roserade no nível 60, Gastrodon no nível 60, Lucario no nível 63, Milotic no nível 63 e Garchomp no nível 66.","Spiritomb é dos tipos Fantasma e Sombrio e sua única fraqueza é o tipo Fada. Roserade é vulnerável aos tipos Fogo, Gelo, Voador e Psíquico, enquanto Gastrodon recebe quatro vezes mais dano de golpes do tipo Planta.","Lucario é vulnerável aos tipos Fogo, Lutador e Terra. Milotic recebe dano superefetivo dos tipos Elétrico e Planta, enquanto Garchomp recebe quatro vezes mais dano de golpes do tipo Gelo e também é vulnerável aos tipos Dragão e Fada.","Contra Spiritomb, você pode usar Clefable com um golpe do tipo Fada. Clefairy pode ser encontrado no Mt. Coronet e evolui com uma Moon Stone. Spiritomb também é imune a golpes dos tipos Normal, Lutador e Psíquico, então escolha seus ataques com cuidado.","Outra opção é ensinar um golpe do tipo Fada a um Pokémon compatível da sua equipe. Mesmo sem ser do tipo Fada, ele poderá aproveitar a fraqueza de Spiritomb.","Para enfrentar Roserade, use Staraptor com um golpe do tipo Voador ou Rapidash com um golpe do tipo Fogo. Se você escolheu Chimchar, seu Infernape também tem vantagem com golpes de Fogo.","Contra Gastrodon, use Roserade com um golpe do tipo Planta. Se você escolheu Turtwig, seu Torterra também pode aproveitar a fraqueza de quatro vezes. Evite golpes de Água, pois a habilidade Storm Drain de Gastrodon os anula e aumenta seu Ataque Especial.","Para Lucario, Machoke ou Machamp com golpes Lutadores são boas opções. Machop pode ser encontrado na Route 207 e evolui para Machoke no nível 28, depois pode evoluir para Machamp por troca. Infernape também pode enfrentá-lo com golpes de Fogo ou Lutador.","Contra Milotic, use Luxray com golpes elétricos ou Roserade com golpes de Planta. Tenha cuidado com Ice Beam de Milotic, que causa dano superefetivo em Roserade e pode congelar seu Pokémon.","Para Garchomp, uma opção é Weavile com Ice Punch. Sneasel pode ser encontrado nas rotas próximas a Snowpoint City e evolui ao subir de nível à noite segurando uma Razor Claw. Outra opção é Abomasnow com golpes de Gelo, evoluído de Snover no nível 40.","Garchomp segura uma Yache Berry, que reduz o dano do primeiro golpe de Gelo superefetivo que receber. Ele também conhece Poison Jab, que é supereficaz contra Pokémon do tipo Fada, além de Swords Dance, que aumenta bastante seu Ataque.","Tenha cuidado com Mirror Coat de Milotic, que devolve o dobro do dano recebido de um golpe especial. Lucario também pode usar Nasty Plot para aumentar seu Ataque Especial, então tente derrotá-lo antes que ele fortaleça seus ataques.","Depois da vitória, Cynthia levará você ao Hall da Fama, onde sua equipe será registrada e a campanha principal chegará ao fim."]}'::jsonb WHERE slug IN ('pokemon-brilliant-diamond','pokemon-shining-pearl');


-- Builds de Black e White e batalha pós-game contra Alder.
UPDATE public.builds SET caps = CASE WHEN COALESCE(cardinality(caps),0)=0 THEN ARRAY['1º GYM - CILAN, CHILI OU CRESS','2º GYM - LENORA','3º GYM - BURGH','4º GYM - ELESA','5º GYM - CLAY','6º GYM - SKYLA','7º GYM - BRYCEN','8º GYM - DRAYDEN','ELITE FOUR - SHAUNTAL','ELITE FOUR - GRIMSLEY','ELITE FOUR - CAITLIN','ELITE FOUR - MARSHAL','CHAMPION'] ELSE caps || ARRAY(SELECT item FROM unnest(ARRAY['1º GYM - CILAN, CHILI OU CRESS','2º GYM - LENORA','3º GYM - BURGH','4º GYM - ELESA','5º GYM - CLAY','6º GYM - SKYLA','7º GYM - BRYCEN','8º GYM - DRAYDEN','ELITE FOUR - SHAUNTAL','ELITE FOUR - GRIMSLEY','ELITE FOUR - CAITLIN','ELITE FOUR - MARSHAL','CHAMPION']) item WHERE NOT item=ANY(caps)) END, dicas = COALESCE(dicas,'{}'::jsonb) || '{"1º GYM - CILAN, CHILI OU CRESS":["O ginásio de Striaton City possui três líderes, mas você enfrentará apenas um deles. O adversário depende do inicial escolhido e sempre terá um Pokémon com vantagem de tipo contra ele.","Os três líderes começam a batalha com Lillipup no nível 12. O segundo Pokémon estará no nível 14 e será Pansage, Pansear ou Panpour, dependendo do líder.","Se você escolheu Snivy, enfrentará Chili, que usa Pansear do tipo Fogo. Se escolheu Tepig, enfrentará Cress, que usa Panpour do tipo Água. Se escolheu Oshawott, enfrentará Cilan, que usa Pansage do tipo Planta.","Antes de entrar no ginásio, visite o Dreamyard, a leste de Striaton City, e converse com a garota próxima às ruínas. Ela entregará um Pokémon no nível 10 que tem vantagem contra o Pokémon principal do líder.","Se você escolheu Snivy, receberá Panpour. Use Water Gun contra o Pansear de Chili.","Se você escolheu Tepig, receberá Pansage. Use Vine Whip contra o Panpour de Cress.","Se você escolheu Oshawott, receberá Pansear. Use Incinerate contra o Pansage de Cilan.","Contra Lillipup, você pode usar seu inicial ou um Pokémon capturado nas primeiras rotas, como Lillipup ou Patrat. Aproveite essa parte da batalha para manter o Pokémon recebido no Dreamyard com bastante vida para enfrentar o segundo adversário.","Tenha cuidado com Work Up, que aumenta o Ataque e o Ataque Especial do usuário. Se o adversário usar o golpe várias vezes, seus ataques podem ficar perigosos, então tente derrotá-lo antes que acumule muitos aumentos.","Antes da batalha, treine sua equipe, cure seus Pokémon e leve algumas Potions. Depois da vitória, você receberá a Trio Badge e a TM83 Work Up."],"2º GYM - LENORA":["Lenora é a líder do ginásio de Nacrene City e usa Pokémon do tipo Normal. Seu time começa com Herdier no nível 18 e termina com Watchog no nível 20.","Os dois recebem dano superefetivo de golpes do tipo Lutador e são imunes a golpes do tipo Fantasma.","Se você escolheu Tepig, treine-o até o nível 17 para evoluí-lo em Pignite. Ele passa a ser dos tipos Fogo e Lutador e aprende Arm Thrust, um golpe que pode atingir o adversário de duas a cinco vezes.","Independentemente do inicial escolhido, você pode capturar Timburr na área externa de Pinwheel Forest, a oeste de Nacrene City. Ele aprende Low Kick no nível 12 e pode usá-lo contra os dois Pokémon de Lenora. No nível 20, Timburr também aprende Wake-Up Slap.","Outra opção é capturar Sawk ou Throh na área externa de Pinwheel Forest. Em Black, Sawk aparece na grama comum e Throh é mais raro, encontrado na grama que se agita. Em White, acontece o contrário. Os dois são do tipo Lutador e podem aproveitar a fraqueza da equipe de Lenora.","Se você capturou Roggenrola na Wellspring Cave, ele pode ajudar a proteger sua equipe por resistir a golpes do tipo Normal. Se possuir a habilidade Sturdy e estiver com a vida cheia, poderá sobreviver a um golpe que o derrotaria, mas ainda será necessário recuperar sua vida depois.","Tenha cuidado com Retaliate, que os dois Pokémon de Lenora conhecem. O golpe causa o dobro de dano se um companheiro tiver sido derrotado no turno anterior, então mantenha sua equipe com bastante vida ao derrotar o primeiro adversário.","Herdier possui Intimidate, que reduz o Ataque do seu Pokémon ao entrar em campo. Os dois adversários também podem usar Leer para reduzir sua Defesa, aumentando o perigo dos golpes físicos de Lenora.","Watchog ainda conhece Hypnosis, que pode colocar seu Pokémon para dormir. Você pode equipar uma Chesto Berry para acordá-lo caso seja atingido.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para se preparar. Depois da vitória, você receberá a Basic Badge e a TM67 Retaliate."],"3º GYM - BURGH":["Burgh é o líder do ginásio de Castelia City e usa Pokémon do tipo Inseto. Seu time começa com Whirlipede no nível 21, seguido de Dwebble no nível 21 e Leavanny no nível 23.","Whirlipede é dos tipos Inseto e Veneno e recebe dano superefetivo de golpes dos tipos Fogo, Voador, Pedra e Psíquico. Dwebble é dos tipos Inseto e Pedra e é vulnerável aos tipos Água, Pedra e Aço.","Leavanny é dos tipos Inseto e Planta e recebe quatro vezes mais dano de golpes dos tipos Fogo e Voador. Ele também é vulnerável aos tipos Gelo, Veneno, Pedra e Inseto.","Se você escolheu Tepig, seu Pignite pode usar Flame Charge contra Whirlipede e Leavanny. Tenha cuidado contra Dwebble, pois ele conhece Smack Down, um golpe de Pedra que causa dano superefetivo em Pignite.","Se você escolheu Oshawott, seu Dewott pode usar golpes de Água contra Dwebble. Mantenha-o longe de Leavanny, pois Razor Leaf causa dano superefetivo nele.","Se você escolheu Snivy, tenha cuidado ao usar seu Servine nessa batalha. Toda a equipe de Burgh conhece golpes do tipo Inseto, e Whirlipede também possui um golpe do tipo Veneno.","Independentemente do inicial escolhido, Roggenrola é uma boa opção com golpes do tipo Pedra contra os três adversários. Ele pode ser capturado na Wellspring Cave, na Route 3, e evolui para Boldore no nível 25. Tome cuidado contra Leavanny, pois Razor Leaf é superefetivo contra Roggenrola.","Você também pode capturar Pidove na Route 3. Treine-o até o nível 21 para evoluí-lo em Tranquill e use golpes do tipo Voador contra Whirlipede e Leavanny. Evite deixá-lo contra Dwebble, pois Smack Down causa dano superefetivo nele.","Se você escolheu Oshawott e recebeu Pansear no Dreamyard, ele pode usar golpes de Fogo contra Whirlipede e Leavanny. Já se escolheu Snivy e recebeu Panpour, ele pode usar golpes de Água contra Dwebble.","Outra opção contra Whirlipede é Munna com Psybeam. Munna pode ser encontrado no Dreamyard e aprende o golpe no nível 19, mas tenha cuidado com Pursuit, que causa dano superefetivo nele e fica mais forte se Munna tentar sair da batalha naquele turno.","Tenha cuidado com Struggle Bug, que toda a equipe de Burgh conhece e que reduz o Ataque Especial do alvo. Dwebble também pode usar Sand Attack para reduzir sua precisão, enquanto Leavanny pode usar Protect para se proteger de um ataque.","Se você capturou Woobat na Wellspring Cave, ele pode usar Confusion contra Whirlipede e Air Cutter contra Leavanny. Woobat aprende Air Cutter no nível 21, e o golpe causa quatro vezes mais dano a Leavanny.","Tenha cuidado com Pursuit de Whirlipede, que é superefetivo contra Woobat e causa mais dano se ele tentar sair da batalha naquele turno. Evite usá-lo contra Dwebble, pois Smack Down também é superefetivo contra ele.","Whirlipede conhece Poison Tail, que pode envenenar seu Pokémon. Leavanny conhece Razor Leaf, então evite deixar Pokémon vulneráveis a Planta contra ele.","Antes da batalha, cure sua equipe e leve algumas Potions e Antidotes. Depois da vitória, você receberá a Insect Badge e a TM76 Struggle Bug."],"4º GYM - ELESA":["Elesa é a líder do ginásio de Nimbasa City e usa Pokémon do tipo Elétrico. Seu time começa com duas Emolga no nível 25 e termina com Zebstrika no nível 27.","As duas Emolga são dos tipos Elétrico e Voador e recebem dano superefetivo de golpes dos tipos Pedra e Gelo. Por serem do tipo Voador, elas são imunes a golpes do tipo Terra.","Zebstrika é do tipo Elétrico e sua única fraqueza é o tipo Terra.","Independentemente do inicial escolhido, você pode usar Roggenrola ou Boldore com golpes do tipo Pedra contra as duas Emolga. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25.","Outra opção é Sandile, encontrado na Route 4 e no Desert Resort. Ele evolui para Krokorok no nível 29 e pode usar golpes de Terra contra Zebstrika. Por ser do tipo Terra, Sandile também é imune aos golpes elétricos de toda a equipe de Elesa.","Para enfrentar as Emolga com Sandile, ensine a ele Rock Tomb pela TM39, encontrada no Desert Resort. O golpe do tipo Pedra é superefetivo contra as duas e ainda reduz a Velocidade do alvo.","Se você encontrou Drilbur nas nuvens de poeira da Wellspring Cave, ele também pode enfrentar Zebstrika com Dig, aprendido no nível 19. Drilbur é imune a golpes elétricos e pode aprender Rock Tomb para enfrentar as Emolga.","Outra opção contra Zebstrika é Palpitoad com Mud Shot. Timburr não é o único Pokémon útil na área externa de Pinwheel Forest, pois você também pode capturar Tympole por lá e treiná-lo até o nível 25 para evoluí-lo. Palpitoad é dos tipos Água e Terra e também é imune aos golpes elétricos da equipe.","Se você escolheu Snivy, seu Servine resiste aos golpes elétricos, mas tome cuidado com Aerial Ace das Emolga e Flame Charge de Zebstrika, pois ambos são superefetivos contra ele. Se escolheu Oshawott, evite deixar seu Dewott contra os ataques elétricos de Elesa.","Tenha cuidado com Volt Switch, que toda a equipe de Elesa conhece. Depois de causar dano, o golpe permite que o Pokémon seja trocado, então prepare-se para as mudanças durante a batalha. Um Pokémon do tipo Terra é imune ao ataque e impede a troca quando Volt Switch não consegue atingi-lo.","As duas Emolga também conhecem Pursuit, que causa mais dano se atingir seu Pokémon enquanto ele está sendo trocado. Zebstrika conhece Flame Charge, que aumenta sua Velocidade a cada uso.","Antes da batalha, cure sua equipe e leve algumas Potions e Paralyze Heals. Depois da vitória, você receberá a Bolt Badge e a TM72 Volt Switch."],"5º GYM - CLAY":["Clay é o líder do ginásio de Driftveil City e usa Pokémon do tipo Terra. Seu time começa com Krokorok no nível 29, seguido de Palpitoad no nível 29 e termina com Excadrill no nível 31.","Krokorok é dos tipos Terra e Sombrio e recebe dano superefetivo de golpes dos tipos Água, Planta, Gelo, Lutador e Inseto. Palpitoad é dos tipos Água e Terra e sua única fraqueza é o tipo Planta, que causa quatro vezes mais dano nele.","Excadrill é dos tipos Terra e Aço e recebe dano superefetivo de golpes dos tipos Água, Fogo, Lutador e Terra.","Se você escolheu Snivy, seu Servine pode usar golpes de Planta contra Krokorok e Palpitoad. Aproveite a fraqueza de quatro vezes de Palpitoad para tentar derrotá-lo rapidamente.","Se você escolheu Oshawott, seu Dewott com Razor Shell pode enfrentar Krokorok e Excadrill. Contra Palpitoad, escolha um Pokémon com golpes de Planta para aproveitar sua fraqueza.","Se você escolheu Tepig, seu Pignite com Arm Thrust pode enfrentar Krokorok e Excadrill. Tenha cuidado, pois os golpes do tipo Terra de Clay causam dano superefetivo em Pignite.","Se você escolheu Tepig, ainda pode usar o Pansage recebido da garota no Dreamyard, a leste de Striaton City. Use Vine Whip contra Krokorok e Palpitoad.","Outra opção, independentemente do inicial, é capturar Pansage ou Panpour na grama que se agita dentro de Pinwheel Forest. Pansage pode enfrentar Krokorok e Palpitoad com golpes de Planta, enquanto Panpour pode usar golpes de Água contra Krokorok e Excadrill.","Outra opção contra Krokorok e Palpitoad é Sewaddle ou Swadloon com golpes de Planta. Sewaddle pode ser encontrado em Pinwheel Forest e evolui para Swadloon no nível 20.","Para enfrentar Krokorok e Excadrill, use Tympole ou Palpitoad com golpes de Água. Tympole pode ser capturado na área externa de Pinwheel Forest e evolui para Palpitoad no nível 25. Contra o Palpitoad de Clay, prefira golpes de Planta, pois ele resiste a golpes de Água.","Se você capturou Timburr em Pinwheel Forest, ele pode ter evoluído para Gurdurr no nível 25. Seus golpes do tipo Lutador são superefetivos contra Krokorok e Excadrill. Sawk e Throh, encontrados na mesma área, também são opções para essas duas batalhas.","Você também pode usar Drilbur com Dig contra Excadrill. Drilbur aparece nas nuvens de poeira da Wellspring Cave e aprende Dig no nível 19, mas tenha cuidado, pois o Excadrill de Clay também conhece um golpe do tipo Terra.","Tenha cuidado com Bulldoze, que reduz a Velocidade do Pokémon atingido. Krokorok possui Intimidate, que reduz o Ataque do seu Pokémon ao entrar em campo, enquanto Palpitoad pode usar Aqua Ring para recuperar um pouco de vida a cada turno.","O maior perigo é Excadrill, que pode usar Hone Claws para aumentar seu Ataque e sua precisão. Ele também conhece Rock Slide, um golpe de Pedra perigoso para Pokémon do tipo Voador, mesmo que eles sejam imunes a Bulldoze.","Antes da batalha, cure sua equipe e leve algumas Potions para recuperar seus Pokémon. Depois da vitória, você receberá a Quake Badge."],"6º GYM - SKYLA":["Skyla é a líder do ginásio de Mistralton City e usa Pokémon do tipo Voador. Seu time começa com Swoobat no nível 33, seguido de Unfezant no nível 33 e termina com Swanna no nível 35.","Os três recebem dano superefetivo de golpes dos tipos Elétrico e Pedra. Swoobat e Unfezant também são vulneráveis ao tipo Gelo, enquanto Swanna recebe quatro vezes mais dano de golpes elétricos por ser dos tipos Água e Voador.","Independentemente do inicial escolhido, você pode usar Zebstrika com golpes elétricos contra toda a equipe. Blitzle pode ser capturado na Route 3 e evolui para Zebstrika no nível 27. Ele também pode ser encontrado na Route 7, próxima a Mistralton City.","Outra opção é Joltik, que pode ser capturado na Chargestone Cave, a caverna que atravessamos antes de chegar a Mistralton. Use seus golpes elétricos contra os três Pokémon de Skyla, especialmente Swanna.","Se você treinou Roggenrola ou Boldore desde a Wellspring Cave, seus golpes de Pedra também são superefetivos contra toda a equipe. Contudo, tenha cuidado com Swanna, pois BubbleBeam causa dano superefetivo nos dois.","Você também pode usar Vanillite ou Vanillish com golpes de Gelo contra Swoobat e Unfezant. Vanillite pode ser encontrado na área de grama do Cold Storage, ao sul de Driftveil City, e evolui para Vanillish no nível 35.","Se você capturou Sandile na Route 4, ele pode ter evoluído para Krokorok no nível 29. Seus golpes do tipo Sombrio são superefetivos contra Swoobat, mas não use golpes do tipo Terra contra a equipe de Skyla, pois os três Pokémon são imunes a eles.","Se você escolheu Snivy, tenha cuidado ao usar Servine, pois os golpes Voadores da equipe de Skyla são superefetivos contra ele. O mesmo vale para Pignite, caso tenha escolhido Tepig, por ele também ser do tipo Lutador.","Tenha cuidado com Acrobatics de Swoobat, que pode causar bastante dano, e com Heart Stamp, que pode fazer seu Pokémon recuar e perder o turno. Unfezant também conhece Air Slash, que possui a mesma chance de impedir o alvo de agir naquele turno.","Swanna pode usar Aqua Ring para recuperar um pouco de vida a cada turno. Tente derrotá-lo com um golpe elétrico antes que ele tenha muitas oportunidades de atacar ou se recuperar.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Jet Badge e a TM62 Acrobatics."],"7º GYM - BRYCEN":["Brycen é o líder do ginásio de Icirrus City e usa Pokémon do tipo Gelo. Seu time começa com Vanillish no nível 37, seguido de Cryogonal no nível 37 e termina com Beartic no nível 39.","Os três recebem dano superefetivo de golpes dos tipos Fogo, Lutador, Pedra e Aço.","Se você escolheu Tepig, seu Pignite pode usar golpes de Fogo ou Lutador contra toda a equipe. Se treinou seu inicial até o nível 36, ele terá evoluído para Emboar. Tenha cuidado contra Beartic, pois ele conhece Brine, um golpe de Água superefetivo contra Pignite e Emboar.","Independentemente do inicial escolhido, você pode usar Darmanitan com golpes de Fogo. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35. Assim como Pignite e Emboar, ele precisa tomar cuidado com Brine de Beartic.","Outra opção de Fogo é Pansear ou Simisear. Pansear pode ser recebido no Dreamyard se você escolheu Oshawott ou encontrado na grama que se agita dentro de Pinwheel Forest. Para evoluí-lo em Simisear, use uma Fire Stone.","Se você treinou Timburr desde Pinwheel Forest, ele pode ter evoluído para Gurdurr no nível 25. Use seus golpes do tipo Lutador contra a equipe de Brycen. Se puder fazer uma troca, Gurdurr também pode evoluir para Conkeldurr.","Sawk e Throh são outras opções do tipo Lutador. Os dois podem ser encontrados na área externa de Pinwheel Forest, embora a frequência deles varie entre Black e White.","Se você capturou Drilbur nas nuvens de poeira da Wellspring Cave ou da Chargestone Cave, ele pode ter evoluído para Excadrill no nível 31. Use seus golpes do tipo Aço contra os três adversários, mas tome cuidado com Brine de Beartic, que também é superefetivo contra Excadrill.","Boldore ou Gigalith com golpes de Pedra também podem aproveitar a fraqueza dos três Pokémon. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois pode evoluir para Gigalith por troca. Mantenha cuidado contra Beartic por causa de Brine.","Tenha cuidado com Frost Breath, conhecido por Vanillish e Cryogonal. Quando acerta, o golpe causa um acerto crítico. Vanillish também pode usar Acid Armor para aumentar bastante sua Defesa, enquanto Cryogonal pode usar Reflect para reduzir o dano dos golpes físicos recebidos pela equipe.","Beartic conhece Swagger, que aumenta o Ataque do seu Pokémon, mas também o deixa confuso. Seu golpe Brine causa ainda mais dano se o alvo estiver com metade da vida ou menos, então mantenha seus Pokémon saudáveis durante a batalha.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Freeze Badge e a TM79 Frost Breath."],"8º GYM - DRAYDEN":["Drayden é o líder do ginásio de Opelucid City em Pokémon Black e usa Pokémon do tipo Dragão. Seu time começa com Fraxure no nível 41, seguido de Druddigon no nível 41 e termina com Haxorus no nível 43.","Os três recebem dano superefetivo de golpes dos tipos Gelo e Dragão. Como o tipo Fada ainda não existe nesses jogos, ele não é uma opção para essa batalha.","Independentemente do inicial escolhido, você pode usar Vanillish com golpes de Gelo contra toda a equipe. Vanillite pode ser capturado na área de grama do Cold Storage, ao sul de Driftveil City, e evolui para Vanillish no nível 35.","Outra opção é Beartic com golpes de Gelo. Cubchoo pode ser encontrado na Twist Mountain e evolui para Beartic no nível 37. Durante o inverno, Cubchoo também aparece na Route 7.","Tenha cuidado ao usar Vanillish ou Beartic contra Druddigon, pois ele conhece Revenge, um golpe do tipo Lutador que causa dano superefetivo nos dois e fica mais forte se ele receber dano antes de atacar naquele turno.","Se você capturou Axew na Mistralton Cave, ele pode ter evoluído para Fraxure no nível 38. Seus golpes do tipo Dragão são superefetivos contra toda a equipe de Drayden, mas Fraxure também recebe dano superefetivo dos golpes Dragão adversários.","Você também pode capturar Druddigon na Dragonspiral Tower e usar seus golpes do tipo Dragão nessa batalha. Assim como Fraxure, ele precisa tomar cuidado com os ataques do mesmo tipo da equipe de Drayden.","Outra opção é ensinar Frost Breath pela TM79 a um Pokémon compatível. Você recebeu a TM depois de derrotar Brycen, e o golpe do tipo Gelo sempre causa um acerto crítico quando atinge o alvo.","Tenha cuidado com Dragon Dance de Fraxure e Haxorus, pois o golpe aumenta o Ataque e a Velocidade deles. Tente derrotá-los antes que consigam acumular aumentos.","Os três Pokémon de Drayden conhecem Dragon Tail, que causa dano e força a troca do seu Pokémon. Mantenha toda a equipe recuperada, pois o golpe pode colocar em campo um companheiro que você pretendia guardar para depois.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Legend Badge e a TM82 Dragon Tail."],"ELITE FOUR - SHAUNTAL":["Shauntal é uma das integrantes da Elite Four de Unova e usa Pokémon do tipo Fantasma. Seu time começa com Cofagrigus no nível 48, seguido de Jellicent no nível 48, Golurk no nível 48 e Chandelure no nível 50.","Os quatro recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma e são imunes a golpes dos tipos Normal e Lutador. Por causa de seus outros tipos, Jellicent, Golurk e Chandelure também possuem outras fraquezas.","Cofagrigus é do tipo Fantasma. Jellicent também é do tipo Água e recebe dano superefetivo dos tipos Elétrico e Planta.","Golurk também é do tipo Terra e é vulnerável aos tipos Água, Planta e Gelo. Chandelure é dos tipos Fantasma e Fogo e recebe dano superefetivo dos tipos Água, Terra e Pedra.","Independentemente do inicial escolhido, você pode usar Krookodile com Crunch contra os quatro Pokémon de Shauntal. Sandile pode ser capturado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40.","Krookodile também pode usar golpes de Terra contra Chandelure, mas tenha cuidado contra Jellicent, pois seus golpes de Água causam quatro vezes mais dano em Krookodile. Cofagrigus também conhece Grass Knot, que é superefetivo contra ele.","Outra opção contra Cofagrigus é Liepard com golpes do tipo Sombrio. Purrloin pode ser encontrado nas primeiras rotas da jornada e evolui para Liepard no nível 20. Mantenha cuidado com Will-O-Wisp, pois a queimadura reduz o Ataque de Liepard e de outros Pokémon que dependem de golpes físicos.","Contra Jellicent, use Zebstrika com golpes elétricos. Blitzle pode ser encontrado na Route 3 e evolui para Zebstrika no nível 27. Se você capturou Joltik na Chargestone Cave, seu Galvantula também pode aproveitar a fraqueza de Jellicent com golpes elétricos.","Se você escolheu Snivy, seu Serperior pode usar golpes de Planta contra Jellicent e Golurk. Outra opção é Leavanny, evoluído de Sewaddle, encontrado em Pinwheel Forest. Sewaddle evolui para Swadloon no nível 20, e Swadloon evolui para Leavanny ao subir de nível com amizade alta.","Para enfrentar Golurk, você também pode usar Vanillish ou Beartic com golpes de Gelo. Vanillite pode ser encontrado no Cold Storage e evolui para Vanillish no nível 35, enquanto Cubchoo pode ser encontrado na Twist Mountain e evolui para Beartic no nível 37.","Se você escolheu Oshawott, seu Samurott com golpes de Água pode enfrentar Golurk e Chandelure. Seismitoad, evoluído de Tympole, também pode usar golpes de Água contra os dois, mas evite deixá-lo contra Jellicent, pois Energy Ball causa quatro vezes mais dano nele.","Contra Chandelure, Boldore ou Gigalith com golpes de Pedra são outras opções. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois pode evoluir para Gigalith por troca.","Tenha cuidado com Earthquake de Golurk, que pode causar muito dano, e com Fire Blast de Chandelure, um golpe de Fogo forte. Cofagrigus e Jellicent também conhecem golpes de Planta, então escolha com cuidado quais Pokémon de Água e Terra enviar contra eles.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four. Em Unova, você pode escolher a ordem das quatro batalhas."],"ELITE FOUR - GRIMSLEY":["Grimsley é um dos integrantes da Elite Four de Unova e usa Pokémon do tipo Sombrio. Seu time começa com Scrafty no nível 48, seguido de Liepard no nível 48, Krookodile no nível 48 e Bisharp no nível 50.","Scrafty é dos tipos Sombrio e Lutador e recebe dano superefetivo de golpes dos tipos Lutador e Voador. Liepard é do tipo Sombrio e é vulnerável aos tipos Lutador e Inseto.","Krookodile também é do tipo Terra e recebe dano superefetivo dos tipos Água, Planta, Gelo, Lutador e Inseto. Bisharp também é do tipo Aço e recebe quatro vezes mais dano de golpes Lutadores, além de ser vulnerável aos tipos Fogo e Terra.","Se você escolheu Tepig, seu Emboar com golpes do tipo Lutador pode enfrentar toda a equipe de Grimsley. Ele também pode usar golpes de Fogo contra Bisharp, mas tenha cuidado contra Krookodile, pois Earthquake causa dano superefetivo em Emboar.","Independentemente do inicial escolhido, você pode usar Sawk ou Throh com golpes Lutadores contra os quatro adversários. Os dois podem ser encontrados na área externa de Pinwheel Forest, embora a frequência deles varie entre Black e White.","Outra opção é Gurdurr ou Conkeldurr. Timburr pode ser capturado na área externa de Pinwheel Forest e evolui para Gurdurr no nível 25, depois pode evoluir para Conkeldurr por troca. Tenha cuidado contra Liepard e Bisharp, pois ambos conhecem Aerial Ace, que causa dano superefetivo em Pokémon do tipo Lutador.","Contra Scrafty, você pode usar Unfezant com golpes Voadores. Pidove pode ser encontrado na Route 3 e evolui para Tranquill no nível 21 e para Unfezant no nível 32.","Outra opção contra Scrafty é Swanna. Ducklett pode ser encontrado nas sombras que aparecem na Driftveil Drawbridge e evolui para Swanna no nível 35. Ele também pode enfrentar Krookodile com golpes de Água, mas tome cuidado com Dragon Claw.","Se você escolheu Oshawott ou Snivy, seu inicial já pode estar em sua forma final, Samurott ou Serperior. Os dois podem aproveitar as fraquezas de Krookodile, usando golpes de Água ou Planta, respectivamente.","Contra Bisharp, você também pode usar Darmanitan com golpes de Fogo ou Excadrill com golpes de Terra. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35, enquanto Drilbur pode ser encontrado nas nuvens de poeira de cavernas e evolui para Excadrill no nível 31.","Tenha cuidado com Moxie de Scrafty, que aumenta seu Ataque sempre que ele derrota um Pokémon. Krookodile possui Intimidate, que reduz o Ataque do seu Pokémon quando ele entra em campo, e conhece Earthquake, um golpe forte do tipo Terra.","Liepard pode usar Attract para dificultar os ataques de um Pokémon do sexo oposto. Bisharp possui Defiant, que aumenta seu Ataque quando uma de suas características é reduzida, então tenha cuidado ao usar Pokémon com Intimidate contra ele.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - CAITLIN":["Caitlin é uma das integrantes da Elite Four de Unova e usa Pokémon do tipo Psíquico. Seu time começa com Reuniclus no nível 48, seguido de Musharna no nível 48, Sigilyph no nível 48 e Gothitelle no nível 50.","Reuniclus, Musharna e Gothitelle recebem dano superefetivo de golpes dos tipos Sombrio, Fantasma e Inseto. Sigilyph também é do tipo Voador e é vulnerável aos tipos Sombrio, Fantasma, Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, você pode usar Krookodile com Crunch contra toda a equipe. Sandile pode ser encontrado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40.","Por ser do tipo Sombrio, Krookodile é imune aos golpes Psíquicos de Caitlin. Porém, tenha muito cuidado com Focus Blast de Reuniclus, que é superefetivo contra ele, e com Ice Beam de Sigilyph, que causa quatro vezes mais dano a Krookodile.","Outra opção é Liepard com golpes do tipo Sombrio. Purrloin pode ser encontrado nas primeiras rotas e evolui para Liepard no nível 20. Assim como Krookodile, ele é imune aos golpes Psíquicos, mas precisa tomar cuidado com Focus Blast de Reuniclus.","Se você capturou Scraggy na Route 4, ele pode ter evoluído para Scrafty no nível 39. Use seus golpes do tipo Sombrio contra a equipe de Caitlin. Embora seja imune a Psychic, Scrafty também precisa tomar cuidado com Focus Blast de Reuniclus e Air Slash de Sigilyph, pois ambos são superefetivos contra ele.","Contra Reuniclus, Musharna e Gothitelle, você pode usar Leavanny com golpes do tipo Inseto. Sewaddle pode ser capturado em Pinwheel Forest e evolui para Swadloon no nível 20, depois Swadloon evolui para Leavanny ao subir de nível com amizade alta.","Tenha cuidado com Air Slash e Ice Beam de Sigilyph, pois os dois causam quatro vezes mais dano a Leavanny. Seus golpes de Inseto também causam dano normal em Sigilyph por ele ser do tipo Voador.","Para enfrentar Sigilyph, use Zebstrika ou Galvantula com golpes elétricos. Blitzle pode ser encontrado na Route 3 e evolui para Zebstrika no nível 27, enquanto Joltik pode ser capturado na Chargestone Cave e evolui para Galvantula no nível 36.","Outra opção contra Sigilyph é Boldore ou Gigalith com golpes de Pedra. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois pode evoluir para Gigalith por troca.","Se você treinou Litwick, seu Lampent ou Chandelure pode usar golpes do tipo Fantasma contra a equipe. Litwick pode ser encontrado na Celestial Tower e evolui para Lampent no nível 41, depois use uma Dusk Stone para obter Chandelure. Tenha cuidado, pois Musharna, Sigilyph e Gothitelle conhecem Shadow Ball, que é superefetivo contra ele.","Tenha cuidado com Reflect de Musharna, que reduz o dano dos golpes físicos recebidos pela equipe de Caitlin. Gothitelle pode usar Calm Mind para aumentar seu Ataque Especial e sua Defesa Especial, então tente derrotá-la antes que acumule muitos aumentos.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - MARSHAL":["Marshal é um dos integrantes da Elite Four de Unova e usa Pokémon do tipo Lutador. Seu time começa com Throh no nível 48, seguido de Sawk no nível 48, Conkeldurr no nível 48 e Mienshao no nível 50.","Os quatro recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Porém, toda a equipe conhece golpes do tipo Pedra para enfrentar Pokémon Voadores, então será necessário tomar cuidado mesmo com a vantagem de tipo.","Independentemente do inicial escolhido, você pode usar Musharna com golpes Psíquicos contra toda a equipe. Munna pode ser capturado no Dreamyard e evolui para Musharna com uma Moon Stone. Tenha cuidado contra Throh, pois ele conhece Payback, um golpe Sombrio superefetivo contra Musharna.","Outra opção é Sigilyph com Psychic ou Air Slash. Ele pode ser encontrado no Desert Resort e possui os tipos Psíquico e Voador, mas precisa tomar cuidado com Stone Edge e Rock Slide, que são superefetivos contra ele.","Se você capturou Woobat na Wellspring Cave, ele pode ter evoluído para Swoobat ao subir de nível com amizade alta. Seus golpes Psíquicos e Voadores também são superefetivos contra os quatro adversários, mas ele precisa do mesmo cuidado com os golpes de Pedra e com Payback de Throh.","Você também pode usar Unfezant com golpes Voadores. Pidove pode ser encontrado na Route 3 e evolui para Tranquill no nível 21 e para Unfezant no nível 32. Mantenha sua vida alta, pois toda a equipe de Marshal pode atingi-lo com golpes de Pedra.","Contra Sawk e Conkeldurr, Cofagrigus pode ajudar por ser imune aos golpes Lutadores e resistir aos golpes do tipo Normal que eles conhecem. Yamask pode ser capturado no Relic Castle e evolui para Cofagrigus no nível 34. Ele também pode usar Psychic, caso você tenha ensinado o golpe pela TM.","Outra opção é Golurk, que também é imune a golpes Lutadores. Golett pode ser encontrado na Dragonspiral Tower e evolui para Golurk no nível 43. Ele pode enfrentar os adversários com Fly, mas tenha cuidado com Grass Knot de Sawk e Conkeldurr, que é superefetivo contra Golurk.","Tenha cuidado com Sturdy de Sawk, que permite que ele sobreviva com um ponto de vida a um golpe que o derrotaria enquanto estiver com a vida cheia. Não conte com uma vitória em apenas um ataque sem antes considerar a possibilidade de receber um golpe em troca.","Throh conhece Storm Throw, que sempre causa um acerto crítico quando atinge o alvo, e Payback, perigoso para Pokémon Psíquicos. Ele também possui Guts, que aumenta seu Ataque caso receba uma condição de estado, então pense bem antes de tentar envenená-lo ou queimá-lo.","Mienshao conhece U-turn, que causa dano e permite que ele seja trocado se Marshal ainda tiver outro Pokémon disponível. Sawk, Conkeldurr e Mienshao também conhecem Retaliate, que causa o dobro de dano se um companheiro deles tiver sido derrotado no turno anterior.","Depois da vitória, recupere sua equipe antes de seguir em frente."],"CHAMPION":["A batalha contra Alder acontece no pós-game, depois de vencer novamente a Elite Four. Sua equipe estará mais forte nessa visita.","Alder é o Champion da Liga Pokémon de Unova e usa uma equipe com tipos variados. Seu time começa com Accelgor no nível 75, seguido de Bouffalant, Druddigon, Vanilluxe e Escavalier, todos no nível 75, e termina com Volcarona no nível 77.","Accelgor é do tipo Inseto e recebe dano superefetivo dos tipos Fogo, Voador e Pedra. Bouffalant é do tipo Normal e sua única fraqueza é o tipo Lutador.","Druddigon é do tipo Dragão e é vulnerável aos tipos Gelo e Dragão. Vanilluxe é do tipo Gelo e recebe dano superefetivo dos tipos Fogo, Lutador, Pedra e Aço.","Escavalier é dos tipos Inseto e Aço e recebe quatro vezes mais dano de golpes de Fogo. Volcarona é dos tipos Inseto e Fogo e recebe quatro vezes mais dano de golpes de Pedra, além de ser vulnerável aos tipos Água e Voador.","Se você escolheu Tepig, seu Emboar pode usar golpes de Fogo contra Accelgor, Vanilluxe e Escavalier. Ele também pode usar golpes do tipo Lutador contra Bouffalant e Vanilluxe, mas tenha cuidado com Earthquake de Bouffalant, que causa dano superefetivo em Emboar.","Independentemente do inicial escolhido, você pode usar Darmanitan com golpes de Fogo contra Accelgor, Vanilluxe e Escavalier. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35.","Para enfrentar Bouffalant e Vanilluxe, use Sawk, Throh ou Conkeldurr com golpes Lutadores. Sawk e Throh podem ser encontrados na área externa de Pinwheel Forest. No mesmo lugar, você pode capturar Timburr e evoluí-lo para Gurdurr no nível 25, depois Gurdurr evolui para Conkeldurr por troca.","Contra Druddigon, você pode usar Vanilluxe ou Beartic com golpes de Gelo. Vanillite pode ser encontrado no Cold Storage, enquanto Cubchoo aparece na Twist Mountain. Vanillite evolui para Vanillish no nível 35 e para Vanilluxe no nível 47, enquanto Cubchoo evolui para Beartic no nível 37.","Tenha cuidado contra Druddigon, pois ele conhece Superpower, um golpe do tipo Lutador que causa dano superefetivo em Vanilluxe e Beartic. Você também pode enfrentá-lo com golpes de Dragão de Haxorus, mas lembre-se de que Haxorus recebe dano superefetivo de Outrage.","Contra Volcarona, uma ótima opção é Gigalith com golpes de Pedra, aproveitando sua fraqueza de quatro vezes. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois Boldore evolui para Gigalith por troca. Boldore também pode usar golpes de Pedra caso você não tenha feito a troca.","Se você escolheu Oshawott, seu Samurott com golpes de Água também pode enfrentar Volcarona. Outra opção é Carracosta, obtido ao reviver o Cover Fossil como Tirtouga e treiná-lo até o nível 37. Por ser dos tipos Água e Pedra, Carracosta pode usar golpes dos dois tipos contra Volcarona.","Tenha cuidado com Quiver Dance de Volcarona, que aumenta seu Ataque Especial, sua Defesa Especial e sua Velocidade. Tente derrotá-lo antes que consiga usar o golpe várias vezes.","Bouffalant conhece Earthquake e Stone Edge, então tenha cuidado ao enviar Pokémon de Fogo ou Voadores contra ele. Vanilluxe pode usar Light Screen para reduzir o dano de golpes especiais e Acid Armor para aumentar sua Defesa.","Antes de voltar à Liga, treine e cure sua equipe e leve itens de recuperação. Depois de vencer Alder, ele levará você ao Hall da Fama para registrar sua equipe."]}'::jsonb WHERE slug = 'pokemon-black';
UPDATE public.builds SET caps = CASE WHEN COALESCE(cardinality(caps),0)=0 THEN ARRAY['1º GYM - CILAN, CHILI OU CRESS','2º GYM - LENORA','3º GYM - BURGH','4º GYM - ELESA','5º GYM - CLAY','6º GYM - SKYLA','7º GYM - BRYCEN','8º GYM - IRIS','ELITE FOUR - SHAUNTAL','ELITE FOUR - GRIMSLEY','ELITE FOUR - CAITLIN','ELITE FOUR - MARSHAL','CHAMPION'] ELSE caps || ARRAY(SELECT item FROM unnest(ARRAY['1º GYM - CILAN, CHILI OU CRESS','2º GYM - LENORA','3º GYM - BURGH','4º GYM - ELESA','5º GYM - CLAY','6º GYM - SKYLA','7º GYM - BRYCEN','8º GYM - IRIS','ELITE FOUR - SHAUNTAL','ELITE FOUR - GRIMSLEY','ELITE FOUR - CAITLIN','ELITE FOUR - MARSHAL','CHAMPION']) item WHERE NOT item=ANY(caps)) END, dicas = COALESCE(dicas,'{}'::jsonb) || '{"1º GYM - CILAN, CHILI OU CRESS":["O ginásio de Striaton City possui três líderes, mas você enfrentará apenas um deles. O adversário depende do inicial escolhido e sempre terá um Pokémon com vantagem de tipo contra ele.","Os três líderes começam a batalha com Lillipup no nível 12. O segundo Pokémon estará no nível 14 e será Pansage, Pansear ou Panpour, dependendo do líder.","Se você escolheu Snivy, enfrentará Chili, que usa Pansear do tipo Fogo. Se escolheu Tepig, enfrentará Cress, que usa Panpour do tipo Água. Se escolheu Oshawott, enfrentará Cilan, que usa Pansage do tipo Planta.","Antes de entrar no ginásio, visite o Dreamyard, a leste de Striaton City, e converse com a garota próxima às ruínas. Ela entregará um Pokémon no nível 10 que tem vantagem contra o Pokémon principal do líder.","Se você escolheu Snivy, receberá Panpour. Use Water Gun contra o Pansear de Chili.","Se você escolheu Tepig, receberá Pansage. Use Vine Whip contra o Panpour de Cress.","Se você escolheu Oshawott, receberá Pansear. Use Incinerate contra o Pansage de Cilan.","Contra Lillipup, você pode usar seu inicial ou um Pokémon capturado nas primeiras rotas, como Lillipup ou Patrat. Aproveite essa parte da batalha para manter o Pokémon recebido no Dreamyard com bastante vida para enfrentar o segundo adversário.","Tenha cuidado com Work Up, que aumenta o Ataque e o Ataque Especial do usuário. Se o adversário usar o golpe várias vezes, seus ataques podem ficar perigosos, então tente derrotá-lo antes que acumule muitos aumentos.","Antes da batalha, treine sua equipe, cure seus Pokémon e leve algumas Potions. Depois da vitória, você receberá a Trio Badge e a TM83 Work Up."],"2º GYM - LENORA":["Lenora é a líder do ginásio de Nacrene City e usa Pokémon do tipo Normal. Seu time começa com Herdier no nível 18 e termina com Watchog no nível 20.","Os dois recebem dano superefetivo de golpes do tipo Lutador e são imunes a golpes do tipo Fantasma.","Se você escolheu Tepig, treine-o até o nível 17 para evoluí-lo em Pignite. Ele passa a ser dos tipos Fogo e Lutador e aprende Arm Thrust, um golpe que pode atingir o adversário de duas a cinco vezes.","Independentemente do inicial escolhido, você pode capturar Timburr na área externa de Pinwheel Forest, a oeste de Nacrene City. Ele aprende Low Kick no nível 12 e pode usá-lo contra os dois Pokémon de Lenora. No nível 20, Timburr também aprende Wake-Up Slap.","Outra opção é capturar Sawk ou Throh na área externa de Pinwheel Forest. Em Black, Sawk aparece na grama comum e Throh é mais raro, encontrado na grama que se agita. Em White, acontece o contrário. Os dois são do tipo Lutador e podem aproveitar a fraqueza da equipe de Lenora.","Se você capturou Roggenrola na Wellspring Cave, ele pode ajudar a proteger sua equipe por resistir a golpes do tipo Normal. Se possuir a habilidade Sturdy e estiver com a vida cheia, poderá sobreviver a um golpe que o derrotaria, mas ainda será necessário recuperar sua vida depois.","Tenha cuidado com Retaliate, que os dois Pokémon de Lenora conhecem. O golpe causa o dobro de dano se um companheiro tiver sido derrotado no turno anterior, então mantenha sua equipe com bastante vida ao derrotar o primeiro adversário.","Herdier possui Intimidate, que reduz o Ataque do seu Pokémon ao entrar em campo. Os dois adversários também podem usar Leer para reduzir sua Defesa, aumentando o perigo dos golpes físicos de Lenora.","Watchog ainda conhece Hypnosis, que pode colocar seu Pokémon para dormir. Você pode equipar uma Chesto Berry para acordá-lo caso seja atingido.","Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para se preparar. Depois da vitória, você receberá a Basic Badge e a TM67 Retaliate."],"3º GYM - BURGH":["Burgh é o líder do ginásio de Castelia City e usa Pokémon do tipo Inseto. Seu time começa com Whirlipede no nível 21, seguido de Dwebble no nível 21 e Leavanny no nível 23.","Whirlipede é dos tipos Inseto e Veneno e recebe dano superefetivo de golpes dos tipos Fogo, Voador, Pedra e Psíquico. Dwebble é dos tipos Inseto e Pedra e é vulnerável aos tipos Água, Pedra e Aço.","Leavanny é dos tipos Inseto e Planta e recebe quatro vezes mais dano de golpes dos tipos Fogo e Voador. Ele também é vulnerável aos tipos Gelo, Veneno, Pedra e Inseto.","Se você escolheu Tepig, seu Pignite pode usar Flame Charge contra Whirlipede e Leavanny. Tenha cuidado contra Dwebble, pois ele conhece Smack Down, um golpe de Pedra que causa dano superefetivo em Pignite.","Se você escolheu Oshawott, seu Dewott pode usar golpes de Água contra Dwebble. Mantenha-o longe de Leavanny, pois Razor Leaf causa dano superefetivo nele.","Se você escolheu Snivy, tenha cuidado ao usar seu Servine nessa batalha. Toda a equipe de Burgh conhece golpes do tipo Inseto, e Whirlipede também possui um golpe do tipo Veneno.","Independentemente do inicial escolhido, Roggenrola é uma boa opção com golpes do tipo Pedra contra os três adversários. Ele pode ser capturado na Wellspring Cave, na Route 3, e evolui para Boldore no nível 25. Tome cuidado contra Leavanny, pois Razor Leaf é superefetivo contra Roggenrola.","Você também pode capturar Pidove na Route 3. Treine-o até o nível 21 para evoluí-lo em Tranquill e use golpes do tipo Voador contra Whirlipede e Leavanny. Evite deixá-lo contra Dwebble, pois Smack Down causa dano superefetivo nele.","Se você escolheu Oshawott e recebeu Pansear no Dreamyard, ele pode usar golpes de Fogo contra Whirlipede e Leavanny. Já se escolheu Snivy e recebeu Panpour, ele pode usar golpes de Água contra Dwebble.","Outra opção contra Whirlipede é Munna com Psybeam. Munna pode ser encontrado no Dreamyard e aprende o golpe no nível 19, mas tenha cuidado com Pursuit, que causa dano superefetivo nele e fica mais forte se Munna tentar sair da batalha naquele turno.","Tenha cuidado com Struggle Bug, que toda a equipe de Burgh conhece e que reduz o Ataque Especial do alvo. Dwebble também pode usar Sand Attack para reduzir sua precisão, enquanto Leavanny pode usar Protect para se proteger de um ataque.","Se você capturou Woobat na Wellspring Cave, ele pode usar Confusion contra Whirlipede e Air Cutter contra Leavanny. Woobat aprende Air Cutter no nível 21, e o golpe causa quatro vezes mais dano a Leavanny.","Tenha cuidado com Pursuit de Whirlipede, que é superefetivo contra Woobat e causa mais dano se ele tentar sair da batalha naquele turno. Evite usá-lo contra Dwebble, pois Smack Down também é superefetivo contra ele.","Whirlipede conhece Poison Tail, que pode envenenar seu Pokémon. Leavanny conhece Razor Leaf, então evite deixar Pokémon vulneráveis a Planta contra ele.","Antes da batalha, cure sua equipe e leve algumas Potions e Antidotes. Depois da vitória, você receberá a Insect Badge e a TM76 Struggle Bug."],"4º GYM - ELESA":["Elesa é a líder do ginásio de Nimbasa City e usa Pokémon do tipo Elétrico. Seu time começa com duas Emolga no nível 25 e termina com Zebstrika no nível 27.","As duas Emolga são dos tipos Elétrico e Voador e recebem dano superefetivo de golpes dos tipos Pedra e Gelo. Por serem do tipo Voador, elas são imunes a golpes do tipo Terra.","Zebstrika é do tipo Elétrico e sua única fraqueza é o tipo Terra.","Independentemente do inicial escolhido, você pode usar Roggenrola ou Boldore com golpes do tipo Pedra contra as duas Emolga. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25.","Outra opção é Sandile, encontrado na Route 4 e no Desert Resort. Ele evolui para Krokorok no nível 29 e pode usar golpes de Terra contra Zebstrika. Por ser do tipo Terra, Sandile também é imune aos golpes elétricos de toda a equipe de Elesa.","Para enfrentar as Emolga com Sandile, ensine a ele Rock Tomb pela TM39, encontrada no Desert Resort. O golpe do tipo Pedra é superefetivo contra as duas e ainda reduz a Velocidade do alvo.","Se você encontrou Drilbur nas nuvens de poeira da Wellspring Cave, ele também pode enfrentar Zebstrika com Dig, aprendido no nível 19. Drilbur é imune a golpes elétricos e pode aprender Rock Tomb para enfrentar as Emolga.","Outra opção contra Zebstrika é Palpitoad com Mud Shot. Timburr não é o único Pokémon útil na área externa de Pinwheel Forest, pois você também pode capturar Tympole por lá e treiná-lo até o nível 25 para evoluí-lo. Palpitoad é dos tipos Água e Terra e também é imune aos golpes elétricos da equipe.","Se você escolheu Snivy, seu Servine resiste aos golpes elétricos, mas tome cuidado com Aerial Ace das Emolga e Flame Charge de Zebstrika, pois ambos são superefetivos contra ele. Se escolheu Oshawott, evite deixar seu Dewott contra os ataques elétricos de Elesa.","Tenha cuidado com Volt Switch, que toda a equipe de Elesa conhece. Depois de causar dano, o golpe permite que o Pokémon seja trocado, então prepare-se para as mudanças durante a batalha. Um Pokémon do tipo Terra é imune ao ataque e impede a troca quando Volt Switch não consegue atingi-lo.","As duas Emolga também conhecem Pursuit, que causa mais dano se atingir seu Pokémon enquanto ele está sendo trocado. Zebstrika conhece Flame Charge, que aumenta sua Velocidade a cada uso.","Antes da batalha, cure sua equipe e leve algumas Potions e Paralyze Heals. Depois da vitória, você receberá a Bolt Badge e a TM72 Volt Switch."],"5º GYM - CLAY":["Clay é o líder do ginásio de Driftveil City e usa Pokémon do tipo Terra. Seu time começa com Krokorok no nível 29, seguido de Palpitoad no nível 29 e termina com Excadrill no nível 31.","Krokorok é dos tipos Terra e Sombrio e recebe dano superefetivo de golpes dos tipos Água, Planta, Gelo, Lutador e Inseto. Palpitoad é dos tipos Água e Terra e sua única fraqueza é o tipo Planta, que causa quatro vezes mais dano nele.","Excadrill é dos tipos Terra e Aço e recebe dano superefetivo de golpes dos tipos Água, Fogo, Lutador e Terra.","Se você escolheu Snivy, seu Servine pode usar golpes de Planta contra Krokorok e Palpitoad. Aproveite a fraqueza de quatro vezes de Palpitoad para tentar derrotá-lo rapidamente.","Se você escolheu Oshawott, seu Dewott com Razor Shell pode enfrentar Krokorok e Excadrill. Contra Palpitoad, escolha um Pokémon com golpes de Planta para aproveitar sua fraqueza.","Se você escolheu Tepig, seu Pignite com Arm Thrust pode enfrentar Krokorok e Excadrill. Tenha cuidado, pois os golpes do tipo Terra de Clay causam dano superefetivo em Pignite.","Se você escolheu Tepig, ainda pode usar o Pansage recebido da garota no Dreamyard, a leste de Striaton City. Use Vine Whip contra Krokorok e Palpitoad.","Outra opção, independentemente do inicial, é capturar Pansage ou Panpour na grama que se agita dentro de Pinwheel Forest. Pansage pode enfrentar Krokorok e Palpitoad com golpes de Planta, enquanto Panpour pode usar golpes de Água contra Krokorok e Excadrill.","Outra opção contra Krokorok e Palpitoad é Sewaddle ou Swadloon com golpes de Planta. Sewaddle pode ser encontrado em Pinwheel Forest e evolui para Swadloon no nível 20.","Para enfrentar Krokorok e Excadrill, use Tympole ou Palpitoad com golpes de Água. Tympole pode ser capturado na área externa de Pinwheel Forest e evolui para Palpitoad no nível 25. Contra o Palpitoad de Clay, prefira golpes de Planta, pois ele resiste a golpes de Água.","Se você capturou Timburr em Pinwheel Forest, ele pode ter evoluído para Gurdurr no nível 25. Seus golpes do tipo Lutador são superefetivos contra Krokorok e Excadrill. Sawk e Throh, encontrados na mesma área, também são opções para essas duas batalhas.","Você também pode usar Drilbur com Dig contra Excadrill. Drilbur aparece nas nuvens de poeira da Wellspring Cave e aprende Dig no nível 19, mas tenha cuidado, pois o Excadrill de Clay também conhece um golpe do tipo Terra.","Tenha cuidado com Bulldoze, que reduz a Velocidade do Pokémon atingido. Krokorok possui Intimidate, que reduz o Ataque do seu Pokémon ao entrar em campo, enquanto Palpitoad pode usar Aqua Ring para recuperar um pouco de vida a cada turno.","O maior perigo é Excadrill, que pode usar Hone Claws para aumentar seu Ataque e sua precisão. Ele também conhece Rock Slide, um golpe de Pedra perigoso para Pokémon do tipo Voador, mesmo que eles sejam imunes a Bulldoze.","Antes da batalha, cure sua equipe e leve algumas Potions para recuperar seus Pokémon. Depois da vitória, você receberá a Quake Badge."],"6º GYM - SKYLA":["Skyla é a líder do ginásio de Mistralton City e usa Pokémon do tipo Voador. Seu time começa com Swoobat no nível 33, seguido de Unfezant no nível 33 e termina com Swanna no nível 35.","Os três recebem dano superefetivo de golpes dos tipos Elétrico e Pedra. Swoobat e Unfezant também são vulneráveis ao tipo Gelo, enquanto Swanna recebe quatro vezes mais dano de golpes elétricos por ser dos tipos Água e Voador.","Independentemente do inicial escolhido, você pode usar Zebstrika com golpes elétricos contra toda a equipe. Blitzle pode ser capturado na Route 3 e evolui para Zebstrika no nível 27. Ele também pode ser encontrado na Route 7, próxima a Mistralton City.","Outra opção é Joltik, que pode ser capturado na Chargestone Cave, a caverna que atravessamos antes de chegar a Mistralton. Use seus golpes elétricos contra os três Pokémon de Skyla, especialmente Swanna.","Se você treinou Roggenrola ou Boldore desde a Wellspring Cave, seus golpes de Pedra também são superefetivos contra toda a equipe. Contudo, tenha cuidado com Swanna, pois BubbleBeam causa dano superefetivo nos dois.","Você também pode usar Vanillite ou Vanillish com golpes de Gelo contra Swoobat e Unfezant. Vanillite pode ser encontrado na área de grama do Cold Storage, ao sul de Driftveil City, e evolui para Vanillish no nível 35.","Se você capturou Sandile na Route 4, ele pode ter evoluído para Krokorok no nível 29. Seus golpes do tipo Sombrio são superefetivos contra Swoobat, mas não use golpes do tipo Terra contra a equipe de Skyla, pois os três Pokémon são imunes a eles.","Se você escolheu Snivy, tenha cuidado ao usar Servine, pois os golpes Voadores da equipe de Skyla são superefetivos contra ele. O mesmo vale para Pignite, caso tenha escolhido Tepig, por ele também ser do tipo Lutador.","Tenha cuidado com Acrobatics de Swoobat, que pode causar bastante dano, e com Heart Stamp, que pode fazer seu Pokémon recuar e perder o turno. Unfezant também conhece Air Slash, que possui a mesma chance de impedir o alvo de agir naquele turno.","Swanna pode usar Aqua Ring para recuperar um pouco de vida a cada turno. Tente derrotá-lo com um golpe elétrico antes que ele tenha muitas oportunidades de atacar ou se recuperar.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Jet Badge e a TM62 Acrobatics."],"7º GYM - BRYCEN":["Brycen é o líder do ginásio de Icirrus City e usa Pokémon do tipo Gelo. Seu time começa com Vanillish no nível 37, seguido de Cryogonal no nível 37 e termina com Beartic no nível 39.","Os três recebem dano superefetivo de golpes dos tipos Fogo, Lutador, Pedra e Aço.","Se você escolheu Tepig, seu Pignite pode usar golpes de Fogo ou Lutador contra toda a equipe. Se treinou seu inicial até o nível 36, ele terá evoluído para Emboar. Tenha cuidado contra Beartic, pois ele conhece Brine, um golpe de Água superefetivo contra Pignite e Emboar.","Independentemente do inicial escolhido, você pode usar Darmanitan com golpes de Fogo. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35. Assim como Pignite e Emboar, ele precisa tomar cuidado com Brine de Beartic.","Outra opção de Fogo é Pansear ou Simisear. Pansear pode ser recebido no Dreamyard se você escolheu Oshawott ou encontrado na grama que se agita dentro de Pinwheel Forest. Para evoluí-lo em Simisear, use uma Fire Stone.","Se você treinou Timburr desde Pinwheel Forest, ele pode ter evoluído para Gurdurr no nível 25. Use seus golpes do tipo Lutador contra a equipe de Brycen. Se puder fazer uma troca, Gurdurr também pode evoluir para Conkeldurr.","Sawk e Throh são outras opções do tipo Lutador. Os dois podem ser encontrados na área externa de Pinwheel Forest, embora a frequência deles varie entre Black e White.","Se você capturou Drilbur nas nuvens de poeira da Wellspring Cave ou da Chargestone Cave, ele pode ter evoluído para Excadrill no nível 31. Use seus golpes do tipo Aço contra os três adversários, mas tome cuidado com Brine de Beartic, que também é superefetivo contra Excadrill.","Boldore ou Gigalith com golpes de Pedra também podem aproveitar a fraqueza dos três Pokémon. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois pode evoluir para Gigalith por troca. Mantenha cuidado contra Beartic por causa de Brine.","Tenha cuidado com Frost Breath, conhecido por Vanillish e Cryogonal. Quando acerta, o golpe causa um acerto crítico. Vanillish também pode usar Acid Armor para aumentar bastante sua Defesa, enquanto Cryogonal pode usar Reflect para reduzir o dano dos golpes físicos recebidos pela equipe.","Beartic conhece Swagger, que aumenta o Ataque do seu Pokémon, mas também o deixa confuso. Seu golpe Brine causa ainda mais dano se o alvo estiver com metade da vida ou menos, então mantenha seus Pokémon saudáveis durante a batalha.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Freeze Badge e a TM79 Frost Breath."],"ELITE FOUR - SHAUNTAL":["Shauntal é uma das integrantes da Elite Four de Unova e usa Pokémon do tipo Fantasma. Seu time começa com Cofagrigus no nível 48, seguido de Jellicent no nível 48, Golurk no nível 48 e Chandelure no nível 50.","Os quatro recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma e são imunes a golpes dos tipos Normal e Lutador. Por causa de seus outros tipos, Jellicent, Golurk e Chandelure também possuem outras fraquezas.","Cofagrigus é do tipo Fantasma. Jellicent também é do tipo Água e recebe dano superefetivo dos tipos Elétrico e Planta.","Golurk também é do tipo Terra e é vulnerável aos tipos Água, Planta e Gelo. Chandelure é dos tipos Fantasma e Fogo e recebe dano superefetivo dos tipos Água, Terra e Pedra.","Independentemente do inicial escolhido, você pode usar Krookodile com Crunch contra os quatro Pokémon de Shauntal. Sandile pode ser capturado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40.","Krookodile também pode usar golpes de Terra contra Chandelure, mas tenha cuidado contra Jellicent, pois seus golpes de Água causam quatro vezes mais dano em Krookodile. Cofagrigus também conhece Grass Knot, que é superefetivo contra ele.","Outra opção contra Cofagrigus é Liepard com golpes do tipo Sombrio. Purrloin pode ser encontrado nas primeiras rotas da jornada e evolui para Liepard no nível 20. Mantenha cuidado com Will-O-Wisp, pois a queimadura reduz o Ataque de Liepard e de outros Pokémon que dependem de golpes físicos.","Contra Jellicent, use Zebstrika com golpes elétricos. Blitzle pode ser encontrado na Route 3 e evolui para Zebstrika no nível 27. Se você capturou Joltik na Chargestone Cave, seu Galvantula também pode aproveitar a fraqueza de Jellicent com golpes elétricos.","Se você escolheu Snivy, seu Serperior pode usar golpes de Planta contra Jellicent e Golurk. Outra opção é Leavanny, evoluído de Sewaddle, encontrado em Pinwheel Forest. Sewaddle evolui para Swadloon no nível 20, e Swadloon evolui para Leavanny ao subir de nível com amizade alta.","Para enfrentar Golurk, você também pode usar Vanillish ou Beartic com golpes de Gelo. Vanillite pode ser encontrado no Cold Storage e evolui para Vanillish no nível 35, enquanto Cubchoo pode ser encontrado na Twist Mountain e evolui para Beartic no nível 37.","Se você escolheu Oshawott, seu Samurott com golpes de Água pode enfrentar Golurk e Chandelure. Seismitoad, evoluído de Tympole, também pode usar golpes de Água contra os dois, mas evite deixá-lo contra Jellicent, pois Energy Ball causa quatro vezes mais dano nele.","Contra Chandelure, Boldore ou Gigalith com golpes de Pedra são outras opções. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois pode evoluir para Gigalith por troca.","Tenha cuidado com Earthquake de Golurk, que pode causar muito dano, e com Fire Blast de Chandelure, um golpe de Fogo forte. Cofagrigus e Jellicent também conhecem golpes de Planta, então escolha com cuidado quais Pokémon de Água e Terra enviar contra eles.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four. Em Unova, você pode escolher a ordem das quatro batalhas."],"ELITE FOUR - GRIMSLEY":["Grimsley é um dos integrantes da Elite Four de Unova e usa Pokémon do tipo Sombrio. Seu time começa com Scrafty no nível 48, seguido de Liepard no nível 48, Krookodile no nível 48 e Bisharp no nível 50.","Scrafty é dos tipos Sombrio e Lutador e recebe dano superefetivo de golpes dos tipos Lutador e Voador. Liepard é do tipo Sombrio e é vulnerável aos tipos Lutador e Inseto.","Krookodile também é do tipo Terra e recebe dano superefetivo dos tipos Água, Planta, Gelo, Lutador e Inseto. Bisharp também é do tipo Aço e recebe quatro vezes mais dano de golpes Lutadores, além de ser vulnerável aos tipos Fogo e Terra.","Se você escolheu Tepig, seu Emboar com golpes do tipo Lutador pode enfrentar toda a equipe de Grimsley. Ele também pode usar golpes de Fogo contra Bisharp, mas tenha cuidado contra Krookodile, pois Earthquake causa dano superefetivo em Emboar.","Independentemente do inicial escolhido, você pode usar Sawk ou Throh com golpes Lutadores contra os quatro adversários. Os dois podem ser encontrados na área externa de Pinwheel Forest, embora a frequência deles varie entre Black e White.","Outra opção é Gurdurr ou Conkeldurr. Timburr pode ser capturado na área externa de Pinwheel Forest e evolui para Gurdurr no nível 25, depois pode evoluir para Conkeldurr por troca. Tenha cuidado contra Liepard e Bisharp, pois ambos conhecem Aerial Ace, que causa dano superefetivo em Pokémon do tipo Lutador.","Contra Scrafty, você pode usar Unfezant com golpes Voadores. Pidove pode ser encontrado na Route 3 e evolui para Tranquill no nível 21 e para Unfezant no nível 32.","Outra opção contra Scrafty é Swanna. Ducklett pode ser encontrado nas sombras que aparecem na Driftveil Drawbridge e evolui para Swanna no nível 35. Ele também pode enfrentar Krookodile com golpes de Água, mas tome cuidado com Dragon Claw.","Se você escolheu Oshawott ou Snivy, seu inicial já pode estar em sua forma final, Samurott ou Serperior. Os dois podem aproveitar as fraquezas de Krookodile, usando golpes de Água ou Planta, respectivamente.","Contra Bisharp, você também pode usar Darmanitan com golpes de Fogo ou Excadrill com golpes de Terra. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35, enquanto Drilbur pode ser encontrado nas nuvens de poeira de cavernas e evolui para Excadrill no nível 31.","Tenha cuidado com Moxie de Scrafty, que aumenta seu Ataque sempre que ele derrota um Pokémon. Krookodile possui Intimidate, que reduz o Ataque do seu Pokémon quando ele entra em campo, e conhece Earthquake, um golpe forte do tipo Terra.","Liepard pode usar Attract para dificultar os ataques de um Pokémon do sexo oposto. Bisharp possui Defiant, que aumenta seu Ataque quando uma de suas características é reduzida, então tenha cuidado ao usar Pokémon com Intimidate contra ele.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - CAITLIN":["Caitlin é uma das integrantes da Elite Four de Unova e usa Pokémon do tipo Psíquico. Seu time começa com Reuniclus no nível 48, seguido de Musharna no nível 48, Sigilyph no nível 48 e Gothitelle no nível 50.","Reuniclus, Musharna e Gothitelle recebem dano superefetivo de golpes dos tipos Sombrio, Fantasma e Inseto. Sigilyph também é do tipo Voador e é vulnerável aos tipos Sombrio, Fantasma, Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, você pode usar Krookodile com Crunch contra toda a equipe. Sandile pode ser encontrado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40.","Por ser do tipo Sombrio, Krookodile é imune aos golpes Psíquicos de Caitlin. Porém, tenha muito cuidado com Focus Blast de Reuniclus, que é superefetivo contra ele, e com Ice Beam de Sigilyph, que causa quatro vezes mais dano a Krookodile.","Outra opção é Liepard com golpes do tipo Sombrio. Purrloin pode ser encontrado nas primeiras rotas e evolui para Liepard no nível 20. Assim como Krookodile, ele é imune aos golpes Psíquicos, mas precisa tomar cuidado com Focus Blast de Reuniclus.","Se você capturou Scraggy na Route 4, ele pode ter evoluído para Scrafty no nível 39. Use seus golpes do tipo Sombrio contra a equipe de Caitlin. Embora seja imune a Psychic, Scrafty também precisa tomar cuidado com Focus Blast de Reuniclus e Air Slash de Sigilyph, pois ambos são superefetivos contra ele.","Contra Reuniclus, Musharna e Gothitelle, você pode usar Leavanny com golpes do tipo Inseto. Sewaddle pode ser capturado em Pinwheel Forest e evolui para Swadloon no nível 20, depois Swadloon evolui para Leavanny ao subir de nível com amizade alta.","Tenha cuidado com Air Slash e Ice Beam de Sigilyph, pois os dois causam quatro vezes mais dano a Leavanny. Seus golpes de Inseto também causam dano normal em Sigilyph por ele ser do tipo Voador.","Para enfrentar Sigilyph, use Zebstrika ou Galvantula com golpes elétricos. Blitzle pode ser encontrado na Route 3 e evolui para Zebstrika no nível 27, enquanto Joltik pode ser capturado na Chargestone Cave e evolui para Galvantula no nível 36.","Outra opção contra Sigilyph é Boldore ou Gigalith com golpes de Pedra. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois pode evoluir para Gigalith por troca.","Se você treinou Litwick, seu Lampent ou Chandelure pode usar golpes do tipo Fantasma contra a equipe. Litwick pode ser encontrado na Celestial Tower e evolui para Lampent no nível 41, depois use uma Dusk Stone para obter Chandelure. Tenha cuidado, pois Musharna, Sigilyph e Gothitelle conhecem Shadow Ball, que é superefetivo contra ele.","Tenha cuidado com Reflect de Musharna, que reduz o dano dos golpes físicos recebidos pela equipe de Caitlin. Gothitelle pode usar Calm Mind para aumentar seu Ataque Especial e sua Defesa Especial, então tente derrotá-la antes que acumule muitos aumentos.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - MARSHAL":["Marshal é um dos integrantes da Elite Four de Unova e usa Pokémon do tipo Lutador. Seu time começa com Throh no nível 48, seguido de Sawk no nível 48, Conkeldurr no nível 48 e Mienshao no nível 50.","Os quatro recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Porém, toda a equipe conhece golpes do tipo Pedra para enfrentar Pokémon Voadores, então será necessário tomar cuidado mesmo com a vantagem de tipo.","Independentemente do inicial escolhido, você pode usar Musharna com golpes Psíquicos contra toda a equipe. Munna pode ser capturado no Dreamyard e evolui para Musharna com uma Moon Stone. Tenha cuidado contra Throh, pois ele conhece Payback, um golpe Sombrio superefetivo contra Musharna.","Outra opção é Sigilyph com Psychic ou Air Slash. Ele pode ser encontrado no Desert Resort e possui os tipos Psíquico e Voador, mas precisa tomar cuidado com Stone Edge e Rock Slide, que são superefetivos contra ele.","Se você capturou Woobat na Wellspring Cave, ele pode ter evoluído para Swoobat ao subir de nível com amizade alta. Seus golpes Psíquicos e Voadores também são superefetivos contra os quatro adversários, mas ele precisa do mesmo cuidado com os golpes de Pedra e com Payback de Throh.","Você também pode usar Unfezant com golpes Voadores. Pidove pode ser encontrado na Route 3 e evolui para Tranquill no nível 21 e para Unfezant no nível 32. Mantenha sua vida alta, pois toda a equipe de Marshal pode atingi-lo com golpes de Pedra.","Contra Sawk e Conkeldurr, Cofagrigus pode ajudar por ser imune aos golpes Lutadores e resistir aos golpes do tipo Normal que eles conhecem. Yamask pode ser capturado no Relic Castle e evolui para Cofagrigus no nível 34. Ele também pode usar Psychic, caso você tenha ensinado o golpe pela TM.","Outra opção é Golurk, que também é imune a golpes Lutadores. Golett pode ser encontrado na Dragonspiral Tower e evolui para Golurk no nível 43. Ele pode enfrentar os adversários com Fly, mas tenha cuidado com Grass Knot de Sawk e Conkeldurr, que é superefetivo contra Golurk.","Tenha cuidado com Sturdy de Sawk, que permite que ele sobreviva com um ponto de vida a um golpe que o derrotaria enquanto estiver com a vida cheia. Não conte com uma vitória em apenas um ataque sem antes considerar a possibilidade de receber um golpe em troca.","Throh conhece Storm Throw, que sempre causa um acerto crítico quando atinge o alvo, e Payback, perigoso para Pokémon Psíquicos. Ele também possui Guts, que aumenta seu Ataque caso receba uma condição de estado, então pense bem antes de tentar envenená-lo ou queimá-lo.","Mienshao conhece U-turn, que causa dano e permite que ele seja trocado se Marshal ainda tiver outro Pokémon disponível. Sawk, Conkeldurr e Mienshao também conhecem Retaliate, que causa o dobro de dano se um companheiro deles tiver sido derrotado no turno anterior.","Depois da vitória, recupere sua equipe antes de seguir em frente."],"CHAMPION":["A batalha contra Alder acontece no pós-game, depois de vencer novamente a Elite Four. Sua equipe estará mais forte nessa visita.","Alder é o Champion da Liga Pokémon de Unova e usa uma equipe com tipos variados. Seu time começa com Accelgor no nível 75, seguido de Bouffalant, Druddigon, Vanilluxe e Escavalier, todos no nível 75, e termina com Volcarona no nível 77.","Accelgor é do tipo Inseto e recebe dano superefetivo dos tipos Fogo, Voador e Pedra. Bouffalant é do tipo Normal e sua única fraqueza é o tipo Lutador.","Druddigon é do tipo Dragão e é vulnerável aos tipos Gelo e Dragão. Vanilluxe é do tipo Gelo e recebe dano superefetivo dos tipos Fogo, Lutador, Pedra e Aço.","Escavalier é dos tipos Inseto e Aço e recebe quatro vezes mais dano de golpes de Fogo. Volcarona é dos tipos Inseto e Fogo e recebe quatro vezes mais dano de golpes de Pedra, além de ser vulnerável aos tipos Água e Voador.","Se você escolheu Tepig, seu Emboar pode usar golpes de Fogo contra Accelgor, Vanilluxe e Escavalier. Ele também pode usar golpes do tipo Lutador contra Bouffalant e Vanilluxe, mas tenha cuidado com Earthquake de Bouffalant, que causa dano superefetivo em Emboar.","Independentemente do inicial escolhido, você pode usar Darmanitan com golpes de Fogo contra Accelgor, Vanilluxe e Escavalier. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35.","Para enfrentar Bouffalant e Vanilluxe, use Sawk, Throh ou Conkeldurr com golpes Lutadores. Sawk e Throh podem ser encontrados na área externa de Pinwheel Forest. No mesmo lugar, você pode capturar Timburr e evoluí-lo para Gurdurr no nível 25, depois Gurdurr evolui para Conkeldurr por troca.","Contra Druddigon, você pode usar Vanilluxe ou Beartic com golpes de Gelo. Vanillite pode ser encontrado no Cold Storage, enquanto Cubchoo aparece na Twist Mountain. Vanillite evolui para Vanillish no nível 35 e para Vanilluxe no nível 47, enquanto Cubchoo evolui para Beartic no nível 37.","Tenha cuidado contra Druddigon, pois ele conhece Superpower, um golpe do tipo Lutador que causa dano superefetivo em Vanilluxe e Beartic. Você também pode enfrentá-lo com golpes de Dragão de Haxorus, mas lembre-se de que Haxorus recebe dano superefetivo de Outrage.","Contra Volcarona, uma ótima opção é Gigalith com golpes de Pedra, aproveitando sua fraqueza de quatro vezes. Roggenrola pode ser capturado na Wellspring Cave e evolui para Boldore no nível 25, depois Boldore evolui para Gigalith por troca. Boldore também pode usar golpes de Pedra caso você não tenha feito a troca.","Se você escolheu Oshawott, seu Samurott com golpes de Água também pode enfrentar Volcarona. Outra opção é Carracosta, obtido ao reviver o Cover Fossil como Tirtouga e treiná-lo até o nível 37. Por ser dos tipos Água e Pedra, Carracosta pode usar golpes dos dois tipos contra Volcarona.","Tenha cuidado com Quiver Dance de Volcarona, que aumenta seu Ataque Especial, sua Defesa Especial e sua Velocidade. Tente derrotá-lo antes que consiga usar o golpe várias vezes.","Bouffalant conhece Earthquake e Stone Edge, então tenha cuidado ao enviar Pokémon de Fogo ou Voadores contra ele. Vanilluxe pode usar Light Screen para reduzir o dano de golpes especiais e Acid Armor para aumentar sua Defesa.","Antes de voltar à Liga, treine e cure sua equipe e leve itens de recuperação. Depois de vencer Alder, ele levará você ao Hall da Fama para registrar sua equipe."]}'::jsonb WHERE slug = 'pokemon-white';


-- Builds de Black 2 e White 2.
UPDATE public.builds SET caps = CASE WHEN COALESCE(cardinality(caps),0)=0 THEN ARRAY['1º GYM - CHEREN','2º GYM - ROXIE','3º GYM - BURGH','4º GYM - ELESA','5º GYM - CLAY','6º GYM - SKYLA','7º GYM - DRAYDEN','8º GYM - MARLON','ELITE FOUR - SHAUNTAL','ELITE FOUR - GRIMSLEY','ELITE FOUR - CAITLIN','ELITE FOUR - MARSHAL','CHAMPION'] ELSE caps || ARRAY(SELECT item FROM unnest(ARRAY['1º GYM - CHEREN','2º GYM - ROXIE','3º GYM - BURGH','4º GYM - ELESA','5º GYM - CLAY','6º GYM - SKYLA','7º GYM - DRAYDEN','8º GYM - MARLON','ELITE FOUR - SHAUNTAL','ELITE FOUR - GRIMSLEY','ELITE FOUR - CAITLIN','ELITE FOUR - MARSHAL','CHAMPION']) item WHERE NOT item=ANY(caps)) END, dicas=COALESCE(dicas,'{}'::jsonb) || '{"1º GYM - CHEREN":["Cheren é o líder do ginásio de Aspertia City e usa Pokémon do tipo Normal. Seu time começa com Patrat no nível 11 e termina com Lillipup no nível 13.","Os dois recebem dano superefetivo de golpes do tipo Lutador e são imunes a golpes do tipo Fantasma.","Independentemente do inicial escolhido, você pode capturar Riolu no Floccesy Ranch. Treine-o até o nível 15 para aprender Force Palm, um golpe do tipo Lutador que tem vantagem contra os dois Pokémon de Cheren.","Se você ainda não quiser treinar Riolu até o nível 15, pode usar seu inicial, seja Snivy, Tepig ou Oshawott, com seus golpes mais fortes. Mantenha a vida dele alta e tenha outro Pokémon preparado para ajudar durante a batalha.","Outra opção é capturar Lillipup ou Patrat nas primeiras áreas da jornada. Os dois podem ajudar a enfrentar a equipe de Cheren e dividir a batalha com seu inicial.","Tenha cuidado com Work Up, que aumenta o Ataque e o Ataque Especial do usuário. Os dois Pokémon de Cheren conhecem o golpe, então tente derrotá-los antes que acumulem muitos aumentos.","Patrat e Lillipup também conhecem Bite, que pode fazer seu Pokémon recuar e perder o turno caso seja mais lento. Patrat ainda pode usar Detect para se proteger de um ataque.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Basic Badge e a TM83 Work Up."],"2º GYM - ROXIE":["Roxie é a líder do ginásio de Virbank City e usa Pokémon do tipo Veneno. Seu time começa com Koffing no nível 16 e termina com Whirlipede no nível 18.","Koffing recebe dano superefetivo de golpes do tipo Psíquico. Embora seja do tipo Veneno, sua habilidade Levitate o torna imune a golpes do tipo Terra.","Whirlipede é dos tipos Inseto e Veneno e recebe dano superefetivo dos tipos Fogo, Voador, Pedra e Psíquico.","Independentemente do inicial escolhido, você pode usar Psyduck com Confusion contra os dois Pokémon de Roxie. Psyduck pode ser encontrado no Floccesy Ranch e aprende Confusion no nível 15.","Outra opção é Magnemite, encontrado no Virbank Complex, ao sul da cidade. Por ser dos tipos Elétrico e Aço, ele é imune aos golpes do tipo Veneno de Roxie. Magnemite pode usar Sonic Boom, que causa 20 pontos de dano quando acerta, para enfrentar os dois adversários.","Se você escolheu Tepig, treine-o até o nível 17 para evoluí-lo em Pignite. Use seus golpes de Fogo contra Whirlipede e mantenha cuidado caso ele seja envenenado.","Você também pode capturar Growlithe no Virbank Complex e usar seus golpes de Fogo contra Whirlipede. Em Black 2, outra opção disponível no complexo é Magby.","Se você capturou Pidove na Route 20, seus golpes do tipo Voador também são superefetivos contra Whirlipede. Tenha cuidado com Pursuit, que causa mais dano se atingir Pidove enquanto ele tenta sair da batalha.","Se você capturou Riolu no Floccesy Ranch para enfrentar Cheren, ele também pode ajudar contra Roxie. Se já conseguiu evoluí-lo para Lucario, ele é imune aos golpes de Veneno por também ser do tipo Aço. Riolu evolui ao subir de nível durante o dia com amizade alta.","Com Riolu, tenha cuidado contra Whirlipede, pois Force Palm faz contato e Poison Point pode envenená-lo, deixando Venoshock mais perigoso. Golpes Lutadores causam dano reduzido aos dois Pokémon de Roxie por eles serem do tipo Veneno.","Tenha cuidado com Smog de Koffing e Poison Sting de Whirlipede, pois os dois podem envenenar seu Pokémon. Whirlipede também possui Poison Point, que pode envenenar adversários que o atinjam com golpes de contato.","O maior perigo é Venoshock de Whirlipede, que causa o dobro de dano se o alvo já estiver envenenado. Se isso acontecer, use um Antidote ou troque de Pokémon antes que ele receba o golpe.","Antes da batalha, cure sua equipe e leve algumas Potions e Antidotes. Depois da vitória, você receberá a Toxic Badge e a TM09 Venoshock."],"3º GYM - BURGH":["Burgh é o líder do ginásio de Castelia City e usa Pokémon do tipo Inseto. Seu time começa com Swadloon no nível 22, seguido de Dwebble no nível 22 e termina com Leavanny no nível 24.","Swadloon e Leavanny são dos tipos Inseto e Planta e recebem quatro vezes mais dano de golpes dos tipos Fogo e Voador. Os dois também são vulneráveis aos tipos Gelo, Veneno, Pedra e Inseto.","Dwebble é dos tipos Inseto e Pedra e recebe dano superefetivo dos tipos Água, Pedra e Aço. Golpes de Fogo e Voador causam dano normal nele.","Se você escolheu Tepig, seu Pignite com golpes de Fogo pode enfrentar Swadloon e Leavanny. Tenha cuidado contra Dwebble, pois ele conhece Smack Down, um golpe de Pedra superefetivo contra Pignite.","Se você escolheu Oshawott, seu Dewott com golpes de Água pode aproveitar a fraqueza de Dwebble. Evite deixá-lo contra Swadloon e Leavanny, pois os dois conhecem Razor Leaf, um golpe de Planta superefetivo contra Dewott.","Se você escolheu Snivy, tenha cuidado ao usar seu Servine, pois toda a equipe de Burgh conhece golpes do tipo Inseto, que causam dano superefetivo nele.","Independentemente do inicial escolhido, você pode usar Growlithe com golpes de Fogo contra Swadloon e Leavanny. Growlithe pode ser capturado no Virbank Complex. Em Black 2, Magby também é uma opção de Fogo encontrada no mesmo lugar.","Outra opção é Pidove ou Tranquill com golpes Voadores contra Swadloon e Leavanny. Pidove pode ser encontrado na Route 20 e evolui para Tranquill no nível 21. Evite deixá-lo contra Dwebble, pois Smack Down é superefetivo contra ele.","Se você capturou Psyduck no Floccesy Ranch, ele pode usar golpes de Água contra Dwebble. Mantenha cuidado contra Swadloon e Leavanny por causa de Razor Leaf.","Você também pode capturar Roggenrola na Relic Passage, acessível pelos esgotos de Castelia. Seus golpes de Pedra são superefetivos contra os três adversários, mas Razor Leaf causa dano superefetivo nele. Na mesma caverna aparece Woobat, que pode usar golpes Voadores contra Swadloon e Leavanny, mas também precisa tomar cuidado com Smack Down de Dwebble.","Tenha cuidado com Struggle Bug, que toda a equipe de Burgh conhece e que reduz o Ataque Especial do alvo. Swadloon também pode usar Protect para se proteger de um golpe, enquanto Dwebble pode aumentar sua Velocidade com Rock Polish.","Leavanny segura uma Sitrus Berry, que recupera parte de sua vida durante a batalha. Ele e Swadloon também conhecem String Shot, que reduz a Velocidade do seu Pokémon.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Insect Badge e a TM76 Struggle Bug."],"4º GYM - ELESA":["Elesa é a líder do ginásio de Nimbasa City e usa Pokémon do tipo Elétrico. Em Black 2 e White 2, seu time começa com Emolga no nível 28, seguido de Flaaffy no nível 28 e termina com Zebstrika no nível 30.","Emolga é dos tipos Elétrico e Voador e recebe dano superefetivo de golpes dos tipos Pedra e Gelo. Por ser do tipo Voador, ela é imune a golpes do tipo Terra.","Flaaffy e Zebstrika são do tipo Elétrico e sua única fraqueza é o tipo Terra.","Independentemente do inicial escolhido, você pode capturar Sandile na Route 4 e usá-lo contra Flaaffy e Zebstrika. Sandile evolui para Krokorok no nível 29. Os dois são imunes aos golpes elétricos de toda a equipe de Elesa.","Você pode ensinar Dig pela TM28, encontrada na Route 4, para Sandile ou Krokorok. O golpe é superefetivo contra Flaaffy e Zebstrika, mas não atinge Emolga por ela ser do tipo Voador.","Outra opção é Drilbur, que pode aparecer nas nuvens de poeira da Relic Passage. Ele também é imune aos golpes elétricos e pode usar golpes de Terra contra Flaaffy e Zebstrika.","Contra Emolga, você pode usar Roggenrola ou Boldore com golpes de Pedra. Roggenrola pode ser capturado na Relic Passage e evolui para Boldore no nível 25. Seus golpes de Pedra são superefetivos contra Emolga, mas causam dano normal em Flaaffy e Zebstrika.","Se você capturou Sandshrew no Desert Resort, ele também pode enfrentar Flaaffy e Zebstrika com golpes do tipo Terra. Assim como Sandile e Drilbur, ele é imune aos golpes elétricos da equipe.","Se você escolheu Snivy, seu Servine resiste aos golpes elétricos e pode ajudar durante a batalha. Tenha cuidado contra Zebstrika, pois ele conhece Flame Charge, que causa dano superefetivo em Servine. Se escolheu Oshawott, evite deixar Dewott exposto aos ataques elétricos de Elesa.","Tenha cuidado com Volt Switch, conhecido pelos três Pokémon de Elesa. Depois de causar dano, o golpe permite que o usuário seja trocado. Um Pokémon do tipo Terra é imune ao ataque e impede essa troca quando Volt Switch não consegue atingi-lo.","Flaaffy conhece Thunder Wave, que pode paralisar seu Pokémon. Emolga e Flaaffy também possuem Static, uma habilidade que pode causar paralisia quando são atingidas por um golpe de contato.","Zebstrika segura uma Sitrus Berry, que recupera parte de sua vida durante a batalha, e pode usar Flame Charge para aumentar sua Velocidade. Emolga e Zebstrika também conhecem Pursuit, que causa mais dano se atingir seu Pokémon enquanto ele tenta sair da batalha.","Antes da batalha, cure sua equipe e leve algumas Potions e Paralyze Heals. Depois da vitória, você receberá a Bolt Badge e a TM72 Volt Switch."],"5º GYM - CLAY":["Clay é o líder do ginásio de Driftveil City e usa Pokémon do tipo Terra. Em Black 2 e White 2, seu time começa com Krokorok no nível 31, seguido de Sandslash no nível 31 e termina com Excadrill no nível 33.","Krokorok é dos tipos Terra e Sombrio e recebe dano superefetivo de golpes dos tipos Água, Planta, Gelo, Lutador e Inseto. Sandslash é do tipo Terra e é vulnerável aos tipos Água, Planta e Gelo.","Excadrill é dos tipos Terra e Aço e recebe dano superefetivo de golpes dos tipos Água, Fogo, Lutador e Terra.","Se você escolheu Oshawott, seu Dewott com golpes de Água pode enfrentar toda a equipe de Clay. Mantenha sua vida alta, principalmente quando Excadrill entrar em campo.","Se você escolheu Snivy, seu Servine pode usar golpes de Planta contra Krokorok e Sandslash. Tenha cuidado contra Sandslash, pois ele conhece Fury Cutter, um golpe do tipo Inseto superefetivo contra Servine.","Se você escolheu Tepig, seu Pignite com golpes Lutadores pode enfrentar Krokorok e Excadrill. Porém, os golpes de Terra de Clay causam dano superefetivo em Pignite, então evite enviá-lo para receber um ataque.","Independentemente do inicial escolhido, você pode usar Psyduck com golpes de Água contra toda a equipe. Psyduck pode ser encontrado no Floccesy Ranch e evolui para Golduck no nível 33.","Outra opção de Água é Marill ou Azumarill, também encontrado no Floccesy Ranch. Azurill evolui para Marill com amizade alta, e Marill evolui para Azumarill no nível 18. Seus golpes de Água são superefetivos contra os três Pokémon de Clay.","Se você capturou Sewaddle na Route 20, ele pode ter evoluído para Swadloon no nível 20. Use golpes de Planta contra Krokorok e Sandslash, mas mantenha cuidado com Fury Cutter. Se Swadloon estiver com amizade alta, ele também pode evoluir para Leavanny ao subir de nível.","Para enfrentar Krokorok e Excadrill, use Riolu ou Lucario com golpes Lutadores. Riolu pode ser capturado no Floccesy Ranch e aprende Force Palm no nível 15. Se ele evoluiu para Lucario, tome cuidado com Bulldoze, pois Lucario também é do tipo Aço e recebe dano superefetivo de golpes de Terra.","Se você capturou Drilbur nas nuvens de poeira da Relic Passage, ele pode ter evoluído para Excadrill no nível 31. Seus golpes de Terra são superefetivos contra o Excadrill de Clay, mas lembre-se de que o adversário também pode atingir o seu com Bulldoze.","Tenha cuidado com Bulldoze, conhecido por toda a equipe de Clay, pois o golpe reduz a Velocidade do Pokémon atingido. Krokorok também possui Intimidate, que reduz o Ataque do seu Pokémon quando ele entra em campo.","Sandslash conhece Fury Cutter, que pode se fortalecer quando usado repetidamente, e Rollout, perigoso para Pokémon Voadores. Excadrill conhece Rock Slide, então mesmo um Pokémon imune a Bulldoze por ser do tipo Voador precisa tomar cuidado.","Excadrill ainda segura uma Sitrus Berry, que recupera parte de sua vida durante a batalha. Antes de enfrentar Clay, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Quake Badge e a TM78 Bulldoze."],"6º GYM - SKYLA":["Skyla é a líder do ginásio de Mistralton City e usa Pokémon do tipo Voador. Em Black 2 e White 2, seu time começa com Swoobat no nível 37, seguido de Skarmory no nível 37 e termina com Swanna no nível 39.","Swoobat é dos tipos Psíquico e Voador e recebe dano superefetivo dos tipos Elétrico, Gelo, Pedra, Fantasma e Sombrio.","Skarmory é dos tipos Aço e Voador e é vulnerável aos tipos Fogo e Elétrico. Swanna é dos tipos Água e Voador e recebe quatro vezes mais dano de golpes elétricos, além de ser vulnerável ao tipo Pedra.","Independentemente do inicial escolhido, você pode usar Magnemite ou Magneton com golpes elétricos contra toda a equipe. Magnemite pode ser capturado no Virbank Complex e evolui para Magneton no nível 30.","Outra opção é Flaaffy ou Ampharos. Mareep pode ser capturado no Floccesy Ranch, evolui para Flaaffy no nível 15 e para Ampharos no nível 30. Seus golpes elétricos são superefetivos contra os três adversários, principalmente Swanna.","Se você capturou Joltik na Chargestone Cave, ele pode ter evoluído para Galvantula no nível 36. Use seus golpes elétricos contra a equipe, mas mantenha cuidado com os golpes Voadores, pois Galvantula também é do tipo Inseto.","Contra Swoobat, você pode usar Krokorok com golpes do tipo Sombrio. Sandile pode ser encontrado na Route 4 e evolui para Krokorok no nível 29. Ele é imune aos golpes Psíquicos de Swoobat, mas precisa tomar cuidado com Acrobatics.","Se você treinou Roggenrola, seu Boldore pode usar golpes de Pedra contra Swoobat e Swanna. Roggenrola pode ser capturado na Relic Passage e evolui para Boldore no nível 25. Tenha cuidado contra Swanna, pois BubbleBeam é superefetivo contra Boldore.","Se você escolheu Tepig, seu Pignite ou Emboar com golpes de Fogo pode enfrentar Skarmory. Growlithe, encontrado no Virbank Complex, é outra opção para essa batalha. Evite usar Pokémon de Fogo contra Swanna, pois BubbleBeam é superefetivo contra eles.","Se você escolheu Snivy, tenha cuidado ao usar Servine ou Serperior, pois os golpes Voadores da equipe de Skyla são superefetivos contra eles. O mesmo vale para Pignite e Emboar por também serem do tipo Lutador.","Tenha cuidado com Sturdy de Skarmory, que permite que ele sobreviva com um ponto de vida a um golpe que o derrotaria enquanto estiver com a vida cheia. Swanna segura uma Sitrus Berry e também pode usar Roost para recuperar sua vida.","Swoobat conhece Attract, que pode dificultar os ataques de um Pokémon do sexo oposto. Swanna também pode usar FeatherDance para reduzir o Ataque do seu Pokémon, então golpes especiais, como os elétricos, são boas opções contra ele.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Jet Badge e a TM62 Acrobatics."],"7º GYM - DRAYDEN":["Drayden é o líder do ginásio de Opelucid City e usa Pokémon do tipo Dragão. Em Black 2 e White 2, seu time começa com Druddigon no nível 46, seguido de Flygon no nível 46 e termina com Haxorus no nível 48.","Druddigon e Haxorus recebem dano superefetivo de golpes dos tipos Gelo e Dragão. Flygon é dos tipos Terra e Dragão e recebe quatro vezes mais dano de golpes de Gelo. Ele também é vulnerável ao tipo Dragão.","Independentemente do inicial escolhido, você pode usar Lapras com golpes de Gelo contra toda a equipe. Lapras pode ser encontrado usando Surf nas áreas de água que se agitam na Village Bridge, antes de chegar a Opelucid City.","Outra opção é Cubchoo ou Beartic. Cubchoo pode ser encontrado na Route 7 durante o inverno e evolui para Beartic no nível 37. Seus golpes de Gelo são superefetivos contra os três adversários, especialmente Flygon.","Tenha cuidado ao usar Beartic contra Druddigon, pois ele conhece Revenge, um golpe do tipo Lutador que é superefetivo contra Pokémon de Gelo. O golpe causa ainda mais dano se Druddigon receber um ataque antes de usá-lo naquele turno.","Se você capturou Axew na Mistralton Cave, ele pode ter evoluído para Fraxure no nível 38. Seus golpes do tipo Dragão são superefetivos contra toda a equipe, mas Fraxure também recebe dano superefetivo dos golpes Dragão adversários.","Você também pode usar Trapinch, Vibrava ou Flygon com golpes do tipo Dragão. Trapinch pode ser encontrado no Desert Resort, evolui para Vibrava no nível 35 e para Flygon no nível 45. Assim como Fraxure, essa família precisa tomar cuidado com Dragon Tail.","Se você escolheu Oshawott, seu Samurott também pode ajudar caso conheça um golpe do tipo Gelo. Flygon recebe quatro vezes mais dano desse tipo, mas evite deixá-lo em campo com pouca vida, pois os ataques de Drayden ainda podem causar bastante dano.","Tenha cuidado com Dragon Tail, conhecido pelos três Pokémon de Drayden. Além de causar dano, o golpe força a troca do seu Pokémon, então mantenha toda a equipe recuperada.","Haxorus pode usar Dragon Dance para aumentar seu Ataque e sua Velocidade e segura uma Sitrus Berry, que recupera parte de sua vida. Flygon também conhece Rock Slide, perigoso para Pokémon vulneráveis ao tipo Pedra.","Antes da batalha, cure sua equipe e leve algumas Potions. Depois da vitória, você receberá a Legend Badge e a TM82 Dragon Tail."],"8º GYM - MARLON":["Marlon é o líder do ginásio de Humilau City e usa Pokémon do tipo Água. Seu time começa com Carracosta no nível 49, seguido de Wailord no nível 49 e termina com Jellicent no nível 51.","Carracosta é dos tipos Água e Pedra e recebe quatro vezes mais dano de golpes do tipo Planta. Ele também é vulnerável aos tipos Elétrico, Lutador e Terra.","Wailord é do tipo Água e recebe dano superefetivo dos tipos Elétrico e Planta. Jellicent é dos tipos Água e Fantasma e é vulnerável aos tipos Elétrico, Planta, Fantasma e Sombrio.","Se você escolheu Snivy, seu Serperior com golpes de Planta pode enfrentar toda a equipe de Marlon. Aproveite a fraqueza de quatro vezes de Carracosta, mas tenha cuidado contra Wailord, pois ele conhece Bounce, um golpe Voador superefetivo contra Serperior.","Independentemente do inicial escolhido, você pode usar Ampharos com golpes elétricos contra os três adversários. Mareep pode ser capturado no Floccesy Ranch e evolui para Flaaffy no nível 15 e para Ampharos no nível 30.","Outra opção é Magnezone, caso você tenha treinado Magnemite desde o Virbank Complex. Magnemite evolui para Magneton no nível 30 e, ao subir de nível na Chargestone Cave, Magneton evolui para Magnezone. Seus golpes elétricos são superefetivos contra toda a equipe.","Se você capturou Joltik na Chargestone Cave, seu Galvantula também pode usar golpes elétricos contra os três adversários. Joltik evolui para Galvantula no nível 36. Tenha cuidado contra Carracosta e Wailord, pois seus golpes de Pedra são superefetivos contra Galvantula.","Você também pode usar Leavanny com golpes de Planta. Sewaddle pode ser encontrado na Route 20 e evolui para Swadloon no nível 20, depois Swadloon evolui para Leavanny ao subir de nível com amizade alta. Tenha cuidado com Bounce de Wailord, que causa quatro vezes mais dano a Leavanny.","Contra Jellicent, você pode usar Krookodile com Crunch. Sandile pode ser capturado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40. Porém, Jellicent conhece Scald e Brine, golpes de Água que causam quatro vezes mais dano em Krookodile, então essa opção exige cuidado.","Tenha cuidado com Sturdy de Carracosta, que permite que ele sobreviva com um ponto de vida a um golpe que o derrotaria enquanto estiver com a vida cheia. Carracosta também pode usar Shell Smash, que reduz suas defesas, mas aumenta bastante seu Ataque, Ataque Especial e Velocidade.","Wailord conhece Bounce, perigoso para Pokémon de Planta, e pode usar Amnesia para aumentar sua Defesa Especial. Jellicent segura uma Sitrus Berry e conhece Recover, permitindo que recupere sua vida durante a batalha.","Os três Pokémon de Marlon conhecem Scald, que pode causar queimadura. Jellicent também conhece Brine, que causa mais dano quando o alvo está com metade da vida ou menos, então mantenha sua equipe saudável.","Antes da batalha, cure sua equipe e leve algumas Potions e Burn Heals. Depois da vitória, você receberá a Wave Badge e a TM55 Scald."],"ELITE FOUR - SHAUNTAL":["Shauntal é uma das integrantes da Elite Four de Unova e usa Pokémon do tipo Fantasma. Em Black 2 e White 2, seu time começa com Cofagrigus no nível 56, seguido de Drifblim no nível 56, Golurk no nível 56 e Chandelure no nível 58.","Os quatro recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma e são imunes a golpes dos tipos Normal e Lutador.","Drifblim também é do tipo Voador e recebe dano superefetivo dos tipos Elétrico, Gelo e Pedra. Golurk também é do tipo Terra e é vulnerável aos tipos Água, Planta e Gelo. Chandelure também é do tipo Fogo e recebe dano superefetivo dos tipos Água, Terra e Pedra.","Independentemente do inicial escolhido, você pode usar Krookodile com Crunch contra os quatro Pokémon de Shauntal. Sandile pode ser capturado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40.","Krookodile também pode usar golpes de Terra contra Chandelure, mas tenha cuidado, pois Chandelure conhece Energy Ball, que causa dano superefetivo em Krookodile. Cofagrigus conhece Grass Knot, outro golpe de Planta perigoso para ele, e Golurk pode usar Brick Break, do tipo Lutador.","Outra opção contra Cofagrigus e Drifblim é Liepard com golpes do tipo Sombrio. Purrloin pode ser encontrado nas primeiras rotas da jornada e evolui para Liepard no nível 20. Mantenha cuidado com Will-O-Wisp de Cofagrigus, pois a queimadura reduz o Ataque de Pokémon que dependem de golpes físicos.","Contra Drifblim, você pode usar Ampharos ou Magnezone com golpes elétricos. Mareep pode ser capturado no Floccesy Ranch, enquanto Magnemite aparece no Virbank Complex. Drifblim conhece Psychic, Thunderbolt e Acrobatics, então mantenha seus Pokémon preparados para receber ataques de tipos diferentes.","Se você escolheu Snivy, seu Serperior com golpes de Planta pode enfrentar Golurk. Outra opção é Leavanny, evoluído de Sewaddle, encontrado na Route 20. Sewaddle evolui para Swadloon no nível 20, depois Swadloon evolui para Leavanny ao subir de nível com amizade alta.","Se você escolheu Oshawott, seu Samurott com golpes de Água pode enfrentar Golurk e Chandelure. Contra Chandelure, tenha cuidado com Energy Ball, que é superefetivo contra Samurott.","Para Golurk, você também pode usar Lapras com golpes de Gelo ou Água. Lapras pode ser encontrado usando Surf nas áreas de água que se agitam na Village Bridge.","Contra Chandelure, outra opção é Gigalith com golpes de Pedra. Roggenrola pode ser capturado na Relic Passage e evolui para Boldore no nível 25, depois Boldore evolui para Gigalith por troca. Tome cuidado com Energy Ball, pois o golpe de Planta é superefetivo contra Boldore e Gigalith.","Tenha cuidado com Earthquake de Golurk, que pode causar muito dano, e com Fire Blast de Chandelure. Chandelure ainda segura uma Sitrus Berry, que recupera parte de sua vida durante a batalha.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - GRIMSLEY":["Grimsley é um dos integrantes da Elite Four de Unova e usa Pokémon do tipo Sombrio. Em Black 2 e White 2, seu time começa com Liepard no nível 56, seguido de Scrafty no nível 56, Krookodile no nível 56 e Bisharp no nível 58.","Liepard é do tipo Sombrio e recebe dano superefetivo dos tipos Lutador e Inseto. Scrafty é dos tipos Sombrio e Lutador e é vulnerável aos tipos Lutador e Voador.","Krookodile é dos tipos Terra e Sombrio e recebe dano superefetivo dos tipos Água, Planta, Gelo, Lutador e Inseto. Bisharp é dos tipos Sombrio e Aço e recebe quatro vezes mais dano de golpes Lutadores, além de ser vulnerável aos tipos Fogo e Terra.","Se você escolheu Tepig, seu Emboar com golpes do tipo Lutador pode enfrentar toda a equipe de Grimsley. Ele também pode usar golpes de Fogo contra Bisharp, mas precisa tomar cuidado com Earthquake de Krookodile, que causa dano superefetivo nele.","Independentemente do inicial escolhido, você pode usar Lucario com golpes Lutadores contra os quatro adversários. Riolu pode ser capturado no Floccesy Ranch e evolui para Lucario ao subir de nível durante o dia com amizade alta. Tenha cuidado contra Krookodile, pois Earthquake também é superefetivo contra Lucario.","Outra opção é Gurdurr ou Conkeldurr. Timburr pode ser encontrado na Relic Passage e evolui para Gurdurr no nível 25, depois pode evoluir para Conkeldurr por troca. Tenha cuidado contra Liepard e Bisharp, pois ambos conhecem Aerial Ace, que causa dano superefetivo em Pokémon do tipo Lutador.","Contra Scrafty, você pode usar Unfezant com golpes Voadores. Pidove pode ser capturado na Route 20 e evolui para Tranquill no nível 21 e para Unfezant no nível 32. Mantenha cuidado com Rock Tomb de Scrafty, que é superefetivo contra Unfezant.","Outra opção contra Scrafty é Swanna. Ducklett pode ser encontrado nas sombras que aparecem na Driftveil Drawbridge e evolui para Swanna no nível 35. Swanna também pode usar golpes de Água contra Krookodile, mas precisa tomar cuidado com Rock Tomb.","Se você escolheu Oshawott ou Snivy, seu inicial já pode estar em sua forma final, Samurott ou Serperior. Os dois podem aproveitar as fraquezas de Krookodile, usando golpes de Água ou Planta, respectivamente.","Contra Bisharp, você também pode usar Darmanitan com golpes de Fogo ou Excadrill com golpes de Terra. Darumaka pode ser capturado na Route 4 e evolui para Darmanitan no nível 35, enquanto Drilbur pode ser encontrado nas nuvens de poeira da Relic Passage e evolui para Excadrill no nível 31.","Tenha cuidado com Fake Out de Liepard, que pode fazer seu Pokémon recuar no primeiro turno em que Liepard estiver em campo. Ele também conhece Attract, que pode dificultar os ataques de um Pokémon do sexo oposto.","Scrafty possui Moxie, que aumenta seu Ataque sempre que ele derrota um Pokémon. Krookodile possui Intimidate, que reduz o Ataque do seu Pokémon quando ele entra em campo, e conhece Earthquake, um golpe forte do tipo Terra.","Bisharp possui Defiant, que aumenta seu Ataque quando uma de suas características é reduzida. Ele também segura uma Sitrus Berry, que recupera parte de sua vida durante a batalha.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - CAITLIN":["Caitlin é uma das integrantes da Elite Four de Unova e usa Pokémon do tipo Psíquico. Em Black 2 e White 2, seu time começa com Musharna no nível 56, seguido de Sigilyph no nível 56, Reuniclus no nível 56 e Gothitelle no nível 58.","Musharna, Reuniclus e Gothitelle recebem dano superefetivo dos tipos Sombrio, Fantasma e Inseto. Sigilyph também é do tipo Voador e é vulnerável aos tipos Sombrio, Fantasma, Elétrico, Gelo e Pedra.","Independentemente do inicial escolhido, você pode usar Krookodile com Crunch contra toda a equipe. Sandile pode ser capturado na Route 4, evolui para Krokorok no nível 29 e para Krookodile no nível 40.","Krookodile é imune aos golpes Psíquicos de Caitlin por também ser do tipo Sombrio. Porém, tenha cuidado com Focus Blast e Energy Ball de Reuniclus, que são superefetivos contra ele, e com Ice Beam de Sigilyph, que causa quatro vezes mais dano nele.","Outra opção é Liepard com golpes do tipo Sombrio. Purrloin pode ser encontrado nas primeiras rotas e evolui para Liepard no nível 20. Ele também é imune aos golpes Psíquicos, mas precisa tomar cuidado com Focus Blast de Reuniclus.","Se você recebeu Zorua em Driftveil City, ele pode ter evoluído para Zoroark no nível 30. Use seus golpes do tipo Sombrio contra a equipe de Caitlin, mas mantenha cuidado com Focus Blast.","Contra Musharna, Reuniclus e Gothitelle, você pode usar Leavanny com golpes do tipo Inseto. Sewaddle pode ser capturado na Route 20 e evolui para Swadloon no nível 20, depois Swadloon evolui para Leavanny ao subir de nível com amizade alta.","Tenha muito cuidado com Sigilyph, pois Air Slash e Ice Beam causam quatro vezes mais dano a Leavanny. Além disso, os golpes de Inseto de Leavanny causam dano normal em Sigilyph por ele também ser do tipo Voador.","Para enfrentar Sigilyph, use Ampharos ou Magnezone com golpes elétricos. Mareep pode ser capturado no Floccesy Ranch e evolui para Ampharos no nível 30, enquanto Magnemite pode ser encontrado no Virbank Complex e evoluir até Magnezone na Chargestone Cave.","Outra opção contra Sigilyph é Boldore ou Gigalith com golpes de Pedra. Roggenrola pode ser capturado na Relic Passage e evolui para Boldore no nível 25, depois Boldore evolui para Gigalith por troca.","Se você treinou Litwick, seu Lampent ou Chandelure pode usar golpes do tipo Fantasma contra a equipe. Litwick pode ser encontrado na Celestial Tower e evolui para Lampent no nível 41, depois use uma Dusk Stone para obter Chandelure. Tenha cuidado contra Sigilyph e Gothitelle, pois os dois conhecem Shadow Ball, que é superefetivo contra ele.","Tenha cuidado com Yawn de Musharna, que faz seu Pokémon adormecer depois de um turno. Ela também pode usar Reflect para reduzir o dano dos golpes físicos recebidos pela equipe.","Reuniclus conhece Recover, que recupera sua vida, enquanto Gothitelle pode usar Calm Mind para aumentar seu Ataque Especial e sua Defesa Especial. Tente derrotá-la antes que ela consiga acumular muitos aumentos.","Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."],"ELITE FOUR - MARSHAL":["Marshal é um dos integrantes da Elite Four de Unova e usa Pokémon do tipo Lutador. Em Black 2 e White 2, seu time começa com Throh no nível 56, seguido de Sawk no nível 56, Mienshao no nível 56 e Conkeldurr no nível 58.","Os quatro recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Porém, Throh, Sawk e Conkeldurr conhecem golpes do tipo Pedra para atingir Pokémon Voadores, então mantenha cuidado ao usá-los.","Independentemente do inicial escolhido, você pode usar Sigilyph com golpes Psíquicos ou Voadores contra toda a equipe. Sigilyph pode ser encontrado no Desert Resort, mas precisa tomar cuidado com Rock Tomb, Rock Slide e Stone Edge, que são superefetivos contra ele.","Outra opção é Espeon com golpes Psíquicos. Eevee pode ser encontrado na área de grama de Castelia City e evolui para Espeon ao subir de nível durante o dia com amizade alta. Evite deixá-lo contra Throh e Sawk sem cuidado, pois ambos conhecem Payback, um golpe Sombrio superefetivo contra Espeon.","Se você capturou Woobat na Relic Passage, ele pode ter evoluído para Swoobat ao subir de nível com amizade alta. Seus golpes Psíquicos e Voadores também são superefetivos contra a equipe, mas ele precisa tomar cuidado com Payback e com os golpes de Pedra.","Contra Mienshao, você pode usar Cofagrigus. Por ser do tipo Fantasma, ele é imune a Hi Jump Kick e Retaliate. Yamask pode ser encontrado no Relic Castle e evolui para Cofagrigus no nível 34. Se você ensinou Psychic a ele, o golpe pode aproveitar a fraqueza de Mienshao.","Tenha cuidado ao usar Cofagrigus contra Throh ou Sawk, pois ambos conhecem Payback, que causa dano superefetivo nele. Mienshao também pode usar U-turn para causar dano e ser trocado caso Marshal ainda tenha outro Pokémon disponível.","Você também pode usar Unfezant com golpes Voadores. Pidove pode ser capturado na Route 20 e evolui para Tranquill no nível 21 e para Unfezant no nível 32. Mantenha sua vida alta, pois Rock Tomb, Rock Slide e Stone Edge são perigosos para ele.","Outra opção é Swanna, evoluído de Ducklett no nível 35. Ducklett pode ser encontrado nas sombras que aparecem na Driftveil Drawbridge. Seus golpes Voadores são superefetivos contra a equipe, mas Swanna também precisa tomar cuidado com os golpes de Pedra.","Tenha cuidado com Sturdy de Sawk, que permite que ele sobreviva com um ponto de vida a um golpe que o derrotaria enquanto estiver com a vida cheia. Throh conhece Storm Throw, que sempre causa um acerto crítico quando atinge o alvo.","Conkeldurr pode usar Bulk Up para aumentar seu Ataque e sua Defesa e segura uma Sitrus Berry para recuperar parte de sua vida. Sawk, Mienshao e Conkeldurr conhecem Retaliate, que causa o dobro de dano se um companheiro deles tiver sido derrotado no turno anterior.","Depois da vitória, recupere sua equipe antes de seguir em frente."],"CHAMPION":["Iris é a Champion da Liga Pokémon de Unova e usa uma equipe com Pokémon de vários tipos. Seu time começa com Hydreigon no nível 57, seguido de Druddigon, Archeops, Aggron e Lapras no nível 57, e termina com Haxorus no nível 59.","Hydreigon é dos tipos Sombrio e Dragão e recebe dano superefetivo dos tipos Gelo, Lutador, Inseto e Dragão. Druddigon e Haxorus são do tipo Dragão e são vulneráveis aos tipos Gelo e Dragão.","Archeops é dos tipos Pedra e Voador e recebe dano superefetivo dos tipos Água, Elétrico, Gelo, Pedra e Aço. Aggron é dos tipos Aço e Pedra e recebe quatro vezes mais dano dos tipos Lutador e Terra, além de ser vulnerável ao tipo Água.","Lapras é dos tipos Água e Gelo e recebe dano superefetivo dos tipos Elétrico, Planta, Lutador e Pedra.","Contra Hydreigon, você pode usar Lucario com golpes do tipo Lutador. Riolu pode ser capturado no Floccesy Ranch e evolui para Lucario ao subir de nível durante o dia com amizade alta. Tenha cuidado, pois Hydreigon conhece Flamethrower, que é superefetivo contra Lucario.","Outra opção contra Hydreigon é Mienshao com golpes Lutadores. Mienfoo pode ser encontrado na Route 14 e evolui para Mienshao no nível 50.","Para enfrentar os três Dragões de Iris, você pode usar Lapras com Ice Beam. Ele pode ser encontrado usando Surf nas áreas de água que se agitam na Village Bridge. Lapras também pode usar golpes de Água contra Archeops e Aggron.","Se você treinou Cubchoo, seu Beartic com golpes de Gelo também pode enfrentar Hydreigon, Druddigon e Haxorus. Cubchoo aparece na Route 7 durante o inverno e evolui para Beartic no nível 37. Tenha cuidado com Flamethrower de Hydreigon e Druddigon e com Focus Blast de Druddigon, pois esses golpes são superefetivos contra Beartic.","Outra opção contra os Dragões é seu próprio Haxorus. Axew pode ser encontrado na Mistralton Cave, evolui para Fraxure no nível 38 e para Haxorus no nível 48. Seus golpes do tipo Dragão são superefetivos contra os três, mas ele também é vulnerável aos golpes Dragão deles.","Contra Archeops, use Ampharos ou Magnezone com golpes elétricos. Mareep pode ser capturado no Floccesy Ranch e evolui até Ampharos no nível 30, enquanto Magnemite pode ser encontrado no Virbank Complex e evoluir até Magnezone na Chargestone Cave.","Para enfrentar Aggron, Lucario, Mienshao ou Conkeldurr com golpes Lutadores podem aproveitar sua fraqueza de quatro vezes. Se você escolheu Tepig, seu Emboar também pode usar golpes Lutadores, mas precisa tomar cuidado com Earthquake.","Se você escolheu Oshawott, seu Samurott pode usar golpes de Água contra Archeops e Aggron. Se escolheu Snivy, seu Serperior pode enfrentar Lapras com golpes de Planta, mas tenha muito cuidado com Ice Beam, que é superefetivo contra Serperior.","Contra Lapras, você também pode usar Ampharos ou Magnezone com golpes elétricos. Pokémon Lutadores, como Lucario e Conkeldurr, são outras opções, mas Lucario precisa tomar cuidado com Surf.","O maior perigo é Haxorus. Ele segura uma Focus Sash, que permite sobreviver com um ponto de vida a um golpe que o derrotaria enquanto estiver com a vida cheia. Ele pode aproveitar esse turno para usar Dragon Dance, aumentando seu Ataque e sua Velocidade.","Haxorus também conhece Earthquake, perigoso para Lucario e Magnezone, e Dual Chop, um golpe de Dragão que atinge duas vezes. Mantenha sua equipe recuperada e prepare um Pokémon capaz de finalizar a batalha caso Haxorus sobreviva ao primeiro ataque.","Archeops possui Defeatist, que reduz seu Ataque e seu Ataque Especial quando sua vida cai à metade ou menos. Já Lapras conhece Sing, que pode colocar seu Pokémon para dormir, então mantenha alguns Awakenings ou Full Restores na mochila.","Depois de derrotar Iris, ela levará você ao Hall da Fama, onde sua equipe será registrada como a nova Champion de Unova."]}'::jsonb WHERE slug IN ('pokemon-black-2','pokemon-white-2');

-- Champion de Pokémon X e Y.
UPDATE public.builds SET caps = CASE WHEN 'CHAMPION' = ANY(caps) THEN caps ELSE array_append(caps, 'CHAMPION') END, dicas = dicas || '{"CHAMPION": ["Diantha é a Champion de Kalos e usa Pokémon de tipos variados. Seu time começa com Hawlucha no nível 64, seguido de Tyrantrum no nível 65, Aurorus no nível 65, Gourgeist no nível 65, Goodra no nível 66 e Gardevoir no nível 68.", "Durante a batalha, Gardevoir usa a Mega Evolution e se transforma em Mega Gardevoir, mantendo os tipos Psíquico e Fada.", "Hawlucha recebe dano superefetivo de golpes dos tipos Elétrico, Gelo, Voador, Psíquico e Fada. Tyrantrum é vulnerável aos tipos Lutador, Terra, Metal, Gelo, Dragão e Fada. Aurorus recebe quatro vezes mais dano de golpes dos tipos Lutador e Metal, além de ser vulnerável aos tipos Água, Planta, Terra e Pedra.", "Gourgeist é vulnerável aos tipos Fogo, Gelo, Voador, Fantasma e Sombrio. Goodra recebe dano superefetivo dos tipos Gelo, Dragão e Fada, enquanto Gardevoir é vulnerável aos tipos Veneno, Fantasma e Metal.", "Contra Hawlucha, você pode usar Pikachu, Raichu ou Heliolisk com Thunderbolt. Outra opção é Talonflame com golpes do tipo Voador. Fletchling pode ser encontrado na Route 2, evolui para Fletchinder no nível 17 e para Talonflame no nível 35.", "Para enfrentar Tyrantrum e Aurorus, use Lucario com golpes do tipo Lutador ou Metal. Lucario é especialmente eficaz contra Aurorus, que recebe quatro vezes mais dano desses dois tipos. Tenha cuidado contra Tyrantrum, pois ele conhece Earthquake.", "Outra opção é usar Dugtrio ou Garchomp com Earthquake contra os dois fósseis. Dugtrio pode ser encontrado na Route 13, assim como Gible, que evolui para Gabite no nível 24 e para Garchomp no nível 48.", "Tenha cuidado com Dragon Claw de Tyrantrum e Blizzard de Aurorus. Os dois golpes são superefetivos contra Garchomp, e Blizzard causa quatro vezes mais dano a ele por ser dos tipos Dragão e Terra.", "Se você escolheu Froakie, seu Greninja com Surf também pode enfrentar Tyrantrum e Aurorus. Greninja pode usar Ice Beam contra Gourgeist e Goodra.", "Contra Gourgeist, você pode usar Delphox ou Talonflame com golpes do tipo Fogo. Talonflame e outros Pokémon voadores, como Pidgeot, também podem aproveitar a fraqueza de Gourgeist com golpes do tipo Voador.", "Outra opção é Doublade com golpes do tipo Fantasma, mas tenha cuidado com Phantom Force e Shadow Sneak, que são superefetivos contra ele.", "Para enfrentar Goodra, use Lapras com Ice Beam ou Sylveon ou Florges com golpes do tipo Fada. Se usar Lapras, fique atento a Focus Blast, que é superefetivo contra ele.", "Flabébé pode ser capturado na Route 4 ou 7 e evolui para Floette no nível 19. Depois, use uma Shiny Stone para evoluí-la para Florges. Se quiser ensinar Moonblast antes da evolução, treine Floette até o nível 46.", "Contra Mega Gardevoir, você pode usar Doublade com Iron Head. Honedge pode ser capturado na Route 6, evolui para Doublade no nível 35 e aprende Iron Head no nível 45. Tenha muito cuidado com Shadow Ball, que causa dano superefetivo a Doublade.", "Outra opção é Venusaur com Sludge Bomb, caso você tenha escolhido Bulbasaur. A TM36 pode ser encontrada na Route 19 usando Surf, mas Mega Gardevoir conhece Psychic, que causa dano superefetivo a Venusaur.", "Hawlucha pode usar Swords Dance para aumentar bastante seu Ataque. Aurorus pode usar Reflect e Light Screen para proteger a equipe, enquanto a habilidade Sap Sipper de Goodra impede que golpes do tipo Planta causem dano a ele e ainda aumenta seu Ataque.", "Antes de enfrentar Diantha, recupere sua equipe e confira seus itens. Depois da vitória, seus Pokémon serão registrados no Hall da Fama e você se tornará Champion de Kalos."]}'::jsonb WHERE slug IN ('pokemon-x', 'pokemon-y');

-- Elite Four de Pokémon X e Y.
UPDATE public.builds SET caps = array_remove(array_remove(array_remove(array_remove(array_remove(caps, 'CHAMPION'), 'ELITE FOUR - MALVA'), 'ELITE FOUR - SIEBOLD'), 'ELITE FOUR - WIKSTROM'), 'ELITE FOUR - DRASNA') || ARRAY['ELITE FOUR - MALVA','ELITE FOUR - SIEBOLD','ELITE FOUR - WIKSTROM','ELITE FOUR - DRASNA'] || ARRAY['CHAMPION'], dicas = dicas || '{"ELITE FOUR - MALVA": ["Malva é uma integrante da Elite Four que usa Pokémon do tipo Fogo. Seu time começa com Pyroar no nível 63, seguido de Torkoal no nível 63, Chandelure no nível 63 e Talonflame no nível 65.", "Pyroar, Torkoal e Chandelure recebem dano superefetivo de golpes dos tipos Água, Terra e Pedra. Talonflame também é do tipo Voador e recebe quatro vezes mais dano de golpes do tipo Pedra, além de ser vulnerável aos tipos Água e Elétrico.", "Se você escolheu Froakie, seu Greninja pode usar Surf contra os quatro Pokémon de Malva. Seu tipo Sombrio também permite usar golpes desse tipo contra Chandelure, mas tenha cuidado com Wild Charge de Pyroar, que é superefetivo contra Greninja.", "Outra opção é Blastoise com Surf, caso você tenha escolhido Squirtle no laboratório do Professor Sycamore. Ele também deve tomar cuidado com Wild Charge de Pyroar.", "Independentemente dos iniciais escolhidos, você pode usar o Lapras recebido na Route 12 com Surf. Contra Talonflame, Lapras também pode usar golpes do tipo Elétrico, mas é melhor mantê-lo longe de Pyroar por causa de Wild Charge.", "Para enfrentar Talonflame, Aerodactyl com Rock Slide aproveita a fraqueza quádrupla ao tipo Pedra. Aerodactyl pode ser revivido a partir de um Old Amber no laboratório de Ambrette Town. O fóssil pode ser encontrado quebrando pedras na Glittering Cave.", "Se você capturou um Trapinch ou Gible na Route 13, suas evoluções Flygon e Garchomp podem usar golpes do tipo Terra contra Pyroar, Torkoal e Chandelure. Golpes desse tipo não atingem Talonflame, pois ele também é Voador.", "Tenha cuidado com Earthquake de Torkoal, especialmente se usar Pokémon do tipo Pedra. Chandelure pode causar confusão com Confuse Ray, enquanto Talonflame conhece Brave Bird e Flare Blitz, dois golpes fortes que também causam dano ao próprio usuário.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para a próxima batalha da Elite Four."], "ELITE FOUR - SIEBOLD": ["Siebold é um integrante da Elite Four que usa Pokémon do tipo Água. Seu time começa com Clawitzer no nível 63, seguido de Starmie no nível 63, Gyarados no nível 63 e Barbaracle no nível 65.", "Clawitzer e Starmie recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Gyarados é dos tipos Água e Voador e recebe quatro vezes mais dano de golpes elétricos, enquanto Barbaracle é dos tipos Pedra e Água e recebe quatro vezes mais dano de golpes de Planta.", "Se você escolheu Chespin, seu Chesnaught pode usar golpes do tipo Planta contra Clawitzer, Starmie e Barbaracle. Tenha cuidado contra Starmie, pois ele conhece Psychic, e contra Gyarados, que conhece Ice Fang.", "Se escolheu Bulbasaur no laboratório do Professor Sycamore, seu Venusaur também pode usar golpes de Planta contra Clawitzer e Barbaracle. Contra Starmie, tome cuidado com Psychic, que é superefetivo contra Venusaur por ele ser do tipo Veneno.", "Independentemente dos iniciais escolhidos, você pode usar Pikachu ou Raichu com Thunderbolt contra Clawitzer, Starmie e Gyarados. Pikachu pode ser encontrado na Santalune Forest e evolui para Raichu com uma Thunder Stone.", "Outra opção é Heliolisk com Thunderbolt. Helioptile pode ser encontrado na Route 9 e evolui para Heliolisk com uma Sun Stone. Contra Gyarados, tenha cuidado com Earthquake, que causa dano superefetivo aos seus Pokémon elétricos.", "Para Barbaracle, você pode usar Gogoat com golpes do tipo Planta. Skiddo pode ser capturado na Route 5 e evolui para Gogoat no nível 32. Ele também pode enfrentar Clawitzer e Starmie, mas deve tomar cuidado com Ice Fang de Gyarados.", "Clawitzer usa Aura Sphere e Dark Pulse, fortalecidos por sua habilidade Mega Launcher. Starmie pode usar Light Screen para reduzir o dano de golpes especiais, enquanto Gyarados pode usar Dragon Dance para aumentar seu Ataque e sua Velocidade.", "Barbaracle conhece Stone Edge, Cross Chop e X-Scissor, então escolha com cuidado o Pokémon que entrará contra ele.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para a próxima batalha da Elite Four."], "ELITE FOUR - WIKSTROM": ["Wikstrom é um integrante da Elite Four que usa Pokémon do tipo Metal. Seu time começa com Klefki no nível 63, seguido de Probopass no nível 63, Scizor no nível 63 e Aegislash no nível 65.", "Klefki e Aegislash recebem dano superefetivo de golpes dos tipos Fogo e Terra. Probopass recebe quatro vezes mais dano de golpes dos tipos Lutador e Terra, enquanto Scizor recebe quatro vezes mais dano de golpes do tipo Fogo.", "Se você escolheu Fennekin, seu Delphox pode usar golpes do tipo Fogo contra Klefki, Scizor e Aegislash. Contra Probopass, tenha cuidado com Power Gem, que é superefetivo contra Delphox.", "Se você escolheu Charmander no laboratório do Professor Sycamore, seu Charizard também pode enfrentar Klefki, Scizor e Aegislash com golpes de Fogo. Evite usá-lo contra Probopass, pois Power Gem causa quatro vezes mais dano a Charizard por ele ser dos tipos Fogo e Voador.", "Independentemente dos iniciais escolhidos, você pode usar Lucario com golpes do tipo Lutador contra Probopass. O Lucario recebido de Korrina também conhece Bone Rush, que pode aproveitar a fraqueza de Probopass ao tipo Terra.", "Outra opção é Garchomp com Earthquake contra Klefki, Probopass e Aegislash. Gible pode ser encontrado na Route 13, evolui para Gabite no nível 24 e para Garchomp no nível 48. Cuidado com Dazzling Gleam de Klefki, que é superefetivo contra Garchomp por ele ser do tipo Dragão.", "Para enfrentar Scizor, você pode usar Talonflame com golpes do tipo Fogo. Fletchling pode ser encontrado logo na Route 2, evolui para Fletchinder no nível 17 e para Talonflame no nível 35.", "Probopass possui a habilidade Sturdy, que permite que ele sobreviva a um golpe que o derrotaria se estiver com a vida cheia. Por isso, esteja preparado para receber um contra-ataque.", "Aegislash usa King’s Shield para se proteger e mudar para sua forma defensiva. Se você usar um golpe que faça contato enquanto ele estiver protegido, seu Ataque será reduzido. Espere a proteção terminar ou use um golpe que não faça contato, como Flamethrower.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para a próxima batalha da Elite Four."], "ELITE FOUR - DRASNA": ["Drasna é uma integrante da Elite Four que usa Pokémon do tipo Dragão. Seu time começa com Dragalge no nível 63, seguido de Altaria no nível 63, Druddigon no nível 63 e Noivern no nível 65.", "Dragalge recebe dano superefetivo de golpes dos tipos Terra, Gelo, Psíquico e Dragão. Druddigon é vulnerável aos tipos Gelo, Dragão e Fada, enquanto Altaria e Noivern recebem quatro vezes mais dano de golpes do tipo Gelo por também serem do tipo Voador.", "Se você escolheu Froakie, seu Greninja com Ice Beam pode enfrentar os quatro Pokémon de Drasna. A TM13 Ice Beam é recebida após a vitória contra Wulfric.", "Independentemente do inicial escolhido, você pode usar Lapras com Ice Beam contra toda a equipe. Lapras é recebido na Route 12, mas tenha cuidado contra Dragalge, que conhece Thunderbolt.", "Outra opção é Sylveon ou Florges com golpes do tipo Fada contra Altaria, Druddigon e Noivern.", "Eevee pode ser capturado na Route 10 e evolui para Sylveon ao subir de nível conhecendo um golpe do tipo Fada e tendo ao menos dois corações de afeto no Pokémon-Amie.", "Para conseguir Florges, capture Flabébé na Route 4 ou 7 e evolua-o para Floette no nível 19. Depois, use uma Shiny Stone, que pode ser encontrada na Route 12.", "Se quiser usar Moonblast, treine Floette até o nível 46 antes de evoluí-la. Se já evoluiu, você também pode ensiná-lo à Florges com o Move Reminder em Dendemille Town, em troca de uma Heart Scale.", "Tenha cuidado contra Dragalge, pois ele conhece Sludge Bomb, que causa dano superefetivo a Sylveon e Florges. Como Dragalge também é do tipo Veneno, golpes de Fada causam dano normal a ele.", "Contra Dragalge, você pode usar Gardevoir com Psychic. Ralts pode ser capturado na Route 4, evolui para Kirlia no nível 20 e para Gardevoir no nível 30. Tome cuidado com Sludge Bomb, que também é superefetivo contra Gardevoir por ela ser do tipo Fada.", "Altaria pode usar Sing para colocar seu Pokémon para dormir e Cotton Guard para aumentar bastante sua Defesa. Já Druddigon conhece Revenge, que pode causar o dobro de dano se ele for atingido antes de atacar.", "Noivern é rápido e conhece Flamethrower, Air Slash e Boomburst, então tente enfrentá-lo com um Pokémon preparado para resistir aos seus ataques.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para as batalhas que ainda faltarem. Após derrotar os quatro integrantes, você poderá enfrentar a Champion Diantha."]}'::jsonb WHERE slug IN ('pokemon-x', 'pokemon-y');

-- Ginásios de Pokémon Omega Ruby e Alpha Sapphire.
INSERT INTO public.builds (slug, caps, dicas) SELECT slug, ARRAY['1º GYM - ROXANNE','2º GYM - BRAWLY','3º GYM - WATTSON','4º GYM - FLANNERY','5º GYM - NORMAN','6º GYM - WINONA','7º GYM - TATE E LIZA','8º GYM - WALLACE'], '{"1º GYM - ROXANNE": ["Roxanne é a líder do ginásio de Rustboro City e usa Pokémon do tipo Pedra. Seu time começa com Geodude no nível 12 e termina com Nosepass no nível 14.", "Os dois recebem dano superefetivo de golpes dos tipos Água, Planta, Lutador, Terra e Metal. Geodude também é do tipo Terra e recebe quatro vezes mais dano dos golpes de Água e Planta.", "Se você escolheu Mudkip, use Water Gun, que ele aprende no nível 4, contra os dois adversários.", "Se você escolheu Treecko, use Absorb, que ele aprende no nível 5. O golpe tem vantagem contra os dois adversários e ainda recupera parte da vida de Treecko.", "Se você escolheu Torchic, uma opção é capturar um Shroomish na Petalburg Woods e usar Absorb contra os Pokémon de Roxanne.", "Outra opção para quem escolheu Torchic é treiná-lo até o nível 16, quando evolui para Combusken e pode aprender Double Kick. O golpe do tipo Lutador é superefetivo contra toda a equipe de Roxanne.", "Em Alpha Sapphire, você também pode capturar Lotad na Route 102 e usar Absorb contra os dois Pokémon de Roxanne.", "Tenha cuidado com Rock Tomb, que reduz a Velocidade do alvo. O golpe é superefetivo contra Torchic, então mantenha atenção à vida dele.", "Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."], "2º GYM - BRAWLY": ["Brawly é o líder do ginásio de Dewford Town e usa Pokémon do tipo Lutador. Seu time começa com Machop no nível 14 e termina com Makuhita no nível 16.", "Os dois recebem dano superefetivo de golpes dos tipos Voador, Psíquico e Fada. Pokémon do tipo Fantasma também são imunes aos golpes do tipo Lutador, mas é preciso tomar cuidado com outros golpes que a equipe conhece.", "Independentemente do inicial escolhido, você pode capturar Ralts na Route 102 e usar Confusion contra os dois adversários. Em Omega Ruby e Alpha Sapphire, Ralts também é do tipo Fada e resiste aos golpes do tipo Lutador. Tenha cuidado com Knock Off de Makuhita, que causa dano superefetivo a Ralts por ele também ser do tipo Psíquico.", "Outra opção é Wingull com Wing Attack. Ele pode ser capturado nas Routes 103 e 104 e aprende o golpe no nível 8. Wingull resiste aos golpes de Lutador e pode aproveitá-los como uma oportunidade para atacar.", "Você também pode usar Taillow com Wing Attack. Taillow aparece nas Routes 104 e 116 e aprende o golpe no nível 13. Por também ser do tipo Normal, ele recebe dano normal dos golpes de Lutador, então mantenha sua vida alta.", "Se você capturou Wurmple e ele evoluiu para Silcoon, treine-o até o nível 10 para conseguir Beautifly. Ele aprende Gust ao evoluir e pode usar o golpe contra os dois Pokémon de Brawly.", "Tenha cuidado com Bulk Up, que aumenta o Ataque e a Defesa do Pokémon que o usa. Tente derrotar os adversários antes que acumulem muitos aumentos, principalmente se estiver usando golpes físicos como Wing Attack.", "Makuhita também conhece Arm Thrust, que pode atingir várias vezes no mesmo turno, e Sand Attack, que reduz a precisão do seu Pokémon. Já Machop conhece Seismic Toss, que causa dano igual ao nível dele.", "Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."], "3º GYM - WATTSON": ["Wattson é especialista no tipo Elétrico. Seu time começa com Magnemite no nível 19, seguido de Voltorb no nível 19 e Magneton no nível 21.", "Todos recebem dano superefetivo de golpes do tipo Terra. Magnemite e Magneton também são do tipo Metal, então recebem quatro vezes mais dano desses golpes. Pokémon do tipo Terra também são imunes aos golpes elétricos da equipe de Wattson.", "Se você escolheu Mudkip, treine-o até evoluir para Marshtomp no nível 16 e use Mud Shot. Por ser dos tipos Água e Terra, Marshtomp é imune aos golpes elétricos e pode usar o golpe contra toda a equipe.", "Se você escolheu Treecko ou Torchic, pode encontrar Geodude em hordas na entrada da Granite Cave, em Dewford. Treine-o até aprender Magnitude no nível 12 e use o golpe contra os adversários de Wattson.", "Outra opção é Nincada, encontrado na Route 116. Por também ser do tipo Terra, ele é imune a golpes elétricos e aprende Mud-Slap no nível 17.", "Se você escolheu Torchic e já o evoluiu para Combusken, ele pode usar Double Kick ou golpes de Fogo contra Magnemite e Magneton, que também são vulneráveis a esses tipos.", "Se você escolheu Treecko, ele já pode ter evoluído para Grovyle. Ele resiste a golpes elétricos, mas não causa dano superefetivo com ataques de Planta, então Geodude pode ajudar a aproveitar a fraqueza da equipe.", "Tenha cuidado com Supersonic de Magneton, que pode confundir seu Pokémon. Voltorb conhece Rollout, cujo dano aumenta em usos consecutivos, e todos podem usar Volt Switch para atacar e trocar de Pokémon.", "Antes de enfrentar Wattson, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."], "4º GYM - FLANNERY": ["Flannery é especialista no tipo Fogo. Seu time começa com Slugma no nível 26, seguido de Numel no nível 26 e Torkoal no nível 28.", "Os três recebem dano superefetivo de golpes dos tipos Água e Terra. Numel também é do tipo Terra e recebe quatro vezes mais dano de golpes de Água. Slugma e Torkoal também são vulneráveis ao tipo Pedra.", "Se você escolheu Mudkip, seu Marshtomp pode usar golpes de Água contra toda a equipe. Aproveite principalmente a fraqueza de quatro vezes de Numel.", "Se você escolheu Treecko ou Torchic, uma opção é Wingull, encontrado na Route 104. Ele pode usar golpes de Água contra toda a equipe e já pode ter ajudado na batalha contra Brawly.", "Outra opção é Marill, que pode ser encontrado na Route 117. Treine-o até o nível 18 para evoluí-lo em Azumarill e use seus golpes de Água contra os Pokémon de Flannery.", "Se você capturou Geodude na Granite Cave para enfrentar Wattson, ele já pode ter evoluído para Graveler. Use Magnitude contra toda a equipe ou golpes de Pedra contra Slugma e Torkoal.", "Você também pode capturar um Numel na Route 112 e treiná-lo até aprender Magnitude no nível 12. Seus golpes do tipo Terra são superefetivos contra todos os Pokémon de Flannery.", "Tenha cuidado com Overheat, um golpe de Fogo muito forte. Depois de usá-lo, o Ataque Especial do adversário diminui. Numel também conhece Earth Power, perigoso para Pokémon vulneráveis ao tipo Terra.", "A equipe de Flannery também pode usar Sunny Day, que fortalece golpes de Fogo e enfraquece golpes de Água por alguns turnos. Mantenha atenção à vida da equipe, mesmo quando estiver usando um Pokémon com vantagem.", "Antes da batalha, cure seus Pokémon e leve algumas Potions e Burn Heals para se preparar."], "5º GYM - NORMAN": ["Norman é especialista no tipo Normal. Seu time começa com Slaking no nível 28, seguido de Vigoroth no nível 28 e outro Slaking no nível 30. Todos recebem dano superefetivo de golpes do tipo Lutador.", "Se você escolheu Torchic, seu Combusken pode usar Double Kick contra toda a equipe. Mantenha atenção à vida dele, pois os ataques de Slaking podem causar bastante dano.", "Se você escolheu Treecko ou Mudkip, pode capturar um Makuhita na Granite Cave e usar seus golpes do tipo Lutador. Ele evolui para Hariyama no nível 24 e pode enfrentar todos os Pokémon de Norman.", "Outra opção é o Shroomish que pode ter ajudado contra Roxanne. Treine-o até evoluir para Breloom no nível 23, quando pode aprender Mach Punch, um golpe do tipo Lutador que ataca com prioridade.", "Se você capturou Aron na Granite Cave, ele pode ajudar a resistir aos golpes do tipo Normal da equipe de Norman. Para chegar aos andares inferiores da caverna, volte com a Mach Bike após chegar a Mauville.", "Em Alpha Sapphire, você também pode capturar Sableye nos andares inferiores da Granite Cave usando a Mach Bike. Por ser do tipo Fantasma, ele é imune aos golpes Normais, mas os Pokémon de Norman conhecem Feint Attack, que pode atingi-lo.", "Os Slaking possuem a habilidade Truant, que os faz descansar no turno seguinte ao que agem. Aproveite esses turnos para atacar ou recuperar sua equipe. Vigoroth não possui essa habilidade e pode agir em todos os turnos.", "Tenha cuidado com Retaliate, que causa o dobro de dano se um aliado tiver sido derrotado no turno anterior. O primeiro Slaking também pode usar Yawn para fazer seu Pokémon dormir.", "Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings."], "6º GYM - WINONA": ["Winona é especialista no tipo Voador. Ela usa Swellow, Pelipper e Skarmory no nível 33 e Altaria no nível 35.", "Pelipper recebe quatro vezes mais dano de golpes elétricos, enquanto Altaria recebe quatro vezes mais dano de golpes de Gelo. Swellow e Pelipper também são vulneráveis a golpes de Pedra.", "Se você treinou Electrike ou Manectric, use golpes elétricos contra Swellow, Pelipper e Skarmory. Electrike pode ser encontrado na Route 110 e evolui para Manectric no nível 26.", "Outra opção elétrica é Magnemite ou Magneton. Magnemite pode ser encontrado em hordas na Route 110 e evolui para Magneton no nível 30.", "Se você capturou Aron na Granite Cave com a Mach Bike, ele já pode ter evoluído para Lairon no nível 32. Os dois resistem a golpes Voadores e podem usar golpes de Pedra contra Swellow e Altaria. Porém, cuidado com Pelipper, cujos golpes de Água causam quatro vezes mais dano a eles.", "O Geodude ou Graveler que pode ter ajudado contra Wattson e Flannery também pode usar golpes de Pedra contra Swellow e Altaria. Assim como Aron e Lairon, ele precisa tomar cuidado com a Água de Pelipper.", "Se você escolheu Torchic, seu Combusken pode usar golpes de Fogo contra Skarmory. Tenha cuidado com os golpes Voadores, que são superefetivos contra ele por também ser do tipo Lutador.", "Tenha cuidado com Earthquake de Altaria. O golpe causa quatro vezes mais dano a Aron e Lairon e também é perigoso para Manectric, Magneton e Combusken. Altaria ainda pode usar Cotton Guard para aumentar sua Defesa e Roost para recuperar vida.", "Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals, pois Dragon Breath de Altaria pode causar paralisia."], "7º GYM - TATE E LIZA": ["Tate e Liza são especialistas no tipo Psíquico e enfrentam você em uma batalha dupla, então prepare dois Pokémon para lutar ao mesmo tempo. Eles usam Lunatone e Solrock no nível 45.", "Os dois são dos tipos Pedra e Psíquico e recebem dano superefetivo de golpes dos tipos Água, Planta, Inseto, Fantasma, Sombrio e Metal. A habilidade Levitate torna os dois imunes a golpes do tipo Terra.", "Independentemente do inicial escolhido, Mightyena com golpes do tipo Sombrio pode enfrentar os dois adversários. Poochyena pode ser encontrado no início da jornada e evolui para Mightyena no nível 18. Por ser do tipo Sombrio, ele também é imune aos golpes Psíquicos dos adversários.", "Outra opção é Sharpedo, dos tipos Água e Sombrio. Você pode pescar um Carvanha com a Good Rod na Route 118 e treiná-lo até o nível 30 para evoluí-lo. Seus golpes de Água e Sombrio têm vantagem contra os dois adversários.", "Em Omega Ruby, você pode capturar Seedot na Route 102 e treiná-lo até Nuzleaf ou Shiftry. Seus golpes dos tipos Planta e Sombrio podem enfrentar Lunatone e Solrock, mas tenha cuidado com Solar Beam de Solrock.", "Em Alpha Sapphire, Sableye é outra opção. Ele pode ser capturado na Granite Cave, nos andares acessíveis com a Mach Bike, e usar golpes dos tipos Sombrio e Fantasma. Por ser do tipo Sombrio, Sableye também é imune a golpes Psíquicos.", "Se você escolheu Mudkip, seu Marshtomp ou Swampert pode usar Surf contra Lunatone e Solrock. Tenha cuidado, pois em Omega Ruby e Alpha Sapphire Surf também atinge o outro Pokémon da sua equipe.", "Se você escolheu Treecko, seu Grovyle ou Sceptile pode usar golpes de Planta contra os dois. Se escolheu Torchic, você pode usar um Pokémon de Água, como Pelipper ou Azumarill, para ajudar.", "Tenha cuidado com Sunny Day de Solrock, que enfraquece golpes de Água e permite que ele use Solar Beam sem esperar um turno para carregar. O golpe é especialmente perigoso para Marshtomp e Swampert, que recebem quatro vezes mais dano dele. Solrock também conhece Rock Slide, que atinge os dois Pokémon da sua equipe.", "Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings, pois Lunatone pode usar Hypnosis para colocar seus Pokémon para dormir."], "8º GYM - WALLACE": ["Wallace é especialista no tipo Água. Seu time começa com Luvdisc no nível 44, seguido de Whiscash no nível 44, Sealeo no nível 44, Seaking no nível 44 e Milotic no nível 46.", "Luvdisc, Sealeo, Seaking e Milotic recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Whiscash também é do tipo Terra, então é imune a golpes elétricos e recebe quatro vezes mais dano de golpes de Planta.", "Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra toda a equipe. Contra Whiscash, aproveite a fraqueza de quatro vezes, mas tenha cuidado com Aurora Beam de Sealeo e Ice Beam de Milotic.", "Se você treinou Electrike ou Manectric, use seus golpes elétricos contra Luvdisc, Sealeo, Seaking e Milotic. Evite usar ataques elétricos contra Whiscash.", "Magnemite ou Magneton também são boas opções elétricas. Magnemite pode ser encontrado em hordas na Route 110 e evolui para Magneton no nível 30.", "Em Omega Ruby, se você treinou um Seedot, seu Nuzleaf ou Shiftry pode usar golpes de Planta contra a equipe de Wallace, principalmente contra Whiscash.", "Em Alpha Sapphire, outra opção é Lotad, encontrado na Route 102. Ele evolui para Lombre no nível 14 e depois para Ludicolo com uma Water Stone. Seus golpes de Planta também podem ajudar contra Whiscash e os demais Pokémon de Água.", "Tenha cuidado com Milotic, que pode usar Recover para recuperar vida. Seaking também conhece Horn Drill, que pode derrotar seu Pokémon em um único acerto.", "Antes da batalha, cure sua equipe e leve Potions e itens para curar confusão, pois Luvdisc pode usar Sweet Kiss."]}'::jsonb FROM public.pokemon WHERE slug IN ('pokemon-omega-ruby', 'pokemon-alpha-sapphire') ON CONFLICT (slug) DO UPDATE SET caps = EXCLUDED.caps || ARRAY(SELECT chapter FROM unnest(public.builds.caps) AS chapter WHERE NOT (chapter = ANY(EXCLUDED.caps))), dicas = public.builds.dicas || EXCLUDED.dicas;

-- Liga de Pokémon Omega Ruby e Alpha Sapphire.
UPDATE public.builds SET caps = ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['ELITE FOUR - SIDNEY','ELITE FOUR - PHOEBE','ELITE FOUR - GLACIA','ELITE FOUR - DRAKE','CHAMPION']))) || ARRAY['ELITE FOUR - SIDNEY','ELITE FOUR - PHOEBE','ELITE FOUR - GLACIA','ELITE FOUR - DRAKE','CHAMPION'], dicas = dicas || '{"ELITE FOUR - SIDNEY": ["Sidney é o primeiro integrante da Elite Four e usa Pokémon do tipo Sombrio. Seu time começa com Mightyena no nível 50, seguido de Shiftry no nível 50, Cacturne no nível 50, Sharpedo no nível 50 e Absol no nível 52.", "Os cinco recebem dano superefetivo de golpes dos tipos Lutador, Inseto e Fada. Shiftry e Cacturne também são do tipo Planta e recebem quatro vezes mais dano de golpes do tipo Inseto. Sharpedo também é do tipo Água e é vulnerável aos tipos Elétrico e Planta.", "Se você escolheu Torchic, seu Blaziken pode usar golpes do tipo Lutador contra toda a equipe. Seus golpes de Fogo também são superefetivos contra Shiftry e Cacturne.", "Tenha cuidado ao usar Blaziken contra Sharpedo, pois ele conhece Aqua Jet. Shiftry conhece Extrasensory, enquanto Absol conhece Aerial Ace e Psycho Cut, golpes superefetivos contra Blaziken por ele também ser do tipo Lutador.", "Independentemente do inicial escolhido, você pode usar Hariyama com golpes do tipo Lutador. Makuhita pode ser capturado na Granite Cave e evolui para Hariyama no nível 24. Assim como Blaziken, ele precisa tomar cuidado com Extrasensory, Aerial Ace e Psycho Cut.", "O Shroomish que pode ter acompanhado você desde a Petalburg Woods também pode participar. Seu Breloom com golpes do tipo Lutador tem vantagem contra toda a equipe, mas deve tomar cuidado com os mesmos golpes Psíquicos e Voadores.", "Outra opção é Heracross, que pode ser capturado na Safari Zone. Seus golpes do tipo Lutador são superefetivos contra toda a equipe, e seus golpes do tipo Inseto causam quatro vezes mais dano a Shiftry e Cacturne. Mantenha-o longe de Aerial Ace de Absol, que causa quatro vezes mais dano a ele.", "Se você treinou Ralts desde a Route 102, sua Gardevoir pode usar golpes do tipo Fada contra a equipe de Sidney. Tome cuidado com os golpes Sombrios dos adversários, que causam dano normal a Gardevoir, e com Poison Fang de Sharpedo, que é superefetivo contra o tipo Fada.", "Contra Sharpedo, você também pode usar Manectric ou Magneton com golpes elétricos. Electrike pode ser encontrado na Route 110, onde Magnemite também aparece em hordas.", "Tenha cuidado com Swagger de Mightyena, que aumenta o Ataque do seu Pokémon, mas também o deixa confuso. Cacturne pode usar Spiky Shield para se proteger e causar dano a quem usar um golpe de contato.", "Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois da vitória, recupere seus Pokémon antes de enfrentar Phoebe."], "ELITE FOUR - PHOEBE": ["Phoebe é a segunda integrante da Elite Four e usa Pokémon do tipo Fantasma. Em Omega Ruby e Alpha Sapphire, seu time começa com Dusclops no nível 51, seguido de Banette no nível 51, Sableye no nível 51, outro Banette no nível 51 e Dusknoir no nível 53.", "Dusclops, os dois Banette e Dusknoir recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma. Sableye é dos tipos Sombrio e Fantasma e, com a chegada do tipo Fada, passou a receber dano superefetivo desse tipo.", "Se você treinou Poochyena, seu Mightyena pode usar golpes do tipo Sombrio contra Dusclops, Banette e Dusknoir. Poochyena pode ser encontrado no início da jornada e evolui para Mightyena no nível 18.", "Outra opção é Sharpedo com golpes do tipo Sombrio. Carvanha pode ser pescado com a Good Rod na Route 118 e evolui para Sharpedo no nível 30. Os dois podem usar golpes de Água contra Sableye, causando dano normal.", "Se você capturou Ralts na Route 102, sua Gardevoir pode usar golpes do tipo Fada contra Sableye. Por também ser do tipo Psíquico, ela precisa tomar cuidado com os golpes Fantasmas da equipe de Phoebe. Ralts evolui para Kirlia no nível 20 e para Gardevoir no nível 30.", "Outra opção contra Sableye é Azumarill com golpes do tipo Fada. Marill pode ser encontrado na Route 117 e evolui para Azumarill no nível 18. Em Omega Ruby e Alpha Sapphire, Azumarill é dos tipos Água e Fada.", "Se você treinou Seedot em Omega Ruby, seu Nuzleaf ou Shiftry também pode usar golpes do tipo Sombrio contra Dusclops, Banette e Dusknoir. Seedot pode ser encontrado na Route 102 e evolui para Nuzleaf no nível 14, depois use uma Leaf Stone para evoluí-lo para Shiftry.", "Em Alpha Sapphire, você pode usar Sableye, encontrado nos andares inferiores da Granite Cave após obter a Mach Bike. Seus golpes do tipo Sombrio têm vantagem contra Dusclops, Banette e Dusknoir, mas tenha cuidado, pois os golpes Fantasmas deles também são superefetivos contra Sableye.", "O Trapinch capturado no deserto da Route 111 também pode ajudar. Seu Vibrava ou Flygon com Crunch pode enfrentar Dusclops e Banette, mas mantenha-o longe de Ice Punch de Dusknoir, que causa quatro vezes mais dano a ele.", "Tenha cuidado com Confuse Ray e Curse de Dusclops. Os Banette também podem causar problemas com Will-O-Wisp, que queima seu Pokémon, e Grudge, que pode esgotar os PP do golpe usado para derrotá-los.", "Dusknoir conhece Fire Punch, Ice Punch e Thunder Punch, então escolha com cuidado qual Pokémon ficará em campo contra ele.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para Glacia, a próxima integrante da Elite Four."], "ELITE FOUR - GLACIA": ["Glacia é a terceira integrante da Elite Four e usa Pokémon do tipo Gelo. Em Omega Ruby e Alpha Sapphire, seu time começa com Glalie no nível 52, seguido de Froslass no nível 52, outro Glalie no nível 52, outro Froslass no nível 52 e Walrein no nível 54.", "Os dois Glalie recebem dano superefetivo de golpes dos tipos Fogo, Lutador, Pedra e Metal. Froslass também é do tipo Fantasma, então é imune a golpes Lutadores e vulnerável aos tipos Fogo, Pedra, Fantasma, Sombrio e Metal. Walrein também é do tipo Água e recebe dano superefetivo dos tipos Elétrico, Planta, Lutador e Pedra.", "Se você escolheu Torchic, seu Blaziken pode usar golpes do tipo Fogo contra os dois Glalie e os dois Froslass. Contra Walrein, use golpes do tipo Lutador, mas tenha cuidado com Surf, que causa dano superefetivo a Blaziken.", "Independentemente do inicial escolhido, você pode usar Hariyama com golpes do tipo Lutador contra Glalie e Walrein. Makuhita pode ser capturado na Granite Cave e evolui para Hariyama no nível 24. Evite usar golpes Lutadores contra Froslass, pois eles não a atingem.", "Se você treinou Poochyena, seu Mightyena com Crunch pode aproveitar a fraqueza dos dois Froslass ao tipo Sombrio. Poochyena pode ser encontrado no início da jornada e evolui para Mightyena no nível 18.", "Outra opção é Sharpedo com Crunch. Carvanha pode ser pescado com a Good Rod na Route 118 e evolui para Sharpedo no nível 30. Tenha cuidado com Draining Kiss de um dos Froslass, pois o golpe do tipo Fada é superefetivo contra Mightyena e Sharpedo.", "Se você treinou Electrike, seu Manectric pode usar golpes elétricos contra Walrein. Electrike pode ser capturado na Route 110 e evolui para Manectric no nível 26. Magnemite, que também pode ser encontrado em hordas na Route 110, pode evoluir para Magneton no nível 30 e usar golpes elétricos contra Walrein.", "Se você treinou Aron desde a Granite Cave, seu Lairon ou Aggron pode usar golpes dos tipos Pedra ou Metal contra Glalie e Froslass. Tenha cuidado contra Walrein, pois seu Surf causa quatro vezes mais dano à linha evolutiva de Aron.", "Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Walrein. Porém, tenha muito cuidado com Blizzard, que é superefetivo contra Sceptile.", "Glacia pode usar Hail para causar dano ao fim de cada turno aos Pokémon que não forem do tipo Gelo. Enquanto o granizo estiver ativo, Blizzard não erra por precisão, tornando os dois Froslass e Walrein ainda mais perigosos.", "Tenha muito cuidado com Sheer Cold de Walrein, que pode derrotar seu Pokémon em um único acerto. Se o seu Pokémon estiver acima do nível 54, o golpe falhará contra ele.", "Um dos Glalie conhece Freeze-Dry, um golpe de Gelo que também é superefetivo contra Pokémon do tipo Água. Por isso, tenha cuidado ao usar Sharpedo ou outros Pokémon aquáticos contra ele.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para Drake, o último integrante da Elite Four."], "ELITE FOUR - DRAKE": ["Drake é o último integrante da Elite Four e usa Pokémon do tipo Dragão. Em Omega Ruby e Alpha Sapphire, seu time começa com Altaria no nível 53, seguido de Flygon no nível 53, Kingdra no nível 53, outro Flygon no nível 53 e Salamence no nível 55.", "Altaria, os dois Flygon e Salamence recebem quatro vezes mais dano de golpes do tipo Gelo. Os quatro também são vulneráveis aos tipos Dragão e Fada.", "Kingdra é dos tipos Água e Dragão, então recebe dano normal de golpes de Gelo. Com a chegada do tipo Fada, ele passou a ser vulnerável a esse tipo, além do tipo Dragão.", "Independentemente do inicial escolhido, você pode usar Walrein com Ice Beam contra Altaria, os dois Flygon e Salamence. Spheal pode ser capturado na Shoal Cave, ao norte de Mossdeep City, e evolui para Sealeo no nível 32 e para Walrein no nível 44.", "A TM13 Ice Beam pode ser encontrada em Sea Mauville usando Surf e Dive. Se você escolheu Mudkip, seu Swampert também pode aprender o golpe e aproveitar a fraqueza dos quatro dragões.", "Se você treinou Ralts desde a Route 102, sua Gardevoir pode usar golpes do tipo Fada contra toda a equipe. Por também ser do tipo Fada, ela é imune aos golpes do tipo Dragão dos adversários. Ralts evolui para Kirlia no nível 20 e para Gardevoir no nível 30.", "Em Omega Ruby, outra opção é Mawile com Play Rough, que ele aprende no nível 49. Mawile pode ser capturado nos andares inferiores da Granite Cave após obter a Mach Bike. Em Alpha Sapphire, ele precisa ser obtido por troca.", "Tenha cuidado ao usar Mawile contra os Flygon, pois um deles conhece Earthquake e o outro conhece Flamethrower. Os dois golpes são superefetivos contra Mawile por ele também ser do tipo Metal.", "Outra opção é Azumarill com Play Rough. Marill pode ser encontrado na Route 117 e evolui para Azumarill no nível 18. Em Omega Ruby e Alpha Sapphire, Azumarill aprende Play Rough no nível 25 e também é imune aos golpes do tipo Dragão.", "Se você treinou o Trapinch capturado no deserto da Route 111, seu Flygon pode usar golpes do tipo Dragão contra toda a equipe de Drake. Porém, tenha muito cuidado, pois Flygon também recebe dano superefetivo dos golpes de Dragão e quatro vezes mais dano de Ice Beam de Kingdra.", "Tenha cuidado com Moonblast de Altaria, que é superefetivo contra seus Pokémon do tipo Dragão. Altaria também pode usar Cotton Guard para aumentar bastante sua Defesa.", "Os dois Flygon conhecem golpes diferentes. Um deles usa Earthquake e Rock Slide, enquanto o outro conhece Flamethrower e Dragon Pulse. Kingdra pode usar Yawn para fazer seu Pokémon dormir e conhece Ice Beam para atingir os seus dragões.", "Salamence conhece Dragon Rush, Zen Headbutt, Crunch e Thunder Fang. Mantenha seu Pokémon com bastante vida e aproveite sua fraqueza de quatro vezes ao tipo Gelo.", "Depois da vitória, recupere toda a equipe e prepare seus Pokémon para a última batalha da Liga, contra o Champion Steven."], "CHAMPION": ["Steven é o Champion de Hoenn em Omega Ruby e Alpha Sapphire. Ele é conhecido pelos Pokémon do tipo Metal, mas sua equipe também inclui Pokémon dos tipos Pedra, Terra, Planta, Inseto, Voador e Psíquico.", "Seu time começa com Skarmory no nível 57, seguido de Claydol no nível 57, Aggron no nível 57, Cradily no nível 57, Armaldo no nível 57 e Metagross no nível 59. Durante a batalha, Metagross usa a Mega Evolution e se transforma em Mega Metagross.", "Skarmory recebe dano superefetivo de golpes dos tipos Fogo e Elétrico. Claydol é vulnerável aos tipos Água, Planta, Gelo, Inseto, Fantasma e Sombrio, enquanto Aggron recebe quatro vezes mais dano de golpes dos tipos Lutador e Terra.", "Cradily recebe dano superefetivo dos tipos Gelo, Lutador, Inseto e Metal. Armaldo é vulnerável aos tipos Água, Pedra e Metal, enquanto Mega Metagross recebe dano superefetivo dos tipos Fogo, Terra, Fantasma e Sombrio.", "Se você escolheu Torchic, seu Blaziken pode usar golpes de Fogo contra Skarmory e Mega Metagross, além de golpes Lutadores contra Aggron e Cradily. Tenha cuidado com Zen Headbutt de Mega Metagross, que é superefetivo contra Blaziken por ele também ser do tipo Lutador.", "Se você escolheu Mudkip, seu Swampert com Surf pode enfrentar Claydol, Aggron e Armaldo. Swampert também pode usar Earthquake contra Aggron e Mega Metagross, mas o golpe não atinge Claydol, pois ele possui a habilidade Levitate.", "Se você escolheu Treecko, seu Sceptile pode usar golpes de Planta contra Claydol. Contra os outros Pokémon, procure aproveitar os companheiros que treinou durante a jornada.", "Independentemente do inicial escolhido, você pode usar Manectric ou Magneton com golpes elétricos contra Skarmory. Electrike pode ser encontrado na Route 110, onde Magnemite também aparece em hordas. Os dois precisam tomar cuidado com Earthquake de Aggron e Earth Power de Claydol.", "Se você treinou Makuhita, seu Hariyama com golpes do tipo Lutador pode enfrentar Aggron e Cradily. O Breloom que pode ter acompanhado você desde a Petalburg Woods também pode aproveitar a fraqueza dos dois com golpes Lutadores.", "O Trapinch capturado no deserto da Route 111 já pode ter evoluído para Flygon. Seus golpes do tipo Terra podem ser usados contra Aggron e Mega Metagross. Por possuir Levitate, Flygon é imune a Earthquake de Aggron, mas precisa tomar cuidado com Dragon Claw, que é superefetivo contra ele.", "Para enfrentar Armaldo, você pode usar Pelipper, Sharpedo ou Azumarill com golpes de Água. Se você treinou Aron até Aggron, seus golpes do tipo Metal também têm vantagem contra Armaldo e Cradily.", "Contra Mega Metagross, outra opção é Mightyena com golpes do tipo Sombrio. Poochyena pode ser encontrado no início da jornada e evolui para Mightyena no nível 18. Se você treinou Sableye em Alpha Sapphire, ele também pode usar golpes dos tipos Sombrio ou Fantasma para aproveitar essa fraqueza.", "Tenha cuidado com Spikes de Skarmory, que causa dano aos Pokémon afetados ao entrarem em campo. Claydol pode usar Reflect e Light Screen para reduzir o dano recebido pela equipe de Steven, enquanto Cradily conhece Confuse Ray.", "O maior desafio é Mega Metagross. Ele conhece Meteor Mash, Zen Headbutt, Bullet Punch e Giga Impact, então mantenha seu Pokémon com bastante vida. Bullet Punch possui prioridade e pode atacar antes mesmo de um adversário mais rápido.", "Depois de derrotar Steven, você e sua equipe serão registrados no Hall da Fama como os novos Champions de Hoenn."]}'::jsonb WHERE slug IN ('pokemon-omega-ruby','pokemon-alpha-sapphire');

-- Builds de Pokémon Sun e Moon.
UPDATE public.builds SET caps = ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - HAPU','TRIAL - KOMMO-O','ELITE FOUR - HALA','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION'] || ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - HAPU','TRIAL - KOMMO-O','ELITE FOUR - HALA','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION']))), dicas = dicas || '{"TRIAL - ILIMA": ["Na prova de Ilima na Verdant Cavern, você enfrenta o Totem Gumshoos no nível 12. Ele é do tipo Normal e pode chamar Yungoos para ajudá-lo.", "Gumshoos e Yungoos recebem dano superefetivo de golpes do tipo Lutador. Independentemente do inicial escolhido, você pode capturar Makuhita na Route 2 e usar seus golpes Lutadores contra os dois.", "A aura do Totem aumenta sua Defesa. Tenha cuidado com Super Fang, que reduz pela metade a vida atual do seu Pokémon, e com Hyper Fang do Yungoos aliado.", "Cure sua equipe antes de entrar e leve Potions. Durante a prova, o Totem e seus aliados não podem ser capturados."], "TRIAL - HALA": ["Hala é o kahuna de Melemele e usa Pokémon do tipo Lutador. Seu time tem Mankey e Makuhita no nível 14 e Crabrawler no nível 15.", "Os três são vulneráveis a golpes dos tipos Voador, Psíquico e Fada. Crabrawler segura o Fightinium Z e pode usar um Z-Move forte durante a batalha.", "Se você escolheu Rowlet, use seus golpes do tipo Voador. Outra opção é Pikipek, que pode ser capturado na Route 1 e usar Peck contra os três adversários.", "Butterfree é outra opção com Confusion. Capture Caterpie na Route 1 e evolua-o até Butterfree no nível 10. Seu tipo Inseto e Voador ajuda a resistir aos golpes de Lutador.", "Tenha cuidado ao trocar para um Pokémon enfraquecido quando Crabrawler ainda puder usar seu Z-Move. Cure a equipe antes da batalha e leve Potions."], "TRIAL - LANA": ["Na prova de Lana em Brooklet Hill, você enfrenta o Totem Wishiwashi no nível 20. Sua habilidade Schooling o mantém na forma de cardume enquanto ele tiver vida suficiente.", "Wishiwashi é do tipo Água e recebe dano superefetivo de golpes dos tipos Elétrico e Planta. Se você escolheu Rowlet, seus golpes de Planta podem aproveitar essa fraqueza.", "Outra opção é Pikachu com golpes elétricos. Pichu pode ser encontrado na Route 1 e evolui para Pikachu ao subir de nível com amizade alta. Mantenha atenção à vida dele, pois o Totem pode chamar um aliado.", "Alomomola pode usar Heal Pulse para recuperar a vida de Wishiwashi. Se ela aparecer, considere derrotá-la primeiro para impedir a cura e depois concentre seus ataques no Totem.", "Quando Wishiwashi perde vida suficiente, volta à forma individual e fica mais fraco. Cure sua equipe antes da prova e leve Potions."], "TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Salazzle no nível 22. Ela é dos tipos Veneno e Fogo e pode chamar Salandit para ajudá-la.", "Salazzle recebe quatro vezes mais dano de golpes do tipo Terra e também é vulnerável aos tipos Água, Pedra e Psíquico. Salandit compartilha os tipos de Salazzle e as mesmas fraquezas.", "Se você escolheu Popplio, sua evolução Brionne pode usar golpes de Água contra os dois adversários. Outra opção é Diglett de Alola com golpes do tipo Terra, encontrado na Diglett’s Tunnel.", "Tenha cuidado com Toxic de Salazzle. Sua habilidade Corrosion permite envenenar até Pokémon dos tipos Veneno e Metal, e Salandit pode aproveitar o envenenamento com Venoshock.", "Cure sua equipe antes da prova e leve Antidotes ou itens que curem envenenamento."], "TRIAL - MALLOW": ["Na prova de Mallow na Lush Jungle, você enfrenta o Totem Lurantis no nível 24. Lurantis é do tipo Planta e recebe dano superefetivo dos tipos Fogo, Gelo, Voador, Inseto e Veneno.", "Se você escolheu Litten, sua evolução Torracat pode usar golpes de Fogo. Se escolheu Rowlet, Dartrix pode usar golpes do tipo Voador, mas fique atento à vida dele durante a batalha.", "Outra opção é Trumbeak com golpes do tipo Voador. Pikipek pode ser encontrado na Route 1 e evolui para Trumbeak no nível 14.", "Lurantis segura uma Power Herb que permite usar Solar Blade sem esperar o turno de preparação. Se Castform aparecer e usar Sunny Day, Solar Blade também poderá ser usado sem carregamento enquanto o sol durar.", "Considere derrotar Castform para reduzir a pressão sobre sua equipe. Lurantis ainda pode usar Synthesis para recuperar vida, então prepare seus golpes mais fortes antes de entrar."], "TRIAL - OLIVIA": ["Olivia é a kahuna de Akala e usa Pokémon do tipo Pedra. Seu time tem Nosepass e Boldore no nível 26 e Lycanroc na forma Midnight no nível 27.", "Os três são vulneráveis a golpes dos tipos Água, Planta, Lutador, Terra e Metal. Se você escolheu Rowlet ou Popplio, sua evolução pode usar golpes de Planta ou Água para aproveitar essas fraquezas.", "Se escolheu Litten, Makuhita pode ajudar com golpes do tipo Lutador. Ele pode ser encontrado na Route 2 e evolui para Hariyama no nível 24.", "Nosepass e Boldore possuem Sturdy, que pode deixá-los com um ponto de vida se estiverem com a vida cheia ao receber um golpe que os derrotaria. Mantenha sua equipe preparada para o contra-ataque.", "Lycanroc segura Rockium Z e pode usar um Z-Move do tipo Pedra. Tenha cuidado com Pokémon de Fogo e Voador e cure sua equipe antes da batalha."], "TRIAL - SOPHOCLES": ["Na prova de Sophocles no Hokulani Observatory, você enfrenta o Totem Vikavolt no nível 29. Ele é dos tipos Inseto e Elétrico e recebe dano superefetivo de golpes dos tipos Fogo e Pedra.", "Sua habilidade Levitate o torna imune a golpes do tipo Terra, então prefira Pedra para aproveitar a fraqueza. Vikavolt segura uma Occa Berry, que reduz o dano do primeiro golpe de Fogo superefetivo.", "Um Pokémon com golpes de Pedra pode enfrentar o Totem, mas cuide da vida da equipe. Vikavolt pode chamar Charjabug, cuja habilidade Battery fortalece os golpes especiais do aliado.", "Considere derrotar Charjabug quando ele aparecer e mantenha itens de cura à mão. Não confunda essa prova com a dos remakes, que usam outro Totem."], "TRIAL - ACEROLA": ["Na prova de Acerola no Thrifty Megamart abandonado, você enfrenta o Totem Mimikyu no nível 33. Ele é dos tipos Fantasma e Fada e recebe dano superefetivo dos tipos Fantasma e Metal.", "A habilidade Disguise bloqueia o dano do primeiro golpe que o atinge. Use um ataque para quebrar o disfarce e depois aproveite a fraqueza com um golpe mais forte.", "Mimikyu pode chamar Haunter ou Gengar. Os dois também são do tipo Fantasma e podem ser atingidos por golpes Sombrios, mas tenha cuidado com Hypnosis, que pode colocar seu Pokémon para dormir.", "Mimikyu conhece Shadow Claw e Play Rough, então evite deixá-lo diante de Pokémon vulneráveis a esses golpes. Cure a equipe antes de entrar e leve Awakenings."], "TRIAL - NANU": ["Nanu é o kahuna de Ula’ula e usa Pokémon do tipo Sombrio. Seu time tem Sableye e Krokorok no nível 38 e Persian de Alola no nível 39.", "Sableye é dos tipos Sombrio e Fantasma e recebe dano superefetivo apenas do tipo Fada. Krokorok também é do tipo Terra e é vulnerável a Água, Planta, Gelo, Lutador, Inseto e Fada. Persian de Alola é vulnerável a Lutador, Inseto e Fada.", "Se você escolheu Popplio, sua evolução pode usar golpes do tipo Fada, desde que já tenha chegado à forma Primarina, e ataques de Água contra Krokorok. Confira o nível da sua equipe antes de depender da evolução.", "Para Sableye, prefira um golpe do tipo Fada. Contra Krokorok, golpes de Água ou Planta são boas alternativas. Contra Persian, leve uma resposta ao Darkinium Z que ele segura.", "Cure sua equipe antes da batalha e mantenha itens de recuperação para enfrentar os três Pokémon em sequência."], "TRIAL - HAPU": ["Hapu é a kahuna de Poni e usa Pokémon do tipo Terra. Seu time tem Dugtrio de Alola, Gastrodon e Flygon no nível 47 e Mudsdale no nível 48.", "Dugtrio de Alola é vulnerável a golpes de Água, Fogo, Lutador e Terra. Gastrodon recebe quatro vezes mais dano de Planta, enquanto Flygon recebe quatro vezes mais dano de Gelo. Mudsdale é vulnerável a Água, Planta e Gelo.", "Se você escolheu Rowlet, seu Decidueye pode usar golpes de Planta contra Gastrodon e Mudsdale. Se escolheu Popplio, sua Primarina pode usar golpes de Água contra Dugtrio e Mudsdale e golpes de Fada contra Flygon.", "Para Flygon, use um golpe de Gelo quando puder. Sua habilidade Levitate o torna imune a golpes do tipo Terra, e seus ataques de Dragão podem ser perigosos para outros dragões.", "Mudsdale pode aumentar sua Defesa com Stamina ao receber golpes. Evite depender de muitos ataques físicos fracos e cure sua equipe antes da batalha."], "TRIAL - KOMMO-O": ["No desafio de Vast Poni Canyon, você enfrenta o Totem Kommo-o no nível 45. Ele é dos tipos Dragão e Lutador e recebe quatro vezes mais dano de golpes do tipo Fada.", "Se você escolheu Popplio, sua Primarina pode usar golpes de Fada contra Kommo-o. Outra opção é levar um Pokémon com golpes de Fada treinado durante a jornada.", "Kommo-o pode chamar Scizor para ajudá-lo. Scizor é dos tipos Inseto e Metal e recebe quatro vezes mais dano de golpes de Fogo, mas resiste aos golpes de Fada usados contra Kommo-o.", "Tenha cuidado com a aura do Totem e com os ataques dos dois adversários. Prepare uma resposta para Scizor antes de concentrar seus golpes de Fada em Kommo-o."], "ELITE FOUR - HALA": ["Hala integra a Elite Four e usa Pokémon do tipo Lutador. Seu time tem Hariyama, Primeape, Bewear e Poliwrath no nível 54 e Crabominable no nível 55.", "Hariyama, Primeape e Bewear são vulneráveis a golpes dos tipos Voador, Psíquico e Fada. Poliwrath também é do tipo Água e recebe dano superefetivo de Elétrico e Planta. Crabominable também é do tipo Gelo e recebe dano superefetivo de Fogo e Lutador.", "Se você escolheu Rowlet, seu Decidueye pode usar golpes Voadores, mas tenha cuidado com golpes de Gelo de Crabominable. Se escolheu Popplio, Primarina pode aproveitar golpes do tipo Fada contra os cinco.", "Pokémon Voadores e Psíquicos são boas opções contra a equipe, mas confira seus pontos de vida antes de enfrentar o Z-Move de Crabominable. Ele segura Fightinium Z e pode usar um golpe forte do tipo Lutador.", "Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."], "ELITE FOUR - OLIVIA": ["Olivia integra a Elite Four e usa Pokémon do tipo Pedra. Seu time tem Relicanth, Carbink, Golem de Alola e Probopass no nível 54 e Lycanroc na forma Midnight no nível 55.", "Relicanth recebe quatro vezes mais dano de Planta. Golem de Alola e Probopass recebem quatro vezes mais dano de Terra, enquanto Carbink recebe quatro vezes mais dano de Metal. Lycanroc é vulnerável a Água, Planta, Lutador, Terra e Metal.", "Se você escolheu Rowlet, Decidueye pode usar golpes de Planta contra Relicanth e Lycanroc. Se escolheu Popplio, Primarina pode usar golpes de Água contra Golem, Probopass e Lycanroc, mas tenha cuidado com ataques elétricos de Golem.", "Pokémon com golpes do tipo Terra são boas opções contra Golem e Probopass. Observe Sturdy, pois um Pokémon com essa habilidade pode sobreviver a um golpe que o derrotaria quando estiver com a vida cheia.", "Lycanroc segura Rockium Z, então mantenha os Pokémon vulneráveis a Pedra com bastante vida ou escolha outro membro da equipe para enfrentá-lo. Depois da vitória, recupere a equipe."], "ELITE FOUR - ACEROLA": ["Acerola integra a Elite Four e usa Pokémon do tipo Fantasma. Seu time tem Sableye, Drifblim, Dhelmise e Froslass no nível 54 e Palossand no nível 55.", "Sableye recebe dano superefetivo apenas do tipo Fada. Drifblim, Dhelmise, Froslass e Palossand são vulneráveis aos tipos Fantasma e Sombrio. Drifblim também é vulnerável a Elétrico, Dhelmise a Fogo e Palossand a Água e Planta.", "Se você escolheu Litten, Incineroar pode usar golpes Sombrios contra os quatro fantasmas vulneráveis e golpes de Fogo contra Dhelmise. Tenha cuidado com golpes de Água e Terra que possam atingir Incineroar.", "Primarina pode usar golpes de Fada contra Sableye e de Água contra Palossand. Pokémon com golpes elétricos podem enfrentar Drifblim, enquanto golpes de Fogo ajudam contra Dhelmise e Froslass.", "Palossand segura Ghostium Z. Mantenha seus Pokémon com bastante vida e evite usar golpes Normais ou Lutadores, pois os fantasmas são imunes a eles. Depois da vitória, recupere a equipe."], "ELITE FOUR - KAHILI": ["Kahili integra a Elite Four e usa Pokémon do tipo Voador. Seu time tem Skarmory, Crobat, Oricorio no estilo Baile e Mandibuzz no nível 54 e Toucannon no nível 55.", "Skarmory é vulnerável a Fogo e Elétrico. Crobat, Mandibuzz e Toucannon recebem dano superefetivo de Elétrico, Gelo e Pedra, enquanto Oricorio recebe quatro vezes mais dano de Pedra por também ser do tipo Fogo.", "Pokémon com golpes elétricos podem enfrentar toda a equipe. Se você treinou Pikachu desde Melemele, ele ou sua evolução Raichu podem aproveitar essa fraqueza, mantendo cuidado com ataques dos adversários.", "Se você escolheu Litten, Incineroar pode usar golpes de Fogo contra Skarmory. Uma opção com golpes de Pedra também pode aproveitar a fraqueza quádrupla de Oricorio.", "Toucannon segura Flyinium Z, então prepare um Pokémon resistente ou com bastante vida para enfrentar seu Z-Move. Depois da vitória, recupere a equipe antes de seguir."], "CHAMPION": ["Após derrotar a Elite Four, você enfrenta o Professor Kukui para conquistar o título de Champion de Alola. Seu time tem Lycanroc na forma Midday, Ninetales de Alola, Braviary, Magnezone e Snorlax no nível 57, além de um inicial na forma final no nível 58.", "O último Pokémon depende do inicial escolhido. Se você escolheu Rowlet, Kukui usa Incineroar. Se escolheu Litten, ele usa Primarina. Se escolheu Popplio, ele usa Decidueye.", "Contra Lycanroc, use golpes de Água, Planta, Lutador, Terra ou Metal. Ninetales de Alola é dos tipos Gelo e Fada e recebe quatro vezes mais dano de golpes de Metal. Braviary é vulnerável a Elétrico, Gelo e Pedra.", "Magnezone recebe quatro vezes mais dano de golpes do tipo Terra. Snorlax é vulnerável a Lutador, mas mantenha cuidado com os golpes de cobertura dos dois adversários.", "Contra Incineroar, aproveite golpes de Água, Lutador ou Terra. Contra Primarina, use Elétrico, Planta ou Veneno. Contra Decidueye, golpes de Fogo, Gelo, Voador, Fantasma ou Sombrio são boas opções.", "O inicial de Kukui segura um Z-Crystal correspondente ao seu tipo. Recupere sua equipe antes da última batalha e mantenha uma resposta preparada para o Z-Move.", "Depois da vitória, sua equipe será registrada no Hall da Fama e você se tornará Champion de Alola."]}'::jsonb WHERE slug = 'pokemon-sun';
UPDATE public.builds SET caps = ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - HAPU','TRIAL - KOMMO-O','ELITE FOUR - HALA','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION'] || ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - HAPU','TRIAL - KOMMO-O','ELITE FOUR - HALA','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION']))), dicas = dicas || '{"TRIAL - ILIMA": ["Na prova de Ilima na Verdant Cavern, você enfrenta o Totem Raticate de Alola no nível 12. Ele é dos tipos Sombrio e Normal e pode chamar Rattata de Alola para ajudá-lo.", "Raticate e Rattata recebem quatro vezes mais dano de golpes do tipo Lutador. Independentemente do inicial escolhido, você pode capturar Makuhita na Route 2 e usar seus golpes Lutadores contra os dois.", "A aura do Totem aumenta sua Defesa. Tenha cuidado com Hyper Fang do Rattata aliado e mantenha seu Pokémon com bastante vida durante a batalha.", "Cure sua equipe antes de entrar e leve Potions. Durante a prova, o Totem e seus aliados não podem ser capturados."], "TRIAL - HALA": ["Hala é o kahuna de Melemele e usa Pokémon do tipo Lutador. Seu time tem Mankey e Makuhita no nível 14 e Crabrawler no nível 15.", "Os três são vulneráveis a golpes dos tipos Voador, Psíquico e Fada. Crabrawler segura o Fightinium Z e pode usar um Z-Move forte durante a batalha.", "Se você escolheu Rowlet, use seus golpes do tipo Voador. Outra opção é Pikipek, que pode ser capturado na Route 1 e usar Peck contra os três adversários.", "Butterfree é outra opção com Confusion. Capture Caterpie na Route 1 e evolua-o até Butterfree no nível 10. Seu tipo Inseto e Voador ajuda a resistir aos golpes de Lutador.", "Tenha cuidado ao trocar para um Pokémon enfraquecido quando Crabrawler ainda puder usar seu Z-Move. Cure a equipe antes da batalha e leve Potions."], "TRIAL - LANA": ["Na prova de Lana em Brooklet Hill, você enfrenta o Totem Wishiwashi no nível 20. Sua habilidade Schooling o mantém na forma de cardume enquanto ele tiver vida suficiente.", "Wishiwashi é do tipo Água e recebe dano superefetivo de golpes dos tipos Elétrico e Planta. Se você escolheu Rowlet, seus golpes de Planta podem aproveitar essa fraqueza.", "Outra opção é Pikachu com golpes elétricos. Pichu pode ser encontrado na Route 1 e evolui para Pikachu ao subir de nível com amizade alta. Mantenha atenção à vida dele, pois o Totem pode chamar um aliado.", "Alomomola pode usar Heal Pulse para recuperar a vida de Wishiwashi. Se ela aparecer, considere derrotá-la primeiro para impedir a cura e depois concentre seus ataques no Totem.", "Quando Wishiwashi perde vida suficiente, volta à forma individual e fica mais fraco. Cure sua equipe antes da prova e leve Potions."], "TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Salazzle no nível 22. Ela é dos tipos Veneno e Fogo e pode chamar Salandit para ajudá-la.", "Salazzle recebe quatro vezes mais dano de golpes do tipo Terra e também é vulnerável aos tipos Água, Pedra e Psíquico. Salandit compartilha os tipos de Salazzle e as mesmas fraquezas.", "Se você escolheu Popplio, sua evolução Brionne pode usar golpes de Água contra os dois adversários. Outra opção é Diglett de Alola com golpes do tipo Terra, encontrado na Diglett’s Tunnel.", "Tenha cuidado com Toxic de Salazzle. Sua habilidade Corrosion permite envenenar até Pokémon dos tipos Veneno e Metal, e Salandit pode aproveitar o envenenamento com Venoshock.", "Cure sua equipe antes da prova e leve Antidotes ou itens que curem envenenamento."], "TRIAL - MALLOW": ["Na prova de Mallow na Lush Jungle, você enfrenta o Totem Lurantis no nível 24. Lurantis é do tipo Planta e recebe dano superefetivo dos tipos Fogo, Gelo, Voador, Inseto e Veneno.", "Se você escolheu Litten, sua evolução Torracat pode usar golpes de Fogo. Se escolheu Rowlet, Dartrix pode usar golpes do tipo Voador, mas fique atento à vida dele durante a batalha.", "Outra opção é Trumbeak com golpes do tipo Voador. Pikipek pode ser encontrado na Route 1 e evolui para Trumbeak no nível 14.", "Lurantis segura uma Power Herb que permite usar Solar Blade sem esperar o turno de preparação. Se Castform aparecer e usar Sunny Day, Solar Blade também poderá ser usado sem carregamento enquanto o sol durar.", "Considere derrotar Castform para reduzir a pressão sobre sua equipe. Lurantis ainda pode usar Synthesis para recuperar vida, então prepare seus golpes mais fortes antes de entrar."], "TRIAL - OLIVIA": ["Olivia é a kahuna de Akala e usa Pokémon do tipo Pedra. Seu time tem Nosepass e Boldore no nível 26 e Lycanroc na forma Midnight no nível 27.", "Os três são vulneráveis a golpes dos tipos Água, Planta, Lutador, Terra e Metal. Se você escolheu Rowlet ou Popplio, sua evolução pode usar golpes de Planta ou Água para aproveitar essas fraquezas.", "Se escolheu Litten, Makuhita pode ajudar com golpes do tipo Lutador. Ele pode ser encontrado na Route 2 e evolui para Hariyama no nível 24.", "Nosepass e Boldore possuem Sturdy, que pode deixá-los com um ponto de vida se estiverem com a vida cheia ao receber um golpe que os derrotaria. Mantenha sua equipe preparada para o contra-ataque.", "Lycanroc segura Rockium Z e pode usar um Z-Move do tipo Pedra. Tenha cuidado com Pokémon de Fogo e Voador e cure sua equipe antes da batalha."], "TRIAL - SOPHOCLES": ["Na prova de Sophocles no Hokulani Observatory, você enfrenta o Totem Vikavolt no nível 29. Ele é dos tipos Inseto e Elétrico e recebe dano superefetivo de golpes dos tipos Fogo e Pedra.", "Sua habilidade Levitate o torna imune a golpes do tipo Terra, então prefira Pedra para aproveitar a fraqueza. Vikavolt segura uma Occa Berry, que reduz o dano do primeiro golpe de Fogo superefetivo.", "Um Pokémon com golpes de Pedra pode enfrentar o Totem, mas cuide da vida da equipe. Vikavolt pode chamar Charjabug, cuja habilidade Battery fortalece os golpes especiais do aliado.", "Considere derrotar Charjabug quando ele aparecer e mantenha itens de cura à mão. Não confunda essa prova com a dos remakes, que usam outro Totem."], "TRIAL - ACEROLA": ["Na prova de Acerola no Thrifty Megamart abandonado, você enfrenta o Totem Mimikyu no nível 33. Ele é dos tipos Fantasma e Fada e recebe dano superefetivo dos tipos Fantasma e Metal.", "A habilidade Disguise bloqueia o dano do primeiro golpe que o atinge. Use um ataque para quebrar o disfarce e depois aproveite a fraqueza com um golpe mais forte.", "Mimikyu pode chamar Haunter ou Gengar. Os dois também são do tipo Fantasma e podem ser atingidos por golpes Sombrios, mas tenha cuidado com Hypnosis, que pode colocar seu Pokémon para dormir.", "Mimikyu conhece Shadow Claw e Play Rough, então evite deixá-lo diante de Pokémon vulneráveis a esses golpes. Cure a equipe antes de entrar e leve Awakenings."], "TRIAL - NANU": ["Nanu é o kahuna de Ula’ula e usa Pokémon do tipo Sombrio. Seu time tem Sableye e Krokorok no nível 38 e Persian de Alola no nível 39.", "Sableye é dos tipos Sombrio e Fantasma e recebe dano superefetivo apenas do tipo Fada. Krokorok também é do tipo Terra e é vulnerável a Água, Planta, Gelo, Lutador, Inseto e Fada. Persian de Alola é vulnerável a Lutador, Inseto e Fada.", "Se você escolheu Popplio, sua evolução pode usar golpes do tipo Fada, desde que já tenha chegado à forma Primarina, e ataques de Água contra Krokorok. Confira o nível da sua equipe antes de depender da evolução.", "Para Sableye, prefira um golpe do tipo Fada. Contra Krokorok, golpes de Água ou Planta são boas alternativas. Contra Persian, leve uma resposta ao Darkinium Z que ele segura.", "Cure sua equipe antes da batalha e mantenha itens de recuperação para enfrentar os três Pokémon em sequência."], "TRIAL - HAPU": ["Hapu é a kahuna de Poni e usa Pokémon do tipo Terra. Seu time tem Dugtrio de Alola, Gastrodon e Flygon no nível 47 e Mudsdale no nível 48.", "Dugtrio de Alola é vulnerável a golpes de Água, Fogo, Lutador e Terra. Gastrodon recebe quatro vezes mais dano de Planta, enquanto Flygon recebe quatro vezes mais dano de Gelo. Mudsdale é vulnerável a Água, Planta e Gelo.", "Se você escolheu Rowlet, seu Decidueye pode usar golpes de Planta contra Gastrodon e Mudsdale. Se escolheu Popplio, sua Primarina pode usar golpes de Água contra Dugtrio e Mudsdale e golpes de Fada contra Flygon.", "Para Flygon, use um golpe de Gelo quando puder. Sua habilidade Levitate o torna imune a golpes do tipo Terra, e seus ataques de Dragão podem ser perigosos para outros dragões.", "Mudsdale pode aumentar sua Defesa com Stamina ao receber golpes. Evite depender de muitos ataques físicos fracos e cure sua equipe antes da batalha."], "TRIAL - KOMMO-O": ["No desafio de Vast Poni Canyon, você enfrenta o Totem Kommo-o no nível 45. Ele é dos tipos Dragão e Lutador e recebe quatro vezes mais dano de golpes do tipo Fada.", "Se você escolheu Popplio, sua Primarina pode usar golpes de Fada contra Kommo-o. Outra opção é levar um Pokémon com golpes de Fada treinado durante a jornada.", "Kommo-o pode chamar Scizor para ajudá-lo. Scizor é dos tipos Inseto e Metal e recebe quatro vezes mais dano de golpes de Fogo, mas resiste aos golpes de Fada usados contra Kommo-o.", "Tenha cuidado com a aura do Totem e com os ataques dos dois adversários. Prepare uma resposta para Scizor antes de concentrar seus golpes de Fada em Kommo-o."], "ELITE FOUR - HALA": ["Hala integra a Elite Four e usa Pokémon do tipo Lutador. Seu time tem Hariyama, Primeape, Bewear e Poliwrath no nível 54 e Crabominable no nível 55.", "Hariyama, Primeape e Bewear são vulneráveis a golpes dos tipos Voador, Psíquico e Fada. Poliwrath também é do tipo Água e recebe dano superefetivo de Elétrico e Planta. Crabominable também é do tipo Gelo e recebe dano superefetivo de Fogo e Lutador.", "Se você escolheu Rowlet, seu Decidueye pode usar golpes Voadores, mas tenha cuidado com golpes de Gelo de Crabominable. Se escolheu Popplio, Primarina pode aproveitar golpes do tipo Fada contra os cinco.", "Pokémon Voadores e Psíquicos são boas opções contra a equipe, mas confira seus pontos de vida antes de enfrentar o Z-Move de Crabominable. Ele segura Fightinium Z e pode usar um golpe forte do tipo Lutador.", "Depois da vitória, recupere sua equipe antes de enfrentar outro integrante da Elite Four."], "ELITE FOUR - OLIVIA": ["Olivia integra a Elite Four e usa Pokémon do tipo Pedra. Seu time tem Relicanth, Carbink, Golem de Alola e Probopass no nível 54 e Lycanroc na forma Midnight no nível 55.", "Relicanth recebe quatro vezes mais dano de Planta. Golem de Alola e Probopass recebem quatro vezes mais dano de Terra, enquanto Carbink recebe quatro vezes mais dano de Metal. Lycanroc é vulnerável a Água, Planta, Lutador, Terra e Metal.", "Se você escolheu Rowlet, Decidueye pode usar golpes de Planta contra Relicanth e Lycanroc. Se escolheu Popplio, Primarina pode usar golpes de Água contra Golem, Probopass e Lycanroc, mas tenha cuidado com ataques elétricos de Golem.", "Pokémon com golpes do tipo Terra são boas opções contra Golem e Probopass. Observe Sturdy, pois um Pokémon com essa habilidade pode sobreviver a um golpe que o derrotaria quando estiver com a vida cheia.", "Lycanroc segura Rockium Z, então mantenha os Pokémon vulneráveis a Pedra com bastante vida ou escolha outro membro da equipe para enfrentá-lo. Depois da vitória, recupere a equipe."], "ELITE FOUR - ACEROLA": ["Acerola integra a Elite Four e usa Pokémon do tipo Fantasma. Seu time tem Sableye, Drifblim, Dhelmise e Froslass no nível 54 e Palossand no nível 55.", "Sableye recebe dano superefetivo apenas do tipo Fada. Drifblim, Dhelmise, Froslass e Palossand são vulneráveis aos tipos Fantasma e Sombrio. Drifblim também é vulnerável a Elétrico, Dhelmise a Fogo e Palossand a Água e Planta.", "Se você escolheu Litten, Incineroar pode usar golpes Sombrios contra os quatro fantasmas vulneráveis e golpes de Fogo contra Dhelmise. Tenha cuidado com golpes de Água e Terra que possam atingir Incineroar.", "Primarina pode usar golpes de Fada contra Sableye e de Água contra Palossand. Pokémon com golpes elétricos podem enfrentar Drifblim, enquanto golpes de Fogo ajudam contra Dhelmise e Froslass.", "Palossand segura Ghostium Z. Mantenha seus Pokémon com bastante vida e evite usar golpes Normais ou Lutadores, pois os fantasmas são imunes a eles. Depois da vitória, recupere a equipe."], "ELITE FOUR - KAHILI": ["Kahili integra a Elite Four e usa Pokémon do tipo Voador. Seu time tem Skarmory, Crobat, Oricorio no estilo Baile e Mandibuzz no nível 54 e Toucannon no nível 55.", "Skarmory é vulnerável a Fogo e Elétrico. Crobat, Mandibuzz e Toucannon recebem dano superefetivo de Elétrico, Gelo e Pedra, enquanto Oricorio recebe quatro vezes mais dano de Pedra por também ser do tipo Fogo.", "Pokémon com golpes elétricos podem enfrentar toda a equipe. Se você treinou Pikachu desde Melemele, ele ou sua evolução Raichu podem aproveitar essa fraqueza, mantendo cuidado com ataques dos adversários.", "Se você escolheu Litten, Incineroar pode usar golpes de Fogo contra Skarmory. Uma opção com golpes de Pedra também pode aproveitar a fraqueza quádrupla de Oricorio.", "Toucannon segura Flyinium Z, então prepare um Pokémon resistente ou com bastante vida para enfrentar seu Z-Move. Depois da vitória, recupere a equipe antes de seguir."], "CHAMPION": ["Após derrotar a Elite Four, você enfrenta o Professor Kukui para conquistar o título de Champion de Alola. Seu time tem Lycanroc na forma Midday, Ninetales de Alola, Braviary, Magnezone e Snorlax no nível 57, além de um inicial na forma final no nível 58.", "O último Pokémon depende do inicial escolhido. Se você escolheu Rowlet, Kukui usa Incineroar. Se escolheu Litten, ele usa Primarina. Se escolheu Popplio, ele usa Decidueye.", "Contra Lycanroc, use golpes de Água, Planta, Lutador, Terra ou Metal. Ninetales de Alola é dos tipos Gelo e Fada e recebe quatro vezes mais dano de golpes de Metal. Braviary é vulnerável a Elétrico, Gelo e Pedra.", "Magnezone recebe quatro vezes mais dano de golpes do tipo Terra. Snorlax é vulnerável a Lutador, mas mantenha cuidado com os golpes de cobertura dos dois adversários.", "Contra Incineroar, aproveite golpes de Água, Lutador ou Terra. Contra Primarina, use Elétrico, Planta ou Veneno. Contra Decidueye, golpes de Fogo, Gelo, Voador, Fantasma ou Sombrio são boas opções.", "O inicial de Kukui segura um Z-Crystal correspondente ao seu tipo. Recupere sua equipe antes da última batalha e mantenha uma resposta preparada para o Z-Move.", "Depois da vitória, sua equipe será registrada no Hall da Fama e você se tornará Champion de Alola."]}'::jsonb WHERE slug = 'pokemon-moon';

-- Builds de Pokémon Ultra Sun e Ultra Moon.
UPDATE public.builds SET caps = ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - KOMMO-O','BATALHA - ULTRA NECROZMA','TRIAL - MINA','TRIAL - HAPU','ELITE FOUR - MOLAYNE','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION'] || ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - KOMMO-O','BATALHA - ULTRA NECROZMA','TRIAL - MINA','TRIAL - HAPU','ELITE FOUR - MOLAYNE','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION']))), dicas = dicas || '{"TRIAL - ILIMA": ["Na prova de Ilima na Verdant Cavern, você enfrenta o Totem Gumshoos no nível 12. Ele é do tipo Normal e pode chamar Yungoos para ajudá-lo.", "Gumshoos e Yungoos recebem dano superefetivo de golpes do tipo Lutador. Independentemente do inicial escolhido, você pode capturar Makuhita na Route 2 e usar seus golpes Lutadores contra os dois.", "A aura do Totem aumenta sua Defesa. Tenha cuidado com Super Fang, que reduz pela metade a vida atual do seu Pokémon, e com Hyper Fang do Yungoos aliado.", "Cure sua equipe antes de entrar e leve Potions. Durante a prova, o Totem e seus aliados não podem ser capturados."], "TRIAL - HALA": ["Hala é o kahuna de Melemele e usa Pokémon do tipo Lutador. Em Ultra Sun e Ultra Moon, seu time tem Machop e Makuhita no nível 15 e Crabrawler no nível 16.", "Os três recebem dano superefetivo de golpes dos tipos Voador, Psíquico e Fada. Crabrawler segura o Fightinium Z e pode usar um Z-Move forte durante a batalha.", "Se você escolheu Rowlet, use seus golpes do tipo Voador. Outra opção é Pikipek, capturado na Route 1, com Peck contra os três adversários.", "Butterfree também pode usar Confusion. Capture Caterpie na Route 1 e evolua-o até Butterfree no nível 10. Seu tipo Inseto e Voador ajuda a resistir aos golpes de Lutador.", "Tenha cuidado quando Crabrawler ainda puder usar seu Z-Move. Cure a equipe antes da batalha e leve Potions."], "TRIAL - LANA": ["Na prova de Lana em Brooklet Hill, você enfrenta o Totem Araquanid no nível 20. Ele é dos tipos Água e Inseto e recebe dano superefetivo de golpes dos tipos Elétrico, Voador e Pedra.", "Se você escolheu Rowlet, sua evolução Dartrix pode usar golpes Voadores. Tenha muito cuidado com Aurora Beam de Araquanid, que causa quatro vezes mais dano a Dartrix por ele ser dos tipos Planta e Voador.", "Outra opção é Pikachu com golpes elétricos. Pichu pode ser encontrado na Route 1 e evolui para Pikachu ao subir de nível com amizade alta. A Wacan Berry do Totem reduz o primeiro golpe elétrico superefetivo.", "Araquanid pode chamar Dewpider ou Masquerain. Sua habilidade Water Bubble fortalece seus golpes de Água, e a chuva pode aumentar ainda mais o dano. Mantenha cuidado com Bubble mesmo se seu Pokémon não tiver desvantagem.", "Dewpider pode usar Sticky Web, que reduz a Velocidade de Pokémon da sua equipe que entrarem depois. Considere derrotar o aliado e mantenha Potions para o Totem."], "TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Marowak de Alola no nível 22. Ele é dos tipos Fogo e Fantasma e pode chamar Salazzle para ajudá-lo.", "Marowak é vulnerável aos tipos Água, Terra, Pedra, Fantasma e Sombrio. Salazzle é dos tipos Fogo e Veneno e recebe quatro vezes mais dano de golpes do tipo Terra.", "Se você escolheu Popplio, Brionne pode usar golpes de Água contra os dois. Outra opção é Diglett de Alola com golpes do tipo Terra, encontrado na Diglett’s Tunnel, mas cuide da vida dele diante dos golpes de Fogo.", "Marowak segura Thick Club, que aumenta muito seu Ataque. Seu Flame Wheel e Brick Break podem causar bastante dano. Salazzle pode envenenar sua equipe com Poison Gas e aproveitar o estado com Venoshock.", "Cure sua equipe antes da prova e leve Potions e Antidotes. Golpes do tipo Elétrico não atingem Marowak quando sua habilidade Lightning Rod está ativa."], "TRIAL - MALLOW": ["Na prova de Mallow na Lush Jungle, você enfrenta o Totem Lurantis no nível 24. Ele é do tipo Planta e recebe dano superefetivo dos tipos Fogo, Gelo, Voador, Inseto e Veneno.", "Se você escolheu Litten, Torracat pode usar golpes de Fogo. Se escolheu Rowlet, Dartrix pode usar golpes do tipo Voador. Trumbeak, evoluído de Pikipek no nível 14, é outra opção com ataques Voadores.", "Lurantis segura uma Power Herb que permite usar Solar Blade sem esperar o turno de preparação. Ele pode chamar Kecleon ou Comfey, que podem usar Sunny Day e permitir novos usos de Solar Blade sem carregamento.", "Comfey também pode recuperar a vida de Lurantis com Floral Healing. Se ele aparecer, considere derrotá-lo rapidamente, e fique atento a Ancient Power de Kecleon contra seus Pokémon Voadores ou de Fogo.", "Lurantis conhece Synthesis para recuperar vida e X-Scissor para atacar. Cure sua equipe e leve Potions antes de entrar."], "TRIAL - OLIVIA": ["Olivia é a kahuna de Akala e usa Pokémon do tipo Pedra. Em Ultra Sun e Ultra Moon, seu time tem Anorith e Lileep no nível 27 e Lycanroc na forma Midnight no nível 28.", "Anorith é dos tipos Pedra e Inseto e é vulnerável a Água, Pedra e Metal. Lileep é dos tipos Pedra e Planta e recebe dano superefetivo de Lutador, Inseto, Gelo e Metal. Lycanroc é vulnerável a Água, Planta, Lutador, Terra e Metal.", "Se você escolheu Popplio, Brionne pode usar golpes de Água contra Anorith e Lycanroc. Se escolheu Rowlet, Dartrix pode usar golpes de Planta contra Lycanroc, mas deve tomar cuidado com golpes do tipo Pedra.", "Outra opção contra Lileep e Lycanroc é Hariyama com golpes Lutadores. Makuhita pode ser encontrado na Route 2 e evolui para Hariyama no nível 24.", "Lycanroc segura Rockium Z e pode usar um Z-Move forte. Lileep possui Storm Drain, que impede golpes de Água de causar dano nele e aumenta seu Ataque Especial, então escolha outro tipo para enfrentá-lo."], "TRIAL - SOPHOCLES": ["Na prova de Sophocles no Hokulani Observatory, você enfrenta o Totem Togedemaru no nível 33. Ele é dos tipos Elétrico e Metal e recebe quatro vezes mais dano de golpes do tipo Terra, além de ser vulnerável a Fogo e Lutador.", "Se você escolheu Litten, Torracat ou Incineroar pode usar golpes de Fogo, mantendo cuidado com os ataques do Totem. Um Pokémon com golpes de Terra também pode aproveitar sua fraqueza de quatro vezes.", "Togedemaru pode chamar Skarmory ou Dedenne. Skarmory é imune a golpes de Terra por também ser do tipo Voador, mas recebe dano superefetivo de Fogo e Elétrico.", "A habilidade Lightning Rod de Togedemaru atrai golpes elétricos e o torna imune a eles. Ele conhece Spiky Shield, que protege o Totem e causa dano a quem usar um golpe de contato.", "Fique atento a Zing Zap e Iron Head, que podem fazer seu Pokémon perder o turno, e à Sitrus Berry, que pode recuperar parte da vida do Totem."], "TRIAL - ACEROLA": ["Na prova de Acerola no Thrifty Megamart abandonado, você enfrenta o Totem Mimikyu no nível 35. Ele é dos tipos Fantasma e Fada e recebe dano superefetivo dos tipos Fantasma e Metal.", "A habilidade Disguise bloqueia o dano do primeiro golpe que o atinge. Quebre o disfarce antes de usar um golpe forte para aproveitar suas fraquezas.", "Mimikyu pode chamar Banette ou Jellicent. Os dois são vulneráveis a golpes Sombrios, mas tenha cuidado com Will-O-Wisp de Banette, que pode queimar seu Pokémon.", "Mimikyu conhece Shadow Claw, Play Rough e Leech Life. Sua aura aumenta os atributos, então evite deixá-lo diante de Pokémon vulneráveis aos seus ataques e cure a equipe antes de entrar."], "TRIAL - NANU": ["Nanu é o kahuna de Ula’ula e usa Pokémon do tipo Sombrio. Em Ultra Sun e Ultra Moon, seu time tem Sableye e Krokorok no nível 43 e Persian de Alola no nível 44.", "Sableye é dos tipos Sombrio e Fantasma e recebe dano superefetivo apenas do tipo Fada. Krokorok também é do tipo Terra e é vulnerável a Água, Planta, Gelo, Lutador, Inseto e Fada. Persian de Alola é vulnerável a Lutador, Inseto e Fada.", "Se você escolheu Popplio, sua Primarina pode usar golpes do tipo Fada contra os três e golpes de Água contra Krokorok. Outra opção é um Pokémon de Fada treinado durante a jornada para enfrentar Sableye.", "Contra Krokorok, você também pode usar golpes de Água ou Planta. Persian segura Darkinium Z, então mantenha a vida da equipe alta para suportar seu Z-Move.", "Cure seus Pokémon antes da batalha e leve itens de recuperação para enfrentar os três em sequência."], "TRIAL - KOMMO-O": ["No desafio de Vast Poni Canyon, você enfrenta o Totem Kommo-o no nível 49. Ele é dos tipos Dragão e Lutador e recebe quatro vezes mais dano de golpes do tipo Fada.", "Se você escolheu Popplio, sua Primarina pode usar golpes de Fada contra Kommo-o. Porém, tenha cuidado com Poison Jab, que é superefetivo contra ela por ser do tipo Fada, e com Thunder Punch, que é superefetivo por ela ser do tipo Água.", "Kommo-o pode chamar Noivern ou Scizor. Scizor recebe quatro vezes mais dano de golpes de Fogo, mas resiste aos golpes de Fada usados contra Kommo-o. Noivern recebe quatro vezes mais dano de Gelo.", "Kommo-o também conhece Drain Punch e pode recuperar vida ao atacar. Prepare uma resposta aos aliados e não dependa apenas de um Pokémon vulnerável a Poison Jab."], "BATALHA - ULTRA NECROZMA": ["Em Ultra Megalopolis, você enfrenta Ultra Necrozma no nível 60. Ele é dos tipos Psíquico e Dragão e sua aura aumenta seus atributos no começo da batalha.", "Ultra Necrozma recebe dano superefetivo dos tipos Gelo, Inseto, Fantasma, Sombrio, Dragão e Fada. Sua habilidade Neuroforce fortalece ainda mais os golpes que atingem uma fraqueza do seu Pokémon.", "Pokémon do tipo Sombrio são imunes a Photon Geyser e podem atacar com golpes Sombrios, mas Necrozma também conhece Dragon Pulse, Power Gem e Smart Strike. Nenhum Pokémon deve ser considerado seguro apenas por ser imune a um desses golpes.", "Se você usar um Pokémon do tipo Fada para bloquear Dragon Pulse, tenha muito cuidado com Smart Strike, que é superefetivo contra ele. Pokémon de Fogo e Voador também precisam tomar cuidado com Power Gem.", "Golpes que causem envenenamento podem ajudar a desgastar Necrozma ao longo dos turnos, mas a estratégia exige sobreviver aos ataques. Cure sua equipe, prepare itens e escolha seus Pokémon antes de iniciar a batalha."], "TRIAL - MINA": ["Na prova de Mina em Seafolk Village, você enfrenta o Totem Ribombee no nível 55. Ele é dos tipos Inseto e Fada e recebe dano superefetivo de golpes dos tipos Fogo, Voador, Pedra, Veneno e Metal.", "Se você escolheu Litten, Incineroar pode usar golpes de Fogo. Pokémon com golpes dos tipos Metal, Veneno ou Voador também podem explorar as fraquezas de Ribombee.", "Ribombee conhece Quiver Dance, que aumenta seu Ataque Especial, Defesa Especial e Velocidade. Procure não deixar o Totem acumular aumentos antes de atacá-lo.", "Ele pode chamar Blissey ou Pelipper. Blissey pode recuperar a vida de Ribombee com Heal Pulse e usar Light Screen, enquanto Pelipper ativa chuva com Drizzle, enfraquecendo golpes de Fogo.", "Se Blissey aparecer, considere derrotá-la antes de concentrar seus ataques no Totem. Mantenha cuidado com Bug Buzz e Dazzling Gleam e cure sua equipe antes da prova."], "TRIAL - HAPU": ["Hapu é a kahuna de Poni e usa Pokémon do tipo Terra. Em Ultra Sun e Ultra Moon, seu time tem Golurk, Gastrodon e Flygon no nível 53 e Mudsdale no nível 54.", "Golurk é dos tipos Terra e Fantasma e é vulnerável a Água, Planta, Gelo, Fantasma e Sombrio. Gastrodon recebe quatro vezes mais dano de Planta, enquanto Flygon recebe quatro vezes mais dano de Gelo. Mudsdale é vulnerável a Água, Planta e Gelo.", "Se você escolheu Rowlet, Decidueye pode usar golpes de Planta contra Gastrodon e Mudsdale e golpes Fantasmas contra Golurk. Se escolheu Popplio, Primarina pode usar golpes de Água contra Golurk e Mudsdale e golpes de Fada contra Flygon.", "Flygon possui Levitate e é imune a golpes do tipo Terra. Um golpe de Gelo aproveita sua fraqueza de quatro vezes, mas mantenha cuidado com os ataques que ele conhece.", "Mudsdale pode aumentar sua Defesa com Stamina ao receber golpes. Evite depender de muitos ataques físicos fracos e cure sua equipe antes da batalha."], "ELITE FOUR - MOLAYNE": ["Molayne integra a Elite Four e usa Pokémon do tipo Metal. Seu time tem Klefki, Bisharp, Magnezone e Metagross no nível 56 e Dugtrio de Alola no nível 57.", "Klefki recebe dano superefetivo de Fogo e Terra. Bisharp recebe quatro vezes mais dano de Lutador, enquanto Magnezone recebe quatro vezes mais dano de Terra. Metagross é vulnerável a Fogo, Terra, Fantasma e Sombrio.", "Se você escolheu Litten, Incineroar pode usar golpes de Fogo contra Klefki, Bisharp, Magnezone e Metagross. Tenha cuidado com golpes de Terra e Lutador que possam atingir Incineroar.", "Um Pokémon com golpes Lutadores pode aproveitar a fraqueza de Bisharp, enquanto golpes de Terra são especialmente eficazes contra Magnezone. Dugtrio de Alola também é do tipo Terra e é vulnerável a Água, Fogo, Lutador e Terra.", "Klefki pode usar Spikes e Thunder Wave. Dugtrio segura Steelium Z e conhece Fissure, que pode derrotar um Pokémon em um único acerto. Recupere sua equipe antes e depois da batalha."], "ELITE FOUR - OLIVIA": ["Olivia integra a Elite Four e usa Pokémon do tipo Pedra. Em Ultra Sun e Ultra Moon, seu time tem Armaldo, Cradily, Gigalith e Probopass no nível 56 e Lycanroc na forma Midnight no nível 57.", "Armaldo é vulnerável a Água, Pedra e Metal. Cradily recebe dano superefetivo de Lutador, Inseto, Gelo e Metal. Probopass recebe quatro vezes mais dano de Lutador e Terra, enquanto Gigalith e Lycanroc são vulneráveis a Água, Planta, Lutador, Terra e Metal.", "Se você escolheu Popplio, Primarina pode usar golpes de Água contra Armaldo, Gigalith, Probopass e Lycanroc. Se escolheu Rowlet, Decidueye pode usar golpes de Planta contra Gigalith e Lycanroc, mas deve ter cuidado com os ataques de Pedra.", "Pokémon com golpes Lutadores podem enfrentar Cradily, Probopass, Gigalith e Lycanroc. Contra Probopass, aproveite sua fraqueza de quatro vezes, mas tenha cuidado com Sturdy, que pode deixá-lo com um ponto de vida quando estiver com a vida cheia.", "Lycanroc segura Rockium Z. Mantenha a equipe recuperada antes de enfrentá-lo e depois cure seus Pokémon antes da próxima batalha."], "ELITE FOUR - ACEROLA": ["Acerola integra a Elite Four e usa Pokémon do tipo Fantasma. Em Ultra Sun e Ultra Moon, seu time tem Sableye, Drifblim, Dhelmise e Froslass no nível 56 e Palossand no nível 57.", "Sableye recebe dano superefetivo apenas do tipo Fada. Drifblim, Dhelmise, Froslass e Palossand são vulneráveis aos tipos Fantasma e Sombrio. Drifblim também é vulnerável a Elétrico, Dhelmise a Fogo e Palossand a Água e Planta.", "Se você escolheu Litten, Incineroar pode usar golpes Sombrios contra os quatro fantasmas vulneráveis e golpes de Fogo contra Dhelmise. Tenha cuidado com golpes de Água e Terra que possam atingir Incineroar.", "Primarina pode usar golpes de Fada contra Sableye e de Água contra Palossand. Pokémon com golpes elétricos podem enfrentar Drifblim, enquanto golpes de Fogo ajudam contra Dhelmise e Froslass.", "Palossand segura Ghostium Z. Mantenha seus Pokémon com bastante vida e evite golpes Normais ou Lutadores, pois os fantasmas são imunes a eles. Depois da vitória, recupere a equipe."], "ELITE FOUR - KAHILI": ["Kahili integra a Elite Four e usa Pokémon do tipo Voador. Em Ultra Sun e Ultra Moon, seu time tem Braviary, Hawlucha, Oricorio no estilo Baile e Mandibuzz no nível 56 e Toucannon no nível 57.", "Braviary, Hawlucha, Mandibuzz e Toucannon recebem dano superefetivo de golpes Elétricos, de Gelo e de Pedra. Oricorio recebe quatro vezes mais dano de Pedra por também ser do tipo Fogo.", "Pokémon com golpes elétricos podem enfrentar toda a equipe. Se você treinou Pikachu desde Melemele, ele ou sua evolução Raichu podem aproveitar essa fraqueza, mantendo cuidado com os ataques adversários.", "Uma opção com golpes de Pedra também pode aproveitar a fraqueza quádrupla de Oricorio. Fique atento a ataques Lutadores de Hawlucha, que podem ser perigosos para Pokémon do tipo Pedra.", "Toucannon segura Flyinium Z, então prepare um Pokémon resistente ou com bastante vida para enfrentar seu Z-Move. Depois da vitória, recupere a equipe antes de seguir."], "CHAMPION": ["Depois de derrotar a Elite Four, você enfrenta seu amigo Hau na última batalha da Liga de Alola. Seu time tem Raichu de Alola no nível 59, Tauros e Noivern no nível 58 e Crabominable no nível 59. Os outros dois Pokémon dependem do inicial escolhido.", "Se você escolheu Rowlet, Hau usa Flareon e Primarina. Se escolheu Litten, ele usa Vaporeon e Decidueye. Se escolheu Popplio, ele usa Leafeon e Incineroar. A evolução do inicial está no nível 60 e segura um Z-Crystal.", "Raichu de Alola é dos tipos Elétrico e Psíquico e recebe dano superefetivo de Terra, Inseto, Fantasma e Sombrio. Tauros é vulnerável a Lutador, mas conhece Zen Headbutt, que pode atingir Pokémon desse tipo.", "Noivern é dos tipos Voador e Dragão e recebe quatro vezes mais dano de Gelo. Crabominable é dos tipos Lutador e Gelo e recebe dano superefetivo de Fogo, Lutador, Voador, Psíquico, Fada e Metal, mas conhece Stone Edge para atingir Pokémon vulneráveis a Pedra.", "Contra Flareon ou Incineroar, use golpes de Água ou Terra. Contra Vaporeon ou Primarina, use Elétrico ou Planta. Contra Leafeon ou Decidueye, golpes de Fogo, Gelo ou Voador são boas opções, mas Decidueye conhece Smack Down para atingir Pokémon Voadores.", "Recupere a equipe antes da batalha e mantenha uma resposta preparada para o Z-Move do inicial de Hau. Depois da vitória, sua equipe será registrada no Hall da Fama e você se tornará Champion de Alola."]}'::jsonb WHERE slug = 'pokemon-ultra-sun';
UPDATE public.builds SET caps = ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - KOMMO-O','BATALHA - ULTRA NECROZMA','TRIAL - MINA','TRIAL - HAPU','ELITE FOUR - MOLAYNE','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION'] || ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['TRIAL - ILIMA','TRIAL - HALA','TRIAL - LANA','TRIAL - KIAWE','TRIAL - MALLOW','TRIAL - OLIVIA','TRIAL - SOPHOCLES','TRIAL - ACEROLA','TRIAL - NANU','TRIAL - KOMMO-O','BATALHA - ULTRA NECROZMA','TRIAL - MINA','TRIAL - HAPU','ELITE FOUR - MOLAYNE','ELITE FOUR - OLIVIA','ELITE FOUR - ACEROLA','ELITE FOUR - KAHILI','CHAMPION']))), dicas = dicas || '{"TRIAL - ILIMA": ["Na prova de Ilima na Verdant Cavern, você enfrenta o Totem Raticate de Alola no nível 12. Ele é dos tipos Sombrio e Normal e pode chamar Rattata de Alola para ajudá-lo.", "Raticate e Rattata recebem quatro vezes mais dano de golpes do tipo Lutador. Independentemente do inicial escolhido, você pode capturar Makuhita na Route 2 e usar seus golpes Lutadores contra os dois.", "A aura do Totem aumenta sua Defesa. Tenha cuidado com Hyper Fang do Rattata aliado e mantenha seu Pokémon com bastante vida durante a batalha.", "Cure sua equipe antes de entrar e leve Potions. Durante a prova, o Totem e seus aliados não podem ser capturados."], "TRIAL - HALA": ["Hala é o kahuna de Melemele e usa Pokémon do tipo Lutador. Em Ultra Sun e Ultra Moon, seu time tem Machop e Makuhita no nível 15 e Crabrawler no nível 16.", "Os três recebem dano superefetivo de golpes dos tipos Voador, Psíquico e Fada. Crabrawler segura o Fightinium Z e pode usar um Z-Move forte durante a batalha.", "Se você escolheu Rowlet, use seus golpes do tipo Voador. Outra opção é Pikipek, capturado na Route 1, com Peck contra os três adversários.", "Butterfree também pode usar Confusion. Capture Caterpie na Route 1 e evolua-o até Butterfree no nível 10. Seu tipo Inseto e Voador ajuda a resistir aos golpes de Lutador.", "Tenha cuidado quando Crabrawler ainda puder usar seu Z-Move. Cure a equipe antes da batalha e leve Potions."], "TRIAL - LANA": ["Na prova de Lana em Brooklet Hill, você enfrenta o Totem Araquanid no nível 20. Ele é dos tipos Água e Inseto e recebe dano superefetivo de golpes dos tipos Elétrico, Voador e Pedra.", "Se você escolheu Rowlet, sua evolução Dartrix pode usar golpes Voadores. Tenha muito cuidado com Aurora Beam de Araquanid, que causa quatro vezes mais dano a Dartrix por ele ser dos tipos Planta e Voador.", "Outra opção é Pikachu com golpes elétricos. Pichu pode ser encontrado na Route 1 e evolui para Pikachu ao subir de nível com amizade alta. A Wacan Berry do Totem reduz o primeiro golpe elétrico superefetivo.", "Araquanid pode chamar Dewpider ou Masquerain. Sua habilidade Water Bubble fortalece seus golpes de Água, e a chuva pode aumentar ainda mais o dano. Mantenha cuidado com Bubble mesmo se seu Pokémon não tiver desvantagem.", "Dewpider pode usar Sticky Web, que reduz a Velocidade de Pokémon da sua equipe que entrarem depois. Considere derrotar o aliado e mantenha Potions para o Totem."], "TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Marowak de Alola no nível 22. Ele é dos tipos Fogo e Fantasma e pode chamar Salazzle para ajudá-lo.", "Marowak é vulnerável aos tipos Água, Terra, Pedra, Fantasma e Sombrio. Salazzle é dos tipos Fogo e Veneno e recebe quatro vezes mais dano de golpes do tipo Terra.", "Se você escolheu Popplio, Brionne pode usar golpes de Água contra os dois. Outra opção é Diglett de Alola com golpes do tipo Terra, encontrado na Diglett’s Tunnel, mas cuide da vida dele diante dos golpes de Fogo.", "Marowak segura Thick Club, que aumenta muito seu Ataque. Seu Flame Wheel e Brick Break podem causar bastante dano. Salazzle pode envenenar sua equipe com Poison Gas e aproveitar o estado com Venoshock.", "Cure sua equipe antes da prova e leve Potions e Antidotes. Golpes do tipo Elétrico não atingem Marowak quando sua habilidade Lightning Rod está ativa."], "TRIAL - MALLOW": ["Na prova de Mallow na Lush Jungle, você enfrenta o Totem Lurantis no nível 24. Ele é do tipo Planta e recebe dano superefetivo dos tipos Fogo, Gelo, Voador, Inseto e Veneno.", "Se você escolheu Litten, Torracat pode usar golpes de Fogo. Se escolheu Rowlet, Dartrix pode usar golpes do tipo Voador. Trumbeak, evoluído de Pikipek no nível 14, é outra opção com ataques Voadores.", "Lurantis segura uma Power Herb que permite usar Solar Blade sem esperar o turno de preparação. Ele pode chamar Kecleon ou Comfey, que podem usar Sunny Day e permitir novos usos de Solar Blade sem carregamento.", "Comfey também pode recuperar a vida de Lurantis com Floral Healing. Se ele aparecer, considere derrotá-lo rapidamente, e fique atento a Ancient Power de Kecleon contra seus Pokémon Voadores ou de Fogo.", "Lurantis conhece Synthesis para recuperar vida e X-Scissor para atacar. Cure sua equipe e leve Potions antes de entrar."], "TRIAL - OLIVIA": ["Olivia é a kahuna de Akala e usa Pokémon do tipo Pedra. Em Ultra Sun e Ultra Moon, seu time tem Anorith e Lileep no nível 27 e Lycanroc na forma Midnight no nível 28.", "Anorith é dos tipos Pedra e Inseto e é vulnerável a Água, Pedra e Metal. Lileep é dos tipos Pedra e Planta e recebe dano superefetivo de Lutador, Inseto, Gelo e Metal. Lycanroc é vulnerável a Água, Planta, Lutador, Terra e Metal.", "Se você escolheu Popplio, Brionne pode usar golpes de Água contra Anorith e Lycanroc. Se escolheu Rowlet, Dartrix pode usar golpes de Planta contra Lycanroc, mas deve tomar cuidado com golpes do tipo Pedra.", "Outra opção contra Lileep e Lycanroc é Hariyama com golpes Lutadores. Makuhita pode ser encontrado na Route 2 e evolui para Hariyama no nível 24.", "Lycanroc segura Rockium Z e pode usar um Z-Move forte. Lileep possui Storm Drain, que impede golpes de Água de causar dano nele e aumenta seu Ataque Especial, então escolha outro tipo para enfrentá-lo."], "TRIAL - SOPHOCLES": ["Na prova de Sophocles no Hokulani Observatory, você enfrenta o Totem Togedemaru no nível 33. Ele é dos tipos Elétrico e Metal e recebe quatro vezes mais dano de golpes do tipo Terra, além de ser vulnerável a Fogo e Lutador.", "Se você escolheu Litten, Torracat ou Incineroar pode usar golpes de Fogo, mantendo cuidado com os ataques do Totem. Um Pokémon com golpes de Terra também pode aproveitar sua fraqueza de quatro vezes.", "Togedemaru pode chamar Skarmory ou Dedenne. Skarmory é imune a golpes de Terra por também ser do tipo Voador, mas recebe dano superefetivo de Fogo e Elétrico.", "A habilidade Lightning Rod de Togedemaru atrai golpes elétricos e o torna imune a eles. Ele conhece Spiky Shield, que protege o Totem e causa dano a quem usar um golpe de contato.", "Fique atento a Zing Zap e Iron Head, que podem fazer seu Pokémon perder o turno, e à Sitrus Berry, que pode recuperar parte da vida do Totem."], "TRIAL - ACEROLA": ["Na prova de Acerola no Thrifty Megamart abandonado, você enfrenta o Totem Mimikyu no nível 35. Ele é dos tipos Fantasma e Fada e recebe dano superefetivo dos tipos Fantasma e Metal.", "A habilidade Disguise bloqueia o dano do primeiro golpe que o atinge. Quebre o disfarce antes de usar um golpe forte para aproveitar suas fraquezas.", "Mimikyu pode chamar Banette ou Jellicent. Os dois são vulneráveis a golpes Sombrios, mas tenha cuidado com Will-O-Wisp de Banette, que pode queimar seu Pokémon.", "Mimikyu conhece Shadow Claw, Play Rough e Leech Life. Sua aura aumenta os atributos, então evite deixá-lo diante de Pokémon vulneráveis aos seus ataques e cure a equipe antes de entrar."], "TRIAL - NANU": ["Nanu é o kahuna de Ula’ula e usa Pokémon do tipo Sombrio. Em Ultra Sun e Ultra Moon, seu time tem Sableye e Krokorok no nível 43 e Persian de Alola no nível 44.", "Sableye é dos tipos Sombrio e Fantasma e recebe dano superefetivo apenas do tipo Fada. Krokorok também é do tipo Terra e é vulnerável a Água, Planta, Gelo, Lutador, Inseto e Fada. Persian de Alola é vulnerável a Lutador, Inseto e Fada.", "Se você escolheu Popplio, sua Primarina pode usar golpes do tipo Fada contra os três e golpes de Água contra Krokorok. Outra opção é um Pokémon de Fada treinado durante a jornada para enfrentar Sableye.", "Contra Krokorok, você também pode usar golpes de Água ou Planta. Persian segura Darkinium Z, então mantenha a vida da equipe alta para suportar seu Z-Move.", "Cure seus Pokémon antes da batalha e leve itens de recuperação para enfrentar os três em sequência."], "TRIAL - KOMMO-O": ["No desafio de Vast Poni Canyon, você enfrenta o Totem Kommo-o no nível 49. Ele é dos tipos Dragão e Lutador e recebe quatro vezes mais dano de golpes do tipo Fada.", "Se você escolheu Popplio, sua Primarina pode usar golpes de Fada contra Kommo-o. Porém, tenha cuidado com Poison Jab, que é superefetivo contra ela por ser do tipo Fada, e com Thunder Punch, que é superefetivo por ela ser do tipo Água.", "Kommo-o pode chamar Noivern ou Scizor. Scizor recebe quatro vezes mais dano de golpes de Fogo, mas resiste aos golpes de Fada usados contra Kommo-o. Noivern recebe quatro vezes mais dano de Gelo.", "Kommo-o também conhece Drain Punch e pode recuperar vida ao atacar. Prepare uma resposta aos aliados e não dependa apenas de um Pokémon vulnerável a Poison Jab."], "BATALHA - ULTRA NECROZMA": ["Em Ultra Megalopolis, você enfrenta Ultra Necrozma no nível 60. Ele é dos tipos Psíquico e Dragão e sua aura aumenta seus atributos no começo da batalha.", "Ultra Necrozma recebe dano superefetivo dos tipos Gelo, Inseto, Fantasma, Sombrio, Dragão e Fada. Sua habilidade Neuroforce fortalece ainda mais os golpes que atingem uma fraqueza do seu Pokémon.", "Pokémon do tipo Sombrio são imunes a Photon Geyser e podem atacar com golpes Sombrios, mas Necrozma também conhece Dragon Pulse, Power Gem e Smart Strike. Nenhum Pokémon deve ser considerado seguro apenas por ser imune a um desses golpes.", "Se você usar um Pokémon do tipo Fada para bloquear Dragon Pulse, tenha muito cuidado com Smart Strike, que é superefetivo contra ele. Pokémon de Fogo e Voador também precisam tomar cuidado com Power Gem.", "Golpes que causem envenenamento podem ajudar a desgastar Necrozma ao longo dos turnos, mas a estratégia exige sobreviver aos ataques. Cure sua equipe, prepare itens e escolha seus Pokémon antes de iniciar a batalha."], "TRIAL - MINA": ["Na prova de Mina em Seafolk Village, você enfrenta o Totem Ribombee no nível 55. Ele é dos tipos Inseto e Fada e recebe dano superefetivo de golpes dos tipos Fogo, Voador, Pedra, Veneno e Metal.", "Se você escolheu Litten, Incineroar pode usar golpes de Fogo. Pokémon com golpes dos tipos Metal, Veneno ou Voador também podem explorar as fraquezas de Ribombee.", "Ribombee conhece Quiver Dance, que aumenta seu Ataque Especial, Defesa Especial e Velocidade. Procure não deixar o Totem acumular aumentos antes de atacá-lo.", "Ele pode chamar Blissey ou Pelipper. Blissey pode recuperar a vida de Ribombee com Heal Pulse e usar Light Screen, enquanto Pelipper ativa chuva com Drizzle, enfraquecendo golpes de Fogo.", "Se Blissey aparecer, considere derrotá-la antes de concentrar seus ataques no Totem. Mantenha cuidado com Bug Buzz e Dazzling Gleam e cure sua equipe antes da prova."], "TRIAL - HAPU": ["Hapu é a kahuna de Poni e usa Pokémon do tipo Terra. Em Ultra Sun e Ultra Moon, seu time tem Golurk, Gastrodon e Flygon no nível 53 e Mudsdale no nível 54.", "Golurk é dos tipos Terra e Fantasma e é vulnerável a Água, Planta, Gelo, Fantasma e Sombrio. Gastrodon recebe quatro vezes mais dano de Planta, enquanto Flygon recebe quatro vezes mais dano de Gelo. Mudsdale é vulnerável a Água, Planta e Gelo.", "Se você escolheu Rowlet, Decidueye pode usar golpes de Planta contra Gastrodon e Mudsdale e golpes Fantasmas contra Golurk. Se escolheu Popplio, Primarina pode usar golpes de Água contra Golurk e Mudsdale e golpes de Fada contra Flygon.", "Flygon possui Levitate e é imune a golpes do tipo Terra. Um golpe de Gelo aproveita sua fraqueza de quatro vezes, mas mantenha cuidado com os ataques que ele conhece.", "Mudsdale pode aumentar sua Defesa com Stamina ao receber golpes. Evite depender de muitos ataques físicos fracos e cure sua equipe antes da batalha."], "ELITE FOUR - MOLAYNE": ["Molayne integra a Elite Four e usa Pokémon do tipo Metal. Seu time tem Klefki, Bisharp, Magnezone e Metagross no nível 56 e Dugtrio de Alola no nível 57.", "Klefki recebe dano superefetivo de Fogo e Terra. Bisharp recebe quatro vezes mais dano de Lutador, enquanto Magnezone recebe quatro vezes mais dano de Terra. Metagross é vulnerável a Fogo, Terra, Fantasma e Sombrio.", "Se você escolheu Litten, Incineroar pode usar golpes de Fogo contra Klefki, Bisharp, Magnezone e Metagross. Tenha cuidado com golpes de Terra e Lutador que possam atingir Incineroar.", "Um Pokémon com golpes Lutadores pode aproveitar a fraqueza de Bisharp, enquanto golpes de Terra são especialmente eficazes contra Magnezone. Dugtrio de Alola também é do tipo Terra e é vulnerável a Água, Fogo, Lutador e Terra.", "Klefki pode usar Spikes e Thunder Wave. Dugtrio segura Steelium Z e conhece Fissure, que pode derrotar um Pokémon em um único acerto. Recupere sua equipe antes e depois da batalha."], "ELITE FOUR - OLIVIA": ["Olivia integra a Elite Four e usa Pokémon do tipo Pedra. Em Ultra Sun e Ultra Moon, seu time tem Armaldo, Cradily, Gigalith e Probopass no nível 56 e Lycanroc na forma Midnight no nível 57.", "Armaldo é vulnerável a Água, Pedra e Metal. Cradily recebe dano superefetivo de Lutador, Inseto, Gelo e Metal. Probopass recebe quatro vezes mais dano de Lutador e Terra, enquanto Gigalith e Lycanroc são vulneráveis a Água, Planta, Lutador, Terra e Metal.", "Se você escolheu Popplio, Primarina pode usar golpes de Água contra Armaldo, Gigalith, Probopass e Lycanroc. Se escolheu Rowlet, Decidueye pode usar golpes de Planta contra Gigalith e Lycanroc, mas deve ter cuidado com os ataques de Pedra.", "Pokémon com golpes Lutadores podem enfrentar Cradily, Probopass, Gigalith e Lycanroc. Contra Probopass, aproveite sua fraqueza de quatro vezes, mas tenha cuidado com Sturdy, que pode deixá-lo com um ponto de vida quando estiver com a vida cheia.", "Lycanroc segura Rockium Z. Mantenha a equipe recuperada antes de enfrentá-lo e depois cure seus Pokémon antes da próxima batalha."], "ELITE FOUR - ACEROLA": ["Acerola integra a Elite Four e usa Pokémon do tipo Fantasma. Em Ultra Sun e Ultra Moon, seu time tem Sableye, Drifblim, Dhelmise e Froslass no nível 56 e Palossand no nível 57.", "Sableye recebe dano superefetivo apenas do tipo Fada. Drifblim, Dhelmise, Froslass e Palossand são vulneráveis aos tipos Fantasma e Sombrio. Drifblim também é vulnerável a Elétrico, Dhelmise a Fogo e Palossand a Água e Planta.", "Se você escolheu Litten, Incineroar pode usar golpes Sombrios contra os quatro fantasmas vulneráveis e golpes de Fogo contra Dhelmise. Tenha cuidado com golpes de Água e Terra que possam atingir Incineroar.", "Primarina pode usar golpes de Fada contra Sableye e de Água contra Palossand. Pokémon com golpes elétricos podem enfrentar Drifblim, enquanto golpes de Fogo ajudam contra Dhelmise e Froslass.", "Palossand segura Ghostium Z. Mantenha seus Pokémon com bastante vida e evite golpes Normais ou Lutadores, pois os fantasmas são imunes a eles. Depois da vitória, recupere a equipe."], "ELITE FOUR - KAHILI": ["Kahili integra a Elite Four e usa Pokémon do tipo Voador. Em Ultra Sun e Ultra Moon, seu time tem Braviary, Hawlucha, Oricorio no estilo Baile e Mandibuzz no nível 56 e Toucannon no nível 57.", "Braviary, Hawlucha, Mandibuzz e Toucannon recebem dano superefetivo de golpes Elétricos, de Gelo e de Pedra. Oricorio recebe quatro vezes mais dano de Pedra por também ser do tipo Fogo.", "Pokémon com golpes elétricos podem enfrentar toda a equipe. Se você treinou Pikachu desde Melemele, ele ou sua evolução Raichu podem aproveitar essa fraqueza, mantendo cuidado com os ataques adversários.", "Uma opção com golpes de Pedra também pode aproveitar a fraqueza quádrupla de Oricorio. Fique atento a ataques Lutadores de Hawlucha, que podem ser perigosos para Pokémon do tipo Pedra.", "Toucannon segura Flyinium Z, então prepare um Pokémon resistente ou com bastante vida para enfrentar seu Z-Move. Depois da vitória, recupere a equipe antes de seguir."], "CHAMPION": ["Depois de derrotar a Elite Four, você enfrenta seu amigo Hau na última batalha da Liga de Alola. Seu time tem Raichu de Alola no nível 59, Tauros e Noivern no nível 58 e Crabominable no nível 59. Os outros dois Pokémon dependem do inicial escolhido.", "Se você escolheu Rowlet, Hau usa Flareon e Primarina. Se escolheu Litten, ele usa Vaporeon e Decidueye. Se escolheu Popplio, ele usa Leafeon e Incineroar. A evolução do inicial está no nível 60 e segura um Z-Crystal.", "Raichu de Alola é dos tipos Elétrico e Psíquico e recebe dano superefetivo de Terra, Inseto, Fantasma e Sombrio. Tauros é vulnerável a Lutador, mas conhece Zen Headbutt, que pode atingir Pokémon desse tipo.", "Noivern é dos tipos Voador e Dragão e recebe quatro vezes mais dano de Gelo. Crabominable é dos tipos Lutador e Gelo e recebe dano superefetivo de Fogo, Lutador, Voador, Psíquico, Fada e Metal, mas conhece Stone Edge para atingir Pokémon vulneráveis a Pedra.", "Contra Flareon ou Incineroar, use golpes de Água ou Terra. Contra Vaporeon ou Primarina, use Elétrico ou Planta. Contra Leafeon ou Decidueye, golpes de Fogo, Gelo ou Voador são boas opções, mas Decidueye conhece Smack Down para atingir Pokémon Voadores.", "Recupere a equipe antes da batalha e mantenha uma resposta preparada para o Z-Move do inicial de Hau. Depois da vitória, sua equipe será registrada no Hall da Fama e você se tornará Champion de Alola."]}'::jsonb WHERE slug = 'pokemon-ultra-moon';

-- Correções das builds de Alola.
UPDATE public.builds SET dicas = dicas || '{"TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Salazzle no nível 22. Ela é dos tipos Veneno e Fogo e pode chamar Salandit para ajudá-la.", "Salazzle recebe quatro vezes mais dano de golpes do tipo Terra e também é vulnerável aos tipos Água, Pedra e Psíquico. Salandit compartilha os tipos de Salazzle e as mesmas fraquezas.", "Se você escolheu Popplio, sua evolução Brionne pode usar golpes de Água contra os dois adversários. Outra opção é Mudbray com Bulldoze. Ele pode ser encontrado na Route 4 e aprende o golpe no nível 10.", "Tenha cuidado com Toxic de Salazzle. Sua habilidade Corrosion permite envenenar até Pokémon dos tipos Veneno e Metal, e Salandit pode aproveitar o envenenamento com Venoshock.", "Cure sua equipe antes da prova e leve Antidotes ou itens que curem envenenamento."], "CHAMPION": ["Após derrotar a Elite Four, você enfrenta o Professor Kukui para conquistar o título de Champion de Alola. Seu time tem Lycanroc na forma Midday no nível 57, Ninetales de Alola, Braviary, Magnezone e Snorlax no nível 56, além de um inicial na forma final no nível 58.", "O último Pokémon depende do inicial escolhido. Se você escolheu Rowlet, Kukui usa Incineroar. Se escolheu Litten, ele usa Primarina. Se escolheu Popplio, ele usa Decidueye.", "Contra Lycanroc, use golpes de Água, Planta, Lutador, Terra ou Metal. Ninetales de Alola é dos tipos Gelo e Fada e recebe quatro vezes mais dano de golpes de Metal. Braviary é vulnerável a Elétrico, Gelo e Pedra.", "Magnezone recebe quatro vezes mais dano de golpes do tipo Terra. Snorlax é vulnerável a Lutador, mas mantenha cuidado com os golpes de cobertura dos dois adversários.", "Contra Incineroar, aproveite golpes de Água, Lutador ou Terra. Contra Primarina, use Elétrico, Planta ou Veneno. Contra Decidueye, golpes de Fogo, Gelo, Voador, Fantasma ou Sombrio são boas opções.", "O inicial de Kukui segura um Z-Crystal correspondente ao seu tipo. Recupere sua equipe antes da última batalha e mantenha uma resposta preparada para o Z-Move.", "Depois da vitória, sua equipe será registrada no Hall da Fama e você se tornará Champion de Alola."]}'::jsonb WHERE slug = 'pokemon-sun';
UPDATE public.builds SET dicas = dicas || '{"TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Salazzle no nível 22. Ela é dos tipos Veneno e Fogo e pode chamar Salandit para ajudá-la.", "Salazzle recebe quatro vezes mais dano de golpes do tipo Terra e também é vulnerável aos tipos Água, Pedra e Psíquico. Salandit compartilha os tipos de Salazzle e as mesmas fraquezas.", "Se você escolheu Popplio, sua evolução Brionne pode usar golpes de Água contra os dois adversários. Outra opção é Mudbray com Bulldoze. Ele pode ser encontrado na Route 4 e aprende o golpe no nível 10.", "Tenha cuidado com Toxic de Salazzle. Sua habilidade Corrosion permite envenenar até Pokémon dos tipos Veneno e Metal, e Salandit pode aproveitar o envenenamento com Venoshock.", "Cure sua equipe antes da prova e leve Antidotes ou itens que curem envenenamento."], "CHAMPION": ["Após derrotar a Elite Four, você enfrenta o Professor Kukui para conquistar o título de Champion de Alola. Seu time tem Lycanroc na forma Midday no nível 57, Ninetales de Alola, Braviary, Magnezone e Snorlax no nível 56, além de um inicial na forma final no nível 58.", "O último Pokémon depende do inicial escolhido. Se você escolheu Rowlet, Kukui usa Incineroar. Se escolheu Litten, ele usa Primarina. Se escolheu Popplio, ele usa Decidueye.", "Contra Lycanroc, use golpes de Água, Planta, Lutador, Terra ou Metal. Ninetales de Alola é dos tipos Gelo e Fada e recebe quatro vezes mais dano de golpes de Metal. Braviary é vulnerável a Elétrico, Gelo e Pedra.", "Magnezone recebe quatro vezes mais dano de golpes do tipo Terra. Snorlax é vulnerável a Lutador, mas mantenha cuidado com os golpes de cobertura dos dois adversários.", "Contra Incineroar, aproveite golpes de Água, Lutador ou Terra. Contra Primarina, use Elétrico, Planta ou Veneno. Contra Decidueye, golpes de Fogo, Gelo, Voador, Fantasma ou Sombrio são boas opções.", "O inicial de Kukui segura um Z-Crystal correspondente ao seu tipo. Recupere sua equipe antes da última batalha e mantenha uma resposta preparada para o Z-Move.", "Depois da vitória, sua equipe será registrada no Hall da Fama e você se tornará Champion de Alola."]}'::jsonb WHERE slug = 'pokemon-moon';
UPDATE public.builds SET dicas = dicas || '{"TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Marowak de Alola no nível 22. Ele é dos tipos Fogo e Fantasma e pode chamar Salazzle para ajudá-lo.", "Marowak é vulnerável aos tipos Água, Terra, Pedra, Fantasma e Sombrio. Salazzle é dos tipos Fogo e Veneno e recebe quatro vezes mais dano de golpes do tipo Terra.", "Se você escolheu Popplio, Brionne pode usar golpes de Água contra os dois. Outra opção é Mudbray com Bulldoze. Ele pode ser encontrado na Route 4 e aprende o golpe no nível 10, mas cuide da vida dele diante dos golpes de Marowak.", "Marowak segura Thick Club, que aumenta muito seu Ataque. Seu Flame Wheel e Brick Break podem causar bastante dano. Salazzle pode envenenar sua equipe com Poison Gas e aproveitar o estado com Venoshock.", "Cure sua equipe antes da prova e leve Potions e Antidotes. Golpes do tipo Elétrico não atingem Marowak quando sua habilidade Lightning Rod está ativa."], "ELITE FOUR - ACEROLA": ["Acerola integra a Elite Four e usa Pokémon do tipo Fantasma. Em Ultra Sun e Ultra Moon, seu time tem Banette, Drifblim, Dhelmise e Froslass no nível 56 e Palossand no nível 57.", "Os cinco recebem dano superefetivo dos tipos Fantasma e Sombrio. Drifblim também é vulnerável a Elétrico, Dhelmise a Fogo e Palossand a Água e Planta.", "Se você escolheu Litten, Incineroar pode usar golpes Sombrios contra toda a equipe e golpes de Fogo contra Dhelmise. Tenha cuidado com golpes de Água e Terra que possam atingir Incineroar.", "Primarina pode usar golpes de Água contra Palossand. Pokémon com golpes elétricos podem enfrentar Drifblim, enquanto golpes de Fogo ajudam contra Dhelmise e Froslass.", "Palossand segura Ghostium Z. Mantenha seus Pokémon com bastante vida e evite golpes Normais ou Lutadores, pois os fantasmas são imunes a eles. Depois da vitória, recupere a equipe."]}'::jsonb WHERE slug = 'pokemon-ultra-sun';
UPDATE public.builds SET dicas = dicas || '{"TRIAL - KIAWE": ["Na prova de Kiawe no Wela Volcano Park, você enfrenta o Totem Marowak de Alola no nível 22. Ele é dos tipos Fogo e Fantasma e pode chamar Salazzle para ajudá-lo.", "Marowak é vulnerável aos tipos Água, Terra, Pedra, Fantasma e Sombrio. Salazzle é dos tipos Fogo e Veneno e recebe quatro vezes mais dano de golpes do tipo Terra.", "Se você escolheu Popplio, Brionne pode usar golpes de Água contra os dois. Outra opção é Mudbray com Bulldoze. Ele pode ser encontrado na Route 4 e aprende o golpe no nível 10, mas cuide da vida dele diante dos golpes de Marowak.", "Marowak segura Thick Club, que aumenta muito seu Ataque. Seu Flame Wheel e Brick Break podem causar bastante dano. Salazzle pode envenenar sua equipe com Poison Gas e aproveitar o estado com Venoshock.", "Cure sua equipe antes da prova e leve Potions e Antidotes. Golpes do tipo Elétrico não atingem Marowak quando sua habilidade Lightning Rod está ativa."], "ELITE FOUR - ACEROLA": ["Acerola integra a Elite Four e usa Pokémon do tipo Fantasma. Em Ultra Sun e Ultra Moon, seu time tem Banette, Drifblim, Dhelmise e Froslass no nível 56 e Palossand no nível 57.", "Os cinco recebem dano superefetivo dos tipos Fantasma e Sombrio. Drifblim também é vulnerável a Elétrico, Dhelmise a Fogo e Palossand a Água e Planta.", "Se você escolheu Litten, Incineroar pode usar golpes Sombrios contra toda a equipe e golpes de Fogo contra Dhelmise. Tenha cuidado com golpes de Água e Terra que possam atingir Incineroar.", "Primarina pode usar golpes de Água contra Palossand. Pokémon com golpes elétricos podem enfrentar Drifblim, enquanto golpes de Fogo ajudam contra Dhelmise e Froslass.", "Palossand segura Ghostium Z. Mantenha seus Pokémon com bastante vida e evite golpes Normais ou Lutadores, pois os fantasmas são imunes a eles. Depois da vitória, recupere a equipe."]}'::jsonb WHERE slug = 'pokemon-ultra-moon';

-- Ginásios de Pokémon Sword e Shield.
UPDATE public.builds SET caps = ARRAY['1º GYM - MILO','2º GYM - NESSA','3º GYM - KABU','4º GYM - BEA','5º GYM - OPAL','6º GYM - GORDIE','7º GYM - PIERS','8º GYM - RAIHAN'] || ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['1º GYM - MILO','2º GYM - NESSA','3º GYM - KABU','4º GYM - BEA','5º GYM - OPAL','6º GYM - GORDIE','7º GYM - PIERS','8º GYM - RAIHAN']))), dicas = dicas || '{"1º GYM - MILO": ["Milo é o líder do ginásio de Turffield e usa Pokémon do tipo Planta. Seu time começa com Gossifleur no nível 19 e termina com Eldegoss no nível 20.", "Os dois recebem dano superefetivo de golpes dos tipos Fogo, Gelo, Voador, Inseto e Veneno. Milo usa Dynamax em Eldegoss, aumentando sua vida e tornando seus golpes mais perigosos por três turnos.", "Se você escolheu Scorbunny, sua evolução Raboot pode usar golpes do tipo Fogo contra os dois. Scorbunny evolui para Raboot no nível 16.", "Se você escolheu Grookey ou Sobble, capture Rookidee na Route 1 ou 2 e use golpes do tipo Voador. Ele evolui para Corvisquire no nível 18 e pode ajudar durante toda a batalha.", "Outra opção é capturar Vulpix na Route 3 em Pokémon Sword ou Growlithe na mesma rota em Pokémon Shield. Use seus golpes de Fogo para aproveitar a fraqueza dos dois adversários.", "Gossifleur e Eldegoss conhecem Magical Leaf, que não erra por mudanças de precisão ou evasão. Tenha atenção ao usar Sobble, pois ele recebe dano superefetivo de Planta.", "Quando Eldegoss usar Dynamax, você também pode usar o Dynamax Band no estádio. Cure sua equipe antes da batalha e leve Potions."], "2º GYM - NESSA": ["Nessa é a líder do ginásio de Hulbury e usa Pokémon do tipo Água. Seu time começa com Goldeen no nível 22, seguido de Arrokuda no nível 23 e Drednaw no nível 24.", "Goldeen e Arrokuda recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Drednaw também é do tipo Pedra e recebe quatro vezes mais dano de Planta, além de ser vulnerável aos tipos Elétrico, Lutador e Terra.", "Se você escolheu Grookey, sua evolução Thwackey pode usar golpes de Planta contra toda a equipe. Grookey evolui para Thwackey no nível 16.", "Independentemente do inicial escolhido, você pode capturar Yamper na Route 2 ou 4 e usar golpes elétricos. Yamper evolui para Boltund no nível 25, caso você decida treiná-lo um pouco mais.", "Outra opção é receber Toxel na Pokémon Nursery da Route 5 e treiná-lo para usar golpes elétricos. Ele evolui para Toxtricity no nível 30, mas não precisa evoluir para participar da batalha.", "Nessa usa Dynamax em Drednaw. Sua vida aumenta e seus ataques podem preparar chuva, fortalecendo golpes de Água. Se possível, reserve seu próprio Dynamax e um golpe de Planta para esse momento.", "Arrokuda conhece Aqua Jet, que pode atacar com prioridade. Cure sua equipe e mantenha bastante vida antes de enfrentar Drednaw."], "3º GYM - KABU": ["Kabu é o líder do ginásio de Motostoke e usa Pokémon do tipo Fogo. Seu time começa com Ninetales e Arcanine no nível 25 e termina com Centiskorch no nível 27.", "Ninetales e Arcanine recebem dano superefetivo dos tipos Água, Terra e Pedra. Centiskorch também é do tipo Inseto e recebe quatro vezes mais dano de Pedra, além de ser vulnerável a Água e Voador.", "Se você escolheu Sobble, sua evolução Drizzile pode usar golpes de Água contra os três. Sobble evolui para Drizzile no nível 16.", "Se você escolheu outro inicial, capture Chewtle na Route 2 e treine-o até evoluir para Drednaw no nível 22. Seus golpes de Água podem atingir toda a equipe, e seus golpes de Pedra aproveitam a fraqueza de Centiskorch.", "Outra opção é Rolycoly, encontrado na Route 3 ou na Galar Mine. Ele evolui para Carkol no nível 18 e pode usar golpes de Pedra, mas tenha cuidado com a vida dele, pois não é imune aos ataques de Kabu.", "Ninetales e Arcanine conhecem Will-O-Wisp, que pode queimar seu Pokémon e reduzir seu Ataque. Se estiver usando golpes físicos, leve Burn Heals para lidar com a queimadura.", "Kabu usa Gigantamax em Centiskorch. Reserve um Pokémon com golpe de Pedra ou seu próprio Dynamax para enfrentá-lo e cure a equipe antes da batalha."], "4º GYM - BEA": ["Bea é a líder do ginásio de Stow-on-Side em Pokémon Sword e usa Pokémon do tipo Lutador. Seu time começa com Hitmontop e Pangoro no nível 34, seguido de Sirfetch’d no nível 35 e Machamp no nível 36.", "Hitmontop, Sirfetch’d e Machamp são vulneráveis aos tipos Voador, Psíquico e Fada. Pangoro também é do tipo Sombrio e recebe quatro vezes mais dano de golpes do tipo Fada, mas é imune a golpes Psíquicos.", "Se você treinou Rookidee desde as primeiras rotas, seu Corvisquire pode usar golpes do tipo Voador contra os quatro. Ele evolui para Corviknight no nível 38, caso você decida treiná-lo mais.", "Outra opção é um Pokémon do tipo Fada contra Pangoro. Cutiefly pode ser encontrado na Route 4 e evolui para Ribombee no nível 25, mas tenha cuidado com Bullet Punch de Pangoro, que causa dano superefetivo por ser do tipo Metal.", "Um Pokémon Psíquico pode ajudar contra Hitmontop, Sirfetch’d e Machamp. Tenha cuidado com Night Slash de Pangoro, Brutal Swing de Sirfetch’d e Knock Off de Machamp, que são perigosos para Pokémon Psíquicos.", "Hitmontop conhece Counter, que devolve o dobro do dano físico recebido. Sirfetch’d pode aumentar seu Ataque com Swords Dance, e Bea usa Gigantamax em Machamp. Cure sua equipe antes da batalha."], "5º GYM - OPAL": ["Opal é a líder do ginásio de Ballonlea e usa Pokémon do tipo Fada. Seu time começa com Weezing de Galar e Mawile no nível 36, seguido de Togekiss no nível 37 e Alcremie no nível 38.", "Weezing de Galar também é do tipo Veneno e é vulnerável a golpes dos tipos Terra, Psíquico e Metal, embora sua habilidade Levitate possa impedir ataques de Terra. Mawile também é do tipo Metal e é vulnerável a Fogo e Terra.", "Togekiss é dos tipos Fada e Voador e recebe dano superefetivo de Elétrico, Gelo, Pedra, Veneno e Metal. Alcremie é vulnerável a Veneno e Metal.", "Se você escolheu Scorbunny, seu Raboot ou Cinderace pode usar golpes de Fogo contra Mawile. Não dependa do tipo Fogo para enfrentar toda a equipe, pois ele não é superefetivo contra as outras fadas.", "Independentemente do inicial, Meowth de Galar pode ser capturado na Route 4 e evolui para Perrserker no nível 28. Seus golpes do tipo Metal ajudam contra Togekiss e Alcremie, além de atingirem Weezing de forma superefetiva.", "O Toxel recebido na Pokémon Nursery da Route 5 pode evoluir para Toxtricity no nível 30. Seus golpes elétricos ajudam contra Togekiss, e golpes do tipo Veneno podem atingir Togekiss e Alcremie.", "Opal faz perguntas durante a batalha. Respostas certas aumentam atributos, enquanto respostas erradas diminuem. Alcremie usa Gigantamax e conhece Sweet Kiss, então leve itens para curar confusão e mantenha sua equipe recuperada."], "6º GYM - GORDIE": ["Gordie é o líder do ginásio de Circhester em Pokémon Sword e usa Pokémon do tipo Pedra. Seu time começa com Barbaracle e Shuckle no nível 40, seguido de Stonjourner no nível 41 e Coalossal no nível 42.", "Barbaracle também é do tipo Água e recebe quatro vezes mais dano de Planta. Coalossal também é do tipo Fogo e recebe quatro vezes mais dano de Água e Terra. Shuckle e Stonjourner são vulneráveis a golpes de Água e Metal.", "Se você escolheu Grookey, seu Rillaboom pode usar golpes de Planta contra Barbaracle e Stonjourner. Se escolheu Sobble, Inteleon pode usar golpes de Água contra Shuckle, Stonjourner e Coalossal.", "Independentemente do inicial, Chewtle pode ser capturado na Route 2 e evolui para Drednaw no nível 22. Seus golpes de Água são úteis contra Shuckle, Stonjourner e Coalossal, mas mantenha-o longe de golpes de Planta.", "Machop, encontrado na Route 3, pode evoluir para Machoke no nível 28 e usar golpes Lutadores contra Stonjourner e Coalossal. Outra opção contra Coalossal é Dugtrio com golpes de Terra, evoluído de Diglett encontrado na Route 4.", "Barbaracle pode usar Shell Smash para aumentar bastante seu Ataque e Velocidade. Shuckle possui defesas altas, enquanto Stonjourner e Coalossal podem colocar Stealth Rock, causando dano aos Pokémon afetados quando entram em campo.", "Gordie usa Gigantamax em Coalossal. Um golpe forte de Água ou Terra aproveita sua fraqueza de quatro vezes, mas mantenha a equipe recuperada para suportar seus ataques."], "7º GYM - PIERS": ["Piers é o líder do ginásio de Spikemuth e usa Pokémon do tipo Sombrio. Seu time começa com Scrafty no nível 44, seguido de Malamar e Skuntank no nível 45 e Obstagoon no nível 46.", "Scrafty é dos tipos Sombrio e Lutador e recebe quatro vezes mais dano de Fada. Malamar é dos tipos Sombrio e Psíquico e recebe quatro vezes mais dano de Inseto. Skuntank também é do tipo Veneno e é vulnerável apenas a Terra, enquanto Obstagoon recebe quatro vezes mais dano de Lutador.", "Se você escolheu Sobble, Inteleon pode usar golpes de Água contra Skuntank. Se escolheu Scorbunny, Cinderace pode usar golpes de Lutador contra Obstagoon, mas cuidado com Counter. Se escolheu Grookey, Rillaboom pode ajudar com seus golpes mais fortes e uma equipe que cubra os demais tipos.", "Independentemente do inicial, Machop pode ser capturado na Route 3 e evolui para Machoke no nível 28. Seus golpes Lutadores podem aproveitar a fraqueza de Obstagoon, mas cuidado com Counter, que devolve o dobro do dano físico recebido.", "Para Scrafty, use um Pokémon com golpes de Fada. Contra Malamar, um golpe do tipo Inseto aproveita sua fraqueza de quatro vezes. Contra Skuntank, Diglett capturado na Route 4 pode ter evoluído para Dugtrio e usar golpes de Terra.", "Scrafty conhece Fake Out, que pode fazer seu Pokémon perder o primeiro turno, enquanto Skuntank pode usar Toxic. Obstagoon também conhece Obstruct, que protege contra ataques e reduz bastante a Defesa de quem fizer contato.", "A batalha de Spikemuth não permite Dynamax. Cure sua equipe antes de entrar e leve itens para curar envenenamento."], "8º GYM - RAIHAN": ["Raihan é o líder do ginásio de Hammerlocke e enfrenta você em uma batalha dupla. Seu time tem Gigalith e Sandaconda no nível 46, Flygon no nível 47 e Duraludon no nível 48.", "Gigalith é vulnerável aos tipos Água, Planta, Lutador, Terra e Metal. Sandaconda recebe dano superefetivo de Água, Planta e Gelo. Flygon recebe quatro vezes mais dano de Gelo, enquanto Duraludon é vulnerável a Lutador e Terra.", "Se você escolheu Sobble, Inteleon pode usar golpes de Água contra Gigalith e Sandaconda. Se escolheu Grookey, Rillaboom pode usar golpes de Planta contra os dois, mas tenha cuidado com Fire Fang de Sandaconda.", "Para Flygon, use um Pokémon com golpe de Gelo e aproveite a fraqueza de quatro vezes. Sua habilidade Levitate o torna imune aos golpes do tipo Terra, então escolha outro ataque para enfrentá-lo.", "Contra Duraludon, você pode usar Machoke com golpes Lutadores ou Dugtrio com golpes do tipo Terra. Machop pode ser encontrado na Route 3, enquanto Diglett pode ser capturado na Route 4.", "Gigalith pode iniciar uma tempestade de areia com Sand Stream, e Sandaconda pode levantar outra com Sand Spit ao ser atingida. A areia causa dano no fim do turno aos Pokémon que não forem dos tipos Pedra, Terra ou Metal.", "Raihan usa Gigantamax em Duraludon. Como dois Pokémon de cada lado lutam ao mesmo tempo, observe as ameaças dos dois adversários e planeje suas trocas antes de usar Dynamax."]}'::jsonb WHERE slug = 'pokemon-sword';
UPDATE public.builds SET caps = ARRAY['1º GYM - MILO','2º GYM - NESSA','3º GYM - KABU','4º GYM - ALLISTER','5º GYM - OPAL','6º GYM - MELONY','7º GYM - PIERS','8º GYM - RAIHAN'] || ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['1º GYM - MILO','2º GYM - NESSA','3º GYM - KABU','4º GYM - ALLISTER','5º GYM - OPAL','6º GYM - MELONY','7º GYM - PIERS','8º GYM - RAIHAN']))), dicas = dicas || '{"1º GYM - MILO": ["Milo é o líder do ginásio de Turffield e usa Pokémon do tipo Planta. Seu time começa com Gossifleur no nível 19 e termina com Eldegoss no nível 20.", "Os dois recebem dano superefetivo de golpes dos tipos Fogo, Gelo, Voador, Inseto e Veneno. Milo usa Dynamax em Eldegoss, aumentando sua vida e tornando seus golpes mais perigosos por três turnos.", "Se você escolheu Scorbunny, sua evolução Raboot pode usar golpes do tipo Fogo contra os dois. Scorbunny evolui para Raboot no nível 16.", "Se você escolheu Grookey ou Sobble, capture Rookidee na Route 1 ou 2 e use golpes do tipo Voador. Ele evolui para Corvisquire no nível 18 e pode ajudar durante toda a batalha.", "Outra opção é capturar Vulpix na Route 3 em Pokémon Sword ou Growlithe na mesma rota em Pokémon Shield. Use seus golpes de Fogo para aproveitar a fraqueza dos dois adversários.", "Gossifleur e Eldegoss conhecem Magical Leaf, que não erra por mudanças de precisão ou evasão. Tenha atenção ao usar Sobble, pois ele recebe dano superefetivo de Planta.", "Quando Eldegoss usar Dynamax, você também pode usar o Dynamax Band no estádio. Cure sua equipe antes da batalha e leve Potions."], "2º GYM - NESSA": ["Nessa é a líder do ginásio de Hulbury e usa Pokémon do tipo Água. Seu time começa com Goldeen no nível 22, seguido de Arrokuda no nível 23 e Drednaw no nível 24.", "Goldeen e Arrokuda recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Drednaw também é do tipo Pedra e recebe quatro vezes mais dano de Planta, além de ser vulnerável aos tipos Elétrico, Lutador e Terra.", "Se você escolheu Grookey, sua evolução Thwackey pode usar golpes de Planta contra toda a equipe. Grookey evolui para Thwackey no nível 16.", "Independentemente do inicial escolhido, você pode capturar Yamper na Route 2 ou 4 e usar golpes elétricos. Yamper evolui para Boltund no nível 25, caso você decida treiná-lo um pouco mais.", "Outra opção é receber Toxel na Pokémon Nursery da Route 5 e treiná-lo para usar golpes elétricos. Ele evolui para Toxtricity no nível 30, mas não precisa evoluir para participar da batalha.", "Nessa usa Dynamax em Drednaw. Sua vida aumenta e seus ataques podem preparar chuva, fortalecendo golpes de Água. Se possível, reserve seu próprio Dynamax e um golpe de Planta para esse momento.", "Arrokuda conhece Aqua Jet, que pode atacar com prioridade. Cure sua equipe e mantenha bastante vida antes de enfrentar Drednaw."], "3º GYM - KABU": ["Kabu é o líder do ginásio de Motostoke e usa Pokémon do tipo Fogo. Seu time começa com Ninetales e Arcanine no nível 25 e termina com Centiskorch no nível 27.", "Ninetales e Arcanine recebem dano superefetivo dos tipos Água, Terra e Pedra. Centiskorch também é do tipo Inseto e recebe quatro vezes mais dano de Pedra, além de ser vulnerável a Água e Voador.", "Se você escolheu Sobble, sua evolução Drizzile pode usar golpes de Água contra os três. Sobble evolui para Drizzile no nível 16.", "Se você escolheu outro inicial, capture Chewtle na Route 2 e treine-o até evoluir para Drednaw no nível 22. Seus golpes de Água podem atingir toda a equipe, e seus golpes de Pedra aproveitam a fraqueza de Centiskorch.", "Outra opção é Rolycoly, encontrado na Route 3 ou na Galar Mine. Ele evolui para Carkol no nível 18 e pode usar golpes de Pedra, mas tenha cuidado com a vida dele, pois não é imune aos ataques de Kabu.", "Ninetales e Arcanine conhecem Will-O-Wisp, que pode queimar seu Pokémon e reduzir seu Ataque. Se estiver usando golpes físicos, leve Burn Heals para lidar com a queimadura.", "Kabu usa Gigantamax em Centiskorch. Reserve um Pokémon com golpe de Pedra ou seu próprio Dynamax para enfrentá-lo e cure a equipe antes da batalha."], "4º GYM - ALLISTER": ["Allister é o líder do ginásio de Stow-on-Side em Pokémon Shield e usa Pokémon do tipo Fantasma. Seu time começa com Yamask de Galar e Mimikyu no nível 34, seguido de Cursola no nível 35 e Gengar no nível 36.", "Yamask, Cursola e Gengar recebem dano superefetivo dos tipos Fantasma e Sombrio. Yamask de Galar também é do tipo Terra e é vulnerável a Água, Planta e Gelo. Gengar também é do tipo Veneno e é vulnerável a Terra e Psíquico.", "Mimikyu é dos tipos Fantasma e Fada e recebe dano superefetivo de Fantasma e Metal. Sua habilidade Disguise bloqueia o dano do primeiro golpe que o atinge, então quebre o disfarce antes de usar um ataque mais forte.", "Independentemente do inicial escolhido, você pode capturar Zigzagoon de Galar na Route 2 e usar golpes Sombrios. Ele evolui para Linoone no nível 20 e pode evoluir para Obstagoon ao subir de nível à noite a partir do nível 35.", "Contra Yamask e Cursola, golpes Sombrios de Linoone ou Obstagoon aproveitam a fraqueza deles. Golpes Sombrios causam dano normal a Mimikyu, pois seu tipo Fada resiste ao tipo Sombrio.", "Gengar pode usar Hypnosis para colocar seu Pokémon para dormir. Allister usa Gigantamax em Gengar, então mantenha sua equipe com bastante vida e prepare itens para curar sono.", "Evite golpes Normais e Lutadores contra a equipe, pois Pokémon Fantasmas são imunes a eles. Cure sua equipe antes da batalha."], "5º GYM - OPAL": ["Opal é a líder do ginásio de Ballonlea e usa Pokémon do tipo Fada. Seu time começa com Weezing de Galar e Mawile no nível 36, seguido de Togekiss no nível 37 e Alcremie no nível 38.", "Weezing de Galar também é do tipo Veneno e é vulnerável a golpes dos tipos Terra, Psíquico e Metal, embora sua habilidade Levitate possa impedir ataques de Terra. Mawile também é do tipo Metal e é vulnerável a Fogo e Terra.", "Togekiss é dos tipos Fada e Voador e recebe dano superefetivo de Elétrico, Gelo, Pedra, Veneno e Metal. Alcremie é vulnerável a Veneno e Metal.", "Se você escolheu Scorbunny, seu Raboot ou Cinderace pode usar golpes de Fogo contra Mawile. Não dependa do tipo Fogo para enfrentar toda a equipe, pois ele não é superefetivo contra as outras fadas.", "Independentemente do inicial, Meowth de Galar pode ser capturado na Route 4 e evolui para Perrserker no nível 28. Seus golpes do tipo Metal ajudam contra Togekiss e Alcremie, além de atingirem Weezing de forma superefetiva.", "O Toxel recebido na Pokémon Nursery da Route 5 pode evoluir para Toxtricity no nível 30. Seus golpes elétricos ajudam contra Togekiss, e golpes do tipo Veneno podem atingir Togekiss e Alcremie.", "Opal faz perguntas durante a batalha. Respostas certas aumentam atributos, enquanto respostas erradas diminuem. Alcremie usa Gigantamax e conhece Sweet Kiss, então leve itens para curar confusão e mantenha sua equipe recuperada."], "6º GYM - MELONY": ["Melony é a líder do ginásio de Circhester em Pokémon Shield e usa Pokémon do tipo Gelo. Seu time começa com Frosmoth e Darmanitan de Galar no nível 40, seguido de Eiscue no nível 41 e Lapras no nível 42.", "Frosmoth também é do tipo Inseto e recebe quatro vezes mais dano de Fogo e Pedra. Darmanitan de Galar e Eiscue são vulneráveis aos tipos Fogo, Lutador, Pedra e Metal. Lapras também é do tipo Água e recebe dano superefetivo de Elétrico, Planta, Lutador e Pedra.", "Se você escolheu Scorbunny, seu Cinderace pode usar golpes de Fogo contra Frosmoth, Darmanitan e Eiscue. Mantenha cuidado com Surf de Lapras, que causa dano superefetivo a ele.", "Independentemente do inicial, Rolycoly pode ser encontrado na Route 3 ou na Galar Mine e evolui para Carkol no nível 18. Seus golpes de Pedra ajudam contra Frosmoth, mas mantenha-o longe de Surf de Lapras.", "Machop pode ser encontrado na Route 3 e evolui para Machoke no nível 28. Seus golpes Lutadores são úteis contra Darmanitan, Eiscue e Lapras. Golpes de Lutador não são superefetivos contra Frosmoth, pois seu tipo Inseto resiste a eles.", "Yamper, encontrado nas Routes 2 e 4, pode ter evoluído para Boltund no nível 25 e usar golpes elétricos contra Lapras. Outra opção é Toxtricity, evolução do Toxel recebido na Pokémon Nursery da Route 5.", "Eiscue possui Ice Face, que bloqueia o dano de um golpe físico enquanto sua forma estiver intacta. Golpes especiais podem causar dano sem depender de quebrar essa proteção. Eiscue também conhece Freeze-Dry, que é superefetivo contra Pokémon do tipo Água.", "Melony usa Gigantamax em Lapras, que conhece Surf e Sing. Prepare uma resposta aos golpes de Água e leve itens para curar sono antes da batalha."], "7º GYM - PIERS": ["Piers é o líder do ginásio de Spikemuth e usa Pokémon do tipo Sombrio. Seu time começa com Scrafty no nível 44, seguido de Malamar e Skuntank no nível 45 e Obstagoon no nível 46.", "Scrafty é dos tipos Sombrio e Lutador e recebe quatro vezes mais dano de Fada. Malamar é dos tipos Sombrio e Psíquico e recebe quatro vezes mais dano de Inseto. Skuntank também é do tipo Veneno e é vulnerável apenas a Terra, enquanto Obstagoon recebe quatro vezes mais dano de Lutador.", "Se você escolheu Sobble, Inteleon pode usar golpes de Água contra Skuntank. Se escolheu Scorbunny, Cinderace pode usar golpes de Lutador contra Obstagoon, mas cuidado com Counter. Se escolheu Grookey, Rillaboom pode ajudar com seus golpes mais fortes e uma equipe que cubra os demais tipos.", "Independentemente do inicial, Machop pode ser capturado na Route 3 e evolui para Machoke no nível 28. Seus golpes Lutadores podem aproveitar a fraqueza de Obstagoon, mas cuidado com Counter, que devolve o dobro do dano físico recebido.", "Para Scrafty, use um Pokémon com golpes de Fada. Contra Malamar, um golpe do tipo Inseto aproveita sua fraqueza de quatro vezes. Contra Skuntank, Diglett capturado na Route 4 pode ter evoluído para Dugtrio e usar golpes de Terra.", "Scrafty conhece Fake Out, que pode fazer seu Pokémon perder o primeiro turno, enquanto Skuntank pode usar Toxic. Obstagoon também conhece Obstruct, que protege contra ataques e reduz bastante a Defesa de quem fizer contato.", "A batalha de Spikemuth não permite Dynamax. Cure sua equipe antes de entrar e leve itens para curar envenenamento."], "8º GYM - RAIHAN": ["Raihan é o líder do ginásio de Hammerlocke e enfrenta você em uma batalha dupla. Seu time tem Gigalith e Sandaconda no nível 46, Flygon no nível 47 e Duraludon no nível 48.", "Gigalith é vulnerável aos tipos Água, Planta, Lutador, Terra e Metal. Sandaconda recebe dano superefetivo de Água, Planta e Gelo. Flygon recebe quatro vezes mais dano de Gelo, enquanto Duraludon é vulnerável a Lutador e Terra.", "Se você escolheu Sobble, Inteleon pode usar golpes de Água contra Gigalith e Sandaconda. Se escolheu Grookey, Rillaboom pode usar golpes de Planta contra os dois, mas tenha cuidado com Fire Fang de Sandaconda.", "Para Flygon, use um Pokémon com golpe de Gelo e aproveite a fraqueza de quatro vezes. Sua habilidade Levitate o torna imune aos golpes do tipo Terra, então escolha outro ataque para enfrentá-lo.", "Contra Duraludon, você pode usar Machoke com golpes Lutadores ou Dugtrio com golpes do tipo Terra. Machop pode ser encontrado na Route 3, enquanto Diglett pode ser capturado na Route 4.", "Gigalith pode iniciar uma tempestade de areia com Sand Stream, e Sandaconda pode levantar outra com Sand Spit ao ser atingida. A areia causa dano no fim do turno aos Pokémon que não forem dos tipos Pedra, Terra ou Metal.", "Raihan usa Gigantamax em Duraludon. Como dois Pokémon de cada lado lutam ao mesmo tempo, observe as ameaças dos dois adversários e planeje suas trocas antes de usar Dynamax."]}'::jsonb WHERE slug = 'pokemon-shield';

-- Champion Cup de Pokémon Sword e Shield.
UPDATE public.builds SET caps = ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['CHAMPION CUP - MARNIE','CHAMPION CUP - HOP','CHAMPION CUP - BEDE','CHAMPION CUP - NESSA','CHAMPION CUP - BEA','CHAMPION CUP - RAIHAN','CHAMPION - LEON']))) || ARRAY['CHAMPION CUP - MARNIE','CHAMPION CUP - HOP','CHAMPION CUP - BEDE','CHAMPION CUP - NESSA','CHAMPION CUP - BEA','CHAMPION CUP - RAIHAN','CHAMPION - LEON'], dicas = dicas || '{"CHAMPION CUP - MARNIE": ["Marnie é sua primeira adversária na Champion Cup. Sua equipe começa com Liepard, Toxicroak e Scrafty no nível 47, seguidos de Morpeko no nível 48 e Grimmsnarl no nível 49.", "Liepard é vulnerável aos tipos Lutador, Inseto e Fada. Toxicroak recebe quatro vezes mais dano de golpes Psíquicos e também é vulnerável aos tipos Terra e Voador. Scrafty recebe quatro vezes mais dano de Fada e também é vulnerável a Lutador e Voador.", "Morpeko é dos tipos Elétrico e Sombrio e recebe dano superefetivo de Terra, Lutador, Inseto e Fada. Grimmsnarl é dos tipos Sombrio e Fada e é vulnerável aos tipos Veneno, Metal e Fada.", "Um Machoke com golpes Lutadores pode enfrentar Liepard, Scrafty e Morpeko. Machop pode ser capturado na Route 3 e evolui para Machoke no nível 28. Cuidado com Bullet Seed de Morpeko se escolher um Pokémon do tipo Terra para enfrentá-lo.", "Contra Scrafty, Ribombee com golpes de Fada aproveita a fraqueza de quatro vezes. Cutiefly pode ser encontrado na Route 4 e evolui no nível 25. Mantenha-o longe de Toxicroak, pois golpes de Veneno causam muito dano a ele.", "Para Toxicroak, use um Pokémon Psíquico ou Corviknight com golpes Voadores. Rookidee aparece nas primeiras rotas e evolui para Corvisquire no nível 18 e Corviknight no nível 38. Toxicroak conhece Sucker Punch, então tome cuidado com um Pokémon Psíquico enfraquecido.", "Contra Grimmsnarl, Perrserker pode usar golpes de Metal. Meowth de Galar pode ser encontrado na Route 4 e evolui no nível 28. Toxtricity com golpes de Veneno também é uma opção, a partir do Toxel recebido na Pokémon Nursery da Route 5.", "Marnie usa Gigantamax em Grimmsnarl. Recupere sua equipe e esteja preparado para enfrentar Hop depois da vitória."], "CHAMPION CUP - HOP": ["Hop é seu próximo adversário na Champion Cup. Ele usa Dubwool e Corviknight no nível 48, Pincurchin e Snorlax no nível 47 e a evolução final do inicial no nível 49.", "Se você escolheu Grookey, Hop usa Inteleon. Se escolheu Scorbunny, ele usa Rillaboom. Se escolheu Sobble, ele usa Cinderace. Hop usa Dynamax em seu inicial.", "Dubwool e Snorlax são do tipo Normal e vulneráveis a golpes Lutadores. Corviknight é dos tipos Voador e Metal e recebe dano superefetivo de Fogo e Elétrico. Pincurchin é vulnerável a golpes de Terra.", "Machoke, evolução de Machop encontrado na Route 3, pode enfrentar Dubwool e Snorlax com golpes Lutadores. Cuidado com Zen Headbutt de Dubwool, que é superefetivo contra Machoke, e com Cotton Guard, que aumenta bastante a Defesa de Dubwool.", "Contra Corviknight, use Boltund com golpes elétricos. Yamper pode ser encontrado nas Routes 2 e 4 e evolui no nível 25. Se escolheu Scorbunny, seu Cinderace também pode usar golpes de Fogo.", "Para Pincurchin, Dugtrio com golpes de Terra é uma opção. Diglett pode ser capturado na Route 4 e evolui no nível 26. Pokémon do tipo Terra são imunes a golpes elétricos, mas Pincurchin também conhece Poison Jab.", "Contra o inicial de Hop, Rillaboom pode enfrentar Inteleon com Planta, Cinderace pode enfrentar Rillaboom com Fogo e Inteleon pode enfrentar Cinderace com Água. Preste atenção aos outros golpes do adversário antes de trocar e prepare sua equipe para o Dynamax."], "CHAMPION CUP - BEDE": ["Bede interrompe a Champion Cup antes das finais e usa Pokémon dos tipos Fada e Psíquico. Sua equipe tem Mawile e Gardevoir no nível 51, Rapidash de Galar no nível 52 e Hatterene no nível 53.", "Mawile é dos tipos Metal e Fada e é vulnerável a Fogo e Terra. Gardevoir, Rapidash de Galar e Hatterene são dos tipos Psíquico e Fada e recebem dano superefetivo de Veneno, Fantasma e Metal.", "Contra Mawile, Cinderace pode usar golpes de Fogo se você escolheu Scorbunny. Independentemente do inicial, Dugtrio pode usar golpes de Terra. Diglett pode ser encontrado na Route 4 e evolui no nível 26.", "Perrserker pode enfrentar os Pokémon de Bede com golpes de Metal. Meowth de Galar aparece na Route 4 e evolui no nível 28. Tenha cuidado com Mystical Fire de Hatterene, que é superefetivo contra Perrserker.", "Toxtricity pode usar golpes de Veneno contra Gardevoir, Rapidash e Hatterene, mas seus golpes Psíquicos também são superefetivos contra ele. O Toxel da Pokémon Nursery na Route 5 evolui no nível 30.", "Bede usa Gigantamax em Hatterene. Prepare um Pokémon que consiga resistir aos seus ataques e cure a equipe antes da batalha."], "CHAMPION CUP - NESSA": ["Nessa retorna nas finais da Champion Cup com uma equipe maior. Ela usa Golisopod e Pelipper no nível 51, Barraskewda e Seaking no nível 52 e Drednaw no nível 53.", "Golisopod é vulnerável aos tipos Elétrico, Voador e Pedra. Pelipper recebe quatro vezes mais dano de Elétrico. Barraskewda e Seaking são vulneráveis a Elétrico e Planta, enquanto Drednaw recebe quatro vezes mais dano de Planta.", "Boltund com golpes elétricos pode enfrentar Golisopod, Pelipper, Barraskewda e Seaking. Yamper aparece nas Routes 2 e 4 e evolui no nível 25. Tenha muito cuidado com Drill Run de Barraskewda, que é superefetivo contra Boltund.", "Se você escolheu Grookey, Rillaboom pode usar golpes de Planta contra Barraskewda, Seaking e Drednaw. Outra opção é Eldegoss, evolução de Gossifleur da Route 3 no nível 20. Contra Golisopod, golpes de Planta causam dano normal por ele também ser do tipo Inseto.", "Corviknight com golpes Voadores é uma opção contra Golisopod. Rookidee aparece nas primeiras rotas e evolui para Corviknight no nível 38. Cuidado com First Impression, um golpe prioritário que Golisopod pode usar no primeiro turno em campo.", "Nessa usa Gigantamax em Drednaw. Deixe seu Pokémon de Planta preparado e cuidado com Rock Tomb, que pode reduzir a Velocidade do alvo."], "CHAMPION CUP - BEA": ["Bea retorna nas finais da Champion Cup em Pokémon Sword. Ela usa Hawlucha e Grapploct no nível 52, Sirfetch’d e Falinks no nível 53 e Machamp no nível 54.", "Os cinco são vulneráveis aos tipos Voador, Psíquico e Fada. Hawlucha também é do tipo Voador e recebe dano superefetivo de Elétrico e Gelo.", "Corviknight com golpes Voadores pode enfrentar a equipe de Bea. Rookidee aparece nas primeiras rotas e evolui para Corviknight no nível 38. Tenha muito cuidado com Fire Punch de Machamp, que é superefetivo contra ele.", "Boltund pode usar golpes elétricos contra Hawlucha. Yamper aparece nas Routes 2 e 4 e evolui no nível 25. Não confunda Grapploct com um Pokémon de Água, pois ele é apenas do tipo Lutador e não recebe dano superefetivo de Elétrico.", "Ribombee pode usar golpes de Fada contra os adversários. Cutiefly aparece na Route 4 e evolui no nível 25. Golpes Psíquicos também ajudam, mas Sirfetch’d conhece Brutal Swing, perigoso para Pokémon Psíquicos.", "Falinks pode usar No Retreat para aumentar seus atributos, e Grapploct pode prender seu Pokémon com Octolock. Bea usa Gigantamax em Machamp, então mantenha sua equipe recuperada."], "CHAMPION CUP - RAIHAN": ["Raihan é seu último adversário nas finais da Champion Cup. Ele usa Torkoal no nível 53, Goodra, Turtonator e Flygon no nível 54 e Duraludon no nível 55.", "Torkoal é vulnerável a Água, Terra e Pedra. Goodra é vulnerável a Gelo, Dragão e Fada. Turtonator é vulnerável a Terra, Pedra e Dragão, enquanto Flygon recebe quatro vezes mais dano de Gelo. Duraludon é vulnerável a Lutador e Terra.", "Contra Torkoal, Drednaw pode usar golpes de Água ou Pedra. Chewtle pode ser encontrado na Route 2 e evolui no nível 22. Torkoal conhece Solar Beam, então tenha cuidado com o dano de Planta, especialmente sob o sol.", "Para Goodra e Flygon, use um Pokémon com golpes de Gelo. Lapras pode ser encontrado na Wild Area, dependendo do clima, e pode enfrentar ambos com golpes desse tipo. Flygon recebe quatro vezes mais dano de Gelo, mas tenha cuidado com seus golpes de Dragão.", "Outra opção contra Goodra é Ribombee com golpes de Fada. Cutiefly pode ser encontrado na Route 4 e evolui no nível 25. Evite usá-lo contra Duraludon, que resiste a Fada e conhece Iron Head.", "Dugtrio pode usar golpes de Terra contra Turtonator e Duraludon. Diglett aparece na Route 4 e evolui no nível 26. Contra Duraludon, Machoke também pode usar golpes Lutadores. Turtonator conhece Shell Trap, que reage a golpes físicos, então considere usar um golpe especial.", "Raihan usa Gigantamax em Duraludon. Após a vitória, prepare sua equipe para os acontecimentos em Hammerlocke e para a batalha contra Leon."], "CHAMPION - LEON": ["Leon é o Champion de Galar e usa uma equipe com tipos variados. Ele sempre tem Aegislash e Dragapult no nível 62, Haxorus no nível 63 e Charizard no nível 65. Os outros dois Pokémon dependem do inicial que você escolheu.", "Se escolheu Grookey, Leon usa Seismitoad e Cinderace no nível 64. Se escolheu Scorbunny, ele usa Mr. Rime e Inteleon no nível 64. Se escolheu Sobble, ele usa Rhyperior e Rillaboom no nível 64.", "Aegislash é vulnerável aos tipos Fogo, Terra, Fantasma e Sombrio. Dragapult recebe dano superefetivo de Gelo, Fantasma, Dragão, Sombrio e Fada. Haxorus é vulnerável a Gelo, Dragão e Fada.", "Contra Aegislash, use Cinderace com golpes de Fogo se escolheu Scorbunny. Outra opção é Dugtrio com golpes de Terra, evoluído do Diglett encontrado na Route 4. Aegislash conhece King''s Shield, que protege de ataques e reduz o Ataque de quem fizer contato.", "Para Dragapult, Obstagoon pode usar golpes Sombrios. Zigzagoon de Galar aparece na Route 2, evolui para Linoone no nível 20 e para Obstagoon ao subir de nível à noite a partir do nível 35. Dragapult conhece Flamethrower e Thunderbolt, então cuidado ao trocar para Pokémon vulneráveis a esses golpes.", "Contra Haxorus, Lapras pode usar golpes de Gelo. Ele pode ser encontrado na Wild Area em condições específicas de clima. Uma opção do tipo Fada é Ribombee, evolução do Cutiefly encontrado na Route 4, mas tenha muito cuidado com Poison Jab e Iron Tail de Haxorus.", "Se Leon tiver Seismitoad, Rillaboom ou Eldegoss pode usar golpes de Planta, que causam quatro vezes mais dano por ele ser dos tipos Água e Terra. Gossifleur pode ser encontrado na Route 3 e evolui no nível 20.", "Se Leon tiver Mr. Rime, golpes de Fogo ou Sombrio são boas opções. Cinderace e Obstagoon podem aproveitar essas fraquezas, mas Obstagoon é imune a Psychic por também ser do tipo Sombrio, mas fique atento aos outros golpes de Mr. Rime.", "Se Leon tiver Rhyperior, use Inteleon ou Drednaw com golpes de Água. Rhyperior recebe quatro vezes mais dano de Água e Planta, mas sua habilidade Solid Rock reduz o dano de golpes superefetivos. Chewtle pode ser encontrado na Route 2 e evolui no nível 22.", "Contra Cinderace, use Drednaw ou Inteleon com golpes de Água. Contra Inteleon, Boltund ou Rillaboom pode usar golpes Elétricos ou de Planta. Contra Rillaboom, Cinderace ou Corviknight pode usar golpes de Fogo ou Voador. Cuidado com os golpes de cobertura antes de trocar.", "Charizard é dos tipos Fogo e Voador e recebe quatro vezes mais dano de golpes de Pedra. Drednaw ou Coalossal pode aproveitar essa fraqueza, mas ambos devem tomar cuidado com Solar Beam, que também causa quatro vezes mais dano a eles.", "Leon usa Gigantamax em Charizard, então guarde seu Dynamax para esse momento se precisar. Treine e cure sua equipe antes da batalha, pois os Pokémon de Leon chegam ao nível 65. Depois da vitória, você se tornará o novo Champion de Galar."]}'::jsonb WHERE slug = 'pokemon-sword';
UPDATE public.builds SET caps = ARRAY(SELECT cap FROM unnest(caps) AS cap WHERE NOT (cap = ANY(ARRAY['CHAMPION CUP - MARNIE','CHAMPION CUP - HOP','CHAMPION CUP - BEDE','CHAMPION CUP - NESSA','CHAMPION CUP - ALLISTER','CHAMPION CUP - RAIHAN','CHAMPION - LEON']))) || ARRAY['CHAMPION CUP - MARNIE','CHAMPION CUP - HOP','CHAMPION CUP - BEDE','CHAMPION CUP - NESSA','CHAMPION CUP - ALLISTER','CHAMPION CUP - RAIHAN','CHAMPION - LEON'], dicas = dicas || '{"CHAMPION CUP - MARNIE": ["Marnie é sua primeira adversária na Champion Cup. Sua equipe começa com Liepard, Toxicroak e Scrafty no nível 47, seguidos de Morpeko no nível 48 e Grimmsnarl no nível 49.", "Liepard é vulnerável aos tipos Lutador, Inseto e Fada. Toxicroak recebe quatro vezes mais dano de golpes Psíquicos e também é vulnerável aos tipos Terra e Voador. Scrafty recebe quatro vezes mais dano de Fada e também é vulnerável a Lutador e Voador.", "Morpeko é dos tipos Elétrico e Sombrio e recebe dano superefetivo de Terra, Lutador, Inseto e Fada. Grimmsnarl é dos tipos Sombrio e Fada e é vulnerável aos tipos Veneno, Metal e Fada.", "Um Machoke com golpes Lutadores pode enfrentar Liepard, Scrafty e Morpeko. Machop pode ser capturado na Route 3 e evolui para Machoke no nível 28. Cuidado com Bullet Seed de Morpeko se escolher um Pokémon do tipo Terra para enfrentá-lo.", "Contra Scrafty, Ribombee com golpes de Fada aproveita a fraqueza de quatro vezes. Cutiefly pode ser encontrado na Route 4 e evolui no nível 25. Mantenha-o longe de Toxicroak, pois golpes de Veneno causam muito dano a ele.", "Para Toxicroak, use um Pokémon Psíquico ou Corviknight com golpes Voadores. Rookidee aparece nas primeiras rotas e evolui para Corvisquire no nível 18 e Corviknight no nível 38. Toxicroak conhece Sucker Punch, então tome cuidado com um Pokémon Psíquico enfraquecido.", "Contra Grimmsnarl, Perrserker pode usar golpes de Metal. Meowth de Galar pode ser encontrado na Route 4 e evolui no nível 28. Toxtricity com golpes de Veneno também é uma opção, a partir do Toxel recebido na Pokémon Nursery da Route 5.", "Marnie usa Gigantamax em Grimmsnarl. Recupere sua equipe e esteja preparado para enfrentar Hop depois da vitória."], "CHAMPION CUP - HOP": ["Hop é seu próximo adversário na Champion Cup. Ele usa Dubwool e Corviknight no nível 48, Pincurchin e Snorlax no nível 47 e a evolução final do inicial no nível 49.", "Se você escolheu Grookey, Hop usa Inteleon. Se escolheu Scorbunny, ele usa Rillaboom. Se escolheu Sobble, ele usa Cinderace. Hop usa Dynamax em seu inicial.", "Dubwool e Snorlax são do tipo Normal e vulneráveis a golpes Lutadores. Corviknight é dos tipos Voador e Metal e recebe dano superefetivo de Fogo e Elétrico. Pincurchin é vulnerável a golpes de Terra.", "Machoke, evolução de Machop encontrado na Route 3, pode enfrentar Dubwool e Snorlax com golpes Lutadores. Cuidado com Zen Headbutt de Dubwool, que é superefetivo contra Machoke, e com Cotton Guard, que aumenta bastante a Defesa de Dubwool.", "Contra Corviknight, use Boltund com golpes elétricos. Yamper pode ser encontrado nas Routes 2 e 4 e evolui no nível 25. Se escolheu Scorbunny, seu Cinderace também pode usar golpes de Fogo.", "Para Pincurchin, Dugtrio com golpes de Terra é uma opção. Diglett pode ser capturado na Route 4 e evolui no nível 26. Pokémon do tipo Terra são imunes a golpes elétricos, mas Pincurchin também conhece Poison Jab.", "Contra o inicial de Hop, Rillaboom pode enfrentar Inteleon com Planta, Cinderace pode enfrentar Rillaboom com Fogo e Inteleon pode enfrentar Cinderace com Água. Preste atenção aos outros golpes do adversário antes de trocar e prepare sua equipe para o Dynamax."], "CHAMPION CUP - BEDE": ["Bede interrompe a Champion Cup antes das finais e usa Pokémon dos tipos Fada e Psíquico. Sua equipe tem Mawile e Gardevoir no nível 51, Rapidash de Galar no nível 52 e Hatterene no nível 53.", "Mawile é dos tipos Metal e Fada e é vulnerável a Fogo e Terra. Gardevoir, Rapidash de Galar e Hatterene são dos tipos Psíquico e Fada e recebem dano superefetivo de Veneno, Fantasma e Metal.", "Contra Mawile, Cinderace pode usar golpes de Fogo se você escolheu Scorbunny. Independentemente do inicial, Dugtrio pode usar golpes de Terra. Diglett pode ser encontrado na Route 4 e evolui no nível 26.", "Perrserker pode enfrentar os Pokémon de Bede com golpes de Metal. Meowth de Galar aparece na Route 4 e evolui no nível 28. Tenha cuidado com Mystical Fire de Hatterene, que é superefetivo contra Perrserker.", "Toxtricity pode usar golpes de Veneno contra Gardevoir, Rapidash e Hatterene, mas seus golpes Psíquicos também são superefetivos contra ele. O Toxel da Pokémon Nursery na Route 5 evolui no nível 30.", "Bede usa Gigantamax em Hatterene. Prepare um Pokémon que consiga resistir aos seus ataques e cure a equipe antes da batalha."], "CHAMPION CUP - NESSA": ["Nessa retorna nas finais da Champion Cup com uma equipe maior. Ela usa Golisopod e Pelipper no nível 51, Barraskewda e Seaking no nível 52 e Drednaw no nível 53.", "Golisopod é vulnerável aos tipos Elétrico, Voador e Pedra. Pelipper recebe quatro vezes mais dano de Elétrico. Barraskewda e Seaking são vulneráveis a Elétrico e Planta, enquanto Drednaw recebe quatro vezes mais dano de Planta.", "Boltund com golpes elétricos pode enfrentar Golisopod, Pelipper, Barraskewda e Seaking. Yamper aparece nas Routes 2 e 4 e evolui no nível 25. Tenha muito cuidado com Drill Run de Barraskewda, que é superefetivo contra Boltund.", "Se você escolheu Grookey, Rillaboom pode usar golpes de Planta contra Barraskewda, Seaking e Drednaw. Outra opção é Eldegoss, evolução de Gossifleur da Route 3 no nível 20. Contra Golisopod, golpes de Planta causam dano normal por ele também ser do tipo Inseto.", "Corviknight com golpes Voadores é uma opção contra Golisopod. Rookidee aparece nas primeiras rotas e evolui para Corviknight no nível 38. Cuidado com First Impression, um golpe prioritário que Golisopod pode usar no primeiro turno em campo.", "Nessa usa Gigantamax em Drednaw. Deixe seu Pokémon de Planta preparado e cuidado com Rock Tomb, que pode reduzir a Velocidade do alvo."], "CHAMPION CUP - ALLISTER": ["Allister retorna nas finais da Champion Cup em Pokémon Shield. Ele usa Dusknoir e Chandelure no nível 52, Cursola e Polteageist no nível 53 e Gengar no nível 54.", "Os cinco são vulneráveis aos tipos Fantasma e Sombrio. Chandelure também é vulnerável a Água, Terra e Pedra por ser do tipo Fogo. Gengar também é vulnerável a Terra e Psíquico por ser do tipo Veneno.", "Obstagoon pode usar golpes Sombrios contra a equipe. Zigzagoon de Galar aparece na Route 2, evolui para Linoone no nível 20 e para Obstagoon ao subir de nível à noite a partir do nível 35. Por também ser do tipo Normal, ele é imune a golpes Fantasmas.", "Contra Chandelure, Drednaw pode usar golpes de Água ou Pedra. Chewtle aparece na Route 2 e evolui no nível 22. Cuidado com Will-O-Wisp, que causa queimadura e reduz o Ataque físico.", "Contra Gengar, Dugtrio pode usar golpes de Terra. Diglett aparece na Route 4 e evolui no nível 26. Um Pokémon Psíquico também pode aproveitar a fraqueza de Gengar, mas deve tomar cuidado com Shadow Ball e Dark Pulse.", "Cursola pode recuperar vida com Strength Sap e Polteageist pode aumentar seu Ataque Especial com Nasty Plot. Allister usa Gigantamax em Gengar, que conhece Hypnosis. Leve itens para curar sono e mantenha a equipe recuperada."], "CHAMPION CUP - RAIHAN": ["Raihan é seu último adversário nas finais da Champion Cup. Ele usa Torkoal no nível 53, Goodra, Turtonator e Flygon no nível 54 e Duraludon no nível 55.", "Torkoal é vulnerável a Água, Terra e Pedra. Goodra é vulnerável a Gelo, Dragão e Fada. Turtonator é vulnerável a Terra, Pedra e Dragão, enquanto Flygon recebe quatro vezes mais dano de Gelo. Duraludon é vulnerável a Lutador e Terra.", "Contra Torkoal, Drednaw pode usar golpes de Água ou Pedra. Chewtle pode ser encontrado na Route 2 e evolui no nível 22. Torkoal conhece Solar Beam, então tenha cuidado com o dano de Planta, especialmente sob o sol.", "Para Goodra e Flygon, use um Pokémon com golpes de Gelo. Lapras pode ser encontrado na Wild Area, dependendo do clima, e pode enfrentar ambos com golpes desse tipo. Flygon recebe quatro vezes mais dano de Gelo, mas tenha cuidado com seus golpes de Dragão.", "Outra opção contra Goodra é Ribombee com golpes de Fada. Cutiefly pode ser encontrado na Route 4 e evolui no nível 25. Evite usá-lo contra Duraludon, que resiste a Fada e conhece Iron Head.", "Dugtrio pode usar golpes de Terra contra Turtonator e Duraludon. Diglett aparece na Route 4 e evolui no nível 26. Contra Duraludon, Machoke também pode usar golpes Lutadores. Turtonator conhece Shell Trap, que reage a golpes físicos, então considere usar um golpe especial.", "Raihan usa Gigantamax em Duraludon. Após a vitória, prepare sua equipe para os acontecimentos em Hammerlocke e para a batalha contra Leon."], "CHAMPION - LEON": ["Leon é o Champion de Galar e usa uma equipe com tipos variados. Ele sempre tem Aegislash e Dragapult no nível 62, Haxorus no nível 63 e Charizard no nível 65. Os outros dois Pokémon dependem do inicial que você escolheu.", "Se escolheu Grookey, Leon usa Seismitoad e Cinderace no nível 64. Se escolheu Scorbunny, ele usa Mr. Rime e Inteleon no nível 64. Se escolheu Sobble, ele usa Rhyperior e Rillaboom no nível 64.", "Aegislash é vulnerável aos tipos Fogo, Terra, Fantasma e Sombrio. Dragapult recebe dano superefetivo de Gelo, Fantasma, Dragão, Sombrio e Fada. Haxorus é vulnerável a Gelo, Dragão e Fada.", "Contra Aegislash, use Cinderace com golpes de Fogo se escolheu Scorbunny. Outra opção é Dugtrio com golpes de Terra, evoluído do Diglett encontrado na Route 4. Aegislash conhece King''s Shield, que protege de ataques e reduz o Ataque de quem fizer contato.", "Para Dragapult, Obstagoon pode usar golpes Sombrios. Zigzagoon de Galar aparece na Route 2, evolui para Linoone no nível 20 e para Obstagoon ao subir de nível à noite a partir do nível 35. Dragapult conhece Flamethrower e Thunderbolt, então cuidado ao trocar para Pokémon vulneráveis a esses golpes.", "Contra Haxorus, Lapras pode usar golpes de Gelo. Ele pode ser encontrado na Wild Area em condições específicas de clima. Uma opção do tipo Fada é Ribombee, evolução do Cutiefly encontrado na Route 4, mas tenha muito cuidado com Poison Jab e Iron Tail de Haxorus.", "Se Leon tiver Seismitoad, Rillaboom ou Eldegoss pode usar golpes de Planta, que causam quatro vezes mais dano por ele ser dos tipos Água e Terra. Gossifleur pode ser encontrado na Route 3 e evolui no nível 20.", "Se Leon tiver Mr. Rime, golpes de Fogo ou Sombrio são boas opções. Cinderace e Obstagoon podem aproveitar essas fraquezas, mas Obstagoon é imune a Psychic por também ser do tipo Sombrio, mas fique atento aos outros golpes de Mr. Rime.", "Se Leon tiver Rhyperior, use Inteleon ou Drednaw com golpes de Água. Rhyperior recebe quatro vezes mais dano de Água e Planta, mas sua habilidade Solid Rock reduz o dano de golpes superefetivos. Chewtle pode ser encontrado na Route 2 e evolui no nível 22.", "Contra Cinderace, use Drednaw ou Inteleon com golpes de Água. Contra Inteleon, Boltund ou Rillaboom pode usar golpes Elétricos ou de Planta. Contra Rillaboom, Cinderace ou Corviknight pode usar golpes de Fogo ou Voador. Cuidado com os golpes de cobertura antes de trocar.", "Charizard é dos tipos Fogo e Voador e recebe quatro vezes mais dano de golpes de Pedra. Drednaw ou Coalossal pode aproveitar essa fraqueza, mas ambos devem tomar cuidado com Solar Beam, que também causa quatro vezes mais dano a eles.", "Leon usa Gigantamax em Charizard, então guarde seu Dynamax para esse momento se precisar. Treine e cure sua equipe antes da batalha, pois os Pokémon de Leon chegam ao nível 65. Depois da vitória, você se tornará o novo Champion de Galar."]}'::jsonb WHERE slug = 'pokemon-shield';

-- Victory Road de Scarlet e Violet.
UPDATE public.builds SET caps = ARRAY['1º GYM - KATY','2º GYM - BRASSIUS','3º GYM - IONO','4º GYM - KOFU','5º GYM - LARRY','6º GYM - RYME','7º GYM - TULIP','8º GYM - GRUSHA','ELITE FOUR - RIKA','ELITE FOUR - POPPY','ELITE FOUR - LARRY','ELITE FOUR - HASSEL','TOP CHAMPION - GEETA','CHAMPION - NEMONA'] || ARRAY(SELECT x FROM unnest(caps) x WHERE NOT x = ANY(ARRAY['1º GYM - KATY','2º GYM - BRASSIUS','3º GYM - IONO','4º GYM - KOFU','5º GYM - LARRY','6º GYM - RYME','7º GYM - TULIP','8º GYM - GRUSHA','ELITE FOUR - RIKA','ELITE FOUR - POPPY','ELITE FOUR - LARRY','ELITE FOUR - HASSEL','TOP CHAMPION - GEETA','CHAMPION - NEMONA'])), dicas = dicas || '{"1º GYM - KATY": ["Katy é a líder de Cortondo e usa Nymble e Tarountula no nível 14 e Teddiursa no nível 15.", "Nymble e Tarountula são vulneráveis aos tipos Fogo, Voador e Pedra. Katy Terastaliza Teddiursa, que passa a ser do tipo Inseto e recebe as mesmas fraquezas.", "Se escolheu Fuecoco, use seus golpes de Fogo. Se escolheu Sprigatito ou Quaxly, Fletchling pode ser encontrado na South Province e usar golpes Voadores.", "Outra opção é Nacli, encontrado na South Province, com golpes de Pedra. Tenha cuidado com Double Kick de Nymble, que é superefetivo contra Nacli.", "Teddiursa pode usar Fury Cutter, que fica mais forte em usos consecutivos. Cure sua equipe antes da batalha."], "2º GYM - BRASSIUS": ["Brassius é o líder de Artazon e usa Petilil e Smoliv no nível 16 e Sudowoodo no nível 17.", "Petilil e Smoliv são vulneráveis aos tipos Fogo, Gelo, Voador, Inseto e Veneno. Depois de Terastalizar, Sudowoodo passa a ser do tipo Planta e recebe as mesmas fraquezas.", "Se escolheu Fuecoco, use golpes de Fogo. Fletchling, encontrado nas primeiras áreas da South Province, também pode usar golpes Voadores e evolui para Fletchinder no nível 17.", "Outra opção é o Pokémon inseto Nymble, encontrado na South Province, com golpes de Inseto. Evite depender de golpes de Água contra Sudowoodo após a Terastalização.", "Petilil pode colocar seu Pokémon para dormir com Sleep Powder. Sudowoodo conhece Rock Throw, perigoso para Pokémon Voadores e de Fogo, e Trailblaze aumenta sua Velocidade."], "3º GYM - IONO": ["Iono lidera o ginásio de Levincia e usa Wattrel, Bellibolt e Luxio no nível 23 e Mismagius no nível 24.", "Bellibolt e Luxio são vulneráveis a Terra. Wattrel também é Voador e é imune a Terra. Mismagius se torna do tipo Elétrico ao Terastalizar, mas sua habilidade Levitate continua impedindo golpes de Terra.", "Clodsire pode enfrentar Bellibolt e Luxio com golpes de Terra. Wooper de Paldea aparece na South Province e evolui no nível 20. Tenha cuidado com Water Gun de Bellibolt.", "Nacli, encontrado na South Province, pode usar golpes de Pedra contra Wattrel. Após evoluir para Naclstack no nível 24, ele também é uma opção para atacar Mismagius com golpes neutros.", "Mismagius usa Confuse Ray e Charge Beam, que pode aumentar seu Ataque Especial. Como Levitate anula sua única fraqueza, use golpes fortes neutros e mantenha a equipe recuperada."], "4º GYM - KOFU": ["Kofu lidera o ginásio de Cascarrafa e usa Veluza e Wugtrio no nível 29 e Crabominable no nível 30.", "Veluza é dos tipos Água e Psíquico e é vulnerável a Elétrico, Planta, Inseto, Fantasma e Sombrio. Wugtrio é vulnerável a Elétrico e Planta. Crabominable torna-se do tipo Água ao Terastalizar.", "Se escolheu Sprigatito, Floragato pode usar golpes de Planta contra os três. Pawmo também pode usar golpes elétricos. Pawmi aparece na South Province e evolui no nível 18.", "Para Veluza, Lokix pode usar golpes de Inseto ou Sombrio. Nymble pode ser encontrado na South Province e evolui no nível 24. Tenha cuidado com Pluck, que é superefetivo contra ele.", "Wugtrio conhece Mud-Slap, perigoso para Pokémon elétricos. Crabominable usa Crabhammer e pode causar muito dano, então mantenha sua equipe com bastante vida."], "5º GYM - LARRY": ["Larry lidera o ginásio de Medali e usa Komala e Dudunsparce no nível 35 e Staraptor no nível 36.", "Komala e Dudunsparce são do tipo Normal e vulneráveis a golpes Lutadores. Staraptor torna-se do tipo Normal ao Terastalizar e também fica vulnerável a Lutador.", "Se escolheu Quaxly, seu Quaxwell já pode ter evoluído para Quaquaval no nível 36 e usar golpes Lutadores. Mankey, encontrado na South Province, evolui para Primeape no nível 28 e oferece outra opção.", "Makuhita também pode ser encontrado na South Province e evolui para Hariyama no nível 24. Ambos podem aproveitar a fraqueza da equipe, mas precisam tomar cuidado com Aerial Ace de Staraptor.", "Komala usa Yawn e Dudunsparce pode paralisar com Glare. Staraptor possui Intimidate, que reduz o Ataque do Pokémon em campo, e conhece Facade. Leve itens para curar sono e paralisia."], "6º GYM - RYME": ["Ryme lidera o ginásio de Montenevera e luta em dupla. Ela usa Banette, Mimikyu e Houndstone no nível 41 e Toxtricity no nível 42.", "Banette e Houndstone são vulneráveis a Fantasma e Sombrio. Mimikyu é dos tipos Fantasma e Fada e é vulnerável a Fantasma e Metal. Toxtricity torna-se Fantasma ao Terastalizar.", "Se escolheu Sprigatito, Meowscarada pode usar golpes Sombrios contra Banette, Houndstone e Toxtricity. Outra opção é Mabosstiff, evolução de Maschiff encontrado em áreas da West Province.", "Tinkaton pode usar golpes de Metal contra Mimikyu. Tinkatink pode ser encontrado perto de ruínas e evolui para Tinkatuff no nível 24 e Tinkaton no nível 38. A habilidade Disguise de Mimikyu bloqueia o dano do primeiro golpe recebido.", "Preste atenção aos dois adversários. Toxtricity conhece Discharge, que atinge os outros Pokémon em campo, e Houndstone usa Play Rough, perigoso contra Pokémon Sombrios. Cure a equipe e planeje as trocas."], "7º GYM - TULIP": ["Tulip lidera o ginásio de Alfornada e usa Farigiraf, Gardevoir e Espathra no nível 44 e Florges no nível 45.", "Farigiraf é dos tipos Normal e Psíquico, imune a Fantasma e vulnerável a Inseto e Sombrio. Gardevoir é Psíquico e Fada, vulnerável a Veneno, Fantasma e Metal. Espathra é vulnerável a Inseto, Fantasma e Sombrio.", "Florges se torna do tipo Psíquico ao Terastalizar e passa a ser vulnerável a Inseto, Fantasma e Sombrio. Seus golpes de Fada continuam perigosos para Pokémon Sombrios.", "Meowscarada pode usar golpes Sombrios contra Farigiraf, Espathra e Florges se você escolheu Sprigatito. Outra opção é Lokix, evolução de Nymble no nível 24, com golpes de Inseto ou Sombrio.", "Tinkaton pode usar golpes de Metal contra Gardevoir. Evite usar golpes Fantasmas contra Farigiraf, que é imune, e tenha cuidado com Dazzling Gleam de Gardevoir e Moonblast de Florges."], "8º GYM - GRUSHA": ["Grusha lidera o ginásio de Glaseado e usa Frosmoth, Beartic e Cetitan no nível 47 e Altaria no nível 48.", "Frosmoth recebe quatro vezes mais dano de Fogo e Pedra. Beartic e Cetitan são vulneráveis a Fogo, Lutador, Pedra e Metal. Altaria torna-se do tipo Gelo ao Terastalizar.", "Se escolheu Fuecoco, Skeledirge pode usar golpes de Fogo. Cuidado com Aqua Jet e Earthquake de Beartic e Liquidation de Cetitan, que são perigosos para ele.", "Garganacl pode usar golpes de Pedra contra Frosmoth e Altaria. Nacli aparece na South Province e evolui para Naclstack no nível 24 e Garganacl no nível 38, mas golpes de Água são perigosos para ele.", "Hariyama ou Primeape pode usar golpes Lutadores. Cetitan possui Thick Fat, que reduz o dano de Fogo, e pode usar Ice Shard com prioridade. Altaria conhece Hurricane e Moonblast, então cure a equipe antes de enfrentá-lo."], "ELITE FOUR - RIKA": ["Rika é a primeira integrante da Elite Four e usa Whiscash, Camerupt, Donphan e Dugtrio no nível 57 e Clodsire no nível 58.", "Whiscash recebe quatro vezes mais dano de Planta e é imune a Elétrico. Camerupt recebe quatro vezes mais dano de Água. Donphan e Dugtrio são vulneráveis a Água, Planta e Gelo.", "Se escolheu Sprigatito, Meowscarada pode enfrentar Whiscash, Donphan e Dugtrio com Planta. Cuidado com Blizzard de Whiscash e Poison Jab de Donphan.", "Se escolheu Quaxly, Quaquaval pode usar Água contra Camerupt, Donphan e Dugtrio. Outra opção é Azumarill, obtido a partir de Azurill ou Marill encontrados em Paldea.", "Clodsire tem Water Absorb e recupera vida quando atingido por Água. Depois de Terastalizar para Terra, ele é vulnerável a Planta e Gelo. Não use golpes de Água contra ele.", "Camerupt pode usar Yawn, e Clodsire conhece Toxic e Protect. Leve itens de cura e recupere sua equipe antes de enfrentar Poppy."], "ELITE FOUR - POPPY": ["Poppy é a segunda integrante da Elite Four e usa Copperajah, Magnezone, Bronzong e Corviknight no nível 58 e Tinkaton no nível 59.", "Copperajah é vulnerável a Fogo, Lutador e Terra. Magnezone recebe quatro vezes mais dano de Terra. Bronzong possui Levitate e Corviknight é Voador, portanto golpes de Terra não os atingem.", "Se escolheu Fuecoco, Skeledirge pode usar golpes de Fogo contra Copperajah, Bronzong e Corviknight. Cuidado com Earthquake de Bronzong e High Horsepower de Copperajah.", "Clodsire pode usar golpes de Terra contra Magnezone. Wooper de Paldea aparece na South Province e evolui no nível 20. Magnezone possui Sturdy, então pode sobreviver a um golpe que o derrotaria com vida cheia.", "Corviknight também é vulnerável a Elétrico. Use Bellibolt ou outro Pokémon elétrico, mas observe Iron Defense e Body Press, que podem tornar seus ataques perigosos.", "Tinkaton Terastaliza para Metal e fica vulnerável a Fogo, Lutador e Terra. Gigaton Hammer é muito forte, embora não possa ser usado em turnos consecutivos. Recupere a equipe depois da vitória."], "ELITE FOUR - LARRY": ["Larry retorna como integrante da Elite Four, agora especialista em Voador. Ele usa Tropius, Oricorio, Altaria e Staraptor no nível 59 e Flamigo no nível 60.", "Tropius e Altaria recebem quatro vezes mais dano de Gelo. Oricorio e Staraptor são vulneráveis a Elétrico, Gelo e Pedra. Flamigo torna-se do tipo Voador ao Terastalizar.", "Cetitan ou outro Pokémon com golpes de Gelo pode enfrentar Tropius e Altaria. Cetoddle aparece na Glaseado Mountain e evolui com uma Ice Stone. Cuidado com Flamethrower de Altaria.", "Bellibolt, evolução de Tadbulb com Thunder Stone, pode usar golpes elétricos contra Oricorio, Staraptor e Flamigo. Garganacl também pode usar golpes de Pedra, mas deve evitar Close Combat e Liquidation de Flamigo.", "Tropius pode usar Sunny Day e Solar Beam. Staraptor possui Intimidate e usa Brave Bird, enquanto Flamigo conhece Close Combat. Recupere sua equipe antes de Hassel."], "ELITE FOUR - HASSEL": ["Hassel é o último integrante da Elite Four e usa Noivern, Haxorus, Dragalge e Flapple no nível 60 e Baxcalibur no nível 61.", "Noivern e Flapple recebem quatro vezes mais dano de Gelo. Haxorus é vulnerável a Gelo, Dragão e Fada. Dragalge é vulnerável a Terra, Gelo, Psíquico e Dragão.", "Baxcalibur se torna do tipo Dragão ao Terastalizar e fica vulnerável a Gelo, Dragão e Fada. Ele mantém seus golpes de Gelo, por isso cuidado ao usar outros Dragões.", "Cetitan com golpes de Gelo pode enfrentar Noivern, Haxorus e Flapple. Cetoddle aparece na Glaseado Mountain e evolui com Ice Stone. Noivern pode usar Super Fang, que retira metade da vida atual.", "Tinkaton pode usar golpes de Fada contra Haxorus e Baxcalibur, mas Haxorus conhece Iron Head. Contra Dragalge, Clodsire pode usar golpes de Terra, tomando cuidado com Hydro Pump.", "Baxcalibur conhece Glaive Rush, um golpe muito forte que deixa o usuário mais exposto no turno seguinte. Recupere sua equipe e prepare-se para Geeta."], "TOP CHAMPION - GEETA": ["Geeta é a Top Champion de Paldea. Seu time usa Espathra, Gogoat, Veluza, Avalugg e Kingambit no nível 61 e Glimmora no nível 62.", "Espathra é vulnerável a Inseto, Fantasma e Sombrio. Gogoat é vulnerável a Fogo, Gelo, Veneno, Voador e Inseto. Veluza é vulnerável a Elétrico, Planta, Inseto, Fantasma e Sombrio.", "Contra Espathra, Meowscarada ou Lokix pode usar golpes Sombrios. Contra Gogoat, Skeledirge pode usar Fogo ou Corviknight pode usar golpes Voadores. Cuidado com Zen Headbutt e Play Rough de Gogoat.", "Contra Veluza, Meowscarada pode usar Planta ou Sombrio. Bellibolt é outra opção com golpes elétricos, mas Veluza conhece Psycho Cut e Ice Fang, então escolha com cuidado.", "Avalugg é vulnerável a Fogo, Lutador, Pedra e Metal. Kingambit é dos tipos Sombrio e Metal e recebe quatro vezes mais dano de Lutador. Quaquaval, Hariyama ou Primeape pode aproveitar essa fraqueza.", "Glimmora passa a ser do tipo Pedra ao Terastalizar e fica vulnerável a Água, Planta, Lutador, Terra e Metal. Ela conhece Earth Power, Sludge Wave e Dazzling Gleam. Mantenha a equipe recuperada e ataque suas fraquezas para conquistar o Champion Rank."], "CHAMPION - NEMONA": ["Depois de conquistar o Champion Rank, enfrente Nemona em Mesagoza. Ela usa Lycanroc, Goodra, Dudunsparce, Orthworm e Pawmot no nível 65 e seu inicial no nível 66.", "Se você escolheu Sprigatito, Nemona usa Quaquaval. Se escolheu Fuecoco, ela usa Meowscarada. Se escolheu Quaxly, ela usa Skeledirge. Seu inicial é Terastalizado para o tipo Água, Planta ou Fogo, respectivamente.", "Lycanroc é vulnerável a Água, Planta, Lutador, Terra e Metal. Dudunsparce é vulnerável a Lutador. Quaquaval ou Hariyama pode ajudar, mas Lycanroc conhece Accelerock e Dudunsparce pode aumentar seus atributos com Coil.", "Goodra é vulnerável a Gelo, Dragão e Fada. Cetitan pode usar golpes de Gelo, mas Goodra conhece ataques variados, incluindo Sludge Bomb. Tinkaton pode usar golpes de Fada, observando o dano recebido.", "Orthworm é vulnerável a Fogo e Lutador, mas sua habilidade Earth Eater o cura quando atingido por Terra. Skeledirge pode usar Fogo, tomando cuidado com Earthquake. Pawmot é vulnerável a Terra, Psíquico e Fada, mas conhece Ice Punch.", "Contra Quaquaval Terastalizado, use golpes Elétricos ou de Planta. Contra Meowscarada Terastalizado, use Fogo, Gelo, Voador, Inseto ou Veneno. Contra Skeledirge Terastalizado, use Água, Terra ou Pedra.", "Os Pokémon de Nemona conhecem golpes de cobertura e seu inicial está no nível 66. Treine e cure a equipe antes da batalha e escolha suas trocas com cuidado."]}'::jsonb, categorias = categorias || '{"1º GYM - KATY": "victory-road", "2º GYM - BRASSIUS": "victory-road", "3º GYM - IONO": "victory-road", "4º GYM - KOFU": "victory-road", "5º GYM - LARRY": "victory-road", "6º GYM - RYME": "victory-road", "7º GYM - TULIP": "victory-road", "8º GYM - GRUSHA": "victory-road", "ELITE FOUR - RIKA": "victory-road", "ELITE FOUR - POPPY": "victory-road", "ELITE FOUR - LARRY": "victory-road", "ELITE FOUR - HASSEL": "victory-road", "TOP CHAMPION - GEETA": "victory-road", "CHAMPION - NEMONA": "victory-road"}'::jsonb WHERE slug IN ('pokemon-scarlet','pokemon-violet');

-- Path of Legends e Starfall Street de Scarlet e Violet.
UPDATE public.builds SET caps = ARRAY(SELECT x FROM unnest(caps) x WHERE NOT x = ANY(ARRAY['TITAN - KLAWF','TITAN - BOMBIRDIER','TITAN - ORTHWORM','TITAN - GREAT TUSK','TITAN - DONDOZO E TATSUGIRI','PATH OF LEGENDS - ARVEN','TEAM STAR - GIACOMO','TEAM STAR - MELA','TEAM STAR - ATTICUS','TEAM STAR - ORTEGA','TEAM STAR - ERI','TEAM STAR - CLAVELL','TEAM STAR - PENNY'])) || ARRAY['TITAN - KLAWF','TITAN - BOMBIRDIER','TITAN - ORTHWORM','TITAN - GREAT TUSK','TITAN - DONDOZO E TATSUGIRI','PATH OF LEGENDS - ARVEN','TEAM STAR - GIACOMO','TEAM STAR - MELA','TEAM STAR - ATTICUS','TEAM STAR - ORTEGA','TEAM STAR - ERI','TEAM STAR - CLAVELL','TEAM STAR - PENNY'], dicas = dicas || '{"TITAN - KLAWF": ["Klawf é o Stony Cliff Titan na South Province Area Three e está no nível 16. Ele é do tipo Pedra e é vulnerável a Água, Planta, Lutador, Terra e Metal.", "Se escolheu Quaxly ou Sprigatito, use golpes de Água ou Planta. Outra opção é Makuhita, encontrado na South Province, com golpes Lutadores.", "Ao perder parte da vida, Klawf usa Anger Shell para aumentar Ataque, Ataque Especial e Velocidade, mas suas defesas diminuem. Cure seus Pokémon antes que ele consiga atacar novamente.", "Depois da primeira fase, Klawf foge e enfrenta você e Arven juntos. Mantenha sua equipe recuperada para a segunda batalha."], "TITAN - BOMBIRDIER": ["Bombirdier é o Open Sky Titan na West Province Area One e está no nível 20. Ele é dos tipos Voador e Sombrio e é vulnerável a Elétrico, Gelo, Pedra e Fada.", "Pawmi pode usar golpes elétricos e Nacli pode usar golpes de Pedra. Os dois podem ser encontrados na South Province. Pawmi evolui para Pawmo no nível 18.", "Se escolheu Quaxly ou Sprigatito, cuidado com os golpes Voadores de Bombirdier. Se escolheu Fuecoco, fique atento a Rock Throw.", "Após a primeira fase, Bombirdier foge e enfrenta você e Arven juntos. Sua habilidade Rocky Payload fortalece golpes de Pedra, então cuide de Pokémon vulneráveis a esse tipo."], "TITAN - ORTHWORM": ["Orthworm é o Lurking Steel Titan na East Province Area Three e está no nível 29. Ele é do tipo Metal e vulnerável a Fogo e Lutador.", "Orthworm possui Earth Eater, que o faz recuperar vida ao receber golpes de Terra. Portanto, use Fogo ou Lutador para explorar suas outras fraquezas.", "Se escolheu Fuecoco, Crocalor pode usar golpes de Fogo. Makuhita pode ser encontrado na South Province e evolui para Hariyama no nível 24, oferecendo uma opção Lutadora.", "Orthworm conhece Iron Tail e Wrap. Depois da primeira fase, ele enfrenta você e Arven juntos, então mantenha sua equipe preparada."], "TITAN - GREAT TUSK": ["Great Tusk é o Quaking Earth Titan em Pokémon Scarlet e está no nível 45. Ele é dos tipos Terra e Lutador e é vulnerável a Água, Planta, Gelo, Voador, Psíquico e Fada.", "Se escolheu Sprigatito ou Quaxly, Meowscarada ou Quaquaval pode usar golpes de Planta ou Água. Outra opção é Corviknight com golpes Voadores, a partir de Rookidee encontrado em Paldea.", "Great Tusk conhece Brick Break e Knock Off. Ele foge após a primeira fase e volta a lutar ao lado de Arven, então mantenha seus Pokémon recuperados."], "TITAN - DONDOZO E TATSUGIRI": ["O False Dragon Titan aparece em Casseroya Lake. Você enfrentará Dondozo no nível 56 e, depois de derrotá-lo, Tatsugiri no nível 57.", "Dondozo é do tipo Água e vulnerável a Elétrico e Planta. Tatsugiri é dos tipos Dragão e Água e vulnerável a Dragão e Fada. Golpes de Planta e Elétrico causam dano normal a Tatsugiri.", "Meowscarada pode enfrentar Dondozo com golpes de Planta se você escolheu Sprigatito. Bellibolt ou Pawmot pode usar golpes elétricos como alternativa.", "Contra Tatsugiri, Tinkaton pode usar golpes de Fada. Tinkatink aparece perto de ruínas e evolui para Tinkatuff no nível 24 e Tinkaton no nível 38.", "Dondozo conhece Aqua Tail e Tatsugiri usa Icy Wind e Muddy Water. Arven ajuda na segunda batalha contra Dondozo, mas Tatsugiri deve ser enfrentado em seguida, então mantenha a equipe saudável."], "PATH OF LEGENDS - ARVEN": ["Depois dos cinco Titãs, Arven desafia você em Poco Path. Ele usa Greedent no nível 58, Cloyster no 59, Scovillain no 60, Toedscruel no 61, Garganacl no 62 e Mabosstiff no 63.", "Greedent é vulnerável a Lutador. Cloyster é vulnerável a Elétrico, Planta, Lutador e Pedra. Scovillain é vulnerável a Voador, Pedra e Veneno, enquanto Toedscruel recebe quatro vezes mais dano de Gelo.", "Quaquaval, Hariyama ou Primeape pode usar golpes Lutadores contra Greedent, Cloyster, Garganacl e Mabosstiff. Tome cuidado com Psychic Fangs de Greedent e Mabosstiff e com os ataques de Cloyster.", "Corviknight pode usar golpes Voadores contra Scovillain e Toedscruel. Outra opção contra Toedscruel é Cetitan com golpes de Gelo. Toedscruel conhece Spore, que coloca o alvo para dormir.", "Garganacl é vulnerável a Água, Planta, Lutador, Terra e Metal. Mabosstiff Terastaliza para Sombrio e fica vulnerável a Lutador, Inseto e Fada, mas conhece Fire Fang e Play Rough. Cure sua equipe antes da batalha."], "TEAM STAR - GIACOMO": ["Giacomo usa Pawniard no nível 21 e o Segin Starmobile no nível 20. Pawniard é dos tipos Sombrio e Metal e recebe quatro vezes mais dano de Lutador. O Starmobile é do tipo Sombrio e vulnerável a Lutador, Inseto e Fada.", "Makuhita ou Mankey, encontrados na South Province, pode usar golpes Lutadores contra os dois. Tenha cuidado com Aerial Ace de Pawniard, que é superefetivo contra eles.", "O Starmobile possui Intimidate, que reduz o Ataque ao entrar em campo, e usa Wicked Torque. Mantenha a equipe recuperada após o desafio da base antes da batalha."], "TEAM STAR - MELA": ["Mela usa Torkoal no nível 27 e o Schedar Starmobile no nível 26. Ambos são do tipo Fogo e vulneráveis a Água, Terra e Pedra.", "Se escolheu Quaxly, Quaxwell pode usar golpes de Água. Outra opção é Naclstack, evolução de Nacli no nível 24, com golpes de Pedra.", "A habilidade Drought de Torkoal invoca sol, fortalecendo golpes de Fogo e enfraquecendo golpes de Água. O Starmobile possui Speed Boost, que aumenta sua Velocidade a cada turno.", "Tenha cuidado com Blazing Torque e Overheat e cure a equipe após enfrentar os Pokémon da base."], "TEAM STAR - ATTICUS": ["Atticus usa Skuntank e Muk no nível 32, Revavroom no nível 33 e o Navi Starmobile no nível 32.", "Skuntank é vulnerável apenas a Terra. Muk é vulnerável a Terra e Psíquico. Revavroom é dos tipos Metal e Veneno e recebe quatro vezes mais dano de Terra. O Starmobile é do tipo Veneno e vulnerável a Terra e Psíquico.", "Clodsire pode usar golpes de Terra contra os adversários. Wooper de Paldea aparece na South Province e evolui no nível 20. Mantenha cuidado com Bulldoze de Revavroom.", "Um Pokémon Psíquico pode ajudar contra Muk e o Starmobile, mas não deve enfrentar Skuntank com golpes Psíquicos, pois ele é imune por ser Sombrio.", "Skuntank pode usar Toxic e Venoshock, que causa dano maior em alvos envenenados. Leve itens para curar veneno e prepare-se para Noxious Torque do Starmobile."], "TEAM STAR - ORTEGA": ["Ortega usa Azumarill e Wigglytuff no nível 50, Dachsbun no nível 51 e o Ruchbah Starmobile no nível 50.", "Azumarill é vulnerável a Elétrico, Planta e Veneno. Wigglytuff, Dachsbun e o Starmobile são vulneráveis a Veneno e Metal.", "Tinkaton pode usar golpes de Metal contra Wigglytuff, Dachsbun e o Starmobile. Tinkatink aparece perto de ruínas e evolui para Tinkatuff no nível 24 e Tinkaton no 38.", "Clodsire pode usar golpes de Veneno contra Azumarill, mas deve tomar cuidado com Aqua Tail. Outra opção é Bellibolt com golpes elétricos.", "Azumarill possui Huge Power e pode causar muito dano físico. O Starmobile conhece Confuse Ray e usa Magical Torque. Leve itens de cura e mantenha a equipe saudável."], "TEAM STAR - ERI": ["Eri usa Toxicroak, Passimian e Lucario no nível 55, Annihilape no nível 56 e o Caph Starmobile no nível 56.", "Toxicroak recebe quatro vezes mais dano de Psíquico. Passimian é vulnerável a Voador, Psíquico e Fada. Lucario é vulnerável a Fogo, Lutador e Terra. Annihilape é vulnerável a Voador, Fantasma, Psíquico e Fada.", "Espathra pode usar golpes Psíquicos contra Toxicroak e Passimian. Flittle aparece em áreas de Paldea e evolui no nível 35, mas Toxicroak conhece Sucker Punch.", "Skeledirge pode usar Fogo contra Lucario. Corviknight pode usar Voador contra Passimian, mas cuidado com Rock Tomb e com Fire Punch de Annihilape.", "O Starmobile é do tipo Lutador e vulnerável a Voador, Psíquico e Fada. Sua habilidade Stamina aumenta a Defesa ao receber golpes, então ataques especiais podem ajudar. Cuidado com Combat Torque e Shift Gear."], "TEAM STAR - CLAVELL": ["Antes de enfrentar a líder da Team Star, você enfrenta Clavell. Ele usa Oranguru, Abomasnow e Polteageist no nível 60, além de outros dois Pokémon no nível 60 e um inicial no nível 61, que variam conforme sua escolha.", "Se você escolheu Sprigatito, Clavell usa Amoonguss, Gyarados e Skeledirge. Se escolheu Fuecoco, usa Houndoom, Amoonguss e Quaquaval. Se escolheu Quaxly, usa Gyarados, Houndoom e Meowscarada.", "Oranguru é vulnerável a Inseto e Sombrio. Abomasnow recebe quatro vezes mais dano de Fogo. Polteageist é vulnerável a Fantasma e Sombrio e pode aumentar seus atributos com Shell Smash.", "Use golpes elétricos contra Gyarados, que recebe quatro vezes mais dano, e golpes de Fogo contra Amoonguss. Contra Houndoom, golpes de Água, Terra, Pedra ou Lutador são eficazes.", "Clavell Terastaliza seu inicial. Quaquaval torna-se Água, Meowscarada torna-se Planta e Skeledirge torna-se Fogo. Prepare respostas para os novos tipos e cuidado com os demais golpes que eles conhecem."], "TEAM STAR - PENNY": ["Penny usa Umbreon, Vaporeon, Jolteon, Flareon e Leafeon no nível 62 e Sylveon no nível 63.", "Umbreon é vulnerável a Lutador, Inseto e Fada. Vaporeon é vulnerável a Elétrico e Planta. Jolteon é vulnerável a Terra. Flareon é vulnerável a Água, Terra e Pedra. Leafeon é vulnerável a Fogo, Gelo, Voador, Inseto e Veneno.", "Hariyama pode usar golpes Lutadores contra Umbreon, mas deve tomar cuidado com Psychic. Meowscarada ou Bellibolt pode enfrentar Vaporeon, observando Aurora Beam.", "Clodsire pode usar golpes de Terra contra Jolteon e Flareon. Contra Leafeon, Skeledirge ou Corviknight pode usar Fogo ou Voador. Flareon possui Flash Fire, portanto golpes de Fogo não são uma boa opção contra ele.", "Sylveon Terastaliza para Fada e é vulnerável a Veneno e Metal. Tinkaton pode usar golpes de Metal, enquanto Clodsire pode usar Veneno. Sylveon conhece Moonblast e Shadow Ball, então mantenha a equipe recuperada."]}'::jsonb, categorias = categorias || '{"TITAN - KLAWF": "path-of-legends", "TITAN - BOMBIRDIER": "path-of-legends", "TITAN - ORTHWORM": "path-of-legends", "TITAN - GREAT TUSK": "path-of-legends", "TITAN - DONDOZO E TATSUGIRI": "path-of-legends", "PATH OF LEGENDS - ARVEN": "path-of-legends", "TEAM STAR - GIACOMO": "starfall-street", "TEAM STAR - MELA": "starfall-street", "TEAM STAR - ATTICUS": "starfall-street", "TEAM STAR - ORTEGA": "starfall-street", "TEAM STAR - ERI": "starfall-street", "TEAM STAR - CLAVELL": "starfall-street", "TEAM STAR - PENNY": "starfall-street"}'::jsonb WHERE slug = 'pokemon-scarlet';
UPDATE public.builds SET caps = ARRAY(SELECT x FROM unnest(caps) x WHERE NOT x = ANY(ARRAY['TITAN - KLAWF','TITAN - BOMBIRDIER','TITAN - ORTHWORM','TITAN - IRON TREADS','TITAN - DONDOZO E TATSUGIRI','PATH OF LEGENDS - ARVEN','TEAM STAR - GIACOMO','TEAM STAR - MELA','TEAM STAR - ATTICUS','TEAM STAR - ORTEGA','TEAM STAR - ERI','TEAM STAR - CLAVELL','TEAM STAR - PENNY'])) || ARRAY['TITAN - KLAWF','TITAN - BOMBIRDIER','TITAN - ORTHWORM','TITAN - IRON TREADS','TITAN - DONDOZO E TATSUGIRI','PATH OF LEGENDS - ARVEN','TEAM STAR - GIACOMO','TEAM STAR - MELA','TEAM STAR - ATTICUS','TEAM STAR - ORTEGA','TEAM STAR - ERI','TEAM STAR - CLAVELL','TEAM STAR - PENNY'], dicas = dicas || '{"TITAN - KLAWF": ["Klawf é o Stony Cliff Titan na South Province Area Three e está no nível 16. Ele é do tipo Pedra e é vulnerável a Água, Planta, Lutador, Terra e Metal.", "Se escolheu Quaxly ou Sprigatito, use golpes de Água ou Planta. Outra opção é Makuhita, encontrado na South Province, com golpes Lutadores.", "Ao perder parte da vida, Klawf usa Anger Shell para aumentar Ataque, Ataque Especial e Velocidade, mas suas defesas diminuem. Cure seus Pokémon antes que ele consiga atacar novamente.", "Depois da primeira fase, Klawf foge e enfrenta você e Arven juntos. Mantenha sua equipe recuperada para a segunda batalha."], "TITAN - BOMBIRDIER": ["Bombirdier é o Open Sky Titan na West Province Area One e está no nível 20. Ele é dos tipos Voador e Sombrio e é vulnerável a Elétrico, Gelo, Pedra e Fada.", "Pawmi pode usar golpes elétricos e Nacli pode usar golpes de Pedra. Os dois podem ser encontrados na South Province. Pawmi evolui para Pawmo no nível 18.", "Se escolheu Quaxly ou Sprigatito, cuidado com os golpes Voadores de Bombirdier. Se escolheu Fuecoco, fique atento a Rock Throw.", "Após a primeira fase, Bombirdier foge e enfrenta você e Arven juntos. Sua habilidade Rocky Payload fortalece golpes de Pedra, então cuide de Pokémon vulneráveis a esse tipo."], "TITAN - ORTHWORM": ["Orthworm é o Lurking Steel Titan na East Province Area Three e está no nível 29. Ele é do tipo Metal e vulnerável a Fogo e Lutador.", "Orthworm possui Earth Eater, que o faz recuperar vida ao receber golpes de Terra. Portanto, use Fogo ou Lutador para explorar suas outras fraquezas.", "Se escolheu Fuecoco, Crocalor pode usar golpes de Fogo. Makuhita pode ser encontrado na South Province e evolui para Hariyama no nível 24, oferecendo uma opção Lutadora.", "Orthworm conhece Iron Tail e Wrap. Depois da primeira fase, ele enfrenta você e Arven juntos, então mantenha sua equipe preparada."], "TITAN - IRON TREADS": ["Iron Treads é o Quaking Earth Titan em Pokémon Violet e está no nível 45. Ele é dos tipos Terra e Metal e é vulnerável a Água, Fogo, Lutador e Terra.", "Se escolheu Quaxly ou Fuecoco, Quaquaval pode usar Água ou Lutador e Skeledirge pode usar Fogo. Hariyama também pode ajudar com golpes Lutadores.", "Iron Treads conhece Iron Head e Knock Off. Ele foge após a primeira fase e volta a lutar ao lado de Arven, então mantenha seus Pokémon recuperados."], "TITAN - DONDOZO E TATSUGIRI": ["O False Dragon Titan aparece em Casseroya Lake. Você enfrentará Dondozo no nível 56 e, depois de derrotá-lo, Tatsugiri no nível 57.", "Dondozo é do tipo Água e vulnerável a Elétrico e Planta. Tatsugiri é dos tipos Dragão e Água e vulnerável a Dragão e Fada. Golpes de Planta e Elétrico causam dano normal a Tatsugiri.", "Meowscarada pode enfrentar Dondozo com golpes de Planta se você escolheu Sprigatito. Bellibolt ou Pawmot pode usar golpes elétricos como alternativa.", "Contra Tatsugiri, Tinkaton pode usar golpes de Fada. Tinkatink aparece perto de ruínas e evolui para Tinkatuff no nível 24 e Tinkaton no nível 38.", "Dondozo conhece Aqua Tail e Tatsugiri usa Icy Wind e Muddy Water. Arven ajuda na segunda batalha contra Dondozo, mas Tatsugiri deve ser enfrentado em seguida, então mantenha a equipe saudável."], "PATH OF LEGENDS - ARVEN": ["Depois dos cinco Titãs, Arven desafia você em Poco Path. Ele usa Greedent no nível 58, Cloyster no 59, Scovillain no 60, Toedscruel no 61, Garganacl no 62 e Mabosstiff no 63.", "Greedent é vulnerável a Lutador. Cloyster é vulnerável a Elétrico, Planta, Lutador e Pedra. Scovillain é vulnerável a Voador, Pedra e Veneno, enquanto Toedscruel recebe quatro vezes mais dano de Gelo.", "Quaquaval, Hariyama ou Primeape pode usar golpes Lutadores contra Greedent, Cloyster, Garganacl e Mabosstiff. Tome cuidado com Psychic Fangs de Greedent e Mabosstiff e com os ataques de Cloyster.", "Corviknight pode usar golpes Voadores contra Scovillain e Toedscruel. Outra opção contra Toedscruel é Cetitan com golpes de Gelo. Toedscruel conhece Spore, que coloca o alvo para dormir.", "Garganacl é vulnerável a Água, Planta, Lutador, Terra e Metal. Mabosstiff Terastaliza para Sombrio e fica vulnerável a Lutador, Inseto e Fada, mas conhece Fire Fang e Play Rough. Cure sua equipe antes da batalha."], "TEAM STAR - GIACOMO": ["Giacomo usa Pawniard no nível 21 e o Segin Starmobile no nível 20. Pawniard é dos tipos Sombrio e Metal e recebe quatro vezes mais dano de Lutador. O Starmobile é do tipo Sombrio e vulnerável a Lutador, Inseto e Fada.", "Makuhita ou Mankey, encontrados na South Province, pode usar golpes Lutadores contra os dois. Tenha cuidado com Aerial Ace de Pawniard, que é superefetivo contra eles.", "O Starmobile possui Intimidate, que reduz o Ataque ao entrar em campo, e usa Wicked Torque. Mantenha a equipe recuperada após o desafio da base antes da batalha."], "TEAM STAR - MELA": ["Mela usa Torkoal no nível 27 e o Schedar Starmobile no nível 26. Ambos são do tipo Fogo e vulneráveis a Água, Terra e Pedra.", "Se escolheu Quaxly, Quaxwell pode usar golpes de Água. Outra opção é Naclstack, evolução de Nacli no nível 24, com golpes de Pedra.", "A habilidade Drought de Torkoal invoca sol, fortalecendo golpes de Fogo e enfraquecendo golpes de Água. O Starmobile possui Speed Boost, que aumenta sua Velocidade a cada turno.", "Tenha cuidado com Blazing Torque e Overheat e cure a equipe após enfrentar os Pokémon da base."], "TEAM STAR - ATTICUS": ["Atticus usa Skuntank e Muk no nível 32, Revavroom no nível 33 e o Navi Starmobile no nível 32.", "Skuntank é vulnerável apenas a Terra. Muk é vulnerável a Terra e Psíquico. Revavroom é dos tipos Metal e Veneno e recebe quatro vezes mais dano de Terra. O Starmobile é do tipo Veneno e vulnerável a Terra e Psíquico.", "Clodsire pode usar golpes de Terra contra os adversários. Wooper de Paldea aparece na South Province e evolui no nível 20. Mantenha cuidado com Bulldoze de Revavroom.", "Um Pokémon Psíquico pode ajudar contra Muk e o Starmobile, mas não deve enfrentar Skuntank com golpes Psíquicos, pois ele é imune por ser Sombrio.", "Skuntank pode usar Toxic e Venoshock, que causa dano maior em alvos envenenados. Leve itens para curar veneno e prepare-se para Noxious Torque do Starmobile."], "TEAM STAR - ORTEGA": ["Ortega usa Azumarill e Wigglytuff no nível 50, Dachsbun no nível 51 e o Ruchbah Starmobile no nível 50.", "Azumarill é vulnerável a Elétrico, Planta e Veneno. Wigglytuff, Dachsbun e o Starmobile são vulneráveis a Veneno e Metal.", "Tinkaton pode usar golpes de Metal contra Wigglytuff, Dachsbun e o Starmobile. Tinkatink aparece perto de ruínas e evolui para Tinkatuff no nível 24 e Tinkaton no 38.", "Clodsire pode usar golpes de Veneno contra Azumarill, mas deve tomar cuidado com Aqua Tail. Outra opção é Bellibolt com golpes elétricos.", "Azumarill possui Huge Power e pode causar muito dano físico. O Starmobile conhece Confuse Ray e usa Magical Torque. Leve itens de cura e mantenha a equipe saudável."], "TEAM STAR - ERI": ["Eri usa Toxicroak, Passimian e Lucario no nível 55, Annihilape no nível 56 e o Caph Starmobile no nível 56.", "Toxicroak recebe quatro vezes mais dano de Psíquico. Passimian é vulnerável a Voador, Psíquico e Fada. Lucario é vulnerável a Fogo, Lutador e Terra. Annihilape é vulnerável a Voador, Fantasma, Psíquico e Fada.", "Espathra pode usar golpes Psíquicos contra Toxicroak e Passimian. Flittle aparece em áreas de Paldea e evolui no nível 35, mas Toxicroak conhece Sucker Punch.", "Skeledirge pode usar Fogo contra Lucario. Corviknight pode usar Voador contra Passimian, mas cuidado com Rock Tomb e com Fire Punch de Annihilape.", "O Starmobile é do tipo Lutador e vulnerável a Voador, Psíquico e Fada. Sua habilidade Stamina aumenta a Defesa ao receber golpes, então ataques especiais podem ajudar. Cuidado com Combat Torque e Shift Gear."], "TEAM STAR - CLAVELL": ["Antes de enfrentar a líder da Team Star, você enfrenta Clavell. Ele usa Oranguru, Abomasnow e Polteageist no nível 60, além de outros dois Pokémon no nível 60 e um inicial no nível 61, que variam conforme sua escolha.", "Se você escolheu Sprigatito, Clavell usa Amoonguss, Gyarados e Skeledirge. Se escolheu Fuecoco, usa Houndoom, Amoonguss e Quaquaval. Se escolheu Quaxly, usa Gyarados, Houndoom e Meowscarada.", "Oranguru é vulnerável a Inseto e Sombrio. Abomasnow recebe quatro vezes mais dano de Fogo. Polteageist é vulnerável a Fantasma e Sombrio e pode aumentar seus atributos com Shell Smash.", "Use golpes elétricos contra Gyarados, que recebe quatro vezes mais dano, e golpes de Fogo contra Amoonguss. Contra Houndoom, golpes de Água, Terra, Pedra ou Lutador são eficazes.", "Clavell Terastaliza seu inicial. Quaquaval torna-se Água, Meowscarada torna-se Planta e Skeledirge torna-se Fogo. Prepare respostas para os novos tipos e cuidado com os demais golpes que eles conhecem."], "TEAM STAR - PENNY": ["Penny usa Umbreon, Vaporeon, Jolteon, Flareon e Leafeon no nível 62 e Sylveon no nível 63.", "Umbreon é vulnerável a Lutador, Inseto e Fada. Vaporeon é vulnerável a Elétrico e Planta. Jolteon é vulnerável a Terra. Flareon é vulnerável a Água, Terra e Pedra. Leafeon é vulnerável a Fogo, Gelo, Voador, Inseto e Veneno.", "Hariyama pode usar golpes Lutadores contra Umbreon, mas deve tomar cuidado com Psychic. Meowscarada ou Bellibolt pode enfrentar Vaporeon, observando Aurora Beam.", "Clodsire pode usar golpes de Terra contra Jolteon e Flareon. Contra Leafeon, Skeledirge ou Corviknight pode usar Fogo ou Voador. Flareon possui Flash Fire, portanto golpes de Fogo não são uma boa opção contra ele.", "Sylveon Terastaliza para Fada e é vulnerável a Veneno e Metal. Tinkaton pode usar golpes de Metal, enquanto Clodsire pode usar Veneno. Sylveon conhece Moonblast e Shadow Ball, então mantenha a equipe recuperada."]}'::jsonb, categorias = categorias || '{"TITAN - KLAWF": "path-of-legends", "TITAN - BOMBIRDIER": "path-of-legends", "TITAN - ORTHWORM": "path-of-legends", "TITAN - IRON TREADS": "path-of-legends", "TITAN - DONDOZO E TATSUGIRI": "path-of-legends", "PATH OF LEGENDS - ARVEN": "path-of-legends", "TEAM STAR - GIACOMO": "starfall-street", "TEAM STAR - MELA": "starfall-street", "TEAM STAR - ATTICUS": "starfall-street", "TEAM STAR - ORTEGA": "starfall-street", "TEAM STAR - ERI": "starfall-street", "TEAM STAR - CLAVELL": "starfall-street", "TEAM STAR - PENNY": "starfall-street"}'::jsonb WHERE slug = 'pokemon-violet';

-- Builds iniciais de Yellow, Let's Go e Crystal, copiadas das versões correspondentes.
UPDATE public.builds AS destino
SET caps = origem.caps, dicas = origem.dicas
FROM public.builds AS origem
WHERE ((destino.slug IN ('pokemon-yellow', 'pokemon-let-s-go-pikachu', 'pokemon-let-s-go-eevee') AND origem.slug = 'pokemon-blue')
    OR (destino.slug = 'pokemon-crystal' AND origem.slug = 'pokemon-gold'))
  AND cardinality(destino.caps) = 0;

-- Estratégias adaptadas para Pokémon Crystal.
UPDATE public.builds SET caps = ARRAY['1º GYM - FALKNER','2º GYM - BUGSY','3º GYM - WHITNEY','4º GYM - MORTY','5º GYM - CHUCK','6º GYM - JASMINE','7º GYM - PRYCE','8º GYM - CLAIR','ELITE FOUR - WILL','ELITE FOUR - KOGA','ELITE FOUR - BRUNO','ELITE FOUR - KAREN','CHAMPION'], dicas = '{"1º GYM - FALKNER": ["Falkner usa dois Pokémon dos tipos Normal e Voador. Seu time começa com Pidgey no nível 7 e termina com Pidgeotto no nível 9.", "Os dois recebem dano superefetivo de golpes dos tipos Elétrico, Gelo e Pedra.", "Independentemente do inicial escolhido, capture um Geodude na Dark Cave e treine-o até o nível 11 para aprender Rock Throw. O golpe tem vantagem contra os dois Pokémon de Falkner.", "Outra opção é o Onix recebido em troca de um Bellsprout em Violet City. Bellsprout aparece na Route 31 e Onix aprende Rock Throw no nível 14.", "Se você escolheu Chikorita, tenha cuidado com Gust de Pidgeotto, que é superefetivo contra Pokémon de Planta. Geodude pode ajudar a enfrentar os dois adversários.", "Se você escolheu Cyndaquil ou Totodile, também pode usá-los na luta. Mantenha atenção à vida deles e use Geodude para aproveitar a fraqueza dos adversários.", "Tenha cuidado com Mud-Slap, que causa dano e reduz a precisão do seu Pokémon. O golpe é especialmente perigoso para Geodude e Cyndaquil, pois os dois são vulneráveis ao tipo Terra.", "Antes da batalha, cure sua equipe e leve algumas Potions para se preparar caso precise recuperar seus Pokémon."], "2º GYM - BUGSY": ["Bugsy usa três Pokémon do tipo Inseto. Seu time começa com Metapod no nível 14, seguido de Kakuna no nível 14 e termina com Scyther no nível 16.", "Os três recebem dano superefetivo de golpes dos tipos Fogo, Voador e Pedra. Scyther também é do tipo Voador, então recebe quatro vezes mais dano de golpes de Pedra.", "Se você escolheu Cyndaquil, treine-o até aprender Ember no nível 12 e use o golpe contra toda a equipe de Bugsy. No nível 14, ele evolui para Quilava, ficando ainda mais preparado para a batalha.", "Se você escolheu Totodile ou Chikorita, uma boa opção é o Geodude que pode ter sido treinado para enfrentar Falkner. Use Rock Throw contra os três adversários, principalmente Scyther.", "Se preferir outro Pokémon, Onix pode ser encontrado na Union Cave ou recebido em troca de um Bellsprout em uma casa de Violet City. Treine-o até aprender Rock Throw no nível 14 para enfrentar a equipe de Bugsy.", "Se você escolheu Chikorita, tenha cuidado especial com Scyther. Seu golpe Fury Cutter é superefetivo contra Chikorita e fica mais forte a cada acerto consecutivo.", "Mesmo com os outros iniciais, não subestime Fury Cutter. Procure derrotar Scyther rapidamente e mantenha sua equipe com bastante vida. Kakuna também pode envenenar seus Pokémon com Poison Sting.", "Antes da batalha, cure sua equipe e leve algumas Potions e Antidotes para se preparar caso precise recuperar seus Pokémon."], "3º GYM - WHITNEY": ["Whitney usa dois Pokémon do tipo Normal. Seu time começa com Clefairy no nível 18 e termina com a temida Miltank no nível 20.", "As duas recebem dano superefetivo de golpes do tipo Lutador, então essa será a melhor opção para a batalha.", "Independentemente do inicial escolhido, capture um Abra na Route 34 e troque-o por um Machop no Goldenrod Department Store. Use os golpes do tipo Lutador de Machop contra Clefairy e Miltank.", "O Machop recebido nessa troca é fêmea, então não será afetado pelo Attract da Miltank. Treine-o antes de entrar no ginásio para aumentar suas chances de resistir aos ataques.", "Se você treinou Geodude ou Onix para enfrentar os líderes anteriores, eles também podem ajudar contra Miltank. Os dois resistem a Stomp e Rollout, mas ainda podem sofrer bastante dano se Rollout acertar vários turnos seguidos.", "Seu inicial também pode participar da batalha, seja Quilava, Croconaw ou Bayleef, mas tenha cuidado ao deixá-lo enfrentar Miltank por muito tempo, principalmente se for macho e for afetado por Attract.", "O maior perigo é Rollout, que fica mais forte a cada acerto consecutivo. Miltank também usa Milk Drink para recuperar vida e Stomp, que pode fazer seu Pokémon perder o turno. Já Attract pode impedir Pokémon machos de atacar.", "Antes da batalha, cure sua equipe e leve algumas Potions. Procure manter Machop com bastante vida e derrotar Miltank antes que Rollout acumule muito dano."], "4º GYM - MORTY": ["Morty usa quatro Pokémon dos tipos Fantasma e Veneno. Seu time começa com Gastly no nível 21, seguido de Haunter no nível 21, Gengar no nível 25 e outro Haunter no nível 23.", "Os quatro recebem dano superefetivo de golpes dos tipos Fantasma, Sombrio, Psíquico e Terra. Eles também são imunes a golpes dos tipos Normal e Lutador.", "Se você escolheu Totodile, ele já pode ter evoluído para Croconaw. Treine-o até aprender Bite no nível 21 e use o golpe do tipo Sombrio contra toda a equipe de Morty.", "Se você escolheu Cyndaquil ou Chikorita, uma opção é capturar um Drowzee na Route 34 e treiná-lo até aprender Confusion no nível 18. O golpe Psíquico é superefetivo contra todos os Pokémon de Morty por causa do tipo Veneno deles.", "Se você treinou Geodude ou Onix, também pode usar Magnitude ou outro golpe do tipo Terra que eles conheçam. Em Crystal, Gastly, Haunter e Gengar ainda não possuem a habilidade Levitate, então podem ser atingidos por esses golpes.", "Tenha muito cuidado com o Gengar de Morty. Ele pode usar Hypnosis para colocar seu Pokémon para dormir e depois atacar com Dream Eater. Gengar também conhece Shadow Ball, que causa bastante dano e é superefetivo contra Drowzee.", "Gastly e um dos Haunter também podem usar Curse, que retira parte da vida do seu Pokémon a cada turno. Se for atingido, troque de Pokémon para remover o efeito.", "Antes da batalha, cure sua equipe e leve algumas Potions e Awakenings para acordar seus Pokémon caso sejam atingidos por Hypnosis."], "5º GYM - CHUCK": ["Chuck usa dois Pokémon do tipo Lutador. Seu time começa com Primeape no nível 27 e termina com Poliwrath no nível 30, que também é do tipo Água.", "Os dois recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Poliwrath também é vulnerável a golpes dos tipos Elétrico e Planta por causa do seu tipo Água.", "Se você escolheu Chikorita, ela já pode ter evoluído para Bayleef. Use Razor Leaf contra Poliwrath para aproveitar sua fraqueza ao tipo Planta.", "Se você escolheu Cyndaquil ou Totodile, uma opção contra Poliwrath é Magnemite com golpes elétricos. Ele pode ser encontrado na Route 38, a oeste de Ecruteak City, antes da viagem a Cianwood.", "Independentemente do inicial escolhido, você pode usar Drowzee ou Hypno com Confusion contra os dois Pokémon de Chuck. Drowzee pode ser encontrado na Route 34, aprende Confusion no nível 18 e evolui para Hypno no nível 26.", "Se você treinou um Pidgey ou Hoothoot, eles também podem ajudar depois de evoluir para Pidgeotto ou Noctowl. Use golpes do tipo Voador, como Gust ou Peck, contra Primeape e Poliwrath.", "Tenha cuidado com Hypnosis de Poliwrath, que pode colocar seu Pokémon para dormir. Ele também pode combinar Mind Reader com DynamicPunch, garantindo o acerto do próximo golpe. DynamicPunch causa bastante dano e deixa o alvo confuso quando acerta.", "Antes da batalha, cure sua equipe e leve algumas Potions, Awakenings e itens para curar confusão."], "6º GYM - JASMINE": ["Jasmine usa três Pokémon do tipo Aço. Seu time começa com dois Magnemite no nível 30 e termina com Steelix no nível 35.", "Os dois Magnemite também são do tipo Elétrico e recebem quatro vezes mais dano de golpes do tipo Terra. Steelix também é do tipo Terra e é vulnerável a golpes dos tipos Água, Fogo, Lutador e Terra.", "Se você escolheu Cyndaquil, ele já pode ter evoluído para Quilava. Use seus golpes do tipo Fogo contra os dois Magnemite e Steelix, mas tenha cuidado com o Rock Throw de Steelix.", "Se você escolheu Totodile, seu Croconaw pode usar Surf contra Steelix. Evite colocá-lo contra os Magnemite, pois os dois conhecem Thunderbolt e têm vantagem contra Pokémon de Água.", "Se você escolheu Chikorita, pode capturar um Tentacool ou Tentacruel enquanto atravessa o mar entre Olivine e Cianwood. Ensine Surf a um deles e use o golpe contra Steelix. Tome cuidado com os Magnemite, pois seus golpes elétricos são superefetivos contra Pokémon de Água.", "Independentemente do inicial escolhido, Geodude ou Graveler com Magnitude são boas opções contra toda a equipe. Os golpes do tipo Terra causam quatro vezes mais dano aos Magnemite, e Geodude pode ser encontrado na Dark Cave ou na Union Cave.", "O Machop recebido em troca de um Abra no Goldenrod Department Store também pode enfrentar os três adversários com golpes do tipo Lutador. Se você o treinou até o nível 28, ele já terá evoluído para Machoke.", "Outra opção é Heracross com Rock Smash. Ele pode ser encontrado usando Headbutt em árvores e aprende o golpe Lutador pela TM08, recebida na Route 36 depois de remover Sudowoodo. Rock Smash é superefetivo contra os três Pokémon de Jasmine, mas tem pouca potência, então mantenha atenção à vida de Heracross.", "Tenha cuidado com Thunder Wave e Supersonic dos Magnemite, que podem paralisar e confundir sua equipe. Steelix pode usar Screech para reduzir a Defesa do seu Pokémon e depois atacar com Iron Tail ou Rock Throw.", "Steelix também pode usar Sunny Day, que fortalece golpes de Fogo e enfraquece golpes de Água. Se isso acontecer, seus golpes de Surf causarão menos dano por alguns turnos.", "Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals para se preparar."], "7º GYM - PRYCE": ["Pryce é especialista no tipo Gelo. Seu time começa com Seel no nível 27, seguido de Dewgong no nível 29 e termina com Piloswine no nível 31. Seel é do tipo Água, Dewgong é dos tipos Água e Gelo, e Piloswine é dos tipos Gelo e Terra.", "Seel e Dewgong recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Dewgong também é vulnerável a golpes do tipo Lutador, assim como Piloswine, que também recebe dano superefetivo de golpes dos tipos Água, Fogo e Planta.", "Se você escolheu Totodile, seu Croconaw ou Feraligatr pode usar Surf contra Piloswine. Contra Seel e Dewgong, prefira um Pokémon com golpes elétricos ou de Planta.", "Se você escolheu Cyndaquil, seu Quilava ou Typhlosion pode usar golpes do tipo Fogo contra Dewgong e Piloswine. Tenha cuidado contra Seel e Dewgong, pois os dois são do tipo Água e resistem aos golpes de Fogo.", "Se você escolheu Chikorita, seu Bayleef ou Meganium pode usar golpes de Planta contra os três adversários. Contudo, tenha muito cuidado com os golpes de Gelo da equipe de Pryce, que são superefetivos contra Pokémon de Planta.", "Se você capturou Magnemite na Route 38, seu Magneton pode usar golpes elétricos contra Seel e Dewgong. Não use esses golpes contra Piloswine, pois ele é do tipo Terra e imune a ataques elétricos.", "Heracross com Rock Smash pode enfrentar Dewgong e Piloswine com um golpe do tipo Lutador. Ele pode ser encontrado usando Headbutt nas árvores depois de receber a TM02 na Ilex Forest. A TM08 Rock Smash é recebida na Route 36 depois de capturar ou derrotar Sudowoodo.", "Rock Smash tem pouca potência em Crystal, então mantenha atenção à vida de Heracross e não conte com uma vitória rápida. Outra opção é o Machop ou Machoke recebido em Goldenrod por um Abra, que pode usar golpes Lutadores contra Dewgong e Piloswine.", "Tenha cuidado com Icy Wind, que causa dano e reduz a Velocidade, e com Blizzard de Piloswine, que pode causar bastante dano e congelar seu Pokémon. Dewgong também pode usar Rest para recuperar vida.", "Antes da batalha, cure sua equipe e leve algumas Potions e Ice Heals para se preparar."], "8º GYM - CLAIR": ["Clair é especialista no tipo Dragão. Seu time começa com três Dragonair no nível 37 e termina com Kingdra no nível 40, que é dos tipos Água e Dragão.", "Os três Dragonair recebem dano superefetivo de golpes dos tipos Gelo e Dragão. Kingdra, por ser dos tipos Água e Dragão, recebe dano superefetivo apenas de golpes do tipo Dragão em Crystal.", "Independentemente do inicial escolhido, uma ótima opção contra os três Dragonair é Lapras com Ice Beam. Ele pode ser encontrado no andar mais profundo da Union Cave às sextas-feiras, depois que você conseguir usar Surf, e aprende Ice Beam no nível 36.", "Se você capturou o Gyarados vermelho no Lake of Rage, pode treiná-lo até aprender Twister no nível 35. O golpe do tipo Dragão é superefetivo contra toda a equipe de Clair, incluindo Kingdra, mas tenha cuidado com o Dragonair que conhece Thunderbolt.", "Seu inicial também pode ajudar contra Kingdra com golpes que causem bastante dano. Seja Typhlosion, Feraligatr ou Meganium, mantenha atenção à vida dele e prepare outro Pokémon caso precise trocar durante a batalha.", "Tenha cuidado com os três Dragonair, pois cada um conhece um golpe diferente entre Surf, Thunderbolt e Ice Beam. Os três também podem usar Thunder Wave para paralisar sua equipe.", "O Kingdra de Clair pode usar Smokescreen para reduzir a precisão dos seus golpes e DragonBreath, que também pode causar paralisia. Ele conhece Hyper Beam, um golpe muito forte que exige um turno de descanso depois de ser usado.", "Antes da batalha, cure sua equipe e leve algumas Potions e Parlyz Heals. Se a precisão do seu Pokémon cair muito, considere trocá-lo para remover a redução antes de continuar atacando."], "ELITE FOUR - WILL": ["Will é o primeiro integrante da Elite Four e usa Pokémon do tipo Psíquico. Seu time começa com Xatu no nível 40, seguido de Jynx no nível 41, Exeggutor no nível 41, Slowbro no nível 41 e outro Xatu no nível 42.", "Todos recebem dano superefetivo de golpes dos tipos Sombrio e Fantasma. Os dois Xatu e Slowbro também são vulneráveis ao tipo Elétrico, enquanto Jynx e Exeggutor são vulneráveis ao tipo Fogo.", "Independentemente do inicial escolhido, Umbreon com Shadow Ball é uma boa opção contra toda a equipe. Para obtê-lo, encontre Bill no Pokémon Center de Ecruteak e depois visite sua casa em Goldenrod para receber um Eevee. Aumente a amizade de Eevee e faça-o subir de nível durante a noite para evoluí-lo em Umbreon.", "A TM30 Shadow Ball é recebida ao derrotar Morty e pode ser ensinada a Umbreon. Por ser do tipo Sombrio, ele também é imune aos golpes Psíquicos da equipe de Will.", "O Gyarados vermelho, encontrado no Lake of Rage, também pode enfrentar os cinco adversários com Bite, caso ainda conheça o golpe. Tenha cuidado com o Ice Punch de Jynx e mantenha a vida de Gyarados alta durante a luta.", "Magnemite ou Magneton pode usar golpes elétricos contra os dois Xatu e Slowbro. Magnemite pode ser encontrado na Route 38 e evolui para Magneton no nível 30.", "Se você escolheu Cyndaquil, seu Typhlosion pode usar golpes de Fogo contra Jynx e Exeggutor. Caso tenha escolhido Totodile ou Chikorita, outro Pokémon com golpes de Fogo também pode enfrentar os dois.", "Se você capturou Lapras na Union Cave, ele pode usar Ice Beam contra os dois Xatu e Exeggutor. Lapras aprende o golpe no nível 36, mas tenha cuidado com os ataques Psíquicos e com a confusão causada por Xatu.", "Tenha cuidado com Lovely Kiss de Jynx, que pode colocar seu Pokémon para dormir, e com Confuse Ray dos Xatu. Slowbro também pode usar Amnesia para aumentar sua Defesa Especial e resistir melhor a golpes como Thunderbolt e Bite.", "Antes da batalha, cure sua equipe e prepare itens de recuperação. Depois de vencer Will, aproveite para recuperar seus Pokémon antes de seguir para Koga."], "ELITE FOUR - KOGA": ["Koga é o segundo integrante da Elite Four e usa principalmente Pokémon dos tipos Veneno e Inseto. Seu time começa com Ariados no nível 40, seguido de Venomoth no nível 41, Forretress no nível 43, Muk no nível 42 e Crobat no nível 44.", "Ariados, Venomoth, Muk e Crobat recebem dano superefetivo de golpes do tipo Psíquico. Forretress é dos tipos Inseto e Aço e recebe quatro vezes mais dano de golpes do tipo Fogo.", "Se você escolheu Cyndaquil, seu Typhlosion pode usar golpes de Fogo contra Ariados, Venomoth e Forretress. Procure derrotar Forretress rapidamente para evitar que ele use Explosion.", "Se você escolheu Totodile ou Chikorita, também pode preparar um Pokémon com golpes de Fogo para enfrentar esses três adversários. Contra Forretress, essa é a opção que mais aproveita sua fraqueza.", "Drowzee ou Hypno com Confusion podem enfrentar Ariados, Venomoth, Muk e Crobat. Drowzee pode ser capturado na Route 34, aprende Confusion no nível 18 e evolui para Hypno no nível 26. Tenha cuidado com Psychic de Venomoth, que também pode causar bastante dano ao seu Pokémon Psíquico.", "Se você capturou Geodude e o evoluiu para Graveler, pode usar golpes do tipo Terra, como Magnitude, contra Muk. Evite esses golpes contra Crobat, pois ele também é do tipo Voador e não pode ser atingido por ataques de Terra.", "Para enfrentar Crobat, você também pode usar Magneton com golpes elétricos ou Lapras com Ice Beam. Magnemite pode ser encontrado na Route 38 e evolui no nível 30.", "Tenha muito cuidado com Explosion de Forretress, que pode causar dano suficiente para derrotar seu Pokémon de uma vez. Venomoth, Muk e Crobat também podem usar Toxic, que envenena gravemente e causa cada vez mais dano a cada turno.", "Antes da batalha, cure sua equipe e prepare Potions e Antidotes. Depois de vencer Koga, aproveite para recuperar seus Pokémon antes de seguir para Bruno."], "ELITE FOUR - BRUNO": ["Bruno é o terceiro integrante da Elite Four e usa principalmente Pokémon do tipo Lutador. Seu time começa com Hitmontop no nível 42, seguido de Hitmonlee no nível 42, Hitmonchan no nível 42, Onix no nível 43 e Machamp no nível 46.", "Hitmontop, Hitmonlee, Hitmonchan e Machamp recebem dano superefetivo de golpes dos tipos Psíquico e Voador. Onix é dos tipos Pedra e Terra e recebe quatro vezes mais dano de golpes dos tipos Água e Planta.", "Independentemente do inicial escolhido, Drowzee ou Hypno com Confusion podem enfrentar os quatro Pokémon Lutadores. Drowzee pode ser capturado na Route 34 e evolui para Hypno no nível 26.", "Se você recebeu o Eevee de Bill e o evoluiu para Espeon, ele também é uma boa opção contra os quatro Lutadores com Psybeam, aprendido no nível 36. Para obter Espeon, aumente a amizade de Eevee e faça-o subir de nível durante o dia.", "Pokémon voadores, como Pidgeot ou Noctowl, também podem usar golpes do tipo Voador contra os Lutadores. Tenha cuidado ao enfrentar Hitmonchan e Machamp, pois eles conhecem golpes que são superefetivos contra Pokémon voadores.", "Se você escolheu Totodile, use seu Feraligatr com Surf contra Onix. Se escolheu Chikorita, seu Meganium pode enfrentá-lo com golpes do tipo Planta, como Razor Leaf.", "Se você escolheu Cyndaquil, pode usar Lapras ou Gyarados com Surf contra Onix. Lapras pode ser encontrado na Union Cave às sextas-feiras, enquanto o Gyarados vermelho pode ser capturado no Lake of Rage.", "Tenha cuidado com Ice Punch e ThunderPunch de Hitmonchan e com Rock Slide de Machamp, que podem causar bastante dano aos seus Pokémon voadores. Hitmontop também conhece Pursuit, um golpe do tipo Sombrio que pode atingir seus Pokémon Psíquicos com vantagem.", "O golpe Cross Chop de Machamp causa bastante dano e tem uma chance maior de acerto crítico, então mantenha seu Pokémon com bastante vida ao enfrentá-lo.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para a próxima integrante da Elite Four, Karen."], "ELITE FOUR - KAREN": ["Karen é a última integrante da Elite Four e usa principalmente Pokémon do tipo Sombrio. Seu time começa com Umbreon no nível 42, seguido de Vileplume no nível 42, Gengar no nível 45, Murkrow no nível 44 e Houndoom no nível 47.", "Umbreon e Houndoom recebem dano superefetivo de golpes do tipo Lutador. Vileplume é vulnerável aos tipos Fogo, Gelo, Voador e Psíquico, enquanto Gengar recebe dano superefetivo de golpes dos tipos Terra, Psíquico, Fantasma e Sombrio. Murkrow é vulnerável aos tipos Elétrico, Gelo e Pedra.", "Independentemente do inicial escolhido, você pode usar Machoke ou Heracross com golpes do tipo Lutador contra Umbreon. Em Crystal, Machop pode ser recebido em troca de um Abra no Goldenrod Department Store e evolui para Machoke no nível 28.", "Heracross pode ser encontrado usando Headbutt nas árvores e aprender Rock Smash pela TM08. Ele também tem vantagem contra Houndoom com esse golpe, mas tenha muito cuidado, pois Houndoom conhece Flamethrower, que causa quatro vezes mais dano a Heracross por ele ser dos tipos Inseto e Lutador.", "Se você escolheu Cyndaquil, seu Typhlosion pode usar golpes do tipo Fogo contra Vileplume. Outra opção é Lapras com Ice Beam, que também pode enfrentar Murkrow com golpes de Gelo.", "Contra Gengar, você pode usar Hypno com Confusion ou Graveler com Magnitude. Drowzee pode ser capturado na Route 34 e evolui para Hypno no nível 26, enquanto Geodude pode ser encontrado na Dark Cave ou Union Cave e evolui para Graveler no nível 25.", "Para enfrentar Murkrow, use Magneton com golpes elétricos. Magnemite pode ser encontrado na Route 38 e evolui para Magneton no nível 30.", "Contra Houndoom, Feraligatr, Lapras ou Gyarados com Surf são boas opções. Se você escolheu Cyndaquil ou Chikorita, Lapras pode ser encontrado na Union Cave às sextas-feiras e o Gyarados vermelho pode ser capturado no Lake of Rage.", "Tenha muito cuidado com Destiny Bond de Gengar. Se ele usar o golpe e for derrotado antes de realizar sua próxima ação, também levará seu Pokémon junto. Nessa situação, use um golpe que não cause dano e espere Gengar agir novamente antes de atacá-lo.", "Umbreon também pode usar Confuse Ray e Mean Look para confundir seu Pokémon e impedir que ele seja trocado. Já Houndoom conhece Flamethrower e Crunch, dois golpes fortes que podem causar bastante dano.", "Depois da vitória, recupere sua equipe e prepare seus Pokémon para a última batalha da Liga, contra o Champion Lance."], "CHAMPION": ["Lance é o Champion da Liga e especialista no tipo Dragão. Seu time começa com Gyarados no nível 44, seguido de dois Dragonite no nível 47, Aerodactyl no nível 46, Charizard no nível 46 e outro Dragonite no nível 50.", "Gyarados recebe quatro vezes mais dano de golpes do tipo Elétrico, enquanto os três Dragonite recebem quatro vezes mais dano de golpes do tipo Gelo. Charizard recebe quatro vezes mais dano de golpes do tipo Pedra, e Aerodactyl é vulnerável aos tipos Água, Elétrico, Gelo e Pedra.", "Independentemente do inicial escolhido, Magneton com golpes elétricos é uma ótima opção contra Gyarados. Magnemite pode ser encontrado na Route 38 e evolui no nível 30. Magneton também pode enfrentar Aerodactyl e Charizard, mas deve tomar cuidado com Flamethrower de Charizard.", "Contra os três Dragonite, uma ótima opção é Lapras com Ice Beam. Ele pode ser encontrado no andar mais profundo da Union Cave às sextas-feiras e aprende Ice Beam no nível 36.", "Outra opção é Piloswine com golpes de Gelo. Você pode capturar um Swinub na Ice Path e treiná-lo até o nível 33 para evoluí-lo. Por também ser do tipo Terra, Piloswine é imune ao Thunder de um dos Dragonite, mas deve tomar cuidado com o Fire Blast do Dragonite de nível 50.", "Se você escolheu Totodile, seu Feraligatr com Surf pode enfrentar Aerodactyl e Charizard. Se escolheu outro inicial, Lapras ou Gyarados com Surf também podem usar a fraqueza dos dois ao tipo Água.", "Se você treinou Graveler ou Golem, eles podem usar golpes de Pedra contra Charizard, que recebe quatro vezes mais dano desse tipo. Também podem enfrentar Aerodactyl, mas tenha cuidado com os ataques dele e mantenha sua vida alta.", "Os três Dragonite conhecem golpes diferentes. Um dos que estão no nível 47 usa Thunder, o outro usa Blizzard, enquanto o Dragonite no nível 50 conhece Fire Blast e Outrage. Tome cuidado especialmente com Thunder se estiver usando Lapras ou outro Pokémon de Água.", "Todos os Pokémon de Lance conhecem Hyper Beam, um golpe muito forte que exige um turno de descanso depois de ser usado. Aproveite esse momento para atacar ou recuperar sua equipe.", "Depois de derrotar Lance, o Professor Carvalho aparecerá e levará você ao Hall da Fama, onde sua equipe será registrada como Champion."]}'::jsonb WHERE slug = 'pokemon-crystal';

-- Estratégias de Pokémon Let’s Go, Pikachu! e Let’s Go, Eevee!.
UPDATE public.builds SET caps = ARRAY['1º GYM - BROCK','2º GYM - MISTY','3º GYM - LT. SURGE','4º GYM - ERIKA','5º GYM - KOGA','6º GYM - SABRINA','7º GYM - BLAINE','8º GYM - GIOVANNI','ELITE FOUR - LORELEI','ELITE FOUR - BRUNO','ELITE FOUR - AGATHA','ELITE FOUR - LANCE','CHAMPION'], dicas = '{"1º GYM - BROCK": ["Brock usa dois Pokémon dos tipos Pedra e Terra. Seu time começa com Geodude no nível 11 e termina com Onix no nível 12.", "Os dois recebem quatro vezes mais dano de golpes dos tipos Água e Planta. Golpes dos tipos Lutador e Terra também são superefetivos.", "Para entrar no ginásio, apresente um Pokémon do tipo Água ou Planta. Oddish pode ser capturado na Route 2 ou na Viridian Forest e usar golpes de Planta contra os dois adversários.", "Bulbasaur também pode aparecer na Viridian Forest e usar golpes de Planta. Sua aparição é rara, então vale preparar outra opção enquanto procura.", "Seu parceiro Pikachu também pode aprender Double Kick no nível 9. O golpe Lutador é superefetivo contra Geodude e Onix, mas golpes elétricos não atingem nenhum dos dois.", "Onix conhece Rock Throw e Bind. Mantenha cuidado com os golpes de Pedra se usar um Pokémon Voador e cure a equipe antes da batalha."], "2º GYM - MISTY": ["Misty usa Psyduck no nível 18 e Starmie no nível 19. Psyduck é do tipo Água e Starmie é dos tipos Água e Psíquico.", "Ambos recebem dano superefetivo de golpes dos tipos Elétrico e Planta. Para entrar no ginásio, apresente um Pokémon de nível 15 ou superior.", "Seu parceiro Pikachu pode usar golpes elétricos contra Psyduck e Starmie. Treine-o e mantenha sua vida alta para suportar os ataques de Água.", "Oddish pode ser capturado na Route 2 ou nas Routes 24 e 25. Seus golpes de Planta aproveitam a fraqueza dos dois adversários.", "Bulbasaur também pode ser capturado na Viridian Forest ou recebido em Cerulean City depois de capturar 30 Pokémon. Ele oferece outra opção com golpes de Planta.", "Psyduck conhece Confusion, perigoso para Oddish e Bulbasaur, pois também são do tipo Veneno. Starmie usa Scald, que pode causar queimadura. Mantenha a equipe recuperada."], "3º GYM - LT. SURGE": ["Lt. Surge usa Voltorb e Magnemite no nível 25 e Raichu no nível 26. Os três são do tipo Elétrico, e Magnemite também é do tipo Metal.", "Os três são vulneráveis a golpes de Terra. Magnemite recebe quatro vezes mais dano desse tipo. Pokémon do tipo Terra são imunes aos golpes elétricos da equipe.", "Capture um Diglett na Diglett’s Cave, a leste de Vermilion City, e use golpes de Terra. Dugtrio também pode aparecer na caverna, mas é mais raro e pode ser difícil de capturar.", "Outra opção é treinar Nidoran até Nidorino ou Nidorina e usar uma Moon Stone para evoluí-lo para Nidoking ou Nidoqueen. Os dois passam a ser do tipo Terra e podem usar golpes desse tipo.", "Raichu conhece Double Kick e Quick Attack, enquanto Magnemite usa Sonic Boom, que causa dano fixo. Diglett tem pouca vida, então não deixe que a imunidade a Elétrico faça você descuidar da equipe."], "4º GYM - ERIKA": ["Erika usa Tangela e Weepinbell no nível 33 e Vileplume no nível 34. Os três são do tipo Planta, enquanto Weepinbell e Vileplume também são do tipo Veneno.", "Os três são vulneráveis a Fogo, Gelo e Voador. Weepinbell e Vileplume também recebem dano superefetivo de Psíquico.", "Você pode receber Charmander na Route 24 depois de capturar 50 Pokémon. Ele evolui para Charmeleon no nível 16 e pode usar golpes de Fogo contra toda a equipe.", "Growlithe, encontrado nas Routes 5 a 8, também é uma opção com golpes de Fogo. Uma Fire Stone comprada em Celadon pode completar sua evolução.", "Pidgeotto ou Pidgeot pode usar golpes Voadores. Pidgey aparece nas primeiras rotas e evolui para Pidgeotto no nível 18 e Pidgeot no nível 36.", "Tangela conhece Sleep Powder e Bind, e Vileplume usa Moonblast. Leve itens para acordar a equipe e mantenha cuidado com Pokémon vulneráveis a Fada."], "5º GYM - KOGA": ["Koga usa Weezing, Muk e Golbat no nível 43 e Venomoth no nível 44. Todos são do tipo Veneno, enquanto Golbat também é Voador e Venomoth também é Inseto.", "Golpes Psíquicos são superefetivos contra os quatro. Terra é eficaz contra Weezing e Muk, mas não atinge Golbat. Venomoth recebe dano normal de Terra por também ser do tipo Inseto.", "Kadabra ou Alakazam pode usar golpes Psíquicos contra a equipe. Abra aparece nas Routes 5 e 6 e evolui para Kadabra no nível 16. Alakazam é obtido por troca.", "Nidoking ou Nidoqueen pode usar golpes de Terra contra Weezing e Muk. Não há habilidades de Pokémon em Let’s Go, então Weezing não possui Levitate para impedir golpes de Terra.", "Contra Golbat, Pikachu ou outro Pokémon elétrico pode usar sua fraqueza ao tipo Voador. Charizard também pode enfrentar Venomoth com golpes de Fogo, mas deve evitar os ataques venenosos.", "Weezing conhece Explosion e os adversários podem usar Toxic e Protect. Venomoth conhece Psychic, perigoso para Pokémon do tipo Veneno. Leve itens de cura e mantenha a equipe recuperada."], "6º GYM - SABRINA": ["Sabrina usa Mr. Mime, Slowbro e Jynx no nível 43 e Alakazam no nível 44. Todos são do tipo Psíquico e alguns têm um segundo tipo.", "Mr. Mime também é Fada e é vulnerável a Veneno, Fantasma e Metal. Slowbro também é Água e é vulnerável a Elétrico, Planta, Inseto, Fantasma e Sombrio. Jynx também é Gelo e é vulnerável a Fogo, Pedra, Inseto, Fantasma, Sombrio e Metal.", "Gastly e Haunter, encontrados na Pokémon Tower, podem usar golpes Fantasmas contra a equipe. Tenha muito cuidado, pois eles também são do tipo Veneno e recebem dano superefetivo de Psychic.", "Pikachu ou Jolteon pode usar golpes elétricos contra Slowbro. Charizard ou outro Pokémon de Fogo pode enfrentar Jynx, mas deve tomar cuidado com Ice Punch.", "Snorlax pode usar sua resistência e golpes físicos contra Alakazam. Ele bloqueia as Routes 12 e 16 e pode ser despertado com a Poké Flute.", "Mr. Mime pode usar Reflect e Light Screen, Jynx conhece Lovely Kiss e Slowbro pode recuperar forças com Calm Mind. Cure sua equipe e leve itens para acordar seus Pokémon."], "7º GYM - BLAINE": ["Blaine usa Magmar, Rapidash e Ninetales no nível 47 e Arcanine no nível 48. Os quatro são do tipo Fogo e vulneráveis a golpes de Água, Terra e Pedra.", "Blastoise, Lapras ou Gyarados pode usar golpes de Água contra toda a equipe. Squirtle pode ser recebido em Vermilion City depois de capturar 60 Pokémon e Lapras é recebido na Silph Company.", "Outra opção é capturar Magikarp e treiná-lo até o nível 20 para evoluí-lo para Gyarados. Também é possível capturar um Gyarados selvagem em locais onde ele aparece.", "Dugtrio, Nidoking ou Nidoqueen pode usar golpes de Terra. Diglett pode ser encontrado na Diglett’s Cave, e os Nidoran podem evoluir com uma Moon Stone depois da primeira evolução.", "Magmar conhece Confuse Ray. Rapidash e Arcanine usam Flare Blitz, que também causa dano ao usuário, e Arcanine conhece Outrage. Mantenha seus Pokémon recuperados e tenha cuidado com a confusão."], "8º GYM - GIOVANNI": ["Giovanni usa Dugtrio, Nidoqueen e Nidoking no nível 49 e Rhydon no nível 50. Todos são do tipo Terra.", "Os quatro são vulneráveis a Água e Gelo. Rhydon também é do tipo Pedra e recebe quatro vezes mais dano de Água e Planta. Nidoqueen e Nidoking também são do tipo Veneno, reduzindo o dano de golpes de Planta.", "Blastoise, Lapras ou Gyarados pode usar golpes de Água contra toda a equipe. Squirtle pode ser recebido em Vermilion City depois de 60 capturas, enquanto Lapras é recebido na Silph Company.", "Venusaur pode usar golpes de Planta contra Dugtrio e Rhydon. Bulbasaur aparece na Viridian Forest e também pode ser recebido em Cerulean City depois de 30 capturas.", "Nidoking conhece Horn Drill, que pode derrotar seu Pokémon em um único acerto. Rhydon conhece Megahorn, perigoso contra Venusaur. Cure sua equipe e aproveite as fraquezas antes que os adversários ataquem."], "ELITE FOUR - LORELEI": ["Lorelei usa Dewgong, Jynx, Cloyster e Slowbro no nível 51 e Lapras no nível 52.", "Dewgong, Cloyster, Slowbro e Lapras recebem dano superefetivo de Elétrico. Jynx é dos tipos Gelo e Psíquico e é vulnerável a Fogo, Pedra, Inseto, Fantasma, Sombrio e Metal.", "Pikachu ou Jolteon pode usar golpes elétricos contra Dewgong, Cloyster, Slowbro e Lapras. Em Let’s Go, Eevee!, você também pode capturar um Pikachu na Viridian Forest.", "Outra opção é Venusaur com golpes de Planta contra os Pokémon de Água. Tenha muito cuidado com os golpes de Gelo da equipe, especialmente Blizzard de Lapras.", "Contra Jynx, Charizard ou Arcanine pode usar golpes de Fogo. Jynx conhece Lovely Kiss e Psychic, então mantenha seu Pokémon com bastante vida e leve itens para curar sono.", "Slowbro conhece Flamethrower e Psychic, enquanto Cloyster usa Hydro Pump e Ice Beam. Depois da vitória, recupere sua equipe antes de enfrentar Bruno."], "ELITE FOUR - BRUNO": ["Bruno usa Onix, Hitmonlee, Hitmonchan e Poliwrath no nível 52 e Machamp no nível 53.", "Onix recebe quatro vezes mais dano de Água e Planta. Hitmonlee, Hitmonchan e Machamp são vulneráveis a Voador, Psíquico e Fada. Poliwrath também é do tipo Água e recebe dano superefetivo de Elétrico e Planta.", "Blastoise, Lapras ou Gyarados pode usar golpes de Água contra Onix. Venusaur também pode aproveitar sua fraqueza de quatro vezes com Planta.", "Kadabra ou Alakazam pode usar golpes Psíquicos contra os quatro Lutadores. Abra aparece nas Routes 5 e 6, evolui para Kadabra no nível 16 e pode evoluir para Alakazam por troca.", "Pidgeot ou Charizard pode usar golpes Voadores contra os Lutadores. Cuidado com Rock Slide de Hitmonlee e Machamp e com Ice Punch e Thunder Punch de Hitmonchan.", "Pikachu ou Jolteon pode usar golpes elétricos contra Poliwrath. Machamp conhece Earthquake, então evite Pokémon vulneráveis a Terra. Recupere sua equipe antes de Agatha."], "ELITE FOUR - AGATHA": ["Agatha usa Arbok, Gengar, Golbat e Weezing no nível 53 e outro Gengar no nível 54. Todos também são do tipo Veneno.", "Os cinco são vulneráveis a Psíquico. Arbok, os dois Gengar e Weezing também são vulneráveis a Terra. Golbat é imune a Terra por ser do tipo Voador.", "Kadabra ou Alakazam com golpes Psíquicos pode enfrentar toda a equipe. Abra aparece nas Routes 5 e 6 e evolui para Kadabra no nível 16.", "Nidoking ou Nidoqueen pode usar golpes de Terra contra Arbok, Gengar e Weezing. Let’s Go não usa habilidades, então não há Levitate para impedir esses golpes.", "Contra Golbat, Pikachu ou Jolteon pode usar golpes elétricos. Golbat conhece Crunch, perigoso para Pokémon Psíquicos, então escolha suas trocas com cuidado.", "Gengar conhece Shadow Ball, que também causa dano superefetivo a Pokémon Psíquicos. O primeiro pode usar Will-O-Wisp e Arbok pode paralisar com Glare. Cure sua equipe antes de Lance."], "ELITE FOUR - LANCE": ["Lance usa Seadra, Aerodactyl, Gyarados e Charizard no nível 54 e Dragonite no nível 55.", "Seadra é vulnerável a Elétrico e Planta. Gyarados recebe quatro vezes mais dano de Elétrico. Aerodactyl é vulnerável a Água, Elétrico, Gelo, Pedra e Metal. Charizard recebe quatro vezes mais dano de Pedra e Dragonite recebe quatro vezes mais dano de Gelo.", "Pikachu ou Jolteon pode usar golpes elétricos contra Seadra, Aerodactyl e Gyarados. Um golpe elétrico também é eficaz contra Charizard.", "Lapras com Ice Beam pode enfrentar Dragonite e Aerodactyl. Ele é recebido na Silph Company e pode aprender golpes de Gelo, mas Dragonite conhece Fire Punch e Outrage.", "Um Pokémon com golpes de Pedra pode aproveitar a fraqueza de Charizard. Graveler, evolução de Geodude no nível 25, é uma opção, mas deve evitar Waterfall de Gyarados e Earthquake de Aerodactyl.", "Toda a equipe de Lance conhece Hyper Beam, e Dragonite pode usar Outrage. Mantenha seus Pokémon saudáveis e recupere a equipe para a batalha contra o Champion."], "CHAMPION": ["Depois de vencer a Elite Four, seu último desafio é seu rival, que chegou à Liga antes de você e se tornou Champion.", "Ele usa Pidgeot, Vileplume, Marowak, Rapidash e Slowbro no nível 56. Em Let’s Go, Pikachu!, seu último Pokémon é Jolteon no nível 57. Em Let’s Go, Eevee!, é Raichu no nível 57.", "Pidgeot, Slowbro e os demais Pokémon têm fraquezas diferentes. Pikachu ou Jolteon pode usar golpes elétricos contra Pidgeot e Slowbro. Pidgeot pode usar Mega Evolução e conhece Heat Wave.", "Contra Vileplume, Charizard ou Arcanine pode usar Fogo. Lapras também pode usar golpes de Gelo, mas deve tomar cuidado com Solar Beam.", "Marowak recebe dano superefetivo de Água, Planta e Gelo. Blastoise, Lapras ou Venusaur pode enfrentá-lo, observando Fire Punch, que é perigoso para Venusaur.", "Contra Rapidash, use Blastoise, Lapras ou Gyarados com golpes de Água. Slowbro pode ser enfrentado com golpes Elétricos ou de Planta, mas conhece Psychic e Surf.", "Contra Jolteon ou Raichu, use Dugtrio, Nidoking ou Nidoqueen com golpes de Terra. Os três são imunes aos golpes elétricos, mas fique atento aos outros ataques.", "Cure sua equipe e prepare itens de recuperação antes da batalha. Depois da vitória, sua equipe será registrada no Hall da Fama como Champion de Kanto."]}'::jsonb WHERE slug = 'pokemon-let-s-go-pikachu';
